async def seed_agents():
    async with SessionLocal() as db:
        for item in AGENT_SEEDS:
            result = await db.execute(
                select(Agent).where(Agent.slug == item["slug"])
            )
            existing = result.scalar_one_or_none()

            if existing is None:
                db.add(Agent(**item))

        await db.commit()


@asynccontextmanager
async def lifespan(app: FastAPI):
    async with engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)

    await seed_agents()

    redis_client = redis.from_url(
        REDIS_URL,
        decode_responses=True,
    )
    await redis_client.ping()
    await redis_client.aclose()

    yield

    await engine.dispose()


app = FastAPI(
    title="Talal Enclave API",
    version="0.1.0",
    lifespan=lifespan,
)


@app.get("/")
async def root():
    return {
        "name": "Talal Enclave",
        "service": "api",
        "version": "0.1.0",
        "status": "running",
    }


@app.get("/health")
async def health():
    async with SessionLocal() as db:
        await db.execute(text("SELECT 1"))

    redis_client = redis.from_url(
        REDIS_URL,
        decode_responses=True,
    )
    redis_ok = await redis_client.ping()
    await redis_client.aclose()

    return {
        "status": "healthy",
        "postgres": True,
        "redis": bool(redis_ok),
    }


@app.get("/api/agents")
async def list_agents(
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(Agent).order_by(Agent.slug)
    )

    agents = result.scalars().all()

    return [
        {
            "id": str(agent.id),
            "slug": agent.slug,
            "name_en": agent.name_en,
            "name_ar": agent.name_ar,
            "role": agent.role,
            "enabled": agent.enabled,
        }
        for agent in agents
    ]


@app.get("/api/agents/{slug}")
async def get_agent(
    slug: str,
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(Agent).where(Agent.slug == slug)
    )
    agent = result.scalar_one_or_none()

    if agent is None:
        raise HTTPException(
            status_code=404,
            detail="Agent not found",
        )

    return {
        "id": str(agent.id),
        "slug": agent.slug,
        "name_en": agent.name_en,
        "name_ar": agent.name_ar,
        "role": agent.role,
        "enabled": agent.enabled,
    }


