async def build_hr_agent_context(
    db: AsyncSession,
    user_text: str,
):
    """
    Build authoritative live HR context from PostgreSQL.

    The base snapshot is always provided.
    Detailed employee/contract data is loaded only when relevant
    to reduce token usage and protect unnecessary personal data.
    """

    import json

    query_text = (user_text or "").lower()

    employee_keywords = [
        "موظف",
        "موظفين",
        "الموظفين",
        "العاملين",
        "القوى العاملة",
        "عدد الموظفين",
        "headcount",
        "employee",
        "employees",
        "workforce",
        "manpower",
        "إدارة",
        "قسم",
        "department",
        "سعودة",
        "saudization",
        "توطين",
    ]

    contract_keywords = [
        "راتب",
        "رواتب",
        "الراتب",
        "salary",
        "salaries",
        "عقد",
        "العقود",
        "contract",
        "contracts",
        "تكلفة",
        "التكلفة",
        "cost",
        "compensation",
        "تعويضات",
        "بدل",
        "بدلات",
        "gosi",
        "تأمينات",
        "تأمين طبي",
        "employment cost",
        "total employment cost",
    ]

    full_hr_keywords = [
        "تقرير hr",
        "تقرير الموارد البشرية",
        "تقرير شامل",
        "تحليل الموارد البشرية",
        "hr report",
        "workforce report",
        "موارد بشرية",
    ]

    include_employees = any(
        word in query_text
        for word in employee_keywords
    )

    include_contracts = any(
        word in query_text
        for word in contract_keywords
    )

    if any(word in query_text for word in full_hr_keywords):
        include_employees = True
        include_contracts = True

    # --------------------------------------------------------
    # Departments
    # --------------------------------------------------------

    result = await db.execute(
        select(HRDepartment)
        .where(HRDepartment.is_active.is_(True))
        .order_by(HRDepartment.name_ar.asc())
    )
    departments = result.scalars().all()

    department_map = {
        x.id: x.name_ar
        for x in departments
    }

    # --------------------------------------------------------
    # Positions
    # --------------------------------------------------------

    result = await db.execute(
        select(HRPosition)
        .where(HRPosition.is_active.is_(True))
        .order_by(HRPosition.title_ar.asc())
    )
    positions = result.scalars().all()

    position_map = {
        x.id: x.title_ar
        for x in positions
    }

    # --------------------------------------------------------
    # Workforce counts
    # --------------------------------------------------------

    result = await db.execute(
        select(func.count())
        .select_from(HREmployee)
    )
    total_employees = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HREmployee)
        .where(
            HREmployee.employment_status == "active"
        )
    )
    active_employees = result.scalar_one()

    # --------------------------------------------------------
    # Contract counts + company employment cost
    # --------------------------------------------------------

    result = await db.execute(
        select(HREmploymentContract)
        .where(
            HREmploymentContract.status == "active"
        )
    )
    active_contract_rows = result.scalars().all()

    active_contracts = len(active_contract_rows)

    total_monthly_cash = 0.0
    total_annual_employment_cost = 0.0

    for c in active_contract_rows:
        monthly_cash = (
            float(c.basic_salary or 0)
            + float(c.housing_allowance or 0)
            + float(c.transport_allowance or 0)
            + float(c.other_fixed_allowances or 0)
        )

        annual_cost = (
            monthly_cash * 12
            + float(c.employer_gosi_cost or 0) * 12
            + float(
                c.medical_insurance_cost_annual or 0
            )
            + float(c.other_annual_cost or 0)
        )

        total_monthly_cash += monthly_cash
        total_annual_employment_cost += annual_cost

    snapshot = {
        "source": "Enclave HR PostgreSQL live database",
        "authoritative": True,
        "summary": {
            "total_employees": total_employees,
            "active_employees": active_employees,
            "departments": len(departments),
            "positions": len(positions),
            "active_contracts": active_contracts,
            "total_monthly_cash_compensation_sar": round(
                total_monthly_cash,
                2,
            ),
            "total_annual_employment_cost_sar": round(
                total_annual_employment_cost,
                2,
            ),
        },
        "departments": [
            {
                "code": x.code,
                "name_ar": x.name_ar,
                "name_en": x.name_en,
                "cost_center": x.cost_center,
            }
            for x in departments
        ],
        "positions": [
            {
                "code": x.code,
                "title_ar": x.title_ar,
                "title_en": x.title_en,
                "department": department_map.get(
                    x.department_id
                ),
                "grade": x.grade,
                "employment_level": x.employment_level,
                "approved_headcount": x.headcount_budget,
                "salary_range_sar": {
                    "min": (
                        float(x.min_salary)
                        if x.min_salary is not None
                        else None
                    ),
                    "mid": (
                        float(x.midpoint_salary)
                        if x.midpoint_salary is not None
                        else None
                    ),
                    "max": (
                        float(x.max_salary)
                        if x.max_salary is not None
                        else None
                    ),
                },
            }
            for x in positions
        ],
    }

    # --------------------------------------------------------
    # Detailed employee register only when relevant
    # --------------------------------------------------------

    if include_employees:
        result = await db.execute(
            select(HREmployee)
            .order_by(
                HREmployee.employee_number.asc()
            )
            .limit(300)
        )
        employees = result.scalars().all()

        snapshot["employees"] = [
            {
                "employee_number": x.employee_number,
                "name": x.full_name_ar,
                "name_en": x.full_name_en,
                "department": department_map.get(
                    x.department_id
                ),
                "position": position_map.get(
                    x.position_id
                ),
                "employment_status": x.employment_status,
                "employment_type": x.employment_type,
                "hire_date": (
                    x.hire_date.isoformat()
                    if x.hire_date else None
                ),
                "work_location": x.work_location,
                "work_email": x.work_email,
                "nationality": x.nationality,
                "gosi_registered": x.gosi_registered,
            }
            for x in employees
        ]

    # --------------------------------------------------------
    # Detailed contract/pay data only when relevant
    # --------------------------------------------------------

    if include_contracts:
        result = await db.execute(
            select(
                HREmploymentContract,
                HREmployee,
            )
            .join(
                HREmployee,
                HREmployee.id
                == HREmploymentContract.employee_id,
            )
            .order_by(
                HREmploymentContract.created_at.desc()
            )
            .limit(300)
        )

        rows = result.all()

        contract_data = []

        for contract, employee in rows:
            monthly_cash = (
                float(contract.basic_salary or 0)
                + float(contract.housing_allowance or 0)
                + float(contract.transport_allowance or 0)
                + float(
                    contract.other_fixed_allowances or 0
                )
            )

            annual_cost = (
                monthly_cash * 12
                + float(
                    contract.employer_gosi_cost or 0
                ) * 12
                + float(
                    contract.medical_insurance_cost_annual
                    or 0
                )
                + float(
                    contract.other_annual_cost or 0
                )
            )

            contract_data.append({
                "employee_number":
                    employee.employee_number,
                "employee_name":
                    employee.full_name_ar,
                "contract_number":
                    contract.contract_number,
                "contract_type":
                    contract.contract_type,
                "status":
                    contract.status,
                "start_date":
                    contract.start_date.isoformat(),
                "end_date": (
                    contract.end_date.isoformat()
                    if contract.end_date else None
                ),
                "auto_renew":
                    contract.auto_renew,
                "notice_period_days":
                    contract.notice_period_days,
                "currency":
                    contract.currency,
                "basic_salary":
                    float(contract.basic_salary or 0),
                "housing_allowance":
                    float(
                        contract.housing_allowance or 0
                    ),
                "transport_allowance":
                    float(
                        contract.transport_allowance or 0
                    ),
                "other_fixed_allowances":
                    float(
                        contract.other_fixed_allowances
                        or 0
                    ),
                "employer_gosi_cost_monthly":
                    float(
                        contract.employer_gosi_cost or 0
                    ),
                "medical_insurance_cost_annual":
                    float(
                        contract.medical_insurance_cost_annual
                        or 0
                    ),
                "other_annual_cost":
                    float(
                        contract.other_annual_cost or 0
                    ),
                "monthly_cash_compensation":
                    round(monthly_cash, 2),
                "annual_employment_cost":
                    round(annual_cost, 2),
            })

        snapshot["contracts_and_compensation"] = (
            contract_data
        )

    # --------------------------------------------------------
    # Onboarding intelligence
    # --------------------------------------------------------

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingPlan)
        .where(HROnboardingPlan.status == "active")
    )
    onboarding_active = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.status.notin_(
                ["completed", "skipped"]
            )
        )
    )
    onboarding_open_items = result.scalar_one()

    from datetime import datetime
    from zoneinfo import ZoneInfo

    onboarding_today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.due_date < onboarding_today,
            HROnboardingItem.status.notin_(
                ["completed", "skipped"]
            ),
        )
    )
    onboarding_overdue = result.scalar_one()

    snapshot["onboarding_summary"] = {
        "active_onboarding_plans": onboarding_active,
        "open_checklist_items": onboarding_open_items,
        "overdue_items": onboarding_overdue,
    }

    onboarding_keywords = [
        "onboarding",
        "تهيئة",
        "تهيئه",
        "موظف جديد",
        "الموظف الجديد",
        "مباشرة",
        "تجربة",
        "التجربة",
        "induction",
    ]

    if any(
        word in query_text
        for word in onboarding_keywords
    ):
        result = await db.execute(
            select(
                HROnboardingPlan,
                HREmployee,
            )
            .join(
                HREmployee,
                HREmployee.id
                == HROnboardingPlan.employee_id,
            )
            .order_by(
                HROnboardingPlan.created_at.desc()
            )
            .limit(100)
        )

        onboarding_rows = result.all()

        result = await db.execute(
            select(HROnboardingItem)
            .order_by(
                HROnboardingItem.due_date.asc()
            )
            .limit(1000)
        )

        onboarding_items = result.scalars().all()

        by_plan = {}

        for item in onboarding_items:
            by_plan.setdefault(
                item.plan_id,
                [],
            ).append({
                "title": item.title,
                "category": item.category,
                "owner": item.owner,
                "status": item.status,
                "due_date": (
                    item.due_date.isoformat()
                    if item.due_date else None
                ),
            })

        snapshot["onboarding_details"] = [
            {
                "employee_number":
                    employee.employee_number,
                "employee_name":
                    employee.full_name_ar,
                "plan_status":
                    plan.status,
                "items":
                    by_plan.get(plan.id, []),
            }
            for plan, employee in onboarding_rows
        ]

    # --------------------------------------------------------
    # Employee lifecycle intelligence
    # --------------------------------------------------------

    from datetime import timedelta

    lifecycle_today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    lifecycle_next_30 = (
        lifecycle_today + timedelta(days=30)
    )

    result = await db.execute(
        select(func.count())
        .select_from(HREmployee)
        .where(
            HREmployee.probation_end_date.is_not(None),
            HREmployee.probation_end_date
            >= lifecycle_today,
            HREmployee.probation_end_date
            <= lifecycle_next_30,
            HREmployee.employment_status == "active",
        )
    )
    probation_due_count = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HREmployeeChange)
        .where(
            HREmployeeChange.status
            == "pending_approval"
        )
    )
    lifecycle_pending_changes = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROffboardingPlan)
        .where(
            HROffboardingPlan.status == "active"
        )
    )
    lifecycle_active_offboarding = result.scalar_one()

    snapshot["employee_lifecycle_summary"] = {
        "probation_due_next_30_days":
            probation_due_count,
        "pending_employee_changes":
            lifecycle_pending_changes,
        "active_offboarding_plans":
            lifecycle_active_offboarding,
    }

    # --------------------------------------------------------
    # Performance management intelligence
    # --------------------------------------------------------

    result = await db.execute(
        select(func.count())
        .select_from(HRPerformanceCycle)
        .where(
            HRPerformanceCycle.status == "active"
        )
    )
    performance_active_cycles = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRPerformancePlan)
        .where(
            HRPerformancePlan.status == "active"
        )
    )
    performance_active_plans = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRPerformancePlan)
        .where(
            HRPerformancePlan.status == "completed"
        )
    )
    performance_completed_reviews = result.scalar_one()

    result = await db.execute(
        select(HRPerformancePlan.final_score)
        .where(
            HRPerformancePlan.status == "completed",
            HRPerformancePlan.final_score.is_not(None),
        )
    )

    performance_scores = [
        float(x)
        for x in result.scalars().all()
    ]

    snapshot["performance_summary"] = {
        "active_cycles":
            performance_active_cycles,
        "active_performance_plans":
            performance_active_plans,
        "completed_reviews":
            performance_completed_reviews,
        "average_final_score": (
            round(
                sum(performance_scores)
                / len(performance_scores),
                2,
            )
            if performance_scores
            else None
        ),
    }

    # --------------------------------------------------------
    # Compensation & rewards intelligence
    # --------------------------------------------------------

    result = await db.execute(
        select(func.count())
        .select_from(HRCompensationCycle)
        .where(
            HRCompensationCycle.status == "active"
        )
    )
    compensation_active_cycles = result.scalar_one()

    result = await db.execute(
        select(HRCompensationRecommendation)
    )

    compensation_recommendations = (
        result.scalars().all()
    )

    snapshot["compensation_summary"] = {
        "active_compensation_cycles":
            compensation_active_cycles,
        "recommendations":
            len(compensation_recommendations),
        "pending_compensation_approvals":
            sum(
                1
                for x in compensation_recommendations
                if x.status == "pending_approval"
            ),
        "proposed_annual_merit_cost_sar":
            round(
                sum(
                    float(x.annual_merit_cost)
                    for x in compensation_recommendations
                    if x.status != "applied"
                ),
                2,
            ),
        "proposed_bonus_amount_sar":
            round(
                sum(
                    float(x.bonus_amount)
                    for x in compensation_recommendations
                    if x.status != "applied"
                ),
                2,
            ),
        "bonus_basis":
            "percentage of one monthly basic salary",
        "sales_bonus_excluded":
            True,
    }

    # --------------------------------------------------------
    # Payroll & benefits intelligence
    # --------------------------------------------------------

    result = await db.execute(
        select(HRPayrollCycle)
        .order_by(
            HRPayrollCycle.year.desc(),
            HRPayrollCycle.month.desc(),
        )
    )

    payroll_latest_cycle = result.scalars().first()

    payroll_latest_net = 0.0
    payroll_latest_employer_cost = 0.0

    if payroll_latest_cycle:
        result = await db.execute(
            select(HRPayrollEntry).where(
                HRPayrollEntry.cycle_id
                == payroll_latest_cycle.id
            )
        )

        payroll_latest_entries = (
            result.scalars().all()
        )

        payroll_latest_net = round(
            sum(
                float(x.net_pay)
                for x in payroll_latest_entries
            ),
            2,
        )

        payroll_latest_employer_cost = round(
            sum(
                float(x.employer_total_cost)
                for x in payroll_latest_entries
            ),
            2,
        )

    result = await db.execute(
        select(func.count())
        .select_from(HROvertimeRecord)
        .where(
            HROvertimeRecord.status == "pending"
        )
    )
    payroll_pending_overtime = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRBenefitEnrollment)
        .where(
            HRBenefitEnrollment.status == "active"
        )
    )
    payroll_active_benefits = result.scalar_one()

    snapshot["payroll_summary"] = {
        "latest_cycle": (
            {
                "year": payroll_latest_cycle.year,
                "month": payroll_latest_cycle.month,
                "status": payroll_latest_cycle.status,
            }
            if payroll_latest_cycle
            else None
        ),
        "latest_net_pay_sar":
            payroll_latest_net,
        "latest_employer_cost_sar":
            payroll_latest_employer_cost,
        "pending_overtime_records":
            payroll_pending_overtime,
        "active_benefit_enrollments":
            payroll_active_benefits,
        "external_payroll_execution":
            False,
    }

    return """
LIVE HR DATABASE CONTEXT
========================

The following data comes directly from the private Enclave HR
PostgreSQL database and is the authoritative current HR source.

Use it when answering HR questions.

Rules:
- Never invent an employee, salary, department, position,
  contract, or workforce number not present here.
- If the database is empty, say so clearly.
- "approved" does not mean an external action was executed.
- Do not reveal unnecessary sensitive personal identifiers.
- Salary/cost data is confidential HR information.
- When making calculations, use the supplied database values.
- Distinguish monthly cash compensation from annual total
  employment cost.

DATA:
""" + json.dumps(
        snapshot,
        ensure_ascii=False,
        default=str,
    )



async def build_agent_policy_context(
    db: AsyncSession,
    agent_slug: str,
):
    """
    Build authoritative policy context injected into every agent.

    Includes:
    - current active rules
    - historical superseded rules
    - future scheduled rules
    - pending rules awaiting activation
    - relevant open policy/system mismatches

    The agent must resolve the correct rule by effective date rather
    than assuming today's rule applies historically.
    """
    from sqlalchemy import or_ as _sa_or

    today = date.today()

    rules = (
        await db.execute(
            select(
                PolicyEnforcementRule,
                HRPolicyVersion,
                HRPolicy,
            )
            .join(
                HRPolicyVersion,
                HRPolicyVersion.id
                    == PolicyEnforcementRule
                    .policy_version_id,
            )
            .join(
                HRPolicy,
                HRPolicy.id
                    == HRPolicyVersion.policy_id,
            )
            .where(
                PolicyEnforcementRule.status.in_(
                    [
                        "active",
                        "superseded",
                        "scheduled",
                        "pending_activation",
                    ]
                ),
                _sa_or(
                    PolicyEnforcementRule
                        .target_agent_slug
                        .is_(None),
                    PolicyEnforcementRule
                        .target_agent_slug
                        == agent_slug,
                ),
            )
            .order_by(
                PolicyEnforcementRule
                    .rule_key.asc(),
                PolicyEnforcementRule
                    .effective_from.asc(),
            )
            .limit(150)
        )
    ).all()

    rule_context = []

    for rule, version, policy in rules:
        is_effective_today = (
            rule.status
            in {
                "active",
                "superseded",
            }
            and (
                rule.effective_from is None
                or rule.effective_from <= today
            )
            and (
                rule.effective_to is None
                or rule.effective_to >= today
            )
        )

        rule_context.append(
            {
                "rule_key":
                    rule.rule_key,
                "rule_type":
                    rule.rule_type,
                "domain":
                    rule.domain,
                "target_agent_slug":
                    rule.target_agent_slug,
                "target_module":
                    rule.target_module,
                "status":
                    rule.status,
                "effective_from": (
                    rule.effective_from.isoformat()
                    if rule.effective_from
                    else None
                ),
                "effective_to": (
                    rule.effective_to.isoformat()
                    if rule.effective_to
                    else None
                ),
                "effective_today":
                    is_effective_today,
                "rule_value":
                    rule.rule_value,
                "source_clause":
                    rule.source_clause,
                "policy": {
                    "code":
                        policy.code,
                    "title_ar":
                        policy.title_ar,
                    "title_en":
                        policy.title_en,
                    "version":
                        version.version_number,
                    "version_status":
                        version.status,
                    "version_effective_date": (
                        version.effective_date.isoformat()
                        if version.effective_date
                        else None
                    ),
                },
            }
        )

    mismatch_query = (
        select(
            PolicySystemMismatch
        )
        .where(
            PolicySystemMismatch.status
                == "open"
        )
    )

    # Domain-specific agents receive their own
    # operational mismatches.
    if agent_slug in {
        "hr",
        "finance",
    }:
        mismatch_query = (
            mismatch_query.where(
                PolicySystemMismatch.domain
                    == agent_slug
            )
        )

    # IT sees all technical mismatches.
    # CEO sees only high/critical unresolved
    # mismatches for executive awareness.
    elif agent_slug == "ceo":
        mismatch_query = (
            mismatch_query.where(
                PolicySystemMismatch.severity.in_(
                    [
                        "high",
                        "critical",
                    ]
                )
            )
        )

    mismatches = (
        await db.execute(
            mismatch_query
            .order_by(
                PolicySystemMismatch
                    .detected_at.desc()
            )
            .limit(50)
        )
    ).scalars().all()

    mismatch_context = [
        {
            "domain":
                row.domain,
            "affected_module":
                row.affected_module,
            "affected_component":
                row.affected_component,
            "severity":
                row.severity,
            "description":
                row.description,
            "expected_behavior":
                row.expected_behavior,
            "current_behavior":
                row.current_behavior,
            "effective_date": (
                row.effective_date.isoformat()
                if row.effective_date
                else None
            ),
            "task_id": (
                str(row.task_id)
                if row.task_id
                else None
            ),
        }
        for row in mismatches
    ]

    if (
        not rule_context
        and not mismatch_context
    ):
        return ""

    payload = {
        "context_date":
            today.isoformat(),
        "agent_slug":
            agent_slug,
        "policy_rules":
            rule_context,
        "open_policy_system_mismatches":
            mismatch_context,
    }

    return """
DYNAMIC POLICY ENFORCEMENT CONTEXT
==================================

This context is generated from approved policy versions and the
Policy Impact & Enforcement Engine. It is authoritative for
policy-driven agent behavior.

MANDATORY RULES:

1. Never rely on the static system prompt when an applicable
   policy enforcement rule below provides a newer or more
   specific rule.

2. For a CURRENT transaction, use the rule whose effective
   period includes CONTEXT_DATE.

3. For a HISTORICAL transaction, use the rule whose:
      effective_from <= transaction date
   and
      effective_to is null OR effective_to >= transaction date.

4. A superseded rule may still be authoritative for a historical
   transaction that falls inside its historical effective period.

5. A scheduled rule is NOT currently effective before its
   effective_from date.

6. A pending_activation rule must NOT be treated as enforced.

7. If the user asks about a future date, use a scheduled rule only
   when that future date falls on or after its effective_from date,
   and clearly distinguish future policy from current policy.

8. If multiple rules appear relevant, prefer the most specific
   applicable rule for the requested agent/module and effective
   date. Never combine conflicting values.

9. If no effective rule covers the requested date, do not invent
   a policy value. State that no enforceable policy rule is
   available for that period.

10. If an effective rule has rule_type="removal" or its
    rule_value contains {"removed": true}, that rule explicitly
    removes the prior policy rule from its effective date.
    Do NOT continue using the superseded value after that date.

11. OPEN POLICY/SYSTEM MISMATCHES are critical:
    - The approved policy may require behavior that the application
      has not yet technically implemented.
    - You may explain the approved policy.
    - You must NOT claim the system currently enforces that behavior
      while the mismatch remains open.
    - Clearly flag the mismatch when it materially affects the
      user's requested transaction or calculation.

12. Never alter production code, database structure, workflow, or
    calculator merely because a policy rule exists. Technical
    implementation remains controlled through the IT change task
    and approval process.

POLICY DATA:
""" + json.dumps(
        payload,
        ensure_ascii=False,
        default=str,
    )


@app.post("/api/chat/{slug}")
async def chat_with_agent(
    slug: str,
    request: ChatRequest,
    db: AsyncSession = Depends(get_db),
):
    # Get agent
    result = await db.execute(
        select(Agent).where(
            Agent.slug == slug,
            Agent.enabled.is_(True),
        )
    )
    agent = result.scalar_one_or_none()

    if agent is None:
        raise HTTPException(
            status_code=404,
            detail="Agent not found or disabled",
        )

    # Existing or new conversation
    conversation = None

    if request.conversation_id:
        try:
            conversation_uuid = uuid.UUID(
                request.conversation_id
            )
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail="Invalid conversation_id",
            )

        result = await db.execute(
            select(Conversation).where(
                Conversation.id == conversation_uuid,
                Conversation.agent_id == agent.id,
            )
        )
        conversation = result.scalar_one_or_none()

        if conversation is None:
            raise HTTPException(
                status_code=404,
                detail="Conversation not found",
            )

    if conversation is None:
        conversation = Conversation(
            agent_id=agent.id,
            title=request.message[:100],
        )
        db.add(conversation)
        await db.flush()

    # Load global memory shared by all agents
    global_memory_result = await db.execute(
        select(Memory)
        .where(
            Memory.scope == "global",
            Memory.agent_id.is_(None),
            Memory.is_active.is_(True),
        )
        .order_by(Memory.created_at.asc())
        .limit(50)
    )

    global_memories = (
        global_memory_result.scalars().all()
    )

    # Load private memory for the current agent
    agent_memory_result = await db.execute(
        select(Memory)
        .where(
            Memory.scope == "agent",
            Memory.agent_id == agent.id,
            Memory.is_active.is_(True),
        )
        .order_by(Memory.created_at.asc())
        .limit(50)
    )

    private_agent_memories = (
        agent_memory_result.scalars().all()
    )

    agent_memories = (
        global_memories + private_agent_memories
    )

    effective_instructions = agent.system_prompt

    # Every agent receives authoritative dynamic policy rules.
    # This allows approved policy changes to affect agent behavior
    # without rewriting the agent's static system prompt.
    policy_context = await build_agent_policy_context(
        db,
        agent.slug,
    )

    if policy_context:
        effective_instructions += (
            "\n\n"
            + policy_context
        )

    # HR Agent receives live authoritative HR database context.
    if agent.slug == "hr":
        hr_live_context = await build_hr_agent_context(
            db,
            request.message,
        )

        effective_instructions += (
            "\n\n"
            + hr_live_context
        )

    if agent_memories:
        memory_context = "\n".join(
            f"- {memory.content}"
            for memory in agent_memories
        )

        effective_instructions += (
            "\n\nPERSISTENT MEMORY ABOUT THE USER AND CONTEXT:\n"
            + memory_context
            + "\n\nUse these memories when relevant. "
              "Do not mention that you are reading from a memory database."
        )

    # Load recent conversation context
    result = await db.execute(
        select(Message)
        .where(
            Message.conversation_id == conversation.id
        )
        .order_by(Message.created_at.desc())
        .limit(20)
    )

    history = list(
        reversed(result.scalars().all())
    )

    input_messages = []

    for msg in history:
        if msg.role in {"user", "assistant"}:
            input_messages.append(
                {
                    "role": msg.role,
                    "content": msg.content,
                }
            )

    input_messages.append(
        {
            "role": "user",
            "content": request.message,
        }
    )

    # Save user message
    user_message = Message(
        conversation_id=conversation.id,
        role="user",
        content=request.message,
    )
    db.add(user_message)

    try:
        response = await openai_client.responses.create(
            model=OPENAI_MODEL,
            instructions=effective_instructions,
            input=input_messages,
            store=False,
        )

        answer = response.output_text

        if not answer:
            raise RuntimeError(
                "Model returned no text"
            )

    except Exception as exc:
        await db.rollback()

        raise HTTPException(
            status_code=502,
            detail=f"AI provider error: {type(exc).__name__}",
        )

    # Save assistant response
    assistant_message = Message(
        conversation_id=conversation.id,
        role="assistant",
        content=answer,
        message_metadata={
            "provider": "openai",
            "model": OPENAI_MODEL,
            "response_id": response.id,
        },
    )
    db.add(assistant_message)

    # Automatically extract durable memory from the user's message.
    # Failure here must never interrupt the main conversation.
    try:
        memory_candidate = await extract_memory_candidate(
            request.message
        )

        if memory_candidate:
            candidate_scope = memory_candidate.get(
                "scope",
                "agent",
            )

            if candidate_scope == "global":
                memory_agent_id = None

                existing_result = await db.execute(
                    select(Memory).where(
                        Memory.scope == "global",
                        Memory.agent_id.is_(None),
                        Memory.is_active.is_(True),
                    )
                )
            else:
                candidate_scope = "agent"
                memory_agent_id = agent.id

                existing_result = await db.execute(
                    select(Memory).where(
                        Memory.scope == "agent",
                        Memory.agent_id == agent.id,
                        Memory.is_active.is_(True),
                    )
                )

            existing_memories = (
                existing_result.scalars().all()
            )

            existing_contents = {
                m.content.strip().casefold()
                for m in existing_memories
            }

            candidate_content = (
                memory_candidate["content"].strip()
            )

            if (
                candidate_content.casefold()
                not in existing_contents
            ):
                db.add(
                    Memory(
                        agent_id=memory_agent_id,
                        source_conversation_id=conversation.id,
                        scope=candidate_scope,
                        memory_type=memory_candidate[
                            "memory_type"
                        ],
                        content=candidate_content,
                        importance=memory_candidate[
                            "importance"
                        ],
                        memory_metadata={
                            "source": "auto_chat",
                            "captured_by": agent.slug,
                        },
                    )
                )

    except Exception:
        pass

    # Automatically create a trackable task when the user's
    # message clearly contains follow-up or execution intent.
    try:
        # If this is a sensitive/external action requiring
        # approval, it must NOT also become a normal task.
        approval_gate_for_task = (
            await extract_approval_candidate(
                request.message,
                agent.slug,
            )
        )

        if approval_gate_for_task:
            task_candidate = None
        else:
            task_candidate = await extract_task_candidate(
                request.message,
                agent.slug,
            )

        if task_candidate:
            due_at = None
            due_at_raw = task_candidate.get("due_at")

            if due_at_raw:
                try:
                    due_at = datetime.fromisoformat(
                        str(due_at_raw).replace(
                            "Z",
                            "+00:00",
                        )
                    )

                    if due_at.tzinfo is None:
                        due_at = due_at.replace(
                            tzinfo=timezone.utc
                        )
                except Exception:
                    due_at = None

            # Prevent duplicate active tasks with the same title
            duplicate_result = await db.execute(
                select(Task).where(
                    Task.agent_id == agent.id,
                    Task.title == task_candidate["title"],
                    Task.status.in_(
                        ["pending", "in_progress"]
                    ),
                )
            )

            duplicate_task = (
                duplicate_result.scalar_one_or_none()
            )

            if duplicate_task is None:
                db.add(
                    Task(
                        agent_id=agent.id,
                        source_conversation_id=conversation.id,
                        title=task_candidate["title"],
                        description=task_candidate[
                            "description"
                        ],
                        status="pending",
                        priority=task_candidate[
                            "priority"
                        ],
                        due_at=due_at,
                        payload={
                            "source": "auto_chat"
                        },
                    )
                )

    except Exception:
        # Task extraction must never break the conversation
        pass

    # Automatically create an approval request when the user
    # asks for a sensitive or consequential external action.
    try:
        approval_candidate = await extract_approval_candidate(
            request.message,
            agent.slug,
        )

        if approval_candidate:
            # Prevent duplicate pending approvals with the same
            # agent, title and action type.
            duplicate_result = await db.execute(
                select(Approval).where(
                    Approval.agent_id == agent.id,
                    Approval.title == approval_candidate["title"],
                    Approval.action_type
                    == approval_candidate["action_type"],
                    Approval.status == "pending",
                )
            )

            duplicate_approval = (
                duplicate_result.scalar_one_or_none()
            )

            if duplicate_approval is None:
                db.add(
                    Approval(
                        agent_id=agent.id,
                        source_conversation_id=conversation.id,
                        title=approval_candidate["title"],
                        description=approval_candidate[
                            "description"
                        ],
                        action_type=approval_candidate[
                            "action_type"
                        ],
                        risk_level=approval_candidate[
                            "risk_level"
                        ],
                        status="pending",
                        action_payload=approval_candidate[
                            "action_payload"
                        ],
                    )
                )

    except Exception:
        # Approval detection must never interrupt normal chat
        pass

    await db.commit()

    return {
        "conversation_id": str(conversation.id),
        "agent": agent.slug,
        "agent_name": agent.name_en,
        "model": OPENAI_MODEL,
        "message": answer,
    }


