@app.get("/api/conversations/{slug}")
async def list_conversations(
    slug: str,
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(Agent).where(Agent.slug == slug)
    )
    agent = result.scalar_one_or_none()

    if agent is None:
        raise HTTPException(
            status_code=404,
            detail="Agent not found",
        )

    result = await db.execute(
        select(Conversation)
        .where(Conversation.agent_id == agent.id)
        .order_by(Conversation.created_at.desc())
        .limit(100)
    )

    conversations = result.scalars().all()

    return [
        {
            "id": str(c.id),
            "title": c.title or "محادثة بدون عنوان",
            "created_at": c.created_at.isoformat()
            if c.created_at else None,
        }
        for c in conversations
    ]


@app.get("/api/conversations/{conversation_id}/messages")
async def get_conversation_messages(
    conversation_id: str,
    db: AsyncSession = Depends(get_db),
):
    try:
        conversation_uuid = uuid.UUID(conversation_id)
    except ValueError:
        raise HTTPException(
            status_code=400,
            detail="Invalid conversation_id",
        )

    result = await db.execute(
        select(Conversation).where(
            Conversation.id == conversation_uuid
        )
    )

    conversation = result.scalar_one_or_none()

    if conversation is None:
        raise HTTPException(
            status_code=404,
            detail="Conversation not found",
        )

    result = await db.execute(
        select(Message)
        .where(
            Message.conversation_id == conversation_uuid
        )
        .order_by(Message.created_at.asc())
    )

    messages = result.scalars().all()

    return {
        "conversation_id": str(conversation.id),
        "title": conversation.title,
        "messages": [
            {
                "id": str(m.id),
                "role": m.role,
                "content": m.content,
                "created_at": m.created_at.isoformat()
                if m.created_at else None,
            }
            for m in messages
        ],
    }


