# ============================================================
# TASK MANAGEMENT
# ============================================================

class TaskCreateRequest(BaseModel):
    title: str
    description: str | None = None
    agent_slug: str | None = None
    priority: str = "normal"
    due_at: datetime | None = None
    source_conversation_id: str | None = None


class TaskUpdateRequest(BaseModel):
    title: str | None = None
    description: str | None = None
    status: str | None = None
    priority: str | None = None
    due_at: datetime | None = None
    agent_slug: str | None = None


VALID_TASK_STATUSES = {
    "pending",
    "in_progress",
    "completed",
    "cancelled",
}

VALID_TASK_PRIORITIES = {
    "low",
    "normal",
    "high",
    "critical",
}


@app.post("/api/tasks")
async def create_task(
    request: TaskCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    title = request.title.strip()

    if not title:
        raise HTTPException(
            status_code=400,
            detail="Task title is required",
        )

    if request.priority not in VALID_TASK_PRIORITIES:
        raise HTTPException(
            status_code=400,
            detail="Invalid priority",
        )

    agent_id = None

    if request.agent_slug:
        result = await db.execute(
            select(Agent).where(
                Agent.slug == request.agent_slug
            )
        )
        agent = result.scalar_one_or_none()

        if agent is None:
            raise HTTPException(
                status_code=404,
                detail="Agent not found",
            )

        agent_id = agent.id

    source_conversation_id = None

    if request.source_conversation_id:
        try:
            source_conversation_id = uuid.UUID(
                request.source_conversation_id
            )
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail="Invalid source_conversation_id",
            )

    task = Task(
        agent_id=agent_id,
        source_conversation_id=source_conversation_id,
        title=title,
        description=(
            request.description.strip()
            if request.description
            else None
        ),
        status="pending",
        priority=request.priority,
        due_at=request.due_at,
        payload={},
    )

    db.add(task)

    # Flush first so the task receives its UUID before audit logging.
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="task.created",
        details={
            "task_id": str(task.id),
            "title": task.title,
            "status": task.status,
            "priority": task.priority,
            "agent_slug": request.agent_slug,
            "source_conversation_id": (
                str(source_conversation_id)
                if source_conversation_id
                else None
            ),
        },
    )

    # Task + audit event commit atomically.
    await db.commit()
    await db.refresh(task)

    return {
        "id": str(task.id),
        "title": task.title,
        "description": task.description,
        "status": task.status,
        "priority": task.priority,
        "agent_slug": request.agent_slug,
        "due_at": (
            task.due_at.isoformat()
            if task.due_at else None
        ),
        "created_at": (
            task.created_at.isoformat()
            if task.created_at else None
        ),
    }


@app.get("/api/tasks")
async def list_tasks(
    status: str | None = None,
    agent_slug: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(Task)

    if status:
        if status not in VALID_TASK_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid status",
            )

        query = query.where(
            Task.status == status
        )

    agent = None

    if agent_slug:
        result = await db.execute(
            select(Agent).where(
                Agent.slug == agent_slug
            )
        )
        agent = result.scalar_one_or_none()

        if agent is None:
            raise HTTPException(
                status_code=404,
                detail="Agent not found",
            )

        query = query.where(
            Task.agent_id == agent.id
        )

    query = query.order_by(
        Task.created_at.desc()
    ).limit(200)

    result = await db.execute(query)
    tasks = result.scalars().all()

    agent_ids = {
        task.agent_id
        for task in tasks
        if task.agent_id is not None
    }

    agent_map = {}

    if agent_ids:
        result = await db.execute(
            select(Agent).where(
                Agent.id.in_(agent_ids)
            )
        )

        agent_map = {
            item.id: item.slug
            for item in result.scalars().all()
        }

    return [
        {
            "id": str(task.id),
            "title": task.title,
            "description": task.description,
            "status": task.status,
            "priority": task.priority,
            "agent_slug": (
                agent_map.get(task.agent_id)
                if task.agent_id else None
            ),
            "due_at": (
                task.due_at.isoformat()
                if task.due_at else None
            ),
            "completed_at": (
                task.completed_at.isoformat()
                if task.completed_at else None
            ),
            "created_at": (
                task.created_at.isoformat()
                if task.created_at else None
            ),
        }
        for task in tasks
    ]


@app.patch("/api/tasks/{task_id}")
async def update_task(
    task_id: str,
    request: TaskUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    try:
        task_uuid = uuid.UUID(task_id)
    except ValueError:
        raise HTTPException(
            status_code=400,
            detail="Invalid task_id",
        )

    result = await db.execute(
        select(Task).where(Task.id == task_uuid)
    )
    task = result.scalar_one_or_none()

    if task is None:
        raise HTTPException(
            status_code=404,
            detail="Task not found",
        )

    before_state = {
        "title": task.title,
        "description": task.description,
        "status": task.status,
        "priority": task.priority,
        "agent_id": (
            str(task.agent_id)
            if task.agent_id else None
        ),
        "due_at": (
            task.due_at.isoformat()
            if task.due_at else None
        ),
        "completed_at": (
            task.completed_at.isoformat()
            if task.completed_at else None
        ),
    }

    changes = request.model_dump(
        exclude_unset=True
    )

    if "title" in changes:
        title = (changes["title"] or "").strip()

        if not title:
            raise HTTPException(
                status_code=400,
                detail="Task title cannot be empty",
            )

        task.title = title

    if "description" in changes:
        task.description = (
            changes["description"].strip()
            if changes["description"]
            else None
        )

    if "priority" in changes:
        if changes["priority"] not in VALID_TASK_PRIORITIES:
            raise HTTPException(
                status_code=400,
                detail="Invalid priority",
            )

        task.priority = changes["priority"]

    if "status" in changes:
        new_status = changes["status"]

        if new_status not in VALID_TASK_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid status",
            )

        task.status = new_status

        if new_status == "completed":
            task.completed_at = datetime.now(
                timezone.utc
            )
        elif task.completed_at is not None:
            task.completed_at = None

    if "due_at" in changes:
        task.due_at = changes["due_at"]

    if "agent_slug" in changes:
        if changes["agent_slug"] is None:
            task.agent_id = None
        else:
            result = await db.execute(
                select(Agent).where(
                    Agent.slug == changes["agent_slug"]
                )
            )
            agent = result.scalar_one_or_none()

            if agent is None:
                raise HTTPException(
                    status_code=404,
                    detail="Agent not found",
                )

            task.agent_id = agent.id

    if changes:
        after_state = {
            "title": task.title,
            "description": task.description,
            "status": task.status,
            "priority": task.priority,
            "agent_id": (
                str(task.agent_id)
                if task.agent_id else None
            ),
            "due_at": (
                task.due_at.isoformat()
                if task.due_at else None
            ),
            "completed_at": (
                task.completed_at.isoformat()
                if task.completed_at else None
            ),
        }

        await write_audit_log(
            db,
            actor="user",
            action="task.updated",
            details={
                "task_id": str(task.id),
                "changed_fields": sorted(changes.keys()),
                "before": before_state,
                "after": after_state,
            },
        )

    # Task update + audit event commit atomically.
    await db.commit()
    await db.refresh(task)

    return {
        "id": str(task.id),
        "title": task.title,
        "status": task.status,
        "priority": task.priority,
        "completed_at": (
            task.completed_at.isoformat()
            if task.completed_at else None
        ),
    }



