@app.post("/api/approvals/{approval_id}/approve")
async def approve_approval(
    approval_id: str,
    request: ApprovalDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    try:
        approval_uuid = uuid.UUID(approval_id)
    except ValueError:
        raise HTTPException(
            status_code=400,
            detail="Invalid approval_id",
        )

    result = await db.execute(
        select(Approval).where(
            Approval.id == approval_uuid
        )
    )

    approval = result.scalar_one_or_none()

    if approval is None:
        raise HTTPException(
            status_code=404,
            detail="Approval not found",
        )

    if approval.status != "pending":
        raise HTTPException(
            status_code=400,
            detail="Approval is no longer pending",
        )

    approval.status = "approved"
    approval.decision_reason = (
        request.reason.strip()
        if request.reason
        else None
    )
    approval.decided_at = datetime.now(
        timezone.utc
    )

    # Policy-driven technical verification approvals have
    # an additional controlled execution step:
    # final user approval closes the Policy/System mismatch.
    if (
        approval.action_type
        == "policy_technical_verification_acceptance"
    ):
        await _apply_policy_technical_approval_decision(
            db,
            approval,
            approved=True,
            decision_reason=approval.decision_reason,
        )

    await write_audit_log(
        db,
        actor="user",
        action="approval.approved",
        details={
            "approval_id": str(approval.id),
            "title": approval.title,
            "action_type": approval.action_type,
            "risk_level": approval.risk_level,
            "status": approval.status,
            "decision_reason": approval.decision_reason,
        },
    )

    await db.commit()
    await db.refresh(approval)

    return {
        "id": str(approval.id),
        "status": approval.status,
        "decided_at": approval.decided_at.isoformat(),
    }


@app.post("/api/approvals/{approval_id}/reject")
async def reject_approval(
    approval_id: str,
    request: ApprovalDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    try:
        approval_uuid = uuid.UUID(approval_id)
    except ValueError:
        raise HTTPException(
            status_code=400,
            detail="Invalid approval_id",
        )

    result = await db.execute(
        select(Approval).where(
            Approval.id == approval_uuid
        )
    )

    approval = result.scalar_one_or_none()

    if approval is None:
        raise HTTPException(
            status_code=404,
            detail="Approval not found",
        )

    if approval.status != "pending":
        raise HTTPException(
            status_code=400,
            detail="Approval is no longer pending",
        )

    approval.status = "rejected"
    approval.decision_reason = (
        request.reason.strip()
        if request.reason
        else None
    )
    approval.decided_at = datetime.now(
        timezone.utc
    )

    # Rejecting final technical acceptance means the system
    # must NOT be considered policy-compliant yet.
    if (
        approval.action_type
        == "policy_technical_verification_acceptance"
    ):
        await _apply_policy_technical_approval_decision(
            db,
            approval,
            approved=False,
            decision_reason=approval.decision_reason,
        )

    await write_audit_log(
        db,
        actor="user",
        action="approval.rejected",
        details={
            "approval_id": str(approval.id),
            "title": approval.title,
            "action_type": approval.action_type,
            "risk_level": approval.risk_level,
            "status": approval.status,
            "decision_reason": approval.decision_reason,
        },
    )

    await db.commit()
    await db.refresh(approval)

    return {
        "id": str(approval.id),
        "status": approval.status,
        "decided_at": approval.decided_at.isoformat(),
    }



# ============================================================
# AUTOMATIC APPROVAL DETECTION
# ============================================================

OPENAI_APPROVAL_MODEL = os.getenv(
    "OPENAI_APPROVAL_MODEL",
    OPENAI_MODEL,
)


async def extract_approval_candidate(
    user_text: str,
    current_agent_slug: str,
):
    """
    Detect whether the user is asking for an action that must
    require explicit approval before execution.

    Returns a normalized approval dict or None.
    Failure must never interrupt the main conversation.
    """

    cleaned = user_text.strip()

    if not cleaned or len(cleaned) > 5000:
        return None

    instructions = f"""
You are a conservative approval-gate classifier inside a private
AI command center.

Current agent: {current_agent_slug}

Analyze ONLY the user's latest message.

Create an approval request when the user clearly asks the agent to
perform an action with an external side effect, sensitive change,
financial commitment, destructive effect, or consequential execution.

Actions that normally REQUIRE approval include:

- sending an email, message, notification, or external communication
- publishing or posting externally
- deleting files, data, records, messages, or resources
- changing external records or employee records
- financial transfers, payments, purchases, subscriptions, refunds,
  or other commitments
- creating, changing, or revoking permissions or access
- security-sensitive configuration changes
- executing a consequential action in an external system
- accepting, signing, booking, cancelling, or committing on behalf
  of the user or organization
- HR actions affecting an employee's employment status or records

Actions that should NOT create an approval:

- answering questions
- analysis and recommendations
- drafting text without sending it
- preparing a report
- summarizing information
- brainstorming
- calculations
- creating an internal task
- reading information
- purely advisory work

Risk levels:

- low: reversible external action with limited impact
- medium: meaningful external action but limited downside
- high: sensitive, destructive, HR, access-control, legal, or material
  business action
- critical: financial transfer/payment, irreversible destructive action,
  or action with very high security/business impact

Return JSON only.

If approval IS required:

{{
  "requires_approval": true,
  "title": "short approval title in the user's language",
  "description": "clear description of exactly what will be approved",
  "action_type": "short_machine_readable_action_type",
  "risk_level": "low|medium|high|critical",
  "action_payload": {{
    "requested_action": "concise standalone description"
  }}
}}

If approval is NOT required:

{{
  "requires_approval": false
}}

Do not invent recipients, amounts, systems, filenames, dates, or details
the user did not provide.
Do not treat a request to draft or prepare something as a request to
send or execute it.
""".strip()

    try:
        response = await openai_client.responses.create(
            model=OPENAI_APPROVAL_MODEL,
            instructions=instructions,
            input=cleaned,
            store=False,
        )

        raw = (response.output_text or "").strip()

        if raw.startswith("```"):
            raw = raw.strip("`").strip()

            if raw.lower().startswith("json"):
                raw = raw[4:].strip()

        data = json.loads(raw)

        if not data.get("requires_approval"):
            return None

        title = str(
            data.get("title", "")
        ).strip()

        description = str(
            data.get("description", "")
        ).strip()

        action_type = str(
            data.get("action_type", "external_action")
        ).strip().lower()

        risk_level = str(
            data.get("risk_level", "medium")
        ).strip().lower()

        action_payload = data.get(
            "action_payload",
            {},
        )

        if len(title) < 3 or len(title) > 255:
            return None

        if risk_level not in {
            "low",
            "medium",
            "high",
            "critical",
        }:
            risk_level = "medium"

        if not isinstance(action_payload, dict):
            action_payload = {}

        return {
            "title": title,
            "description": description or None,
            "action_type": action_type or "external_action",
            "risk_level": risk_level,
            "action_payload": action_payload,
        }

    except Exception:
        # Approval detection must never break normal chat
        return None



