@app.get("/api/dashboard")
async def executive_dashboard(
    db: AsyncSession = Depends(get_db),
):
    # Agents
    result = await db.execute(
        select(func.count())
        .select_from(Agent)
        .where(Agent.enabled.is_(True))
    )
    active_agents = result.scalar_one()

    # Tasks
    result = await db.execute(
        select(func.count())
        .select_from(Task)
        .where(Task.status == "pending")
    )
    pending_tasks = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(Task)
        .where(Task.status == "in_progress")
    )
    in_progress_tasks = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(Task)
        .where(Task.status == "completed")
    )
    completed_tasks = result.scalar_one()

    # Approvals
    result = await db.execute(
        select(func.count())
        .select_from(Approval)
        .where(Approval.status == "pending")
    )
    pending_approvals = result.scalar_one()

    # Conversations
    result = await db.execute(
        select(func.count())
        .select_from(Conversation)
    )
    total_conversations = result.scalar_one()

    # Recent tasks
    result = await db.execute(
        select(Task)
        .order_by(Task.created_at.desc())
        .limit(5)
    )
    recent_tasks_rows = result.scalars().all()

    # Recent approvals
    result = await db.execute(
        select(Approval)
        .order_by(Approval.created_at.desc())
        .limit(5)
    )
    recent_approval_rows = result.scalars().all()

    return {
        "summary": {
            "active_agents": active_agents,
            "pending_tasks": pending_tasks,
            "in_progress_tasks": in_progress_tasks,
            "completed_tasks": completed_tasks,
            "pending_approvals": pending_approvals,
            "total_conversations": total_conversations,
        },
        "recent_tasks": [
            {
                "id": str(item.id),
                "title": item.title,
                "status": item.status,
                "priority": item.priority,
                "created_at": (
                    item.created_at.isoformat()
                    if item.created_at else None
                ),
            }
            for item in recent_tasks_rows
        ],
        "recent_approvals": [
            {
                "id": str(item.id),
                "title": item.title,
                "status": item.status,
                "risk_level": item.risk_level,
                "created_at": (
                    item.created_at.isoformat()
                    if item.created_at else None
                ),
            }
            for item in recent_approval_rows
        ],
    }



# ============================================================
# CEO MORNING BRIEF
# ============================================================

async def _generate_and_store_morning_brief(
    db: AsyncSession,
    generation_type: str = "on_demand",
):
    """
    Generate the CEO Morning Brief and persist one record per
    Riyadh calendar day.
    """

    import json
    from datetime import datetime
    from zoneinfo import ZoneInfo

    riyadh_now = datetime.now(ZoneInfo("Asia/Riyadh"))
    today = riyadh_now.date()

    # --------------------------------------------------------
    # Current tasks requiring attention
    # --------------------------------------------------------
    result = await db.execute(
        select(Task)
        .where(Task.status.in_(["pending", "in_progress"]))
        .order_by(Task.created_at.desc())
        .limit(25)
    )
    active_tasks = result.scalars().all()

    # --------------------------------------------------------
    # Pending approvals requiring user decision
    # --------------------------------------------------------
    result = await db.execute(
        select(Approval)
        .where(Approval.status == "pending")
        .order_by(Approval.created_at.desc())
        .limit(25)
    )
    pending_approvals = result.scalars().all()

    # --------------------------------------------------------
    # Counts
    # --------------------------------------------------------
    result = await db.execute(
        select(func.count())
        .select_from(Task)
        .where(Task.status == "pending")
    )
    pending_tasks_count = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(Task)
        .where(Task.status == "in_progress")
    )
    in_progress_tasks_count = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(Approval)
        .where(Approval.status == "pending")
    )
    pending_approvals_count = result.scalar_one()

    tasks_data = [
        {
            "title": item.title,
            "description": item.description,
            "status": item.status,
            "priority": item.priority,
            "due_at": (
                item.due_at.isoformat()
                if item.due_at else None
            ),
        }
        for item in active_tasks
    ]

    approvals_data = [
        {
            "title": item.title,
            "description": item.description,
            "action_type": item.action_type,
            "risk_level": item.risk_level,
            "status": item.status,
        }
        for item in pending_approvals
    ]

    snapshot = {
        "pending_tasks": pending_tasks_count,
        "in_progress_tasks": in_progress_tasks_count,
        "pending_approvals": pending_approvals_count,
        "tasks": tasks_data,
        "approvals": approvals_data,
    }

    instructions = """
أنت CEO Agent داخل Enclave AI Command Center.

مهمتك إعداد موجز تنفيذي صباحي خاص بالرئيس التنفيذي اعتمادًا فقط
على بيانات النظام المرسلة لك.

اكتب بالعربية الواضحة والمباشرة.

رتب التقرير بهذه الأقسام بالضبط:

صباح الخير

1. ما يحتاج انتباهك اليوم
اذكر أهم الأمور فقط مرتبة حسب الأهمية والمخاطر.

2. القرارات المطلوبة منك
اذكر الموافقات المعلقة أو القرارات التي تحتاج تدخل المستخدم.
لا تدّعي تنفيذ أي إجراء.

3. المهام ذات الأولوية
ركز على Critical ثم High ثم بقية المهام المهمة.
اذكر حالة المهمة إن كانت معلقة أو قيد التنفيذ.

4. المخاطر أو التأخير
اذكر أي شيء يستحق التنبيه.
إذا لم يوجد شيء واضح، قل إنه لا توجد مخاطر تشغيلية واضحة
من البيانات الحالية.

5. توصية CEO
قدم توصية عملية ومختصرة لما ينبغي التركيز عليه أولًا.

قواعد مهمة:
- لا تخترع معلومات غير موجودة.
- لا تقل إن إجراءً تم تنفيذه ما لم تثبت البيانات ذلك.
- لا ترسل رسائل أو بريدًا أو تنفذ قرارات.
- الموافقات المعلقة تعني أنها تنتظر قرار المستخدم.
- اجعل الموجز مختصرًا وتنفيذيًا وليس تقريرًا طويلًا.
"""

    try:
        response = await openai_client.responses.create(
            model=OPENAI_MODEL,
            instructions=instructions,
            input=json.dumps(
                snapshot,
                ensure_ascii=False,
                default=str,
            ),
            store=False,
        )

        brief_text = (response.output_text or "").strip()

        if not brief_text:
            raise RuntimeError("OpenAI returned an empty Morning Brief")

        # One persistent record per Riyadh calendar day.
        result = await db.execute(
            select(MorningBrief).where(
                MorningBrief.brief_date == today
            )
        )
        record = result.scalar_one_or_none()

        if record:
            record.brief = brief_text
            record.model = OPENAI_MODEL
            record.snapshot = snapshot
            record.generation_type = generation_type
        else:
            record = MorningBrief(
                brief_date=today,
                brief=brief_text,
                model=OPENAI_MODEL,
                snapshot=snapshot,
                generation_type=generation_type,
            )
            db.add(record)

        await write_audit_log(
            db,
            actor=(
                "system"
                if generation_type == "scheduled"
                else "user"
                if generation_type == "manual"
                else "agent:ceo"
            ),
            action="morning_brief.generated",
            details={
                "brief_date": today.isoformat(),
                "generation_type": generation_type,
                "pending_tasks": pending_tasks_count,
                "in_progress_tasks": in_progress_tasks_count,
                "pending_approvals": pending_approvals_count,
                "model": OPENAI_MODEL,
            },
        )

        await db.commit()
        await db.refresh(record)

        return {
            "status": "ok",
            "model": record.model,
            "brief": record.brief,
            "snapshot": record.snapshot,
            "brief_date": record.brief_date.isoformat(),
            "generation_type": record.generation_type,
            "cached": False,
        }

    except Exception as exc:
        await db.rollback()
        print(f"MORNING BRIEF ERROR: {exc}")

        return {
            "status": "error",
            "brief": "تعذر إنشاء الموجز التنفيذي حاليًا.",
            "snapshot": {
                "pending_tasks": pending_tasks_count,
                "in_progress_tasks": in_progress_tasks_count,
                "pending_approvals": pending_approvals_count,
            },
        }


@app.get("/api/morning-brief")
async def get_morning_brief(
    db: AsyncSession = Depends(get_db),
):
    """
    Return today's saved Morning Brief.
    Generate it only if today's brief does not exist yet.
    """

    from datetime import datetime
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(MorningBrief).where(
            MorningBrief.brief_date == today
        )
    )
    record = result.scalar_one_or_none()

    if record:
        return {
            "status": "ok",
            "model": record.model,
            "brief": record.brief,
            "snapshot": record.snapshot,
            "brief_date": record.brief_date.isoformat(),
            "generation_type": record.generation_type,
            "cached": True,
        }

    return await _generate_and_store_morning_brief(
        db,
        generation_type="on_demand",
    )


@app.post("/api/morning-brief/refresh")
async def refresh_morning_brief(
    db: AsyncSession = Depends(get_db),
):
    """
    Manually regenerate today's Morning Brief and replace
    today's saved version.
    """

    return await _generate_and_store_morning_brief(
        db,
        generation_type="manual",
    )




