# ============================================================
# CEO WEEKLY EXECUTIVE REVIEW
# ============================================================

async def _generate_and_store_weekly_review(
    db: AsyncSession,
    generation_type: str = "on_demand",
):
    import json
    from datetime import datetime, timedelta, time
    from zoneinfo import ZoneInfo
    from sqlalchemy import or_

    riyadh_tz = ZoneInfo("Asia/Riyadh")
    now = datetime.now(riyadh_tz)
    review_date = now.date()

    # Most recent completed Sunday-Thursday operating week.
    # On Saturday this resolves to the immediately preceding Sun-Thu.
    days_since_thursday = (now.weekday() - 3) % 7
    period_end = review_date - timedelta(days=days_since_thursday)
    period_start = period_end - timedelta(days=4)

    start_dt = datetime.combine(
        period_start,
        time.min,
        tzinfo=riyadh_tz,
    )
    end_dt = datetime.combine(
        period_end + timedelta(days=1),
        time.min,
        tzinfo=riyadh_tz,
    )

    # --------------------------------------------------------
    # Tasks active/changed during the review period
    # --------------------------------------------------------
    result = await db.execute(
        select(Task)
        .where(
            or_(
                Task.created_at.between(start_dt, end_dt),
                Task.updated_at.between(start_dt, end_dt),
                Task.completed_at.between(start_dt, end_dt),
            )
        )
        .order_by(Task.updated_at.desc())
        .limit(100)
    )
    tasks = result.scalars().all()

    # --------------------------------------------------------
    # Approval activity during the review period
    # --------------------------------------------------------
    result = await db.execute(
        select(Approval)
        .where(
            or_(
                Approval.created_at.between(start_dt, end_dt),
                Approval.decided_at.between(start_dt, end_dt),
            )
        )
        .order_by(Approval.updated_at.desc())
        .limit(100)
    )
    approvals = result.scalars().all()

    tasks_data = [
        {
            "title": item.title,
            "description": item.description,
            "status": item.status,
            "priority": item.priority,
            "created_at": item.created_at.isoformat()
            if item.created_at else None,
            "updated_at": item.updated_at.isoformat()
            if item.updated_at else None,
            "completed_at": item.completed_at.isoformat()
            if item.completed_at else None,
        }
        for item in tasks
    ]

    approvals_data = [
        {
            "title": item.title,
            "description": item.description,
            "action_type": item.action_type,
            "risk_level": item.risk_level,
            "status": item.status,
            "created_at": item.created_at.isoformat()
            if item.created_at else None,
            "decided_at": item.decided_at.isoformat()
            if item.decided_at else None,
        }
        for item in approvals
    ]

    snapshot = {
        "period_start": period_start.isoformat(),
        "period_end": period_end.isoformat(),
        "tasks_total": len(tasks_data),
        "tasks_completed": sum(
            1 for x in tasks_data if x["status"] == "completed"
        ),
        "tasks_pending": sum(
            1 for x in tasks_data if x["status"] == "pending"
        ),
        "tasks_in_progress": sum(
            1 for x in tasks_data if x["status"] == "in_progress"
        ),
        "approvals_total": len(approvals_data),
        "approvals_approved": sum(
            1 for x in approvals_data if x["status"] == "approved"
        ),
        "approvals_rejected": sum(
            1 for x in approvals_data if x["status"] == "rejected"
        ),
        "approvals_pending": sum(
            1 for x in approvals_data if x["status"] == "pending"
        ),
        "tasks": tasks_data,
        "approvals": approvals_data,
    }

    instructions = """
أنت CEO Agent داخل Enclave AI Command Center.

أعد مراجعة تنفيذية أسبوعية للرئيس التنفيذي اعتمادًا فقط
على بيانات النظام المرسلة لك، وتغطي فترة الأحد إلى الخميس.

اكتب بالعربية الواضحة والمباشرة.

رتب التقرير بهذه الأقسام بالضبط:

المراجعة التنفيذية الأسبوعية

1. الملخص التنفيذي
لخص حالة الأسبوع في نقاط قليلة.

2. أبرز الإنجازات
اذكر الأعمال أو المهام التي أُنجزت فعليًا فقط.

3. الأعمال المفتوحة والمتعثرة
اذكر المهام المعلقة أو قيد التنفيذ وما يستحق المتابعة.

4. القرارات والموافقات
لخص الموافقات التي تم اتخاذ قرار بشأنها وما لا يزال ينتظر القرار.

5. المخاطر والتنبيهات
اذكر المخاطر أو التأخير أو النقاط التي تستحق انتباه الإدارة.
لا تخترع مخاطر غير موجودة في البيانات.

6. أولويات الأسبوع القادم
حدد أهم الأولويات العملية بناءً على البيانات الحالية.

7. توصية CEO
قدم خيارين عمليين عند وجود قرار إداري حقيقي،
ثم حدد توصيتك بوضوح.
إذا لم يوجد قرار يتطلب خيارين، قدم توصية تنفيذية واحدة واضحة.

قواعد مهمة:
- لا تخترع أي معلومة.
- لا تعتبر المهمة منجزة إلا إذا كانت حالتها completed.
- لا تعتبر الموافقة منفذة خارجيًا لمجرد أن حالتها approved.
- لا تدّعي إرسال بريد أو تنفيذ إجراء خارجي.
- اجعل التقرير تنفيذيًا ومختصرًا.
"""

    try:
        response = await openai_client.responses.create(
            model=OPENAI_MODEL,
            instructions=instructions,
            input=json.dumps(
                snapshot,
                ensure_ascii=False,
                default=str,
            ),
            store=False,
        )

        review_text = (response.output_text or "").strip()

        if not review_text:
            raise RuntimeError(
                "OpenAI returned an empty Weekly Executive Review"
            )

        result = await db.execute(
            select(WeeklyExecutiveReview).where(
                WeeklyExecutiveReview.review_date == review_date
            )
        )
        record = result.scalar_one_or_none()

        if record:
            record.period_start = period_start
            record.period_end = period_end
            record.review = review_text
            record.model = OPENAI_MODEL
            record.snapshot = snapshot
            record.generation_type = generation_type
        else:
            record = WeeklyExecutiveReview(
                review_date=review_date,
                period_start=period_start,
                period_end=period_end,
                review=review_text,
                model=OPENAI_MODEL,
                snapshot=snapshot,
                generation_type=generation_type,
            )
            db.add(record)

        await write_audit_log(
            db,
            actor=(
                "system"
                if generation_type == "scheduled"
                else "user"
                if generation_type == "manual"
                else "agent:ceo"
            ),
            action="weekly_review.generated",
            details={
                "review_date": review_date.isoformat(),
                "period_start": period_start.isoformat(),
                "period_end": period_end.isoformat(),
                "generation_type": generation_type,
                "tasks_total": len(tasks_data),
                "approvals_total": len(approvals_data),
                "model": OPENAI_MODEL,
            },
        )

        await db.commit()
        await db.refresh(record)

        return {
            "status": "ok",
            "review_date": record.review_date.isoformat(),
            "period_start": record.period_start.isoformat(),
            "period_end": record.period_end.isoformat(),
            "model": record.model,
            "review": record.review,
            "snapshot": record.snapshot,
            "generation_type": record.generation_type,
            "cached": False,
        }

    except Exception as exc:
        await db.rollback()
        print(f"WEEKLY EXECUTIVE REVIEW ERROR: {exc}")

        return {
            "status": "error",
            "review": "تعذر إنشاء المراجعة التنفيذية الأسبوعية حاليًا.",
        }


@app.get("/api/weekly-review")
async def get_weekly_review(
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(WeeklyExecutiveReview).where(
            WeeklyExecutiveReview.review_date == today
        )
    )
    record = result.scalar_one_or_none()

    if record:
        return {
            "status": "ok",
            "review_date": record.review_date.isoformat(),
            "period_start": record.period_start.isoformat(),
            "period_end": record.period_end.isoformat(),
            "model": record.model,
            "review": record.review,
            "snapshot": record.snapshot,
            "generation_type": record.generation_type,
            "cached": True,
        }

    return await _generate_and_store_weekly_review(
        db,
        generation_type="on_demand",
    )


