# ============================================================
# AUDIT TRAIL
# ============================================================

async def write_audit_log(
    db: AsyncSession,
    actor: str,
    action: str,
    details: dict | None = None,
):
    """
    Add an audit event to the current database transaction.

    actor examples:
      user
      system
      agent:ceo
      agent:hr
      agent:finance
    """
    audit = AuditLog(
        actor=actor,
        action=action,
        details=details or {},
    )

    db.add(audit)
    return audit



# ============================================================
# AUDIT TRAIL API
# ============================================================

@app.get("/api/audit-logs")
async def get_audit_logs(
    limit: int = 50,
    actor: str | None = None,
    action_prefix: str | None = None,
    action_contains: str | None = None,
    from_date: date | None = None,
    to_date: date | None = None,
    db: AsyncSession = Depends(get_db),
):
    """
    Read-only audit trail.

    Existing callers remain compatible because all
    new filters are optional.

    HR-specific UI can use:
      action_prefix=hr.
    """

    limit = max(
        1,
        min(
            limit,
            500,
        ),
    )

    query = select(AuditLog)

    if actor:
        query = query.where(
            AuditLog.actor
            == actor.strip()
        )

    if action_prefix:
        query = query.where(
            AuditLog.action.startswith(
                action_prefix.strip()
            )
        )

    if action_contains:
        query = query.where(
            AuditLog.action.ilike(
                f"%{action_contains.strip()}%"
            )
        )

    if from_date:
        from_dt = datetime(
            from_date.year,
            from_date.month,
            from_date.day,
            tzinfo=timezone.utc,
        )

        query = query.where(
            AuditLog.created_at
            >= from_dt
        )

    if to_date:
        next_day = (
            to_date
            + timedelta(days=1)
        )

        to_dt = datetime(
            next_day.year,
            next_day.month,
            next_day.day,
            tzinfo=timezone.utc,
        )

        query = query.where(
            AuditLog.created_at
            < to_dt
        )

    result = await db.execute(
        query
        .order_by(
            AuditLog.created_at.desc()
        )
        .limit(limit)
    )

    rows = result.scalars().all()

    return [
        {
            "id": str(row.id),
            "actor": row.actor,
            "action": row.action,
            "details": row.details or {},
            "created_at": (
                row.created_at.isoformat()
                if row.created_at
                else None
            ),
        }
        for row in rows
    ]



