@app.post("/api/hr/contracts")
async def hr_create_contract(
    request: HRContractCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    employee_id = uuid.UUID(request.employee_id)

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == employee_id
        )
    )
    employee = result.scalar_one_or_none()

    if employee is None:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    contract = HREmploymentContract(
        employee_id=employee_id,
        contract_number=request.contract_number,
        contract_type=request.contract_type,
        start_date=request.start_date,
        end_date=request.end_date,
        auto_renew=request.auto_renew,
        notice_period_days=request.notice_period_days,
        currency=request.currency,
        basic_salary=request.basic_salary,
        housing_allowance=request.housing_allowance,
        transport_allowance=request.transport_allowance,
        other_fixed_allowances=request.other_fixed_allowances,
        employer_gosi_cost=request.employer_gosi_cost,
        medical_insurance_cost_annual=(
            request.medical_insurance_cost_annual
        ),
        other_annual_cost=request.other_annual_cost,
    )

    db.add(contract)
    await db.flush()

    monthly_cash = (
        float(contract.basic_salary)
        + float(contract.housing_allowance)
        + float(contract.transport_allowance)
        + float(contract.other_fixed_allowances)
    )

    annual_employment_cost = (
        (monthly_cash * 12)
        + (float(contract.employer_gosi_cost) * 12)
        + float(contract.medical_insurance_cost_annual)
        + float(contract.other_annual_cost)
    )

    await write_audit_log(
        db,
        actor="user",
        action="hr.contract.created",
        details={
            "contract_id": str(contract.id),
            "employee_id": str(employee_id),
            "contract_type": contract.contract_type,
            "monthly_cash_compensation": monthly_cash,
            "annual_employment_cost": annual_employment_cost,
            "currency": contract.currency,
        },
    )

    await db.commit()
    await db.refresh(contract)

    return {
        "id": str(contract.id),
        "employee_id": str(contract.employee_id),
        "contract_number": contract.contract_number,
        "contract_type": contract.contract_type,
        "monthly_cash_compensation": monthly_cash,
        "annual_employment_cost": annual_employment_cost,
        "currency": contract.currency,
        "status": contract.status,
    }


