@app.get("/api/hr/contracts")
async def hr_list_contracts(
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(
            HREmploymentContract,
            HREmployee,
        )
        .join(
            HREmployee,
            HREmployee.id == HREmploymentContract.employee_id,
        )
        .order_by(HREmploymentContract.created_at.desc())
    )

    rows = result.all()

    output = []

    for contract, employee in rows:
        monthly_cash = (
            float(contract.basic_salary)
            + float(contract.housing_allowance)
            + float(contract.transport_allowance)
            + float(contract.other_fixed_allowances)
        )

        annual_cost = (
            (monthly_cash * 12)
            + (float(contract.employer_gosi_cost) * 12)
            + float(contract.medical_insurance_cost_annual)
            + float(contract.other_annual_cost)
        )

        output.append({
            "id": str(contract.id),
            "employee_id": str(employee.id),
            "employee_number": employee.employee_number,
            "employee_name": employee.full_name_ar,
            "contract_number": contract.contract_number,
            "contract_type": contract.contract_type,
            "start_date": contract.start_date.isoformat(),
            "end_date": (
                contract.end_date.isoformat()
                if contract.end_date else None
            ),
            "status": contract.status,
            "currency": contract.currency,
            "basic_salary": float(contract.basic_salary),
            "housing_allowance": float(contract.housing_allowance),
            "transport_allowance": float(contract.transport_allowance),
            "other_fixed_allowances": float(
                contract.other_fixed_allowances
            ),
            "employer_gosi_cost": float(
                contract.employer_gosi_cost
            ),
            "medical_insurance_cost_annual": float(
                contract.medical_insurance_cost_annual
            ),
            "other_annual_cost": float(
                contract.other_annual_cost
            ),
            "monthly_cash_compensation": monthly_cash,
            "annual_employment_cost": annual_cost,
        })

    return output



