@app.patch("/api/hr/recruitment/candidates/{candidate_id}/stage")
async def recruitment_update_candidate_stage(
    candidate_id: str,
    request: HRCandidateStageRequest,
    db: AsyncSession = Depends(get_db),
):
    if request.stage not in VALID_CANDIDATE_STAGES:
        raise HTTPException(
            status_code=400,
            detail="Invalid candidate stage",
        )

    candidate_uuid = uuid.UUID(candidate_id)

    result = await db.execute(
        select(HRCandidate).where(
            HRCandidate.id == candidate_uuid
        )
    )

    candidate = result.scalar_one_or_none()

    if candidate is None:
        raise HTTPException(
            status_code=404,
            detail="Candidate not found",
        )

    old_stage = candidate.stage
    candidate.stage = request.stage

    await write_audit_log(
        db,
        actor="user",
        action="hr.candidate.stage_changed",
        details={
            "candidate_id": str(candidate.id),
            "full_name": candidate.full_name,
            "before": old_stage,
            "after": candidate.stage,
        },
    )

    await db.commit()
    await db.refresh(candidate)

    return {
        "id": str(candidate.id),
        "stage": candidate.stage,
    }


