@app.post("/api/hr/recruitment/offers")
async def recruitment_create_offer(
    request: HROfferCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    candidate_uuid = uuid.UUID(request.candidate_id)

    result = await db.execute(
        select(HRCandidate).where(
            HRCandidate.id == candidate_uuid
        )
    )
    candidate = result.scalar_one_or_none()

    if candidate is None:
        raise HTTPException(
            status_code=404,
            detail="Candidate not found",
        )

    offer = HROffer(
        candidate_id=candidate_uuid,
        status="draft",
        proposed_start_date=request.proposed_start_date,
        basic_salary=request.basic_salary,
        housing_allowance=request.housing_allowance,
        transport_allowance=request.transport_allowance,
        other_allowances=request.other_allowances,
    )

    db.add(offer)
    candidate.stage = "offer"
    await db.flush()

    monthly_cash = (
        float(offer.basic_salary)
        + float(offer.housing_allowance)
        + float(offer.transport_allowance)
        + float(offer.other_allowances)
    )

    await write_audit_log(
        db,
        actor="user",
        action="hr.offer.draft_created",
        details={
            "offer_id": str(offer.id),
            "candidate_id": str(candidate_uuid),
            "monthly_cash_compensation": monthly_cash,
            "status": "draft",
        },
    )

    await db.commit()

    return {
        "id": str(offer.id),
        "candidate_id": str(candidate_uuid),
        "status": offer.status,
        "monthly_cash_compensation": monthly_cash,
    }


