# ============================================================
# HR RECRUITMENT AI INTELLIGENCE
# ============================================================

async def _hr_ai_json(
    instructions: str,
    payload: dict,
):
    import json

    response = await openai_client.responses.create(
        model=OPENAI_MODEL,
        instructions=instructions,
        input=json.dumps(
            payload,
            ensure_ascii=False,
            default=str,
        ),
        store=False,
    )

    raw = (response.output_text or "").strip()

    if not raw:
        raise RuntimeError("AI returned an empty response")

    # Tolerate markdown fences if the model returns them.
    if raw.startswith("```"):
        raw = raw.replace("```json", "", 1)
        raw = raw.replace("```", "", 1)
        raw = raw.strip()

    first = raw.find("{")
    last = raw.rfind("}")

    if first != -1 and last != -1:
        raw = raw[first:last + 1]

    return json.loads(raw)


async def _extract_cv_text(file: UploadFile):
    from io import BytesIO

    content = await file.read()

    if len(content) > 10 * 1024 * 1024:
        raise HTTPException(
            status_code=413,
            detail="CV file exceeds 10 MB",
        )

    filename = (file.filename or "").lower()

    if filename.endswith(".pdf"):
        from pypdf import PdfReader

        reader = PdfReader(BytesIO(content))
        chunks = []

        for page in reader.pages:
            try:
                chunks.append(page.extract_text() or "")
            except Exception:
                pass

        text = "\n".join(chunks)

    elif filename.endswith(".docx"):
        from docx import Document

        document = Document(BytesIO(content))

        text = "\n".join(
            paragraph.text
            for paragraph in document.paragraphs
        )

    elif filename.endswith(".txt"):
        text = content.decode(
            "utf-8",
            errors="ignore",
        )

    else:
        raise HTTPException(
            status_code=400,
            detail="Supported CV formats: PDF, DOCX, TXT",
        )

    text = text.strip()

    if len(text) < 50:
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not extract enough text from the CV. "
                "Scanned/image-only PDFs are not supported yet."
            ),
        )

    # Reset stream so the same uploaded CV can be
    # persisted after AI analysis.
    await file.seek(0)

    # Hard ceiling for model/context safety.
    return text[:100000]


@app.post(
    "/api/hr/recruitment/vacancies/{vacancy_id}/generate-jd"
)
async def recruitment_generate_jd(
    vacancy_id: str,
    db: AsyncSession = Depends(get_db),
):
    vacancy_uuid = uuid.UUID(vacancy_id)

    result = await db.execute(
        select(HRVacancy).where(
            HRVacancy.id == vacancy_uuid
        )
    )
    vacancy = result.scalar_one_or_none()

    if vacancy is None:
        raise HTTPException(
            status_code=404,
            detail="Vacancy not found",
        )

    position = None
    department = None

    if vacancy.position_id:
        result = await db.execute(
            select(HRPosition).where(
                HRPosition.id == vacancy.position_id
            )
        )
        position = result.scalar_one_or_none()

        if position and position.department_id:
            result = await db.execute(
                select(HRDepartment).where(
                    HRDepartment.id
                    == position.department_id
                )
            )
            department = result.scalar_one_or_none()

    payload = {
        "company": {
            "name": "Enclave",
            "industry": "Cybersecurity",
            "country": "Saudi Arabia",
        },
        "vacancy": {
            "title_ar": vacancy.title_ar,
            "title_en": vacancy.title_en,
            "employment_type":
                vacancy.employment_type,
            "work_location":
                vacancy.work_location,
            "openings":
                vacancy.openings,
            "salary_min":
                float(vacancy.salary_min)
                if vacancy.salary_min is not None
                else None,
            "salary_max":
                float(vacancy.salary_max)
                if vacancy.salary_max is not None
                else None,
            "existing_description":
                vacancy.description,
        },
        "position": {
            "title_ar":
                position.title_ar
                if position else None,
            "title_en":
                position.title_en
                if position else None,
            "grade":
                position.grade
                if position else None,
            "employment_level":
                position.employment_level
                if position else None,
            "department":
                department.name_ar
                if department else None,
        },
    }

    instructions = """
أنت HR Talent Acquisition Agent لشركة Enclave في السعودية.

أنشئ وصفًا وظيفيًا احترافيًا اعتمادًا فقط على البيانات المرسلة.

أعد JSON فقط بهذا الشكل:
{
  "title_ar": "",
  "title_en": "",
  "summary_ar": "",
  "responsibilities_ar": [],
  "requirements_ar": [],
  "preferred_ar": [],
  "competencies_ar": [],
  "screening_criteria": []
}

قواعد:
- لا تخترع شهادات أو سنوات خبرة إلزامية إذا لم يمكن استنتاجها
  منطقيًا من مستوى الوظيفة.
- لا تضف شروطًا متعلقة بالعمر أو الجنس أو الحالة الاجتماعية
  أو الأصل أو الدين أو أي سمة حساسة.
- ركز على الخبرات والمهارات والكفاءات المهنية.
- اجعل الوصف مناسبًا لشركة أمن سيبراني في السعودية.
- screening_criteria يجب أن تكون معايير مهنية قابلة للتحقق
  من السيرة الذاتية.
"""

    data = await _hr_ai_json(
        instructions,
        payload,
    )

    vacancy.title_en = (
        data.get("title_en")
        or vacancy.title_en
    )

    vacancy.description = (
        data.get("summary_ar")
        or vacancy.description
    )

    vacancy.requirements = data

    await write_audit_log(
        db,
        actor="agent:hr",
        action="hr.vacancy.jd_generated",
        details={
            "vacancy_id": str(vacancy.id),
            "title_ar": vacancy.title_ar,
            "model": OPENAI_MODEL,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "vacancy_id": str(vacancy.id),
        "jd": data,
    }


@app.post("/api/hr/recruitment/cv/analyze")
async def recruitment_analyze_cv(
    candidate_id: str = Form(...),
    file: UploadFile = File(...),
    db: AsyncSession = Depends(get_db),
):
    candidate_uuid = uuid.UUID(candidate_id)

    result = await db.execute(
        select(HRCandidate).where(
            HRCandidate.id == candidate_uuid
        )
    )
    candidate = result.scalar_one_or_none()

    if candidate is None:
        raise HTTPException(
            status_code=404,
            detail="Candidate not found",
        )

    if candidate.vacancy_id is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "Candidate must be linked to a vacancy "
                "before CV analysis."
            ),
        )

    result = await db.execute(
        select(HRVacancy).where(
            HRVacancy.id == candidate.vacancy_id
        )
    )
    vacancy = result.scalar_one_or_none()

    if vacancy is None:
        raise HTTPException(
            status_code=404,
            detail="Vacancy not found",
        )

    cv_text = await _extract_cv_text(file)

    payload = {
        "vacancy": {
            "title_ar": vacancy.title_ar,
            "title_en": vacancy.title_en,
            "description": vacancy.description,
            "job_description":
                vacancy.requirements or {},
        },
        "candidate_resume": cv_text,
    }

    instructions = """
أنت HR Recruitment Analyst.

قيّم مدى تطابق السيرة الذاتية مع الوظيفة اعتمادًا فقط على
المؤهلات المهنية ذات الصلة بالوظيفة.

تجاهل بالكامل ولا تستخدم في الدرجة أو الترتيب:
- العمر أو تاريخ الميلاد
- الجنس
- الجنسية أو الأصل
- الحالة الاجتماعية
- الدين
- الإعاقة أو الحالة الصحية
- الصورة
- أي سمة شخصية حساسة أو محمية قانونيًا

لا تستنتج هذه السمات إذا لم تكن مذكورة.

أعد JSON فقط:
{
  "fit_score": 0,
  "summary_ar": "",
  "strengths_ar": [],
  "gaps_ar": [],
  "evidence_ar": [],
  "missing_information_ar": []
}

قواعد الدرجة:
- من 0 إلى 100.
- تعتمد فقط على الخبرة والمهارات والتعليم المهني والشهادات
  والمتطلبات الفنية ذات الصلة بالشاغر.
- لا تعطي قرار تعيين أو رفض.
- إذا كانت الأدلة غير كافية، اخفض الثقة واذكر المعلومات
  الناقصة بدل التخمين.
"""

    data = await _hr_ai_json(
        instructions,
        payload,
    )

    score = float(
        data.get("fit_score") or 0
    )

    score = max(
        0.0,
        min(100.0, score),
    )

    candidate.fit_score = score
    candidate.ai_summary = data.get(
        "summary_ar"
    )

    candidate.ai_strengths = {
        "items": data.get(
            "strengths_ar",
            [],
        ),
        "evidence": data.get(
            "evidence_ar",
            [],
        ),
    }

    candidate.ai_gaps = {
        "items": data.get(
            "gaps_ar",
            [],
        ),
        "missing_information":
            data.get(
                "missing_information_ar",
                [],
            ),
    }

    candidate.cv_text = cv_text
    candidate.cv_file_name = file.filename

    # --------------------------------------------------------
    # Unified private CV storage
    # --------------------------------------------------------
    previous_cv_attachments = (
        await db.execute(
            select(HRAttachment).where(
                HRAttachment.module
                    == "recruitment",
                HRAttachment.entity_type
                    == "candidate",
                HRAttachment.entity_id
                    == candidate.id,
                HRAttachment.document_type
                    == "cv",
                HRAttachment.status
                    == "active",
            )
        )
    ).scalars().all()

    now_utc = datetime.now(
        _timezone.utc
    )

    for previous in previous_cv_attachments:
        previous.status = "archived"
        previous.archived_by = "agent:hr"
        previous.archived_at = now_utc
        previous.archive_reason = (
            "Replaced by a newer CV submitted "
            "for recruitment analysis"
        )

    # _extract_cv_text resets the stream, but seek again
    # defensively before passing it to unified storage.
    await file.seek(0)

    cv_attachment = (
        await upload_hr_attachment(
            module="recruitment",
            entity_type="candidate",
            entity_id=str(candidate.id),
            document_type="cv",
            uploaded_by="agent:hr",
            confidentiality_level="restricted",
            employee_id=None,
            title=(
                file.filename
                or "Candidate CV"
            ),
            description=(
                "Candidate CV used for "
                "recruitment AI analysis"
            ),
            file=file,
            db=db,
        )
    )

    await write_audit_log(
        db,
        actor="agent:hr",
        action="hr.candidate.cv_analyzed",
        details={
            "candidate_id": str(candidate.id),
            "candidate_name":
                candidate.full_name,
            "vacancy_id":
                str(candidate.vacancy_id),
            "fit_score":
                score,
            "file_name":
                file.filename,
            "cv_attachment_id":
                str(
                    cv_attachment["id"]
                ),
            "model":
                OPENAI_MODEL,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "candidate_id": str(candidate.id),
        "candidate_name":
            candidate.full_name,
        "fit_score": score,
        "analysis": data,
    }


@app.get("/api/hr/recruitment/ranking")
async def recruitment_candidate_ranking(
    vacancy_id: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRCandidate).where(
        HRCandidate.fit_score.is_not(None)
    )

    if vacancy_id:
        query = query.where(
            HRCandidate.vacancy_id
            == uuid.UUID(vacancy_id)
        )

    query = query.order_by(
        HRCandidate.fit_score.desc(),
        HRCandidate.created_at.asc(),
    )

    result = await db.execute(query)

    rows = result.scalars().all()

    return [
        {
            "rank": index + 1,
            "candidate_id": str(x.id),
            "vacancy_id": (
                str(x.vacancy_id)
                if x.vacancy_id else None
            ),
            "candidate_name": x.full_name,
            "current_title": x.current_title,
            "years_experience": (
                float(x.years_experience)
                if x.years_experience is not None
                else None
            ),
            "fit_score": float(x.fit_score),
            "summary": x.ai_summary,
            "strengths":
                (x.ai_strengths or {}).get(
                    "items",
                    [],
                ),
            "gaps":
                (x.ai_gaps or {}).get(
                    "items",
                    [],
                ),
            "stage": x.stage,
        }
        for index, x in enumerate(rows)
    ]


class HRInterviewAIEvaluateRequest(BaseModel):
    candidate_id: str
    interview_type: str = "hr"
    interviewer: str | None = None
    notes: str


@app.post(
    "/api/hr/recruitment/interviews/ai-evaluate"
)
async def recruitment_ai_interview_evaluate(
    request: HRInterviewAIEvaluateRequest,
    db: AsyncSession = Depends(get_db),
):
    candidate_uuid = uuid.UUID(
        request.candidate_id
    )

    result = await db.execute(
        select(HRCandidate).where(
            HRCandidate.id == candidate_uuid
        )
    )
    candidate = result.scalar_one_or_none()

    if candidate is None:
        raise HTTPException(
            status_code=404,
            detail="Candidate not found",
        )

    vacancy = None

    if candidate.vacancy_id:
        result = await db.execute(
            select(HRVacancy).where(
                HRVacancy.id
                == candidate.vacancy_id
            )
        )
        vacancy = result.scalar_one_or_none()

    payload = {
        "candidate": {
            "current_title":
                candidate.current_title,
            "years_experience":
                float(candidate.years_experience)
                if candidate.years_experience is not None
                else None,
            "cv_analysis": {
                "fit_score":
                    float(candidate.fit_score)
                    if candidate.fit_score is not None
                    else None,
                "summary":
                    candidate.ai_summary,
            },
        },
        "vacancy": {
            "title_ar":
                vacancy.title_ar
                if vacancy else None,
            "description":
                vacancy.description
                if vacancy else None,
            "requirements":
                vacancy.requirements
                if vacancy else {},
        },
        "interview": {
            "type": request.interview_type,
            "notes": request.notes,
        },
    }

    instructions = """
أنت HR Interview Evaluation Assistant.

قيّم ملاحظات المقابلة فقط وفق الكفاءات المهنية المتعلقة
بالوظيفة.

تجاهل بالكامل أي معلومات عن العمر والجنس والجنسية والأصل
والدين والحالة الاجتماعية والصحة والإعاقة أو أي سمة حساسة.

لا تصدر قرار تعيين أو رفض نهائي.

أعد JSON فقط:
{
  "assessment_score": 0,
  "summary_ar": "",
  "strengths_ar": [],
  "concerns_ar": [],
  "follow_up_questions_ar": [],
  "suggested_next_step": "human_review"
}

suggested_next_step يجب أن يكون واحدًا من:
- human_review
- additional_interview
- insufficient_evidence

الدرجة من 0 إلى 100 وتعتمد فقط على الأدلة المهنية في
ملاحظات المقابلة ومتطلبات الوظيفة.
"""

    data = await _hr_ai_json(
        instructions,
        payload,
    )

    score = float(
        data.get(
            "assessment_score",
            0,
        )
    )

    score = max(
        0.0,
        min(100.0, score),
    )

    feedback = (
        data.get("summary_ar", "")
        + "\n\nنقاط القوة:\n- "
        + "\n- ".join(
            data.get(
                "strengths_ar",
                [],
            )
        )
        + "\n\nملاحظات تحتاج متابعة:\n- "
        + "\n- ".join(
            data.get(
                "concerns_ar",
                [],
            )
        )
    )

    interview = HRInterview(
        candidate_id=candidate.id,
        interview_type=request.interview_type,
        interviewer=request.interviewer,
        score=score,
        recommendation=data.get(
            "suggested_next_step",
            "human_review",
        ),
        feedback=feedback,
    )

    db.add(interview)
    await db.flush()

    await write_audit_log(
        db,
        actor="agent:hr",
        action="hr.interview.ai_evaluated",
        details={
            "interview_id":
                str(interview.id),
            "candidate_id":
                str(candidate.id),
            "assessment_score":
                score,
            "suggested_next_step":
                interview.recommendation,
            "model":
                OPENAI_MODEL,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "interview_id":
            str(interview.id),
        "candidate_id":
            str(candidate.id),
        "assessment_score":
            score,
        "evaluation":
            data,
    }



