VALID_ONBOARDING_STATUSES = {
    "pending",
    "in_progress",
    "completed",
    "skipped",
}


async def ensure_hr_onboarding_plan(
    db: AsyncSession,
    employee: HREmployee,
):
    from datetime import datetime, timedelta
    from zoneinfo import ZoneInfo

    result = await db.execute(
        select(HROnboardingPlan).where(
            HROnboardingPlan.employee_id == employee.id
        )
    )

    existing = result.scalar_one_or_none()

    if existing:
        return existing

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    start_date = employee.hire_date or today

    plan = HROnboardingPlan(
        employee_id=employee.id,
        status="active",
        start_date=start_date,
    )

    db.add(plan)
    await db.flush()

    checklist = [
        {
            "category": "documents",
            "title": "استكمال المستندات الوظيفية",
            "owner": "HR",
            "offset": -3,
        },
        {
            "category": "documents",
            "title": "التحقق من توقيع العقد",
            "owner": "HR",
            "offset": -2,
        },
        {
            "category": "government",
            "title": "التسجيل في التأمينات الاجتماعية GOSI",
            "owner": "HR",
            "offset": 0,
        },
        {
            "category": "benefits",
            "title": "إضافة الموظف إلى التأمين الطبي",
            "owner": "HR",
            "offset": 2,
        },
        {
            "category": "payroll",
            "title": "استكمال بيانات الحساب البنكي والرواتب",
            "owner": "HR / Finance",
            "offset": 3,
        },
        {
            "category": "it",
            "title": "إنشاء البريد والحسابات الوظيفية",
            "owner": "IT",
            "offset": -1,
        },
        {
            "category": "it",
            "title": "تجهيز الجهاز والمعدات",
            "owner": "IT / Admin",
            "offset": -1,
        },
        {
            "category": "security",
            "title": "منح الصلاحيات المطلوبة حسب الدور",
            "owner": "IT / Cybersecurity",
            "offset": 0,
        },
        {
            "category": "security",
            "title": "التوعية بسياسات الأمن السيبراني",
            "owner": "Cybersecurity",
            "offset": 7,
        },
        {
            "category": "orientation",
            "title": "جلسة تعريف الموارد البشرية والسياسات",
            "owner": "HR",
            "offset": 0,
        },
        {
            "category": "orientation",
            "title": "التعريف بالفريق والمدير المباشر",
            "owner": "Manager",
            "offset": 0,
        },
        {
            "category": "performance",
            "title": "تحديد أهداف أول 30 يومًا",
            "owner": "Manager",
            "offset": 7,
        },
        {
            "category": "follow_up",
            "title": "متابعة الموظف بعد 30 يومًا",
            "owner": "HR / Manager",
            "offset": 30,
        },
        {
            "category": "follow_up",
            "title": "متابعة الموظف بعد 60 يومًا",
            "owner": "HR / Manager",
            "offset": 60,
        },
        {
            "category": "probation",
            "title": "مراجعة فترة التجربة حسب العقد",
            "owner": "HR / Manager",
            "offset": None,
        },
    ]

    for spec in checklist:
        due_date = (
            start_date + timedelta(days=spec["offset"])
            if spec["offset"] is not None
            else employee.probation_end_date
        )

        item = HROnboardingItem(
            plan_id=plan.id,
            category=spec["category"],
            title=spec["title"],
            owner=spec["owner"],
            due_date=due_date,
            status="pending",
            is_required=True,
        )

        db.add(item)

    await write_audit_log(
        db,
        actor="system",
        action="hr.onboarding.plan_created",
        details={
            "plan_id": str(plan.id),
            "employee_id": str(employee.id),
            "employee_number": employee.employee_number,
            "employee_name": employee.full_name_ar,
            "start_date": start_date.isoformat(),
            "checklist_items": len(checklist),
        },
    )

    return plan


