@app.post(
    "/api/hr/onboarding/employees/{employee_id}/ensure"
)
async def hr_ensure_onboarding(
    employee_id: str,
    db: AsyncSession = Depends(get_db),
):
    employee_uuid = uuid.UUID(employee_id)

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == employee_uuid
        )
    )

    employee = result.scalar_one_or_none()

    if employee is None:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    plan = await ensure_hr_onboarding_plan(
        db,
        employee,
    )

    await db.commit()

    return {
        "status": "ok",
        "plan_id": str(plan.id),
        "employee_id": str(employee.id),
    }


@app.get("/api/hr/onboarding/plans")
async def hr_list_onboarding_plans(
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(
            HROnboardingPlan,
            HREmployee,
        )
        .join(
            HREmployee,
            HREmployee.id
            == HROnboardingPlan.employee_id,
        )
        .order_by(
            HROnboardingPlan.created_at.desc()
        )
    )

    plan_rows = result.all()

    result = await db.execute(
        select(HROnboardingItem)
        .order_by(
            HROnboardingItem.due_date.asc()
        )
    )

    all_items = result.scalars().all()

    grouped = {}

    for item in all_items:
        grouped.setdefault(
            item.plan_id,
            [],
        ).append(item)

    output = []

    for plan, employee in plan_rows:
        items = grouped.get(plan.id, [])

        completed = sum(
            1
            for x in items
            if x.status in {
                "completed",
                "skipped",
            }
        )

        required_total = len(items)

        progress = (
            round(
                completed / required_total * 100,
                1,
            )
            if required_total else 0
        )

        overdue = sum(
            1
            for x in items
            if x.due_date
            and x.due_date < today
            and x.status
            not in {"completed", "skipped"}
        )

        output.append({
            "id": str(plan.id),
            "employee_id": str(employee.id),
            "employee_number":
                employee.employee_number,
            "employee_name":
                employee.full_name_ar,
            "hire_date": (
                employee.hire_date.isoformat()
                if employee.hire_date else None
            ),
            "status": plan.status,
            "progress": progress,
            "overdue_items": overdue,
            "items": [
                {
                    "id": str(x.id),
                    "category": x.category,
                    "title": x.title,
                    "description": x.description,
                    "owner": x.owner,
                    "status": x.status,
                    "is_required": x.is_required,
                    "due_date": (
                        x.due_date.isoformat()
                        if x.due_date else None
                    ),
                    "completed_at": (
                        x.completed_at.isoformat()
                        if x.completed_at else None
                    ),
                    "completion_note":
                        x.completion_note,
                    "overdue": bool(
                        x.due_date
                        and x.due_date < today
                        and x.status
                        not in {
                            "completed",
                            "skipped",
                        }
                    ),
                }
                for x in items
            ],
        })

    return output


@app.patch(
    "/api/hr/onboarding/items/{item_id}"
)
async def hr_update_onboarding_item(
    item_id: str,
    request: HROnboardingItemUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    item_uuid = uuid.UUID(item_id)

    result = await db.execute(
        select(HROnboardingItem).where(
            HROnboardingItem.id == item_uuid
        )
    )

    item = result.scalar_one_or_none()

    if item is None:
        raise HTTPException(
            status_code=404,
            detail="Onboarding item not found",
        )

    before = {
        "status": item.status,
        "owner": item.owner,
        "due_date": (
            item.due_date.isoformat()
            if item.due_date else None
        ),
    }

    changes = request.model_dump(
        exclude_unset=True
    )

    if "status" in changes:
        new_status = changes["status"]

        if new_status not in VALID_ONBOARDING_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid onboarding status",
            )

        item.status = new_status

        if new_status == "completed":
            item.completed_at = datetime.now(
                ZoneInfo("Asia/Riyadh")
            )
        elif item.completed_at is not None:
            item.completed_at = None

    if "owner" in changes:
        item.owner = changes["owner"]

    if "due_date" in changes:
        item.due_date = changes["due_date"]

    if "completion_note" in changes:
        item.completion_note = (
            changes["completion_note"]
        )

    await db.flush()

    after = {
        "status": item.status,
        "owner": item.owner,
        "due_date": (
            item.due_date.isoformat()
            if item.due_date else None
        ),
    }

    await write_audit_log(
        db,
        actor="user",
        action="hr.onboarding.item_updated",
        details={
            "item_id": str(item.id),
            "plan_id": str(item.plan_id),
            "title": item.title,
            "before": before,
            "after": after,
        },
    )

    result = await db.execute(
        select(HROnboardingItem).where(
            HROnboardingItem.plan_id
            == item.plan_id
        )
    )

    plan_items = result.scalars().all()

    all_done = bool(plan_items) and all(
        x.status in {
            "completed",
            "skipped",
        }
        for x in plan_items
    )

    if all_done:
        result = await db.execute(
            select(HROnboardingPlan).where(
                HROnboardingPlan.id
                == item.plan_id
            )
        )

        plan = result.scalar_one_or_none()

        if plan:
            plan.status = "completed"

            await write_audit_log(
                db,
                actor="system",
                action="hr.onboarding.completed",
                details={
                    "plan_id": str(plan.id),
                    "employee_id":
                        str(plan.employee_id),
                },
            )

    await db.commit()

    return {
        "status": "ok",
        "item_id": str(item.id),
        "item_status": item.status,
    }


