@app.get("/api/hr/onboarding/summary")
async def hr_onboarding_summary(
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingPlan)
        .where(
            HROnboardingPlan.status == "active"
        )
    )
    active_plans = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.status == "pending"
        )
    )
    pending_items = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.status
            == "in_progress"
        )
    )
    in_progress_items = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.status
            == "completed"
        )
    )
    completed_items = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROnboardingItem)
        .where(
            HROnboardingItem.due_date < today,
            HROnboardingItem.status.notin_(
                ["completed", "skipped"]
            ),
        )
    )
    overdue_items = result.scalar_one()

    return {
        "active_plans": active_plans,
        "pending_items": pending_items,
        "in_progress_items": in_progress_items,
        "completed_items": completed_items,
        "overdue_items": overdue_items,
    }



# ============================================================
# HR EMPLOYEE LIFECYCLE API
# ============================================================

VALID_EMPLOYEE_CHANGE_TYPES = {
    "promotion",
    "transfer",
    "salary_change",
    "status_change",
    "termination",
}

VALID_PROBATION_OUTCOMES = {
    "pass",
    "extend",
    "review",
    "concern",
}


class HRProbationReviewCreateRequest(BaseModel):
    employee_id: str
    review_date: date
    reviewer: str | None = None
    performance_score: float | None = None
    outcome: str = "review"
    comments: str | None = None


class HREmployeeChangeCreateRequest(BaseModel):
    employee_id: str
    change_type: str
    effective_date: date

    new_department_id: str | None = None
    new_position_id: str | None = None
    new_basic_salary: float | None = None
    new_employment_status: str | None = None

    notes: str | None = None


class HROffboardingItemUpdateRequest(BaseModel):
    status: str
    notes: str | None = None


async def ensure_hr_offboarding_plan(
    db: AsyncSession,
    employee: HREmployee,
    termination_date: date,
    reason: str | None = None,
):
    from datetime import timedelta

    result = await db.execute(
        select(HROffboardingPlan).where(
            HROffboardingPlan.employee_id == employee.id
        )
    )

    existing = result.scalar_one_or_none()

    if existing:
        return existing

    plan = HROffboardingPlan(
        employee_id=employee.id,
        termination_date=termination_date,
        status="active",
        reason=reason,
    )

    db.add(plan)
    await db.flush()

    items = [
        ("hr", "توثيق قرار انتهاء العلاقة الوظيفية", "HR", -7),
        ("hr", "إجراء مقابلة نهاية الخدمة", "HR", -3),
        ("finance", "احتساب التسوية النهائية ومستحقات الموظف", "HR / Finance", -2),
        ("government", "تحديث حالة الموظف في GOSI", "HR", 0),
        ("benefits", "إلغاء/تحديث التأمين الطبي", "HR", 0),
        ("it", "إغلاق البريد والحسابات والصلاحيات", "IT / Cybersecurity", 0),
        ("assets", "استلام الأجهزة والأصول", "IT / Admin", 0),
        ("security", "إلغاء جميع صلاحيات الأنظمة", "Cybersecurity", 0),
        ("handover", "استلام وتسليم المهام والملفات", "Manager", -2),
        ("records", "أرشفة ملف الموظف والمستندات", "HR", 2),
    ]

    for category, title, owner, offset in items:
        db.add(
            HROffboardingItem(
                plan_id=plan.id,
                category=category,
                title=title,
                owner=owner,
                due_date=termination_date + timedelta(days=offset),
                status="pending",
            )
        )

    await write_audit_log(
        db,
        actor="system",
        action="hr.offboarding.plan_created",
        details={
            "plan_id": str(plan.id),
            "employee_id": str(employee.id),
            "employee_number": employee.employee_number,
            "employee_name": employee.full_name_ar,
            "termination_date": termination_date.isoformat(),
        },
    )

    return plan


@app.post("/api/hr/lifecycle/probation-reviews")
async def hr_create_probation_review(
    request: HRProbationReviewCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    employee_uuid = uuid.UUID(request.employee_id)

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == employee_uuid
        )
    )

    employee = result.scalar_one_or_none()

    if employee is None:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    if request.outcome not in VALID_PROBATION_OUTCOMES:
        raise HTTPException(
            status_code=400,
            detail="Invalid probation outcome",
        )

    score = request.performance_score

    if score is not None:
        score = max(0, min(100, score))

    review = HRProbationReview(
        employee_id=employee.id,
        review_date=request.review_date,
        reviewer=request.reviewer,
        performance_score=score,
        outcome=request.outcome,
        comments=request.comments,
    )

    db.add(review)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.probation.review_created",
        details={
            "review_id": str(review.id),
            "employee_id": str(employee.id),
            "employee_name": employee.full_name_ar,
            "outcome": review.outcome,
            "performance_score": (
                float(review.performance_score)
                if review.performance_score is not None
                else None
            ),
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "id": str(review.id),
    }


