@app.post(
    "/api/hr/lifecycle/changes/{change_id}/apply"
)
async def hr_apply_employee_change(
    change_id: str,
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    change_uuid = uuid.UUID(change_id)

    result = await db.execute(
        select(HREmployeeChange).where(
            HREmployeeChange.id == change_uuid
        )
    )

    change = result.scalar_one_or_none()

    if change is None:
        raise HTTPException(
            status_code=404,
            detail="Employee change not found",
        )

    if change.status == "applied":
        raise HTTPException(
            status_code=409,
            detail="Change already applied",
        )

    result = await db.execute(
        select(Approval).where(
            Approval.id == change.approval_id
        )
    )

    approval = result.scalar_one_or_none()

    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Change must be approved before application"
            ),
        )

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == change.employee_id
        )
    )

    employee = result.scalar_one()

    result = await db.execute(
        select(HREmploymentContract)
        .where(
            HREmploymentContract.employee_id == employee.id,
            HREmploymentContract.status == "active",
        )
        .order_by(
            HREmploymentContract.created_at.desc()
        )
    )

    contract = result.scalars().first()

    proposed = change.proposed_state or {}

    if proposed.get("department_id"):
        employee.department_id = uuid.UUID(
            proposed["department_id"]
        )

    if proposed.get("position_id"):
        employee.position_id = uuid.UUID(
            proposed["position_id"]
        )

    if proposed.get("employment_status"):
        employee.employment_status = (
            proposed["employment_status"]
        )

    if (
        proposed.get("basic_salary") is not None
        and contract is not None
    ):
        contract.basic_salary = float(
            proposed["basic_salary"]
        )

    if change.change_type == "termination":
        employee.employment_status = "terminated"
        employee.termination_date = change.effective_date

        if contract:
            contract.status = "ended"

        await ensure_hr_offboarding_plan(
            db,
            employee,
            change.effective_date,
            change.notes,
        )

    change.status = "applied"
    change.applied_at = datetime.now(
        ZoneInfo("Asia/Riyadh")
    )

    await write_audit_log(
        db,
        actor="user",
        action="hr.employee_change.applied",
        details={
            "change_id": str(change.id),
            "approval_id": str(approval.id),
            "employee_id": str(employee.id),
            "employee_name": employee.full_name_ar,
            "change_type": change.change_type,
            "effective_date": (
                change.effective_date.isoformat()
            ),
            "before": change.before_state,
            "applied": proposed,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "change_id": str(change.id),
        "employee_id": str(employee.id),
        "change_status": "applied",
    }


@app.get("/api/hr/lifecycle/offboarding")
async def hr_list_offboarding(
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    result = await db.execute(
        select(
            HROffboardingPlan,
            HREmployee,
        )
        .join(
            HREmployee,
            HREmployee.id
            == HROffboardingPlan.employee_id,
        )
        .order_by(
            HROffboardingPlan.created_at.desc()
        )
    )

    plan_rows = result.all()

    result = await db.execute(
        select(HROffboardingItem)
        .order_by(
            HROffboardingItem.due_date.asc()
        )
    )

    items = result.scalars().all()

    grouped = {}

    for item in items:
        grouped.setdefault(
            item.plan_id,
            [],
        ).append(item)

    output = []

    for plan, employee in plan_rows:
        plan_items = grouped.get(plan.id, [])

        completed = sum(
            1
            for x in plan_items
            if x.status == "completed"
        )

        total = len(plan_items)

        output.append({
            "id": str(plan.id),
            "employee_id": str(employee.id),
            "employee_number": employee.employee_number,
            "employee_name": employee.full_name_ar,
            "termination_date": (
                plan.termination_date.isoformat()
            ),
            "status": plan.status,
            "reason": plan.reason,
            "progress": (
                round(completed / total * 100, 1)
                if total else 0
            ),
            "items": [
                {
                    "id": str(x.id),
                    "category": x.category,
                    "title": x.title,
                    "owner": x.owner,
                    "due_date": (
                        x.due_date.isoformat()
                        if x.due_date else None
                    ),
                    "status": x.status,
                    "overdue": bool(
                        x.due_date
                        and x.due_date < today
                        and x.status != "completed"
                    ),
                    "notes": x.notes,
                }
                for x in plan_items
            ],
        })

    return output


@app.patch(
    "/api/hr/lifecycle/offboarding/items/{item_id}"
)
async def hr_update_offboarding_item(
    item_id: str,
    request: HROffboardingItemUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    if request.status not in {
        "pending",
        "in_progress",
        "completed",
        "skipped",
    }:
        raise HTTPException(
            status_code=400,
            detail="Invalid offboarding status",
        )

    item_uuid = uuid.UUID(item_id)

    result = await db.execute(
        select(HROffboardingItem).where(
            HROffboardingItem.id == item_uuid
        )
    )

    item = result.scalar_one_or_none()

    if item is None:
        raise HTTPException(
            status_code=404,
            detail="Offboarding item not found",
        )

    before_status = item.status
    item.status = request.status

    if request.notes is not None:
        item.notes = request.notes

    if request.status == "completed":
        item.completed_at = datetime.now(
            ZoneInfo("Asia/Riyadh")
        )
    elif item.completed_at is not None:
        item.completed_at = None

    await write_audit_log(
        db,
        actor="user",
        action="hr.offboarding.item_updated",
        details={
            "item_id": str(item.id),
            "plan_id": str(item.plan_id),
            "title": item.title,
            "before": before_status,
            "after": item.status,
        },
    )

    result = await db.execute(
        select(HROffboardingItem).where(
            HROffboardingItem.plan_id == item.plan_id
        )
    )

    plan_items = result.scalars().all()

    if plan_items and all(
        x.status in {"completed", "skipped"}
        for x in plan_items
    ):
        result = await db.execute(
            select(HROffboardingPlan).where(
                HROffboardingPlan.id == item.plan_id
            )
        )

        plan = result.scalar_one_or_none()

        if plan:
            plan.status = "completed"

            await write_audit_log(
                db,
                actor="system",
                action="hr.offboarding.completed",
                details={
                    "plan_id": str(plan.id),
                    "employee_id": str(plan.employee_id),
                },
            )

    await db.commit()

    return {
        "status": "ok",
        "item_id": str(item.id),
        "item_status": item.status,
    }


@app.get("/api/hr/lifecycle/summary")
async def hr_lifecycle_summary(
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime, timedelta
    from zoneinfo import ZoneInfo

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    next_30 = today + timedelta(days=30)

    result = await db.execute(
        select(func.count())
        .select_from(HREmployee)
        .where(
            HREmployee.probation_end_date.is_not(None),
            HREmployee.probation_end_date >= today,
            HREmployee.probation_end_date <= next_30,
            HREmployee.employment_status == "active",
        )
    )
    probation_due = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HREmployeeChange)
        .where(
            HREmployeeChange.status == "pending_approval"
        )
    )
    pending_changes = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HREmployeeChange)
        .where(
            HREmployeeChange.status == "applied"
        )
    )
    applied_changes = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROffboardingPlan)
        .where(
            HROffboardingPlan.status == "active"
        )
    )
    active_offboarding = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROffboardingItem)
        .where(
            HROffboardingItem.due_date < today,
            HROffboardingItem.status.notin_(
                ["completed", "skipped"]
            ),
        )
    )
    overdue_offboarding = result.scalar_one()

    return {
        "probation_due_30_days": probation_due,
        "pending_changes": pending_changes,
        "applied_changes": applied_changes,
        "active_offboarding": active_offboarding,
        "overdue_offboarding_items": overdue_offboarding,
    }



# ============================================================
# HR PERFORMANCE MANAGEMENT API
# ============================================================

VALID_PERFORMANCE_CYCLE_TYPES = {
    "annual",
    "semiannual",
    "quarterly",
}

VALID_PERFORMANCE_CYCLE_STATUSES = {
    "draft",
    "active",
    "closed",
}

VALID_KPI_DIRECTIONS = {
    "higher_better",
    "lower_better",
    "target",
}


class HRPerformanceCycleCreateRequest(BaseModel):
    name: str
    cycle_type: str = "annual"
    start_date: date
    end_date: date
    bell_curve_enabled: bool = False
    notes: str | None = None


class HRKPITemplateCreateRequest(BaseModel):
    name: str
    position_id: str | None = None
    description: str | None = None


class HRKPIMetricCreateRequest(BaseModel):
    template_id: str
    name: str
    description: str | None = None
    weight: float
    target_value: float | None = None
    unit: str | None = None
    direction: str = "higher_better"


class HRPerformancePlanCreateRequest(BaseModel):
    employee_id: str
    cycle_id: str
    template_id: str


class HRPerformanceMetricUpdateRequest(BaseModel):
    actual_value: float | None = None
    self_score: float | None = None
    manager_score: float | None = None
    final_score: float | None = None
    comments: str | None = None


class HRPerformancePlanFinalizeRequest(BaseModel):
    manager_comments: str | None = None
    employee_comments: str | None = None


def _performance_rating(score: float):
    if score >= 90:
        return "exceptional"
    if score >= 80:
        return "exceeds_expectations"
    if score >= 70:
        return "meets_expectations"
    if score >= 60:
        return "partially_meets"
    return "needs_improvement"


@app.post("/api/hr/performance/cycles")
async def hr_create_performance_cycle(
    request: HRPerformanceCycleCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if request.cycle_type not in VALID_PERFORMANCE_CYCLE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid performance cycle type",
        )

    if request.end_date < request.start_date:
        raise HTTPException(
            status_code=400,
            detail="End date cannot be before start date",
        )

    cycle = HRPerformanceCycle(
        name=request.name.strip(),
        cycle_type=request.cycle_type,
        start_date=request.start_date,
        end_date=request.end_date,
        status="draft",
        bell_curve_enabled=request.bell_curve_enabled,
        notes=request.notes,
    )

    db.add(cycle)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.performance.cycle_created",
        details={
            "cycle_id": str(cycle.id),
            "name": cycle.name,
            "cycle_type": cycle.cycle_type,
            "start_date": cycle.start_date.isoformat(),
            "end_date": cycle.end_date.isoformat(),
            "bell_curve_enabled": cycle.bell_curve_enabled,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "id": str(cycle.id),
        "name": cycle.name,
    }


