@app.post("/api/hr/compensation/merit-rules")
async def hr_create_merit_rule(
    request: HRMeritRuleCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if request.performance_rating not in COMPENSATION_RATINGS:
        raise HTTPException(
            status_code=400,
            detail="Invalid performance rating",
        )

    if request.compa_ratio_max < request.compa_ratio_min:
        raise HTTPException(
            status_code=400,
            detail="Compa-ratio max cannot be below min",
        )

    if request.increase_pct < 0:
        raise HTTPException(
            status_code=400,
            detail="Increase percentage cannot be negative",
        )

    cycle_uuid = uuid.UUID(request.cycle_id)

    result = await db.execute(
        select(HRCompensationCycle).where(
            HRCompensationCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Compensation cycle not found",
        )

    rule = HRMeritRule(
        cycle_id=cycle.id,
        performance_rating=request.performance_rating,
        compa_ratio_min=request.compa_ratio_min,
        compa_ratio_max=request.compa_ratio_max,
        increase_pct=request.increase_pct,
    )

    db.add(rule)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.compensation.merit_rule_created",
        details={
            "rule_id": str(rule.id),
            "cycle_id": str(cycle.id),
            "rating": rule.performance_rating,
            "compa_ratio_min": float(rule.compa_ratio_min),
            "compa_ratio_max": float(rule.compa_ratio_max),
            "increase_pct": float(rule.increase_pct),
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "id": str(rule.id),
    }


