@app.get("/api/hr/compensation/rules")
async def hr_list_compensation_rules(
    cycle_id: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    merit_query = select(HRMeritRule)
    bonus_query = select(HRBonusRule)

    if cycle_id:
        cycle_uuid = uuid.UUID(cycle_id)

        merit_query = merit_query.where(
            HRMeritRule.cycle_id == cycle_uuid
        )

        bonus_query = bonus_query.where(
            HRBonusRule.cycle_id == cycle_uuid
        )

    merit_result = await db.execute(
        merit_query.order_by(
            HRMeritRule.performance_rating.asc(),
            HRMeritRule.compa_ratio_min.asc(),
        )
    )

    bonus_result = await db.execute(
        bonus_query.order_by(
            HRBonusRule.performance_rating.asc()
        )
    )

    merit_rules = merit_result.scalars().all()
    bonus_rules = bonus_result.scalars().all()

    return {
        "merit_rules": [
            {
                "id": str(x.id),
                "cycle_id": str(x.cycle_id),
                "performance_rating":
                    x.performance_rating,
                "compa_ratio_min":
                    float(x.compa_ratio_min),
                "compa_ratio_max":
                    float(x.compa_ratio_max),
                "increase_pct":
                    float(x.increase_pct),
            }
            for x in merit_rules
        ],
        "bonus_rules": [
            {
                "id": str(x.id),
                "cycle_id": str(x.cycle_id),
                "performance_rating":
                    x.performance_rating,
                "bonus_pct_of_monthly_basic":
                    float(
                        x.bonus_pct_of_monthly_basic
                    ),
            }
            for x in bonus_rules
        ],
    }


@app.post("/api/hr/compensation/recommendations")
async def hr_generate_compensation_recommendation(
    request: HRCompensationRecommendationCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    cycle_uuid = uuid.UUID(request.cycle_id)
    employee_uuid = uuid.UUID(request.employee_id)

    result = await db.execute(
        select(HRCompensationCycle).where(
            HRCompensationCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Compensation cycle not found",
        )

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == employee_uuid
        )
    )

    employee = result.scalar_one_or_none()

    if employee is None:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    result = await db.execute(
        select(HRCompensationRecommendation).where(
            HRCompensationRecommendation.cycle_id
            == cycle.id,
            HRCompensationRecommendation.employee_id
            == employee.id,
        )
    )

    if result.scalar_one_or_none():
        raise HTTPException(
            status_code=409,
            detail=(
                "Employee already has a recommendation "
                "in this compensation cycle"
            ),
        )

    result = await db.execute(
        select(HREmploymentContract)
        .where(
            HREmploymentContract.employee_id
            == employee.id,
            HREmploymentContract.status == "active",
        )
        .order_by(
            HREmploymentContract.created_at.desc()
        )
    )

    contract = result.scalars().first()

    if contract is None:
        raise HTTPException(
            status_code=400,
            detail="Employee has no active contract",
        )

    if employee.position_id is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "Employee must be assigned to a position "
                "before compensation review"
            ),
        )

    result = await db.execute(
        select(HRPosition).where(
            HRPosition.id == employee.position_id
        )
    )

    position = result.scalar_one_or_none()

    if (
        position is None
        or position.min_salary is None
        or position.midpoint_salary is None
        or position.max_salary is None
        or float(position.midpoint_salary) <= 0
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Position salary range Min/Mid/Max "
                "must be configured first"
            ),
        )

    performance_query = select(
        HRPerformancePlan
    ).where(
        HRPerformancePlan.employee_id == employee.id,
        HRPerformancePlan.status == "completed",
        HRPerformancePlan.final_score.is_not(None),
        HRPerformancePlan.rating.is_not(None),
    )

    if cycle.performance_cycle_id:
        performance_query = performance_query.where(
            HRPerformancePlan.cycle_id
            == cycle.performance_cycle_id
        )

    performance_query = performance_query.order_by(
        HRPerformancePlan.completed_at.desc()
    )

    result = await db.execute(performance_query)

    performance_plan = result.scalars().first()

    if performance_plan is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "A completed performance review is required "
                "before compensation recommendation"
            ),
        )

    current_basic = float(contract.basic_salary)

    salary_min = float(position.min_salary)
    salary_mid = float(position.midpoint_salary)
    salary_max = float(position.max_salary)

    compa_ratio = round(
        current_basic / salary_mid * 100,
        2,
    )

    rating = performance_plan.rating

    result = await db.execute(
        select(HRMeritRule)
        .where(
            HRMeritRule.cycle_id == cycle.id,
            HRMeritRule.performance_rating == rating,
            HRMeritRule.compa_ratio_min <= compa_ratio,
            HRMeritRule.compa_ratio_max >= compa_ratio,
        )
        .order_by(
            HRMeritRule.compa_ratio_min.desc()
        )
    )

    merit_rule = result.scalars().first()

    merit_pct = (
        float(merit_rule.increase_pct)
        if merit_rule else 0.0
    )

    result = await db.execute(
        select(HRBonusRule)
        .where(
            HRBonusRule.cycle_id == cycle.id,
            HRBonusRule.performance_rating == rating,
        )
        .order_by(HRBonusRule.created_at.desc())
    )

    bonus_rule = result.scalars().first()

    bonus_pct = (
        float(
            bonus_rule.bonus_pct_of_monthly_basic
        )
        if bonus_rule else 0.0
    )

    bonus_eligible = True

    if employee.department_id:
        result = await db.execute(
            select(HRDepartment).where(
                HRDepartment.id
                == employee.department_id
            )
        )

        department = result.scalar_one_or_none()

        if department:
            department_name = (
                f"{department.name_ar or ''} "
                f"{department.name_en or ''}"
            ).lower()

            if (
                "المبيعات" in department_name
                or "sales" in department_name
            ):
                bonus_eligible = False
                bonus_pct = 0.0

    proposed_basic = round(
        current_basic
        * (1 + merit_pct / 100),
        2,
    )

    # Do not recommend a basic salary above the approved range.
    proposed_basic = min(
        proposed_basic,
        salary_max,
    )

    monthly_increase = round(
        proposed_basic - current_basic,
        2,
    )

    annual_merit_cost = round(
        monthly_increase * 12,
        2,
    )

    # Annual KPI bonus policy basis:
    # percentage of ONE monthly basic salary.
    bonus_amount = round(
        current_basic * bonus_pct / 100,
        2,
    )

    total_year1_cost = round(
        annual_merit_cost + bonus_amount,
        2,
    )

    recommendation = HRCompensationRecommendation(
        cycle_id=cycle.id,
        employee_id=employee.id,
        contract_id=contract.id,
        performance_plan_id=performance_plan.id,
        effective_date=request.effective_date,
        current_basic=current_basic,
        salary_min=salary_min,
        salary_mid=salary_mid,
        salary_max=salary_max,
        compa_ratio=compa_ratio,
        performance_score=float(
            performance_plan.final_score
        ),
        performance_rating=rating,
        merit_pct=merit_pct,
        proposed_basic=proposed_basic,
        monthly_increase=monthly_increase,
        annual_merit_cost=annual_merit_cost,
        bonus_eligible=bonus_eligible,
        bonus_pct=bonus_pct,
        bonus_amount=bonus_amount,
        total_year1_cost=total_year1_cost,
        status="draft",
        notes=request.notes,
    )

    db.add(recommendation)
    await db.flush()

    await write_audit_log(
        db,
        actor="system",
        action=(
            "hr.compensation.recommendation_generated"
        ),
        details={
            "recommendation_id":
                str(recommendation.id),
            "cycle_id": str(cycle.id),
            "employee_id": str(employee.id),
            "employee_name":
                employee.full_name_ar,
            "current_basic":
                current_basic,
            "compa_ratio":
                compa_ratio,
            "performance_score":
                float(
                    performance_plan.final_score
                ),
            "performance_rating":
                rating,
            "merit_pct":
                merit_pct,
            "proposed_basic":
                proposed_basic,
            "bonus_pct":
                bonus_pct,
            "bonus_amount":
                bonus_amount,
            "bonus_eligible":
                bonus_eligible,
            "total_year1_cost":
                total_year1_cost,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "recommendation_id":
            str(recommendation.id),
        "employee_name":
            employee.full_name_ar,
        "current_basic":
            current_basic,
        "compa_ratio":
            compa_ratio,
        "performance_score":
            float(
                performance_plan.final_score
            ),
        "performance_rating":
            rating,
        "merit_pct":
            merit_pct,
        "proposed_basic":
            proposed_basic,
        "annual_merit_cost":
            annual_merit_cost,
        "bonus_eligible":
            bonus_eligible,
        "bonus_pct":
            bonus_pct,
        "bonus_amount":
            bonus_amount,
        "total_year1_cost":
            total_year1_cost,
    }


@app.post(
    "/api/hr/compensation/recommendations/"
    "{recommendation_id}/request-approval"
)
async def hr_request_compensation_approval(
    recommendation_id: str,
    db: AsyncSession = Depends(get_db),
):
    recommendation_uuid = uuid.UUID(
        recommendation_id
    )

    result = await db.execute(
        select(
            HRCompensationRecommendation,
            HREmployee,
        )
        .join(
            HREmployee,
            HREmployee.id
            == HRCompensationRecommendation.employee_id,
        )
        .where(
            HRCompensationRecommendation.id
            == recommendation_uuid
        )
    )

    row = result.first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Recommendation not found",
        )

    recommendation, employee = row

    existing = await _latest_compensation_approval(
        db,
        recommendation_id,
    )

    if existing and existing.status in {
        "pending",
        "approved",
    }:
        return {
            "status": "ok",
            "approval_id": str(existing.id),
            "approval_status": existing.status,
        }

    result = await db.execute(
        select(Agent).where(
            Agent.slug == "hr"
        )
    )

    hr_agent = result.scalar_one_or_none()

    approval = Approval(
        agent_id=(
            hr_agent.id
            if hr_agent else None
        ),
        title=(
            "اعتماد مراجعة التعويضات - "
            f"{employee.full_name_ar}"
        ),
        description=(
            f"الراتب الأساسي الحالي "
            f"{float(recommendation.current_basic):,.2f} SAR، "
            f"المقترح "
            f"{float(recommendation.proposed_basic):,.2f} SAR، "
            f"Bonus "
            f"{float(recommendation.bonus_amount):,.2f} SAR."
        ),
        action_type="hr_compensation_adjustment",
        risk_level="high",
        status="pending",
        action_payload={
            "recommendation_id":
                str(recommendation.id),
            "employee_id":
                str(employee.id),
            "employee_name":
                employee.full_name_ar,
            "effective_date":
                recommendation.effective_date.isoformat(),
            "current_basic":
                float(
                    recommendation.current_basic
                ),
            "proposed_basic":
                float(
                    recommendation.proposed_basic
                ),
            "merit_pct":
                float(
                    recommendation.merit_pct
                ),
            "bonus_amount":
                float(
                    recommendation.bonus_amount
                ),
            "total_year1_cost":
                float(
                    recommendation.total_year1_cost
                ),
            "requested_action": (
                "Approve compensation recommendation. "
                "Approval does NOT execute payroll "
                "or pay the bonus."
            ),
        },
    )

    db.add(approval)
    await db.flush()

    recommendation.approval_id = approval.id
    recommendation.status = "pending_approval"

    await write_audit_log(
        db,
        actor="user",
        action=(
            "hr.compensation.approval_requested"
        ),
        details={
            "recommendation_id":
                str(recommendation.id),
            "approval_id":
                str(approval.id),
            "employee_id":
                str(employee.id),
            "employee_name":
                employee.full_name_ar,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "approval_id": str(approval.id),
        "approval_status": "pending",
    }


@app.post(
    "/api/hr/compensation/recommendations/"
    "{recommendation_id}/apply"
)
async def hr_apply_compensation_recommendation(
    recommendation_id: str,
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    recommendation_uuid = uuid.UUID(
        recommendation_id
    )

    result = await db.execute(
        select(
            HRCompensationRecommendation,
            HREmployee,
            HREmploymentContract,
        )
        .join(
            HREmployee,
            HREmployee.id
            == HRCompensationRecommendation.employee_id,
        )
        .join(
            HREmploymentContract,
            HREmploymentContract.id
            == HRCompensationRecommendation.contract_id,
        )
        .where(
            HRCompensationRecommendation.id
            == recommendation_uuid
        )
    )

    row = result.first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Recommendation not found",
        )

    recommendation, employee, contract = row

    if recommendation.status == "applied":
        raise HTTPException(
            status_code=409,
            detail="Recommendation already applied",
        )

    approval = await _latest_compensation_approval(
        db,
        recommendation_id,
    )

    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Compensation recommendation must be "
                "approved before application"
            ),
        )

    today = datetime.now(
        ZoneInfo("Asia/Riyadh")
    ).date()

    if recommendation.effective_date > today:
        raise HTTPException(
            status_code=409,
            detail=(
                "The approved salary change cannot be "
                "applied before its effective date"
            ),
        )

    previous_basic = float(contract.basic_salary)

    contract.basic_salary = float(
        recommendation.proposed_basic
    )

    recommendation.status = "applied"

    await write_audit_log(
        db,
        actor="user",
        action="hr.compensation.applied",
        details={
            "recommendation_id":
                str(recommendation.id),
            "approval_id":
                str(approval.id),
            "employee_id":
                str(employee.id),
            "employee_name":
                employee.full_name_ar,
            "effective_date":
                recommendation.effective_date.isoformat(),
            "previous_basic":
                previous_basic,
            "new_basic":
                float(
                    recommendation.proposed_basic
                ),
            "bonus_amount_approved_not_paid":
                float(
                    recommendation.bonus_amount
                ),
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "employee_id": str(employee.id),
        "previous_basic": previous_basic,
        "new_basic": float(
            recommendation.proposed_basic
        ),
        "bonus_amount": float(
            recommendation.bonus_amount
        ),
        "bonus_execution": "not_executed",
    }


