@app.get("/api/hr/compensation/summary")
async def hr_compensation_summary(
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(func.count())
        .select_from(HRCompensationCycle)
        .where(
            HRCompensationCycle.status == "active"
        )
    )
    active_cycles = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRMeritRule)
    )
    merit_rules = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRBonusRule)
    )
    bonus_rules = result.scalar_one()

    result = await db.execute(
        select(HRCompensationRecommendation)
    )

    recommendations = result.scalars().all()

    pending = sum(
        1
        for x in recommendations
        if x.status == "pending_approval"
    )

    proposed_annual_merit = round(
        sum(
            float(x.annual_merit_cost)
            for x in recommendations
            if x.status != "applied"
        ),
        2,
    )

    proposed_bonus = round(
        sum(
            float(x.bonus_amount)
            for x in recommendations
            if x.status != "applied"
        ),
        2,
    )

    return {
        "active_cycles": active_cycles,
        "merit_rules": merit_rules,
        "bonus_rules": bonus_rules,
        "recommendations": len(recommendations),
        "pending_approvals": pending,
        "proposed_annual_merit_cost":
            proposed_annual_merit,
        "proposed_bonus_amount":
            proposed_bonus,
    }



# ============================================================
# HR PAYROLL & BENEFITS API
# ============================================================

VALID_PAYROLL_STATUSES = {
    "draft",
    "preview",
    "pending_approval",
    "approved",
    "closed",
}

VALID_OVERTIME_STATUSES = {
    "pending",
    "approved",
    "rejected",
}


class HRPayrollCycleCreateRequest(BaseModel):
    year: int
    month: int
    variance_threshold_pct: float = 10
    notes: str | None = None


class HRPayrollEntryUpdateRequest(BaseModel):
    employee_gosi_deduction: float | None = None
    other_deductions: float | None = None
    other_earnings: float | None = None


class HROvertimeCreateRequest(BaseModel):
    employee_id: str
    work_date: date
    hours: float
    approved_amount: float = 0
    notes: str | None = None


class HROvertimeStatusRequest(BaseModel):
    status: str


class HRBenefitCreateRequest(BaseModel):
    employee_id: str
    benefit_type: str = "medical"
    provider: str | None = None
    plan_name: str | None = None
    annual_employer_cost: float = 0
    employee_monthly_deduction: float = 0
    start_date: date | None = None
    end_date: date | None = None
    notes: str | None = None


def _recalculate_payroll_entry(entry):
    fixed_cash = (
        float(entry.basic_salary or 0)
        + float(entry.housing_allowance or 0)
        + float(entry.transport_allowance or 0)
        + float(entry.other_fixed_allowances or 0)
    )

    # Payroll is salary-only: basic salary + fixed allowances.
    # Overtime and other employee payments are handled separately.
    gross = fixed_cash

    deductions = (
        float(entry.employee_gosi_deduction or 0)
        + float(entry.other_deductions or 0)
    )

    net = gross - deductions

    employer_cost = (
        gross
        + float(entry.employer_gosi_cost or 0)
        + float(entry.benefit_cost_monthly or 0)
    )

    entry.gross_pay = round(gross, 2)
    entry.net_pay = round(net, 2)
    entry.employer_total_cost = round(
        employer_cost,
        2,
    )


async def _latest_payroll_approval(
    db: AsyncSession,
    cycle_id: str,
):
    result = await db.execute(
        select(Approval)
        .where(
            Approval.action_type
            == "hr_payroll_approval"
        )
        .order_by(
            Approval.created_at.desc()
        )
    )

    for approval in result.scalars().all():
        payload = approval.action_payload or {}

        if str(payload.get("cycle_id")) == str(cycle_id):
            return approval

    return None


@app.post("/api/hr/payroll/cycles")
async def hr_create_payroll_cycle(
    request: HRPayrollCycleCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if request.month < 1 or request.month > 12:
        raise HTTPException(
            status_code=400,
            detail="Invalid payroll month",
        )

    if request.year < 2000 or request.year > 2200:
        raise HTTPException(
            status_code=400,
            detail="Invalid payroll year",
        )

    result = await db.execute(
        select(HRPayrollCycle).where(
            HRPayrollCycle.year == request.year,
            HRPayrollCycle.month == request.month,
        )
    )

    if result.scalar_one_or_none():
        raise HTTPException(
            status_code=409,
            detail="Payroll cycle already exists",
        )

    cycle = HRPayrollCycle(
        year=request.year,
        month=request.month,
        status="draft",
        variance_threshold_pct=max(
            0,
            request.variance_threshold_pct,
        ),
        notes=request.notes,
    )

    db.add(cycle)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.payroll.cycle_created",
        details={
            "cycle_id": str(cycle.id),
            "year": cycle.year,
            "month": cycle.month,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "id": str(cycle.id),
    }


