@app.post(
    "/api/hr/payroll/cycles/{cycle_id}/generate-preview"
)
async def hr_generate_payroll_preview(
    cycle_id: str,
    db: AsyncSession = Depends(get_db),
):
    import calendar
    from datetime import date

    cycle_uuid = uuid.UUID(cycle_id)

    result = await db.execute(
        select(HRPayrollCycle).where(
            HRPayrollCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll cycle not found",
        )

    if cycle.status not in {"draft", "preview"}:
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll preview cannot be regenerated "
                "after approval workflow starts"
            ),
        )

    result = await db.execute(
        select(HRPayrollEntry).where(
            HRPayrollEntry.cycle_id == cycle.id
        )
    )

    if result.scalars().first():
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll preview already exists for this cycle"
            ),
        )

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.employment_status == "active"
        )
        .order_by(
            HREmployee.employee_number.asc()
        )
    )

    employees = result.scalars().all()

    first_day = date(
        cycle.year,
        cycle.month,
        1,
    )

    last_day = date(
        cycle.year,
        cycle.month,
        calendar.monthrange(
            cycle.year,
            cycle.month,
        )[1],
    )

    created = 0

    for employee in employees:
        result = await db.execute(
            select(HREmploymentContract)
            .where(
                HREmploymentContract.employee_id
                == employee.id,
                HREmploymentContract.status == "active",
            )
            .order_by(
                HREmploymentContract.created_at.desc()
            )
        )

        contract = result.scalars().first()

        if contract is None:
            continue

        result = await db.execute(
            select(HROvertimeRecord).where(
                HROvertimeRecord.employee_id
                == employee.id,
                HROvertimeRecord.status == "approved",
                HROvertimeRecord.work_date >= first_day,
                HROvertimeRecord.work_date <= last_day,
            )
        )

        overtime_rows = result.scalars().all()

        overtime_amount = round(
            sum(
                float(x.approved_amount or 0)
                for x in overtime_rows
            ),
            2,
        )

        result = await db.execute(
            select(HRBenefitEnrollment).where(
                HRBenefitEnrollment.employee_id
                == employee.id,
                HRBenefitEnrollment.status == "active",
            )
        )

        benefits = result.scalars().all()

        if benefits:
            annual_benefit_cost = sum(
                float(x.annual_employer_cost or 0)
                for x in benefits
            )

            employee_benefit_deduction = sum(
                float(
                    x.employee_monthly_deduction or 0
                )
                for x in benefits
            )
        else:
            annual_benefit_cost = float(
                contract.medical_insurance_cost_annual
                or 0
            )
            employee_benefit_deduction = 0.0

        entry = HRPayrollEntry(
            cycle_id=cycle.id,
            employee_id=employee.id,
            contract_id=contract.id,
            basic_salary=float(
                contract.basic_salary or 0
            ),
            housing_allowance=float(
                contract.housing_allowance or 0
            ),
            transport_allowance=float(
                contract.transport_allowance or 0
            ),
            other_fixed_allowances=float(
                contract.other_fixed_allowances or 0
            ),
            overtime_amount=0,
            other_earnings=0,
            employee_gosi_deduction=0,
            other_deductions=(
                employee_benefit_deduction
            ),
            employer_gosi_cost=float(
                contract.employer_gosi_cost or 0
            ),
            benefit_cost_monthly=round(
                annual_benefit_cost / 12,
                2,
            ),
            entry_metadata={
                "source": "payroll_preview",
                "period_start":
                    first_day.isoformat(),
                "period_end":
                    last_day.isoformat(),
                "approved_overtime_records":
                    len(overtime_rows),
            },
        )

        _recalculate_payroll_entry(entry)

        db.add(entry)
        created += 1

    cycle.status = "preview"

    await write_audit_log(
        db,
        actor="system",
        action="hr.payroll.preview_generated",
        details={
            "cycle_id": str(cycle.id),
            "year": cycle.year,
            "month": cycle.month,
            "entries_created": created,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "entries_created": created,
    }


@app.get(
    "/api/hr/payroll/cycles/{cycle_id}/entries"
)
async def hr_list_payroll_entries(
    cycle_id: str,
    db: AsyncSession = Depends(get_db),
):
    cycle_uuid = uuid.UUID(cycle_id)

    result = await db.execute(
        select(HRPayrollCycle).where(
            HRPayrollCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll cycle not found",
        )

    result = await db.execute(
        select(
            HRPayrollEntry,
            HREmployee,
        )
        .join(
            HREmployee,
            HREmployee.id
            == HRPayrollEntry.employee_id,
        )
        .where(
            HRPayrollEntry.cycle_id == cycle.id
        )
        .order_by(
            HREmployee.employee_number.asc()
        )
    )

    rows = result.all()

    result = await db.execute(
        select(HRPayrollCycle)
        .where(
            (
                HRPayrollCycle.year
                < cycle.year
            )
            | (
                (
                    HRPayrollCycle.year
                    == cycle.year
                )
                & (
                    HRPayrollCycle.month
                    < cycle.month
                )
            )
        )
        .order_by(
            HRPayrollCycle.year.desc(),
            HRPayrollCycle.month.desc(),
        )
    )

    previous_cycle = result.scalars().first()

    previous_map = {}

    if previous_cycle:
        result = await db.execute(
            select(HRPayrollEntry).where(
                HRPayrollEntry.cycle_id
                == previous_cycle.id
            )
        )

        for previous in result.scalars().all():
            previous_map[
                previous.employee_id
            ] = previous

    output = []

    threshold = float(
        cycle.variance_threshold_pct
    )

    for entry, employee in rows:
        previous = previous_map.get(
            employee.id
        )

        previous_net = (
            float(previous.net_pay)
            if previous else None
        )

        current_net = float(entry.net_pay)

        variance_amount = (
            round(
                current_net - previous_net,
                2,
            )
            if previous_net is not None
            else None
        )

        variance_pct = None

        if (
            previous_net is not None
            and abs(previous_net) > 0.0001
        ):
            variance_pct = round(
                (
                    current_net - previous_net
                )
                / previous_net
                * 100,
                2,
            )

        variance_alert = bool(
            variance_pct is not None
            and abs(variance_pct) >= threshold
        )

        output.append({
            "id": str(entry.id),
            "employee_id": str(employee.id),
            "employee_number":
                employee.employee_number,
            "employee_name":
                employee.full_name_ar,
            "basic_salary":
                float(entry.basic_salary),
            "housing_allowance":
                float(entry.housing_allowance),
            "transport_allowance":
                float(entry.transport_allowance),
            "other_fixed_allowances":
                float(
                    entry.other_fixed_allowances
                ),
            "overtime_amount":
                float(entry.overtime_amount),
            "other_earnings":
                float(entry.other_earnings),
            "employee_gosi_deduction":
                float(
                    entry.employee_gosi_deduction
                ),
            "other_deductions":
                float(entry.other_deductions),
            "employer_gosi_cost":
                float(entry.employer_gosi_cost),
            "benefit_cost_monthly":
                float(entry.benefit_cost_monthly),
            "gross_pay":
                float(entry.gross_pay),
            "net_pay":
                current_net,
            "employer_total_cost":
                float(
                    entry.employer_total_cost
                ),
            "previous_net_pay":
                previous_net,
            "variance_amount":
                variance_amount,
            "variance_pct":
                variance_pct,
            "variance_alert":
                variance_alert,
        })

    totals = {
        "gross_pay": round(
            sum(x["gross_pay"] for x in output),
            2,
        ),
        "net_pay": round(
            sum(x["net_pay"] for x in output),
            2,
        ),
        "employer_total_cost": round(
            sum(
                x["employer_total_cost"]
                for x in output
            ),
            2,
        ),
        "overtime_amount": round(
            sum(
                x["overtime_amount"]
                for x in output
            ),
            2,
        ),
        "variance_alerts": sum(
            1
            for x in output
            if x["variance_alert"]
        ),
    }

    return {
        "cycle": {
            "id": str(cycle.id),
            "year": cycle.year,
            "month": cycle.month,
            "status": cycle.status,
            "variance_threshold_pct":
                threshold,
        },
        "totals": totals,
        "entries": output,
    }


@app.patch(
    "/api/hr/payroll/entries/{entry_id}"
)
async def hr_update_payroll_entry(
    entry_id: str,
    request: HRPayrollEntryUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    entry_uuid = uuid.UUID(entry_id)

    result = await db.execute(
        select(
            HRPayrollEntry,
            HRPayrollCycle,
        )
        .join(
            HRPayrollCycle,
            HRPayrollCycle.id
            == HRPayrollEntry.cycle_id,
        )
        .where(
            HRPayrollEntry.id == entry_uuid
        )
    )

    row = result.first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll entry not found",
        )

    entry, cycle = row

    if cycle.status not in {
        "draft",
        "preview",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll entry cannot be edited "
                "after approval workflow starts"
            ),
        )

    changes = request.model_dump(
        exclude_unset=True
    )

    before = {
        "employee_gosi_deduction":
            float(
                entry.employee_gosi_deduction
            ),
        "other_deductions":
            float(entry.other_deductions),
        "other_earnings":
            float(entry.other_earnings),
        "net_pay":
            float(entry.net_pay),
    }

    for field, value in changes.items():
        setattr(
            entry,
            field,
            max(0, float(value or 0)),
        )

    _recalculate_payroll_entry(entry)

    await write_audit_log(
        db,
        actor="user",
        action="hr.payroll.entry_updated",
        details={
            "entry_id": str(entry.id),
            "cycle_id": str(cycle.id),
            "employee_id":
                str(entry.employee_id),
            "before": before,
            "changed_fields":
                sorted(changes.keys()),
            "new_net_pay":
                float(entry.net_pay),
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "entry_id": str(entry.id),
        "net_pay": float(entry.net_pay),
    }


@app.post(
    "/api/hr/payroll/cycles/{cycle_id}/request-approval"
)
async def hr_request_payroll_approval(
    cycle_id: str,
    db: AsyncSession = Depends(get_db),
):
    cycle_uuid = uuid.UUID(cycle_id)

    result = await db.execute(
        select(HRPayrollCycle).where(
            HRPayrollCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll cycle not found",
        )

    result = await db.execute(
        select(HRPayrollEntry).where(
            HRPayrollEntry.cycle_id == cycle.id
        )
    )

    entries = result.scalars().all()

    if not entries:
        raise HTTPException(
            status_code=400,
            detail="Generate payroll preview first",
        )

    existing = await _latest_payroll_approval(
        db,
        cycle_id,
    )

    if existing and existing.status in {
        "pending",
        "approved",
    }:
        return {
            "status": "ok",
            "approval_id":
                str(existing.id),
            "approval_status":
                existing.status,
        }

    total_gross = round(
        sum(
            float(x.gross_pay)
            for x in entries
        ),
        2,
    )

    total_net = round(
        sum(
            float(x.net_pay)
            for x in entries
        ),
        2,
    )

    total_employer_cost = round(
        sum(
            float(x.employer_total_cost)
            for x in entries
        ),
        2,
    )

    result = await db.execute(
        select(Agent).where(
            Agent.slug == "hr"
        )
    )

    hr_agent = result.scalar_one_or_none()

    approval = Approval(
        agent_id=(
            hr_agent.id
            if hr_agent else None
        ),
        title=(
            f"اعتماد مسودة رواتب "
            f"{cycle.year}-{cycle.month:02d}"
        ),
        description=(
            f"إجمالي Gross {total_gross:,.2f} SAR، "
            f"إجمالي Net {total_net:,.2f} SAR، "
            f"إجمالي تكلفة صاحب العمل "
            f"{total_employer_cost:,.2f} SAR."
        ),
        action_type="hr_payroll_approval",
        risk_level="critical",
        status="pending",
        action_payload={
            "cycle_id": str(cycle.id),
            "year": cycle.year,
            "month": cycle.month,
            "employees": len(entries),
            "gross_pay": total_gross,
            "net_pay": total_net,
            "employer_total_cost":
                total_employer_cost,
            "requested_action": (
                "Approve internal payroll preview. "
                "Approval does NOT transfer money, "
                "submit a bank file, or execute payroll."
            ),
        },
    )

    db.add(approval)
    await db.flush()

    cycle.approval_id = approval.id
    cycle.status = "pending_approval"

    await write_audit_log(
        db,
        actor="user",
        action="hr.payroll.approval_requested",
        details={
            "cycle_id": str(cycle.id),
            "approval_id":
                str(approval.id),
            "year": cycle.year,
            "month": cycle.month,
            "employees": len(entries),
            "net_pay": total_net,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "approval_id": str(approval.id),
        "approval_status": "pending",
    }


@app.post(
    "/api/hr/payroll/cycles/{cycle_id}/close"
)
async def hr_close_payroll_cycle(
    cycle_id: str,
    db: AsyncSession = Depends(get_db),
):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    cycle_uuid = uuid.UUID(cycle_id)

    result = await db.execute(
        select(HRPayrollCycle).where(
            HRPayrollCycle.id == cycle_uuid
        )
    )

    cycle = result.scalar_one_or_none()

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll cycle not found",
        )

    if cycle.status == "closed":
        raise HTTPException(
            status_code=409,
            detail="Payroll cycle already closed",
        )

    approval = await _latest_payroll_approval(
        db,
        cycle_id,
    )

    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll cycle must be approved "
                "before closing"
            ),
        )

    cycle.status = "closed"
    cycle.closed_at = datetime.now(
        ZoneInfo("Asia/Riyadh")
    )

    await write_audit_log(
        db,
        actor="user",
        action="hr.payroll.cycle_closed",
        details={
            "cycle_id": str(cycle.id),
            "approval_id":
                str(approval.id),
            "year": cycle.year,
            "month": cycle.month,
            "external_payment_executed": False,
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "cycle_status": "closed",
        "payment_execution": "not_executed",
    }


@app.post("/api/hr/payroll/overtime")
async def hr_create_overtime_record(
    request: HROvertimeCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    employee_uuid = uuid.UUID(
        request.employee_id
    )

    result = await db.execute(
        select(HREmployee).where(
            HREmployee.id == employee_uuid
        )
    )

    employee = result.scalar_one_or_none()

    if employee is None:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    if request.hours <= 0:
        raise HTTPException(
            status_code=400,
            detail="Overtime hours must be greater than zero",
        )

    record = HROvertimeRecord(
        employee_id=employee.id,
        work_date=request.work_date,
        hours=request.hours,
        approved_amount=max(
            0,
            request.approved_amount,
        ),
        status="pending",
        notes=request.notes,
    )

    db.add(record)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.overtime.created",
        details={
            "overtime_id":
                str(record.id),
            "employee_id":
                str(employee.id),
            "employee_name":
                employee.full_name_ar,
            "work_date":
                record.work_date.isoformat(),
            "hours":
                float(record.hours),
            "proposed_amount":
                float(record.approved_amount),
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "id": str(record.id),
    }


