@app.get("/api/hr/payroll/summary")
async def hr_payroll_summary(
    db: AsyncSession = Depends(get_db),
):
    result = await db.execute(
        select(func.count())
        .select_from(HRPayrollCycle)
    )
    cycles = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRPayrollCycle)
        .where(
            HRPayrollCycle.status
            == "pending_approval"
        )
    )
    pending_cycles = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HROvertimeRecord)
        .where(
            HROvertimeRecord.status
            == "pending"
        )
    )
    pending_overtime = result.scalar_one()

    result = await db.execute(
        select(func.count())
        .select_from(HRBenefitEnrollment)
        .where(
            HRBenefitEnrollment.status
            == "active"
        )
    )
    active_benefits = result.scalar_one()

    result = await db.execute(
        select(HRPayrollCycle)
        .order_by(
            HRPayrollCycle.year.desc(),
            HRPayrollCycle.month.desc(),
        )
    )

    latest_cycle = result.scalars().first()

    latest_net = 0.0
    latest_employer_cost = 0.0

    if latest_cycle:
        result = await db.execute(
            select(HRPayrollEntry).where(
                HRPayrollEntry.cycle_id
                == latest_cycle.id
            )
        )

        latest_entries = result.scalars().all()

        latest_net = round(
            sum(
                float(x.net_pay)
                for x in latest_entries
            ),
            2,
        )

        latest_employer_cost = round(
            sum(
                float(
                    x.employer_total_cost
                )
                for x in latest_entries
            ),
            2,
        )

    return {
        "cycles": cycles,
        "pending_payroll_approvals":
            pending_cycles,
        "pending_overtime":
            pending_overtime,
        "active_benefits":
            active_benefits,
        "latest_cycle": (
            {
                "id": str(latest_cycle.id),
                "year": latest_cycle.year,
                "month": latest_cycle.month,
                "status": latest_cycle.status,
            }
            if latest_cycle else None
        ),
        "latest_net_pay":
            latest_net,
        "latest_employer_cost":
            latest_employer_cost,
    }


# ============================================================
# HR - Leave & Attendance API
# ============================================================

from datetime import timezone as _timezone
from decimal import Decimal as _Decimal


class HRLeaveTypeCreateRequest(BaseModel):
    code: str
    name_en: str
    name_ar: str | None = None
    annual_entitlement: float = 0
    is_paid: bool = True
    carry_forward_allowed: bool = False
    max_carry_forward_days: float = 0


class HRLeaveRequestCreateRequest(BaseModel):
    employee_id: uuid.UUID
    contract_id: uuid.UUID | None = None
    leave_type_id: uuid.UUID
    start_date: date
    end_date: date
    total_days: float | None = None
    reason: str | None = None
    attachment_url: str | None = None


class HRLeaveDecisionRequest(BaseModel):
    status: str
    approver_name: str | None = None
    decision_note: str | None = None


class HRAttendanceRecordRequest(BaseModel):
    employee_id: uuid.UUID
    contract_id: uuid.UUID | None = None
    work_date: date
    clock_in: datetime | None = None
    clock_out: datetime | None = None
    scheduled_hours: float = 8
    worked_hours: float = 0
    late_minutes: float = 0
    early_leave_minutes: float = 0
    overtime_hours: float = 0
    status: str = "present"
    source: str = "manual"
    notes: str | None = None


class HRAttendanceExceptionRequest(BaseModel):
    employee_id: uuid.UUID
    attendance_record_id: uuid.UUID | None = None
    exception_date: date
    exception_type: str
    minutes: float = 0
    reason: str | None = None


def _num(value):
    return float(value or 0)


def _dec(value):
    return _Decimal(str(value or 0))


def _leave_type_payload(row):
    return {
        "id": row.id,
        "code": row.code,
        "name_en": row.name_en,
        "name_ar": row.name_ar,
        "annual_entitlement": _num(row.annual_entitlement),
        "is_paid": row.is_paid,
        "carry_forward_allowed": row.carry_forward_allowed,
        "max_carry_forward_days": _num(row.max_carry_forward_days),
        "status": row.status,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _leave_balance_payload(row):
    available = (
        _num(row.entitlement_days)
        + _num(row.carried_forward_days)
        + _num(row.adjustment_days)
        - _num(row.used_days)
        - _num(row.pending_days)
    )
    return {
        "id": row.id,
        "employee_id": row.employee_id,
        "leave_type_id": row.leave_type_id,
        "balance_year": row.balance_year,
        "entitlement_days": _num(row.entitlement_days),
        "carried_forward_days": _num(row.carried_forward_days),
        "used_days": _num(row.used_days),
        "pending_days": _num(row.pending_days),
        "adjustment_days": _num(row.adjustment_days),
        "available_days": round(available, 2),
    }


def _leave_request_payload(row):
    return {
        "id": row.id,
        "employee_id": row.employee_id,
        "contract_id": row.contract_id,
        "leave_type_id": row.leave_type_id,
        "start_date": row.start_date,
        "end_date": row.end_date,
        "total_days": _num(row.total_days),
        "status": row.status,
        "reason": row.reason,
        "attachment_url": row.attachment_url,
        "approver_name": row.approver_name,
        "decision_note": row.decision_note,
        "requested_at": row.requested_at,
        "decided_at": row.decided_at,
    }


def _attendance_payload(row):
    return {
        "id": row.id,
        "employee_id": row.employee_id,
        "contract_id": row.contract_id,
        "work_date": row.work_date,
        "clock_in": row.clock_in,
        "clock_out": row.clock_out,
        "scheduled_hours": _num(row.scheduled_hours),
        "worked_hours": _num(row.worked_hours),
        "late_minutes": _num(row.late_minutes),
        "early_leave_minutes": _num(row.early_leave_minutes),
        "overtime_hours": _num(row.overtime_hours),
        "status": row.status,
        "source": row.source,
        "notes": row.notes,
    }


@app.post("/api/hr/leave/types")
async def create_hr_leave_type(
    payload: HRLeaveTypeCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip().upper()

    existing = (
        await db.execute(
            select(HRLeaveType).where(HRLeaveType.code == code)
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail="Leave type code already exists",
        )

    row = HRLeaveType(
        code=code,
        name_en=payload.name_en.strip(),
        name_ar=payload.name_ar.strip() if payload.name_ar else None,
        annual_entitlement=payload.annual_entitlement,
        is_paid=payload.is_paid,
        carry_forward_allowed=payload.carry_forward_allowed,
        max_carry_forward_days=payload.max_carry_forward_days,
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _leave_type_payload(row)


