@app.post("/api/hr/leave/requests")
async def create_hr_leave_request(
    payload: HRLeaveRequestCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.end_date < payload.start_date:
        raise HTTPException(
            status_code=400,
            detail="End date cannot be before start date",
        )

    employee = (
        await db.execute(
            select(HREmployee).where(HREmployee.id == payload.employee_id)
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(status_code=404, detail="Employee not found")

    leave_type = (
        await db.execute(
            select(HRLeaveType).where(HRLeaveType.id == payload.leave_type_id)
        )
    ).scalars().first()

    if not leave_type:
        raise HTTPException(status_code=404, detail="Leave type not found")

    if leave_type.status != "active":
        raise HTTPException(status_code=400, detail="Leave type is inactive")

    calculated_days = float(
        (payload.end_date - payload.start_date).days + 1
    )
    total_days = (
        float(payload.total_days)
        if payload.total_days is not None
        else calculated_days
    )

    if total_days <= 0:
        raise HTTPException(
            status_code=400,
            detail="Total leave days must be greater than zero",
        )

    balance_year = str(payload.start_date.year)

    balance = (
        await db.execute(
            select(HRLeaveBalance).where(
                HRLeaveBalance.employee_id == payload.employee_id,
                HRLeaveBalance.leave_type_id == payload.leave_type_id,
                HRLeaveBalance.balance_year == balance_year,
            )
        )
    ).scalars().first()

    if not balance:
        contract = await _active_contract_for_employee(
            db,
            payload.employee_id,
        )

        if not contract or not contract.start_date:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Employment contract with start date is required "
                    "to calculate annual leave entitlement"
                ),
            )

        prorated_entitlement = (
            _prorated_annual_leave_entitlement(
                _num(leave_type.annual_entitlement),
                payload.start_date.year,
                contract.start_date,
            )
        )

        balance = HRLeaveBalance(
            employee_id=payload.employee_id,
            leave_type_id=payload.leave_type_id,
            balance_year=balance_year,
            entitlement_days=prorated_entitlement,
            carried_forward_days=0,
            used_days=0,
            pending_days=0,
            adjustment_days=0,
        )
        db.add(balance)
        await db.flush()

    available = (
        _num(balance.entitlement_days)
        + _num(balance.carried_forward_days)
        + _num(balance.adjustment_days)
        - _num(balance.used_days)
        - _num(balance.pending_days)
    )

    balance_controlled = (
        _num(balance.entitlement_days)
        + _num(balance.carried_forward_days)
        + _num(balance.adjustment_days)
    ) > 0

    if balance_controlled and total_days > available:
        raise HTTPException(
            status_code=400,
            detail=f"Insufficient leave balance. Available: {available:.2f}",
        )

    row = HRLeaveRequest(
        employee_id=payload.employee_id,
        contract_id=payload.contract_id,
        leave_type_id=payload.leave_type_id,
        start_date=payload.start_date,
        end_date=payload.end_date,
        total_days=total_days,
        status="pending",
        reason=payload.reason,
        attachment_url=payload.attachment_url,
    )

    db.add(row)
    balance.pending_days = _dec(balance.pending_days) + _dec(total_days)

    await db.commit()
    await db.refresh(row)

    return _leave_request_payload(row)


