@app.put("/api/hr/leave/requests/{request_id}/decision")
async def decide_hr_leave_request(
    request_id: uuid.UUID,
    payload: HRLeaveDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    decision = payload.status.strip().lower()

    if decision not in {"approved", "rejected"}:
        raise HTTPException(
            status_code=400,
            detail="Status must be approved or rejected",
        )

    row = (
        await db.execute(
            select(HRLeaveRequest).where(HRLeaveRequest.id == request_id)
        )
    ).scalars().first()

    if not row:
        raise HTTPException(status_code=404, detail="Leave request not found")

    if row.status != "pending":
        raise HTTPException(
            status_code=409,
            detail="Leave request has already been decided",
        )

    balance = (
        await db.execute(
            select(HRLeaveBalance).where(
                HRLeaveBalance.employee_id == row.employee_id,
                HRLeaveBalance.leave_type_id == row.leave_type_id,
                HRLeaveBalance.balance_year == str(row.start_date.year),
            )
        )
    ).scalars().first()

    days = _dec(row.total_days)

    if balance:
        balance.pending_days = max(
            _Decimal("0"),
            _dec(balance.pending_days) - days,
        )

        if decision == "approved":
            balance.used_days = _dec(balance.used_days) + days

    row.status = decision
    row.approver_name = payload.approver_name
    row.decision_note = payload.decision_note
    row.decided_at = datetime.now(_timezone.utc)

    await db.commit()
    await db.refresh(row)

    return _leave_request_payload(row)


@app.post("/api/hr/attendance/records")
async def save_hr_attendance_record(
    payload: HRAttendanceRecordRequest,
    db: AsyncSession = Depends(get_db),
):
    employee = (
        await db.execute(
            select(HREmployee).where(HREmployee.id == payload.employee_id)
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(status_code=404, detail="Employee not found")

    row = (
        await db.execute(
            select(HRAttendanceRecord).where(
                HRAttendanceRecord.employee_id == payload.employee_id,
                HRAttendanceRecord.work_date == payload.work_date,
            )
        )
    ).scalars().first()

    values = {
        "contract_id": payload.contract_id,
        "clock_in": payload.clock_in,
        "clock_out": payload.clock_out,
        "scheduled_hours": payload.scheduled_hours,
        "worked_hours": payload.worked_hours,
        "late_minutes": payload.late_minutes,
        "early_leave_minutes": payload.early_leave_minutes,
        "overtime_hours": payload.overtime_hours,
        "status": payload.status,
        "source": payload.source,
        "notes": payload.notes,
    }

    if row:
        for key, value in values.items():
            setattr(row, key, value)
    else:
        row = HRAttendanceRecord(
            employee_id=payload.employee_id,
            work_date=payload.work_date,
            **values,
        )
        db.add(row)

    await db.commit()
    await db.refresh(row)

    return _attendance_payload(row)


