@app.put(
    "/api/hr/employee-payments/requests/{request_id}/overtime/final-decision"
)
async def overtime_final_decision(
    request_id: uuid.UUID,
    payload: HROvertimeStageDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    decision = payload.status.strip().lower()

    if decision not in {"approved", "rejected"}:
        raise HTTPException(
            status_code=400,
            detail="Status must be approved or rejected",
        )

    row = await _get_overtime_payment_request(db, request_id)

    if row.status != "pending":
        raise HTTPException(
            status_code=409,
            detail="Overtime request is no longer pending",
        )

    if row.manager_approval_status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Direct Manager approval is required first",
        )

    if row.ceo_approval_status != "approved":
        raise HTTPException(
            status_code=409,
            detail="CEO approval is required first",
        )

    if row.final_approval_status != "pending":
        raise HTTPException(
            status_code=409,
            detail="Final decision has already been recorded",
        )

    final_date = payload.decision_date or date.today()
    final_timestamp = _overtime_stage_timestamp(
        payload.decision_date
    )

    row.final_approval_status = decision
    row.final_approver_name = payload.approver_name
    row.final_approval_note = payload.approval_note
    row.final_approved_at = final_timestamp

    if decision == "rejected":
        row.status = "rejected"

        await db.commit()
        await db.refresh(row)

        return _employee_payment_payload(row)

    # Final approval is the financial receipt point.
    # Only now is the cutoff rule applied.
    cycle_month = _payment_cycle_month(final_date)

    batch = await _get_or_create_payment_batch(
        db,
        cycle_month,
    )

    row.batch_id = batch.id
    row.eligible_cycle_month = cycle_month
    row.status = "approved"

    row.approver_name = payload.approver_name
    row.approval_note = payload.approval_note
    row.approved_at = final_timestamp

    await db.flush()
    await _recalculate_payment_batch(db, batch.id)

    await db.commit()
    await db.refresh(row)

    return {
        **_employee_payment_payload(row),
        "cutoff_date": batch.cutoff_date,
        "due_date": batch.due_date,
        "rolled_to_next_cycle": final_date.day > 10,
        "cycle_based_on": "final_approval_date",
    }


# ============================================================
# HR - Annual Leave Year Policy
# 30 days/year by policy.
# New hires are prorated by actual calendar days in service.
# Standard carry forward max = 10 days.
# Exceptional carry forward above 10 days requires manual entry.
# ============================================================

class HRAnnualLeaveInitializeRequest(BaseModel):
    year: int
    leave_type_code: str = "ANNUAL"


class HRLeaveYearEndCarryForwardRequest(BaseModel):
    from_year: int
    leave_type_code: str = "ANNUAL"


class HRExceptionalCarryForwardRequest(BaseModel):
    employee_id: uuid.UUID
    leave_type_id: uuid.UUID
    from_year: int
    approved_carry_days: float
    reason: str
    approved_by: str
    approval_reference: str | None = None
    notes: str | None = None


def _leave_year_start(year: int) -> date:
    return date(year, 1, 1)


def _leave_year_end(year: int) -> date:
    return date(year, 12, 31)


def _days_in_leave_year(year: int) -> int:
    return (
        date(year + 1, 1, 1)
        - date(year, 1, 1)
    ).days


def _prorated_annual_leave_entitlement(
    annual_entitlement: float,
    year: int,
    employment_start: date,
) -> float:
    year_start = _leave_year_start(year)
    year_end = _leave_year_end(year)

    if employment_start > year_end:
        return 0.0

    if employment_start <= year_start:
        return round(float(annual_entitlement), 2)

    eligible_days = (
        year_end - employment_start
    ).days + 1

    entitlement = (
        float(annual_entitlement)
        * eligible_days
        / _days_in_leave_year(year)
    )

    return round(entitlement, 2)


def _leave_balance_available(row: HRLeaveBalance) -> float:
    return round(
        _num(row.entitlement_days)
        + _num(row.carried_forward_days)
        + _num(row.adjustment_days)
        - _num(row.used_days)
        - _num(row.pending_days),
        2,
    )


async def _active_contract_for_employee(
    db: AsyncSession,
    employee_id: uuid.UUID,
):
    result = await db.execute(
        select(HREmploymentContract)
        .where(
            HREmploymentContract.employee_id == employee_id,
        )
        .order_by(
            HREmploymentContract.start_date.desc(),
            HREmploymentContract.created_at.desc(),
        )
    )

    contracts = result.scalars().all()

    for contract in contracts:
        if getattr(contract, "status", None) == "active":
            return contract

    return contracts[0] if contracts else None


async def _get_leave_type_by_code(
    db: AsyncSession,
    code: str,
):
    return (
        await db.execute(
            select(HRLeaveType).where(
                HRLeaveType.code
                == code.strip().upper()
            )
        )
    ).scalars().first()


@app.post("/api/hr/leave/annual-initialize")
async def initialize_annual_leave_balances(
    payload: HRAnnualLeaveInitializeRequest,
    db: AsyncSession = Depends(get_db),
):
    year = payload.year

    if year < 2000 or year > 2200:
        raise HTTPException(
            status_code=400,
            detail="Invalid leave year",
        )

    leave_type = await _get_leave_type_by_code(
        db,
        payload.leave_type_code,
    )

    if not leave_type:
        raise HTTPException(
            status_code=404,
            detail="Leave type not found",
        )

    employees = (
        await db.execute(
            select(HREmployee)
        )
    ).scalars().all()

    created = 0
    updated = 0
    skipped = 0
    details = []

    for employee in employees:
        contract = await _active_contract_for_employee(
            db,
            employee.id,
        )

        if not contract or not contract.start_date:
            skipped += 1
            continue

        entitlement = _prorated_annual_leave_entitlement(
            _num(leave_type.annual_entitlement),
            year,
            contract.start_date,
        )

        if entitlement <= 0:
            skipped += 1
            continue

        existing = (
            await db.execute(
                select(HRLeaveBalance).where(
                    HRLeaveBalance.employee_id == employee.id,
                    HRLeaveBalance.leave_type_id == leave_type.id,
                    HRLeaveBalance.balance_year == str(year),
                )
            )
        ).scalars().first()

        if existing:
            # Idempotent annual initialization:
            # update entitlement only; never reset usage,
            # adjustments, pending or carry-forward.
            existing.entitlement_days = _dec(entitlement)
            updated += 1
            balance = existing
        else:
            balance = HRLeaveBalance(
                employee_id=employee.id,
                leave_type_id=leave_type.id,
                balance_year=str(year),
                entitlement_days=entitlement,
                carried_forward_days=0,
                used_days=0,
                pending_days=0,
                adjustment_days=0,
            )

            db.add(balance)
            created += 1

        details.append({
            "employee_id": str(employee.id),
            "employment_start": contract.start_date.isoformat(),
            "entitlement_days": entitlement,
        })

    await db.commit()

    return {
        "status": "ok",
        "year": year,
        "leave_type_code": leave_type.code,
        "annual_entitlement": _num(
            leave_type.annual_entitlement
        ),
        "calculation_method": "daily_proration",
        "created": created,
        "updated": updated,
        "skipped": skipped,
        "employees": details,
    }


@app.post("/api/hr/leave/year-end-carry-forward")
async def process_leave_year_end_carry_forward(
    payload: HRLeaveYearEndCarryForwardRequest,
    db: AsyncSession = Depends(get_db),
):
    from_year = payload.from_year
    to_year = from_year + 1

    leave_type = await _get_leave_type_by_code(
        db,
        payload.leave_type_code,
    )

    if not leave_type:
        raise HTTPException(
            status_code=404,
            detail="Leave type not found",
        )

    prior_balances = (
        await db.execute(
            select(HRLeaveBalance).where(
                HRLeaveBalance.leave_type_id == leave_type.id,
                HRLeaveBalance.balance_year == str(from_year),
            )
        )
    ).scalars().all()

    processed = 0
    details = []

    for prior in prior_balances:
        unused = max(
            0.0,
            _leave_balance_available(prior),
        )

        standard_carry = min(
            unused,
            10.0,
        )

        contract = await _active_contract_for_employee(
            db,
            prior.employee_id,
        )

        if not contract or not contract.start_date:
            continue

        entitlement = _prorated_annual_leave_entitlement(
            _num(leave_type.annual_entitlement),
            to_year,
            contract.start_date,
        )

        next_balance = (
            await db.execute(
                select(HRLeaveBalance).where(
                    HRLeaveBalance.employee_id == prior.employee_id,
                    HRLeaveBalance.leave_type_id == leave_type.id,
                    HRLeaveBalance.balance_year == str(to_year),
                )
            )
        ).scalars().first()

        if next_balance:
            next_balance.entitlement_days = _dec(entitlement)
            next_balance.carried_forward_days = _dec(
                standard_carry
            )
        else:
            next_balance = HRLeaveBalance(
                employee_id=prior.employee_id,
                leave_type_id=leave_type.id,
                balance_year=str(to_year),
                entitlement_days=entitlement,
                carried_forward_days=standard_carry,
                used_days=0,
                pending_days=0,
                adjustment_days=0,
            )

            db.add(next_balance)

        processed += 1

        details.append({
            "employee_id": str(prior.employee_id),
            "from_year": from_year,
            "to_year": to_year,
            "unused_days": round(unused, 2),
            "standard_carry_days": round(
                standard_carry,
                2,
            ),
            "new_year_entitlement": entitlement,
            "new_year_available": round(
                entitlement + standard_carry,
                2,
            ),
        })

    await db.commit()

    return {
        "status": "ok",
        "from_year": from_year,
        "to_year": to_year,
        "standard_carry_limit": 10,
        "processed": processed,
        "employees": details,
    }


@app.post("/api/hr/leave/carry-forward/exception")
async def create_exceptional_leave_carry_forward(
    payload: HRExceptionalCarryForwardRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.approved_carry_days <= 10:
        raise HTTPException(
            status_code=400,
            detail=(
                "Exceptional carry forward must be greater "
                "than the standard 10-day limit"
            ),
        )

    from_year = payload.from_year
    to_year = from_year + 1

    prior = (
        await db.execute(
            select(HRLeaveBalance).where(
                HRLeaveBalance.employee_id == payload.employee_id,
                HRLeaveBalance.leave_type_id == payload.leave_type_id,
                HRLeaveBalance.balance_year == str(from_year),
            )
        )
    ).scalars().first()

    if not prior:
        raise HTTPException(
            status_code=404,
            detail="Previous-year leave balance not found",
        )

    unused = max(
        0.0,
        _leave_balance_available(prior),
    )

    if payload.approved_carry_days > unused:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Approved carry forward cannot exceed "
                f"unused balance ({unused:.2f} days)"
            ),
        )

    next_balance = (
        await db.execute(
            select(HRLeaveBalance).where(
                HRLeaveBalance.employee_id == payload.employee_id,
                HRLeaveBalance.leave_type_id == payload.leave_type_id,
                HRLeaveBalance.balance_year == str(to_year),
            )
        )
    ).scalars().first()

    if not next_balance:
        raise HTTPException(
            status_code=409,
            detail=(
                "Initialize the next leave year before "
                "applying an exceptional carry forward"
            ),
        )

    override = HRLeaveCarryForwardOverride(
        employee_id=payload.employee_id,
        leave_type_id=payload.leave_type_id,
        from_year=str(from_year),
        to_year=str(to_year),
        unused_days_at_year_end=unused,
        standard_carry_limit=10,
        approved_carry_days=payload.approved_carry_days,
        reason=payload.reason.strip(),
        approved_by=payload.approved_by.strip(),
        approval_reference=(
            payload.approval_reference.strip()
            if payload.approval_reference
            else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(override)

    next_balance.carried_forward_days = _dec(
        payload.approved_carry_days
    )

    await db.commit()
    await db.refresh(override)

    return {
        "status": "ok",
        "override_id": override.id,
        "employee_id": payload.employee_id,
        "from_year": from_year,
        "to_year": to_year,
        "unused_days_at_year_end": round(unused, 2),
        "standard_limit": 10,
        "approved_carry_days": payload.approved_carry_days,
        "reason": override.reason,
        "approved_by": override.approved_by,
        "approval_reference": override.approval_reference,
    }


@app.get("/api/hr/leave/carry-forward/exceptions")
async def list_exceptional_leave_carry_forwards(
    employee_id: uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRLeaveCarryForwardOverride)

    if employee_id:
        query = query.where(
            HRLeaveCarryForwardOverride.employee_id
            == employee_id
        )

    rows = (
        await db.execute(
            query.order_by(
                HRLeaveCarryForwardOverride.created_at.desc()
            )
        )
    ).scalars().all()

    return [
        {
            "id": row.id,
            "employee_id": row.employee_id,
            "leave_type_id": row.leave_type_id,
            "from_year": row.from_year,
            "to_year": row.to_year,
            "unused_days_at_year_end": _num(
                row.unused_days_at_year_end
            ),
            "standard_carry_limit": _num(
                row.standard_carry_limit
            ),
            "approved_carry_days": _num(
                row.approved_carry_days
            ),
            "reason": row.reason,
            "approved_by": row.approved_by,
            "approval_reference": row.approval_reference,
            "notes": row.notes,
            "created_at": row.created_at,
        }
        for row in rows
    ]


# ============================================================
# HR - EOSB / Final Settlement
# Saudi Labor Law calculation engine
# ============================================================

class HRFinalSettlementCreateRequest(BaseModel):
    employee_id: uuid.UUID
    contract_id: uuid.UUID
    offboarding_plan_id: uuid.UUID | None = None

    last_working_day: date

    # employer / employee / mutual
    termination_initiator: str

    # employer_termination
    # resignation
    # article_80
    # article_81
    # force_majeure
    # mutual
    # contract_expiry
    # retirement
    # death
    # unlawful_termination
    # other
    termination_reason: str

    # Salary already paid through this date.
    # If omitted, system assumes salary was paid
    # through the end of the previous month.
    salary_paid_through: date | None = None

    # Article 77 is separate from EOSB.
    article_77_applies: bool = False

    # If the employment contract already specifies
    # a termination compensation, enter it here.
    article_77_contractual_amount: float | None = None

    # Notice compensation is kept explicit because
    # applicability depends on contract/notice circumstances.
    notice_compensation_amount: float = 0

    other_entitlements: float = 0
    deductions: float = 0

    calculation_notes: str | None = None


class HRFinalSettlementApprovalRequest(BaseModel):
    approved_by: str
    approval_note: str | None = None


class HRFinalSettlementPaidRequest(BaseModel):
    payment_reference: str | None = None


def _safe_anniversary(
    start: date,
    years: int,
) -> date:
    try:
        return start.replace(
            year=start.year + years
        )
    except ValueError:
        # 29-Feb anniversary in a non-leap year
        return date(
            start.year + years,
            2,
            28,
        )


def _service_year_segments(
    start_date: date,
    last_working_day: date,
):
    if last_working_day < start_date:
        raise HTTPException(
            status_code=400,
            detail=(
                "Last working day cannot be before "
                "employment start date"
            ),
        )

    end_exclusive = (
        last_working_day
        + _payment_timedelta(days=1)
    )

    segments = []
    year_index = 0
    cursor = start_date

    while cursor < end_exclusive:
        next_anniversary = _safe_anniversary(
            start_date,
            year_index + 1,
        )

        segment_end = min(
            next_anniversary,
            end_exclusive,
        )

        actual_days = (
            segment_end - cursor
        ).days

        full_service_year_days = (
            next_anniversary - cursor
        ).days

        fraction = (
            actual_days
            / full_service_year_days
            if full_service_year_days > 0
            else 0
        )

        segments.append({
            "service_year_index": year_index + 1,
            "fraction": fraction,
            "actual_days": actual_days,
        })

        cursor = segment_end
        year_index += 1

    return segments


def _calculate_full_eosb(
    wage_basis: float,
    start_date: date,
    last_working_day: date,
) -> float:
    total = 0.0

    for segment in _service_year_segments(
        start_date,
        last_working_day,
    ):
        multiplier = (
            0.5
            if segment["service_year_index"] <= 5
            else 1.0
        )

        total += (
            float(wage_basis)
            * multiplier
            * segment["fraction"]
        )

    return round(total, 2)


def _completed_service_years(
    start_date: date,
    last_working_day: date,
) -> int:
    # Service includes the employee's actual Last Working Day.
    # Use the following day as the exclusive service boundary
    # so 01-Jan-2020 through 31-Dec-2025 = 6 completed years.
    end_exclusive = (
        last_working_day
        + _payment_timedelta(days=1)
    )

    years = (
        end_exclusive.year
        - start_date.year
    )

    anniversary = _safe_anniversary(
        start_date,
        years,
    )

    if anniversary > end_exclusive:
        years -= 1

    return max(0, years)


def _eosb_entitlement_ratio(
    termination_reason: str,
    start_date: date,
    last_working_day: date,
) -> float:
    reason = termination_reason.strip().lower()

    # Article 80 termination may be without EOSB.
    if reason == "article_80":
        return 0.0

    # Full-right cases.
    if reason in {
        "article_81",
        "force_majeure",
        "employer_termination",
        "contract_expiry",
        "mutual",
        "retirement",
        "death",
        "unlawful_termination",
        "other",
    }:
        return 1.0

    if reason != "resignation":
        return 1.0

    completed_years = _completed_service_years(
        start_date,
        last_working_day,
    )

    # Saudi Labor Law Article 85.
    if completed_years < 2:
        return 0.0

    if completed_years <= 5:
        return 1.0 / 3.0

    if completed_years < 10:
        return 2.0 / 3.0

    return 1.0


def _current_year_leave_accrual_to_lwd(
    annual_entitlement: float,
    employment_start: date,
    last_working_day: date,
) -> float:
    year = last_working_day.year

    accrual_start = max(
        employment_start,
        date(year, 1, 1),
    )

    if accrual_start > last_working_day:
        return 0.0

    eligible_days = (
        last_working_day
        - accrual_start
    ).days + 1

    year_days = _days_in_leave_year(year)

    return round(
        float(annual_entitlement)
        * eligible_days
        / year_days,
        2,
    )


async def _approved_annual_leave_used_to_lwd(
    db: AsyncSession,
    employee_id: uuid.UUID,
    leave_type_id: uuid.UUID,
    year: int,
    last_working_day: date,
) -> float:
    year_start = date(year, 1, 1)

    rows = (
        await db.execute(
            select(HRLeaveRequest).where(
                HRLeaveRequest.employee_id
                    == employee_id,
                HRLeaveRequest.leave_type_id
                    == leave_type_id,
                HRLeaveRequest.status
                    == "approved",
                HRLeaveRequest.end_date
                    >= year_start,
                HRLeaveRequest.start_date
                    <= last_working_day,
            )
        )
    ).scalars().all()

    used = 0.0

    for row in rows:
        full_calendar_days = (
            row.end_date - row.start_date
        ).days + 1

        overlap_start = max(
            row.start_date,
            year_start,
        )

        overlap_end = min(
            row.end_date,
            last_working_day,
        )

        overlap_calendar_days = max(
            0,
            (overlap_end - overlap_start).days + 1,
        )

        if (
            full_calendar_days <= 0
            or overlap_calendar_days <= 0
        ):
            continue

        # Preserve half-day/custom leave totals proportionally
        # when a request crosses the settlement cutoff.
        ratio = (
            overlap_calendar_days
            / full_calendar_days
        )

        used += (
            _num(row.total_days)
            * ratio
        )

    return round(used, 2)


def _salary_due_period(
    last_working_day: date,
    salary_paid_through: date | None,
):
    if salary_paid_through is None:
        first_of_month = date(
            last_working_day.year,
            last_working_day.month,
            1,
        )

        due_start = first_of_month

    else:
        due_start = (
            salary_paid_through
            + _payment_timedelta(days=1)
        )

    if due_start > last_working_day:
        return None, None, 0

    due_days = (
        last_working_day
        - due_start
    ).days + 1

    return (
        due_start,
        last_working_day,
        due_days,
    )


def _article_77_amount(
    contract,
    wage_basis: float,
    start_date: date,
    last_working_day: date,
    contractual_amount: float | None,
) -> float:
    # If contract contains an agreed termination
    # compensation, that amount takes precedence.
    if contractual_amount is not None:
        return round(
            max(0.0, contractual_amount),
            2,
        )

    contract_type = str(
        getattr(contract, "contract_type", "")
        or ""
    ).strip().lower()

    minimum = float(wage_basis) * 2

    # Fixed-term contract:
    # remaining contract wage, min two months.
    if (
        "fixed" in contract_type
        or "محدد" in contract_type
    ):
        contract_end = getattr(
            contract,
            "end_date",
            None,
        )

        if (
            contract_end is None
            or contract_end <= last_working_day
        ):
            return round(minimum, 2)

        remaining_days = (
            contract_end
            - last_working_day
        ).days

        remaining_wage = (
            float(wage_basis)
            / 30.0
            * remaining_days
        )

        return round(
            max(
                minimum,
                remaining_wage,
            ),
            2,
        )

    # Indefinite-term:
    # 15 days' wage for every year of service,
    # min two months.
    service_factor = 0.0

    for segment in _service_year_segments(
        start_date,
        last_working_day,
    ):
        service_factor += (
            segment["fraction"]
        )

    statutory = (
        float(wage_basis)
        / 30.0
        * 15.0
        * service_factor
    )

    return round(
        max(
            minimum,
            statutory,
        ),
        2,
    )


