@app.post("/api/hr/final-settlements")
async def create_hr_final_settlement(
    payload: HRFinalSettlementCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    employee = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.id
                    == payload.employee_id
            )
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    contract = (
        await db.execute(
            select(HREmploymentContract).where(
                HREmploymentContract.id
                    == payload.contract_id,
                HREmploymentContract.employee_id
                    == payload.employee_id,
            )
        )
    ).scalars().first()

    if not contract:
        raise HTTPException(
            status_code=404,
            detail="Employment contract not found",
        )

    if not contract.start_date:
        raise HTTPException(
            status_code=409,
            detail=(
                "Employment contract start date "
                "is required"
            ),
        )

    if (
        payload.last_working_day
        < contract.start_date
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Last working day cannot be "
                "before employment start date"
            ),
        )

    initiator = (
        payload.termination_initiator
        .strip()
        .lower()
    )

    if initiator not in {
        "employer",
        "employee",
        "mutual",
    }:
        raise HTTPException(
            status_code=400,
            detail=(
                "termination_initiator must be "
                "employer, employee or mutual"
            ),
        )

    reason = (
        payload.termination_reason
        .strip()
        .lower()
    )

    valid_reasons = {
        "employer_termination",
        "resignation",
        "article_80",
        "article_81",
        "force_majeure",
        "mutual",
        "contract_expiry",
        "retirement",
        "death",
        "unlawful_termination",
        "other",
    }

    if reason not in valid_reasons:
        raise HTTPException(
            status_code=400,
            detail="Invalid termination reason",
        )

    # Snapshot final fixed wage.
    basic = _num(contract.basic_salary)

    housing = _num(
        contract.housing_allowance
    )

    transport = _num(
        contract.transport_allowance
    )

    other_fixed = _num(
        contract.other_fixed_allowances
    )

    wage_basis = round(
        basic
        + housing
        + transport
        + other_fixed,
        2,
    )

    service_start = contract.start_date
    lwd = payload.last_working_day

    service_days = (
        lwd - service_start
    ).days + 1

    full_eosb = _calculate_full_eosb(
        wage_basis,
        service_start,
        lwd,
    )

    eosb_ratio = _eosb_entitlement_ratio(
        reason,
        service_start,
        lwd,
    )

    eosb_amount = round(
        full_eosb * eosb_ratio,
        2,
    )

    # --------------------------------------------------------
    # Salary due
    # --------------------------------------------------------

    (
        salary_due_from,
        salary_due_to,
        salary_due_days,
    ) = _salary_due_period(
        lwd,
        payload.salary_paid_through,
    )

    salary_daily_rate = (
        wage_basis / 30.0
        if wage_basis > 0
        else 0.0
    )

    salary_due_amount = round(
        salary_daily_rate
        * salary_due_days,
        2,
    )

    # --------------------------------------------------------
    # Annual leave through LAST WORKING DAY ONLY.
    # Do not use the front-loaded 30-day balance as
    # payable current-year entitlement.
    # --------------------------------------------------------

    annual_type = await _get_leave_type_by_code(
        db,
        "ANNUAL",
    )

    leave_current_year_accrued = 0.0
    leave_carried_forward = 0.0
    leave_used_to_lwd = 0.0
    leave_adjustment = 0.0

    if annual_type:
        leave_current_year_accrued = (
            _current_year_leave_accrual_to_lwd(
                _num(
                    annual_type.annual_entitlement
                ),
                service_start,
                lwd,
            )
        )

        current_balance = (
            await db.execute(
                select(HRLeaveBalance).where(
                    HRLeaveBalance.employee_id
                        == employee.id,
                    HRLeaveBalance.leave_type_id
                        == annual_type.id,
                    HRLeaveBalance.balance_year
                        == str(lwd.year),
                )
            )
        ).scalars().first()

        if current_balance:
            leave_carried_forward = _num(
                current_balance
                .carried_forward_days
            )

            leave_adjustment = _num(
                current_balance
                .adjustment_days
            )

        leave_used_to_lwd = (
            await _approved_annual_leave_used_to_lwd(
                db,
                employee.id,
                annual_type.id,
                lwd.year,
                lwd,
            )
        )

    leave_payable_days = round(
        max(
            0.0,
            leave_current_year_accrued
            + leave_carried_forward
            + leave_adjustment
            - leave_used_to_lwd,
        ),
        2,
    )

    leave_daily_rate = round(
        wage_basis / 30.0
        if wage_basis > 0
        else 0.0,
        4,
    )

    leave_encashment = round(
        leave_payable_days
        * leave_daily_rate,
        2,
    )

    # --------------------------------------------------------
    # Article 77 compensation - separate from EOSB.
    # --------------------------------------------------------

    article_77_amount = 0.0

    if payload.article_77_applies:
        article_77_amount = (
            _article_77_amount(
                contract,
                wage_basis,
                service_start,
                lwd,
                payload.article_77_contractual_amount,
            )
        )

    notice_amount = round(
        max(
            0.0,
            payload.notice_compensation_amount,
        ),
        2,
    )

    other_entitlements = round(
        max(
            0.0,
            payload.other_entitlements,
        ),
        2,
    )

    deductions = round(
        max(
            0.0,
            payload.deductions,
        ),
        2,
    )

    gross_settlement = round(
        eosb_amount
        + salary_due_amount
        + leave_encashment
        + notice_amount
        + article_77_amount
        + other_entitlements,
        2,
    )

    net_settlement = round(
        gross_settlement
        - deductions,
        2,
    )

    # Article 88:
    # employee-initiated -> max 2 weeks.
    # otherwise -> max 1 week.
    statutory_due_date = (
        lwd
        + _payment_timedelta(
            days=14
            if initiator == "employee"
            else 7
        )
    )

    notes = []

    notes.append(
        "Annual leave payable recalculated "
        "through Last Working Day only."
    )

    if salary_due_from:
        notes.append(
            "Salary due period: "
            f"{salary_due_from.isoformat()} "
            f"to {salary_due_to.isoformat()}."
        )

    if payload.calculation_notes:
        notes.append(
            payload.calculation_notes.strip()
        )

    row = HRFinalSettlement(
        employee_id=employee.id,
        contract_id=contract.id,
        offboarding_plan_id=(
            payload.offboarding_plan_id
        ),
        status="draft",

        termination_initiator=initiator,
        termination_reason=reason,

        service_start_date=service_start,
        last_working_day=lwd,
        service_days=service_days,

        basic_salary=basic,
        housing_allowance=housing,
        transport_allowance=transport,
        other_fixed_allowances=other_fixed,
        eosb_wage_basis=wage_basis,

        eosb_full_amount=full_eosb,
        eosb_entitlement_ratio=eosb_ratio,
        eosb_amount=eosb_amount,

        salary_due_days=salary_due_days,
        salary_due_amount=salary_due_amount,

        leave_current_year_accrued=(
            leave_current_year_accrued
        ),
        leave_carried_forward=(
            leave_carried_forward
        ),
        leave_used_to_last_working_day=(
            leave_used_to_lwd
        ),
        leave_adjustment_days=(
            leave_adjustment
        ),
        leave_payable_days=(
            leave_payable_days
        ),
        leave_daily_rate=(
            leave_daily_rate
        ),
        leave_encashment_amount=(
            leave_encashment
        ),

        notice_compensation_amount=(
            notice_amount
        ),
        article_77_compensation_amount=(
            article_77_amount
        ),
        other_entitlements=(
            other_entitlements
        ),
        deductions=deductions,

        gross_settlement=(
            gross_settlement
        ),
        net_settlement=(
            net_settlement
        ),

        statutory_due_date=(
            statutory_due_date
        ),

        calculation_version=(
            "saudi_labor_2026_v1"
        ),

        calculation_notes=(
            "\n".join(notes)
        ),
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _final_settlement_payload(row)


@app.get("/api/hr/final-settlements")
async def list_hr_final_settlements(
    employee_id: uuid.UUID | None = None,
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRFinalSettlement)

    if employee_id:
        query = query.where(
            HRFinalSettlement.employee_id
                == employee_id
        )

    if status:
        query = query.where(
            HRFinalSettlement.status
                == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                HRFinalSettlement.created_at.desc()
            )
        )
    ).scalars().all()

    return [
        _final_settlement_payload(row)
        for row in rows
    ]


@app.get("/api/hr/final-settlements/{settlement_id}")
async def get_hr_final_settlement(
    settlement_id: uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRFinalSettlement).where(
                HRFinalSettlement.id
                    == settlement_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Final settlement not found",
        )

    return _final_settlement_payload(row)


@app.put(
    "/api/hr/final-settlements/{settlement_id}/approve"
)
async def approve_hr_final_settlement(
    settlement_id: uuid.UUID,
    payload: HRFinalSettlementApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRFinalSettlement).where(
                HRFinalSettlement.id
                    == settlement_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Final settlement not found",
        )

    if row.status != "draft":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only draft settlements "
                "can be approved"
            ),
        )

    row.status = "approved"
    row.approved_by = (
        payload.approved_by.strip()
    )
    row.approved_at = datetime.now(
        _timezone.utc
    )

    if payload.approval_note:
        existing = (
            row.calculation_notes or ""
        )

        row.calculation_notes = (
            existing
            + "\nApproval note: "
            + payload.approval_note.strip()
        ).strip()

    await db.commit()
    await db.refresh(row)

    return _final_settlement_payload(row)


@app.put(
    "/api/hr/final-settlements/{settlement_id}/paid"
)
async def mark_hr_final_settlement_paid(
    settlement_id: uuid.UUID,
    payload: HRFinalSettlementPaidRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRFinalSettlement).where(
                HRFinalSettlement.id
                    == settlement_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Final settlement not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only approved settlements "
                "can be marked as paid"
            ),
        )

    row.status = "paid"
    row.paid_at = datetime.now(
        _timezone.utc
    )
    row.payment_reference = (
        payload.payment_reference
    )

    await db.commit()
    await db.refresh(row)

    return _final_settlement_payload(row)


