@app.post("/api/hr/employee-relations/disciplinary-actions")
async def create_disciplinary_action(
    payload: HRDisciplinaryActionCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    action_type = payload.action_type.strip().lower()

    if action_type not in DISCIPLINARY_ACTION_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid disciplinary action type",
        )

    case = (
        await db.execute(
            select(HREmployeeRelationCase).where(
                HREmployeeRelationCase.id == payload.case_id
            )
        )
    ).scalars().first()

    if not case:
        raise HTTPException(
            status_code=404,
            detail="Employee relations case not found",
        )

    if case.status not in {"decision", "closed"}:
        raise HTTPException(
            status_code=409,
            detail=(
                "Record the case decision before issuing "
                "a disciplinary action"
            ),
        )

    row = HRDisciplinaryAction(
        case_id=case.id,
        employee_id=case.employee_id,
        action_type=action_type,
        action_date=payload.action_date,
        effective_date=payload.effective_date,
        expiry_date=payload.expiry_date,
        status="issued",
        reason=payload.reason.strip(),
        reference_number=(
            payload.reference_number.strip()
            if payload.reference_number
            else None
        ),
        issued_by=payload.issued_by.strip(),
        attachment_url=payload.attachment_url,
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.disciplinary.action_issued",
        details={
            "action_id": str(row.id),
            "case_id": str(row.case_id),
            "employee_id": str(row.employee_id),
            "action_type": row.action_type,
            "issued_by": row.issued_by,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _disciplinary_action_payload(row)


