@app.post("/api/hr/employee-relations/grievances")
async def create_grievance_appeal(
    payload: HRGrievanceCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    employee = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.id == payload.employee_id
            )
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    if payload.case_id:
        case = (
            await db.execute(
                select(HREmployeeRelationCase).where(
                    HREmployeeRelationCase.id == payload.case_id,
                    HREmployeeRelationCase.employee_id
                    == payload.employee_id,
                )
            )
        ).scalars().first()

        if not case:
            raise HTTPException(
                status_code=404,
                detail=(
                    "Related case not found for this employee"
                ),
            )

    row = HRGrievanceAppeal(
        employee_id=payload.employee_id,
        case_id=payload.case_id,
        submitted_date=(
            payload.submitted_date or date.today()
        ),
        subject=payload.subject.strip(),
        details=payload.details.strip(),
        status="pending",
        attachment_url=payload.attachment_url,
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.grievance.submitted",
        details={
            "grievance_id": str(row.id),
            "employee_id": str(row.employee_id),
            "case_id": (
                str(row.case_id)
                if row.case_id
                else None
            ),
            "subject": row.subject,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _grievance_payload(row)


