@app.put(
    "/api/hr/employee-relations/grievances/{grievance_id}/decision"
)
async def decide_grievance_appeal(
    grievance_id: uuid.UUID,
    payload: HRGrievanceDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    decision_status = payload.status.strip().lower()

    if decision_status not in {
        "accepted",
        "rejected",
    }:
        raise HTTPException(
            status_code=400,
            detail=(
                "Grievance status must be "
                "accepted or rejected"
            ),
        )

    row = (
        await db.execute(
            select(HRGrievanceAppeal).where(
                HRGrievanceAppeal.id == grievance_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Grievance not found",
        )

    if row.status != "pending":
        raise HTTPException(
            status_code=409,
            detail="Grievance has already been decided",
        )

    row.status = decision_status
    row.reviewed_by = payload.reviewed_by.strip()
    row.decision = payload.decision.strip()
    row.decided_at = datetime.now(_timezone.utc)

    await write_audit_log(
        db,
        actor=payload.actor,
        action="hr.grievance.decision_recorded",
        details={
            "grievance_id": str(row.id),
            "employee_id": str(row.employee_id),
            "status": row.status,
            "reviewed_by": row.reviewed_by,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _grievance_payload(row)


@app.get("/api/hr/employee-relations/summary")
async def employee_relations_summary(
    db: AsyncSession = Depends(get_db),
):
    cases = (
        await db.execute(
            select(HREmployeeRelationCase)
        )
    ).scalars().all()

    actions = (
        await db.execute(
            select(HRDisciplinaryAction)
        )
    ).scalars().all()

    grievances = (
        await db.execute(
            select(HRGrievanceAppeal)
        )
    ).scalars().all()

    return {
        "open_cases": sum(
            1 for row in cases
            if row.status == "open"
        ),
        "investigations": sum(
            1 for row in cases
            if row.status == "investigation"
        ),
        "cases_awaiting_closure": sum(
            1 for row in cases
            if row.status == "decision"
        ),
        "closed_cases": sum(
            1 for row in cases
            if row.status == "closed"
        ),
        "critical_cases": sum(
            1 for row in cases
            if row.severity == "critical"
            and row.status != "closed"
        ),
        "issued_disciplinary_actions": sum(
            1 for row in actions
            if row.status == "issued"
        ),
        "pending_grievances": sum(
            1 for row in grievances
            if row.status == "pending"
        ),
    }



