@app.get(
    "/api/hr/government-compliance/summary"
)
async def government_compliance_summary(
    db: AsyncSession = Depends(get_db),
):
    corporate_rows = (
        await db.execute(
            select(HRCorporateComplianceRecord)
        )
    ).scalars().all()

    employee_rows = (
        await db.execute(
            select(HREmployeeGovernmentDocument)
        )
    ).scalars().all()

    corporate = [
        _corporate_compliance_payload(row)
        for row in corporate_rows
    ]

    employee_docs = [
        _employee_government_document_payload(row)
        for row in employee_rows
    ]

    all_rows = corporate + employee_docs

    status_counts = {
        "active": 0,
        "renewal_due": 0,
        "escalation": 0,
        "expired": 0,
        "inactive": 0,
        "cancelled": 0,
    }

    for row in all_rows:
        status = row["status"]

        status_counts[status] = (
            status_counts.get(status, 0) + 1
        )

    upcoming_cost = round(
        sum(
            _num(row["renewal_cost"])
            for row in all_rows
            if row["status"] in {
                "renewal_due",
                "escalation",
                "expired",
            }
        ),
        2,
    )

    return {
        "corporate_records": len(corporate),
        "employee_documents": len(employee_docs),
        "total_records": len(all_rows),
        "active": status_counts.get("active", 0),
        "renewal_due": status_counts.get(
            "renewal_due",
            0,
        ),
        "escalation": status_counts.get(
            "escalation",
            0,
        ),
        "expired": status_counts.get(
            "expired",
            0,
        ),
        "inactive": status_counts.get(
            "inactive",
            0,
        ),
        "cancelled": status_counts.get(
            "cancelled",
            0,
        ),
        "upcoming_renewal_cost": upcoming_cost,
        "currency": "SAR",
    }



# ============================================================
# HR - Training & Development
# Operational / ad-hoc training only.
# No annual training plan in initial version.
# ============================================================

TRAINING_SESSION_STATUSES = {
    "requested",
    "approved",
    "scheduled",
    "in_progress",
    "completed",
    "cancelled",
}

TRAINING_ENROLLMENT_RESULTS = {
    "passed",
    "failed",
    "completed",
    "no_show",
}


class HRTrainingCourseCreateRequest(BaseModel):
    code: str
    title: str
    category: str = "professional"
    provider: str | None = None
    delivery_mode: str = "in_person"
    duration_hours: float = 0
    standard_cost: float = 0
    currency: str = "SAR"
    certification: bool = False
    certification_validity_months: int | None = None
    mandatory: bool = False
    description: str | None = None


class HRTrainingSessionCreateRequest(BaseModel):
    course_id: uuid.UUID
    request_source: str = "hr"
    requested_by: str | None = None
    request_date: date | None = None
    start_date: date | None = None
    end_date: date | None = None
    location: str | None = None
    provider: str | None = None
    delivery_mode: str = "in_person"
    capacity: int | None = None
    estimated_cost: float = 0
    currency: str = "SAR"
    notes: str | None = None


class HRTrainingSessionStatusRequest(BaseModel):
    status: str
    actual_cost: float | None = None
    notes: str | None = None


class HRTrainingEnrollmentCreateRequest(BaseModel):
    session_id: uuid.UUID
    employee_id: uuid.UUID
    nomination_source: str = "hr"
    employee_paid_amount: float = 0
    notes: str | None = None


class HRTrainingCompletionRequest(BaseModel):
    result: str
    attendance_pct: float = 100
    score: float | None = None
    completion_date: date | None = None

    certificate_number: str | None = None
    certificate_issue_date: date | None = None
    certificate_expiry_date: date | None = None

    notes: str | None = None


def _training_course_payload(row):
    return {
        "id": row.id,
        "code": row.code,
        "title": row.title,
        "category": row.category,
        "provider": row.provider,
        "delivery_mode": row.delivery_mode,
        "duration_hours": _num(row.duration_hours),
        "standard_cost": _num(row.standard_cost),
        "currency": row.currency,
        "certification": row.certification,
        "certification_validity_months":
            row.certification_validity_months,
        "mandatory": row.mandatory,
        "description": row.description,
        "status": row.status,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _training_session_payload(row):
    return {
        "id": row.id,
        "course_id": row.course_id,
        "request_source": row.request_source,
        "requested_by": row.requested_by,
        "request_date": row.request_date,
        "start_date": row.start_date,
        "end_date": row.end_date,
        "location": row.location,
        "provider": row.provider,
        "delivery_mode": row.delivery_mode,
        "capacity": row.capacity,
        "estimated_cost": _num(row.estimated_cost),
        "actual_cost": _num(row.actual_cost),
        "currency": row.currency,
        "status": row.status,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _training_enrollment_payload(row):
    return {
        "id": row.id,
        "session_id": row.session_id,
        "employee_id": row.employee_id,
        "nomination_source": row.nomination_source,
        "status": row.status,
        "attendance_pct": _num(row.attendance_pct),
        "result": row.result,
        "score": (
            _num(row.score)
            if row.score is not None
            else None
        ),
        "completion_date": row.completion_date,
        "certificate_number":
            row.certificate_number,
        "certificate_issue_date":
            row.certificate_issue_date,
        "certificate_expiry_date":
            row.certificate_expiry_date,
        "employee_paid_amount":
            _num(row.employee_paid_amount),
        "reimbursement_eligible":
            row.reimbursement_eligible,
        "reimbursement_amount":
            _num(row.reimbursement_amount),
        "reimbursement_status":
            row.reimbursement_status,
        "reimbursement_payment_request_id":
            row.reimbursement_payment_request_id,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


@app.post("/api/hr/training/courses")
async def create_training_course(
    payload: HRTrainingCourseCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip().upper()

    existing = (
        await db.execute(
            select(HRTrainingCourse).where(
                HRTrainingCourse.code == code
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail="Training course code already exists",
        )

    if payload.duration_hours < 0:
        raise HTTPException(
            status_code=400,
            detail="Duration hours cannot be negative",
        )

    if payload.standard_cost < 0:
        raise HTTPException(
            status_code=400,
            detail="Standard cost cannot be negative",
        )

    row = HRTrainingCourse(
        code=code,
        title=payload.title.strip(),
        category=payload.category.strip().lower(),
        provider=(
            payload.provider.strip()
            if payload.provider
            else None
        ),
        delivery_mode=payload.delivery_mode.strip().lower(),
        duration_hours=payload.duration_hours,
        standard_cost=payload.standard_cost,
        currency=payload.currency.strip().upper(),
        certification=payload.certification,
        certification_validity_months=(
            payload.certification_validity_months
        ),
        mandatory=payload.mandatory,
        description=(
            payload.description.strip()
            if payload.description
            else None
        ),
        status="active",
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.training.course_created",
        details={
            "course_id": str(row.id),
            "code": row.code,
            "title": row.title,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _training_course_payload(row)


