@app.post("/api/hr/training/sessions")
async def create_training_session(
    payload: HRTrainingSessionCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    course = (
        await db.execute(
            select(HRTrainingCourse).where(
                HRTrainingCourse.id
                == payload.course_id
            )
        )
    ).scalars().first()

    if not course:
        raise HTTPException(
            status_code=404,
            detail="Training course not found",
        )

    if course.status != "active":
        raise HTTPException(
            status_code=409,
            detail="Training course is inactive",
        )

    if (
        payload.start_date
        and payload.end_date
        and payload.end_date < payload.start_date
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Training end date cannot be "
                "before start date"
            ),
        )

    row = HRTrainingSession(
        course_id=course.id,
        request_source=(
            payload.request_source.strip().lower()
        ),
        requested_by=(
            payload.requested_by.strip()
            if payload.requested_by
            else None
        ),
        request_date=(
            payload.request_date or date.today()
        ),
        start_date=payload.start_date,
        end_date=payload.end_date,
        location=(
            payload.location.strip()
            if payload.location
            else None
        ),
        provider=(
            payload.provider.strip()
            if payload.provider
            else course.provider
        ),
        delivery_mode=(
            payload.delivery_mode.strip().lower()
        ),
        capacity=payload.capacity,
        estimated_cost=max(
            0,
            payload.estimated_cost,
        ),
        actual_cost=0,
        currency=payload.currency.strip().upper(),
        status="requested",
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.training.session_created",
        details={
            "session_id": str(row.id),
            "course_id": str(row.course_id),
            "request_source":
                row.request_source,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _training_session_payload(row)


