@app.post("/api/hr/talent/critical-positions")
async def create_critical_position(
    payload: HRCriticalPositionCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    position = (
        await db.execute(
            select(HRPosition).where(
                HRPosition.id
                == payload.position_id
            )
        )
    ).scalars().first()

    if not position:
        raise HTTPException(
            status_code=404,
            detail="HR Position not found",
        )

    existing = (
        await db.execute(
            select(HRCriticalPosition).where(
                HRCriticalPosition.position_id
                == payload.position_id
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "Position is already registered "
                "as a critical position"
            ),
        )

    if payload.target_successors < 1:
        raise HTTPException(
            status_code=400,
            detail=(
                "Target successors must be "
                "at least 1"
            ),
        )

    row = HRCriticalPosition(
        position_id=position.id,
        criticality_level=(
            payload.criticality_level
            .strip()
            .lower()
        ),
        vacancy_risk=(
            payload.vacancy_risk
            .strip()
            .lower()
        ),
        business_impact=(
            payload.business_impact
            .strip()
            .lower()
        ),
        succession_required=(
            payload.succession_required
        ),
        target_successors=(
            payload.target_successors
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
        status="active",
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.talent.critical_position_created",
        details={
            "critical_position_id":
                str(row.id),
            "position_id":
                str(position.id),
            "position_code":
                position.code,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _critical_position_payload(row)


