@app.put("/api/hr/talent/profiles")
async def upsert_talent_profile(
    payload: HRTalentProfileUpsertRequest,
    db: AsyncSession = Depends(get_db),
):
    if (
        payload.potential_score < 0
        or payload.potential_score > 100
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Potential score must be "
                "between 0 and 100"
            ),
        )

    employee = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.id
                == payload.employee_id
            )
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    row = (
        await db.execute(
            select(HRTalentProfile).where(
                HRTalentProfile.employee_id
                == employee.id
            )
        )
    ).scalars().first()

    potential_level = _potential_band(
        payload.potential_score
    )

    high_potential = (
        potential_level == "high"
    )

    values = {
        "potential_score":
            payload.potential_score,
        "potential_level":
            potential_level,
        "high_potential":
            high_potential,
        "talent_pool": (
            payload.talent_pool.strip()
            if payload.talent_pool
            else None
        ),
        "retention_risk": (
            payload.retention_risk
            .strip()
            .lower()
        ),
        "mobility": (
            payload.mobility.strip()
            if payload.mobility
            else None
        ),
        "career_aspiration": (
            payload.career_aspiration.strip()
            if payload.career_aspiration
            else None
        ),
        "strengths": (
            payload.strengths.strip()
            if payload.strengths
            else None
        ),
        "development_gaps": (
            payload.development_gaps.strip()
            if payload.development_gaps
            else None
        ),
        "development_actions": (
            payload.development_actions.strip()
            if payload.development_actions
            else None
        ),
        "assessed_by": (
            payload.assessed_by.strip()
            if payload.assessed_by
            else None
        ),
        "assessment_date": (
            payload.assessment_date
            or date.today()
        ),
        "notes": (
            payload.notes.strip()
            if payload.notes
            else None
        ),
    }

    if row:
        for key, value in values.items():
            setattr(row, key, value)
    else:
        row = HRTalentProfile(
            employee_id=employee.id,
            **values,
        )

        db.add(row)

    await db.flush()

    # Refresh active succession candidates
    # with the latest Potential score.
    candidates = (
        await db.execute(
            select(HRSuccessionCandidate).where(
                HRSuccessionCandidate.employee_id
                    == employee.id,
                HRSuccessionCandidate.status
                    == "active",
            )
        )
    ).scalars().all()

    for candidate in candidates:
        candidate.potential_score = (
            payload.potential_score
        )

        candidate.nine_box = (
            _nine_box_label(
                candidate.performance_score,
                payload.potential_score,
            )
        )

        candidate.last_review_date = (
            date.today()
        )

    await write_audit_log(
        db,
        actor="user",
        action="hr.talent.profile_updated",
        details={
            "employee_id":
                str(employee.id),
            "potential_score":
                payload.potential_score,
            "potential_level":
                potential_level,
            "high_potential":
                high_potential,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _talent_profile_payload(row)


