@app.post("/api/hr/talent/successors")
async def create_successor_candidate(
    payload: HRSuccessionCandidateCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    readiness = (
        payload.readiness
        .strip()
        .lower()
    )

    if readiness not in SUCCESSION_READINESS:
        raise HTTPException(
            status_code=400,
            detail=(
                "Readiness must be ready_now, "
                "1_2_years or 3_plus_years"
            ),
        )

    critical = (
        await db.execute(
            select(HRCriticalPosition).where(
                HRCriticalPosition.id
                == payload.critical_position_id
            )
        )
    ).scalars().first()

    if not critical:
        raise HTTPException(
            status_code=404,
            detail="Critical position not found",
        )

    employee = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.id
                == payload.employee_id
            )
        )
    ).scalars().first()

    if not employee:
        raise HTTPException(
            status_code=404,
            detail="Employee not found",
        )

    existing = (
        await db.execute(
            select(HRSuccessionCandidate).where(
                HRSuccessionCandidate
                    .critical_position_id
                    == critical.id,
                HRSuccessionCandidate
                    .employee_id
                    == employee.id,
                HRSuccessionCandidate.status
                    == "active",
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "Employee is already an active "
                "successor for this position"
            ),
        )

    performance_plan = (
        await _latest_completed_performance_plan(
            db,
            employee.id,
        )
    )

    performance_score = (
        _num(performance_plan.final_score)
        if performance_plan
        and performance_plan.final_score
        is not None
        else None
    )

    talent_profile = (
        await db.execute(
            select(HRTalentProfile).where(
                HRTalentProfile.employee_id
                == employee.id
            )
        )
    ).scalars().first()

    potential_score = (
        _num(talent_profile.potential_score)
        if talent_profile
        and talent_profile.potential_score
        is not None
        else None
    )

    nine_box = _nine_box_label(
        performance_score,
        potential_score,
    )

    row = HRSuccessionCandidate(
        critical_position_id=critical.id,
        employee_id=employee.id,
        performance_plan_id=(
            performance_plan.id
            if performance_plan
            else None
        ),
        performance_score=(
            performance_score
        ),
        potential_score=(
            potential_score
        ),
        nine_box=nine_box,
        readiness=readiness,
        candidate_rank=(
            payload.candidate_rank
        ),
        nomination_reason=(
            payload.nomination_reason.strip()
            if payload.nomination_reason
            else None
        ),
        development_gaps=(
            payload.development_gaps.strip()
            if payload.development_gaps
            else (
                talent_profile.development_gaps
                if talent_profile
                else None
            )
        ),
        development_actions=(
            payload.development_actions.strip()
            if payload.development_actions
            else (
                talent_profile.development_actions
                if talent_profile
                else None
            )
        ),
        status="active",
        nominated_by=(
            payload.nominated_by.strip()
            if payload.nominated_by
            else None
        ),
        nomination_date=(
            payload.nomination_date
            or date.today()
        ),
        last_review_date=(
            date.today()
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.talent.successor_nominated",
        details={
            "candidate_id":
                str(row.id),
            "critical_position_id":
                str(critical.id),
            "employee_id":
                str(employee.id),
            "performance_score":
                performance_score,
            "potential_score":
                potential_score,
            "nine_box":
                nine_box,
            "readiness":
                readiness,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _succession_candidate_payload(row)


@app.get("/api/hr/talent/successors")
async def list_successor_candidates(
    critical_position_id: uuid.UUID | None = None,
    employee_id: uuid.UUID | None = None,
    readiness: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRSuccessionCandidate)

    if critical_position_id:
        query = query.where(
            HRSuccessionCandidate
                .critical_position_id
                == critical_position_id
        )

    if employee_id:
        query = query.where(
            HRSuccessionCandidate.employee_id
            == employee_id
        )

    if readiness:
        query = query.where(
            HRSuccessionCandidate.readiness
            == readiness.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                HRSuccessionCandidate
                    .critical_position_id.asc(),
                HRSuccessionCandidate
                    .candidate_rank.asc()
                    .nullslast(),
                HRSuccessionCandidate
                    .created_at.desc(),
            )
        )
    ).scalars().all()

    return [
        _succession_candidate_payload(row)
        for row in rows
    ]


@app.put(
    "/api/hr/talent/successors/{candidate_id}"
)
async def update_successor_candidate(
    candidate_id: uuid.UUID,
    payload: HRSuccessionCandidateUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRSuccessionCandidate).where(
                HRSuccessionCandidate.id
                == candidate_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Successor candidate not found",
        )

    if payload.readiness is not None:
        readiness = (
            payload.readiness
            .strip()
            .lower()
        )

        if readiness not in SUCCESSION_READINESS:
            raise HTTPException(
                status_code=400,
                detail="Invalid readiness",
            )

        row.readiness = readiness

    if payload.candidate_rank is not None:
        row.candidate_rank = (
            payload.candidate_rank
        )

    if payload.nomination_reason is not None:
        row.nomination_reason = (
            payload.nomination_reason.strip()
            or None
        )

    if payload.development_gaps is not None:
        row.development_gaps = (
            payload.development_gaps.strip()
            or None
        )

    if payload.development_actions is not None:
        row.development_actions = (
            payload.development_actions.strip()
            or None
        )

    if payload.status is not None:
        row.status = (
            payload.status.strip().lower()
        )

    if payload.notes is not None:
        row.notes = (
            payload.notes.strip() or None
        )

    if payload.refresh_scores:
        performance_plan = (
            await _latest_completed_performance_plan(
                db,
                row.employee_id,
            )
        )

        talent_profile = (
            await db.execute(
                select(HRTalentProfile).where(
                    HRTalentProfile.employee_id
                    == row.employee_id
                )
            )
        ).scalars().first()

        row.performance_plan_id = (
            performance_plan.id
            if performance_plan
            else None
        )

        row.performance_score = (
            _dec(performance_plan.final_score)
            if performance_plan
            and performance_plan.final_score
            is not None
            else None
        )

        row.potential_score = (
            _dec(talent_profile.potential_score)
            if talent_profile
            and talent_profile.potential_score
            is not None
            else None
        )

        row.nine_box = (
            _nine_box_label(
                row.performance_score,
                row.potential_score,
            )
        )

    row.last_review_date = date.today()

    await write_audit_log(
        db,
        actor="user",
        action="hr.talent.successor_updated",
        details={
            "candidate_id":
                str(row.id),
            "employee_id":
                str(row.employee_id),
            "readiness":
                row.readiness,
            "candidate_rank":
                row.candidate_rank,
            "nine_box":
                row.nine_box,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _succession_candidate_payload(row)


@app.get("/api/hr/talent/summary")
async def succession_talent_summary(
    db: AsyncSession = Depends(get_db),
):
    critical_positions = (
        await db.execute(
            select(HRCriticalPosition)
        )
    ).scalars().all()

    talent_profiles = (
        await db.execute(
            select(HRTalentProfile)
        )
    ).scalars().all()

    candidates = (
        await db.execute(
            select(HRSuccessionCandidate)
        )
    ).scalars().all()

    active_critical = [
        row for row in critical_positions
        if row.status == "active"
    ]

    active_candidates = [
        row for row in candidates
        if row.status == "active"
    ]

    covered_position_ids = {
        row.critical_position_id
        for row in active_candidates
    }

    positions_with_ready_now = {
        row.critical_position_id
        for row in active_candidates
        if row.readiness == "ready_now"
    }

    succession_gaps = sum(
        1
        for position in active_critical
        if position.succession_required
        and position.id
        not in covered_position_ids
    )

    return {
        "critical_positions":
            len(active_critical),
        "succession_gaps":
            succession_gaps,
        "positions_with_successor":
            len(covered_position_ids),
        "positions_with_ready_now":
            len(positions_with_ready_now),
        "successor_candidates":
            len(active_candidates),
        "ready_now_candidates": sum(
            1
            for row in active_candidates
            if row.readiness
            == "ready_now"
        ),
        "high_potentials": sum(
            1
            for row in talent_profiles
            if row.high_potential
        ),
        "top_talent": sum(
            1
            for row in active_candidates
            if row.nine_box
            == "top_talent"
        ),
    }



# ============================================================
# HR - Workforce Planning & Manpower
# Reuses Departments, Positions and Employee Master Data.
# ============================================================

WORKFORCE_PLAN_STATUSES = {
    "draft",
    "submitted",
    "approved",
    "frozen",
    "closed",
}

WORKFORCE_HIRE_TYPES = {
    "replacement",
    "new_hire",
    "expansion",
}

WORKFORCE_BUDGET_SCENARIOS = {
    "min",
    "mid",
    "max",
}


class HRWorkforcePlanCreateRequest(BaseModel):
    year: int
    name: str
    version: int = 1
    created_by: str | None = None
    notes: str | None = None


class HRWorkforcePlanStatusRequest(BaseModel):
    status: str
    actor: str
    notes: str | None = None


class HRWorkforcePlanLineCreateRequest(BaseModel):
    plan_id: uuid.UUID
    department_id: uuid.UUID
    position_id: uuid.UUID | None = None

    is_new_position: bool = False

    proposed_position_code: str | None = None
    proposed_position_title: str | None = None
    proposed_grade: str | None = None
    proposed_employment_type: str | None = None

    hire_type: str = "new_hire"
    replacement_employee_id: uuid.UUID | None = None

    approved_headcount: int
    planned_hires: int = 0
    planned_exits: int = 0

    priority: str = "medium"
    target_hiring_date: date | None = None

    # Used only for a completely new proposed position.
    min_salary: float | None = None
    mid_salary: float | None = None
    max_salary: float | None = None

    budget_scenario: str = "mid"

    justification: str | None = None
    notes: str | None = None


class HRWorkforcePlanLineUpdateRequest(BaseModel):
    approved_headcount: int | None = None
    planned_hires: int | None = None
    planned_exits: int | None = None

    priority: str | None = None
    target_hiring_date: date | None = None

    budget_scenario: str | None = None

    min_salary: float | None = None
    mid_salary: float | None = None
    max_salary: float | None = None

    hire_type: str | None = None
    replacement_employee_id: uuid.UUID | None = None

    justification: str | None = None
    notes: str | None = None
    status: str | None = None


async def _position_current_headcount(
    db: AsyncSession,
    position_id: uuid.UUID,
) -> int:
    rows = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.position_id == position_id,
                HREmployee.employment_status == "active",
            )
        )
    ).scalars().all()

    return len(rows)


async def _department_current_headcount(
    db: AsyncSession,
    department_id: uuid.UUID,
) -> int:
    rows = (
        await db.execute(
            select(HREmployee).where(
                HREmployee.department_id == department_id,
                HREmployee.employment_status == "active",
            )
        )
    ).scalars().all()

    return len(rows)


def _workforce_budget_salary(
    min_salary: float,
    mid_salary: float,
    max_salary: float,
    scenario: str,
) -> float:
    if scenario == "min":
        return round(min_salary, 2)

    if scenario == "max":
        return round(max_salary, 2)

    return round(mid_salary, 2)


def _workforce_line_payload(row):
    current = int(row.current_headcount_snapshot or 0)
    approved = int(row.approved_headcount or 0)
    hires = int(row.planned_hires or 0)
    exits = int(row.planned_exits or 0)

    vacancy = max(
        0,
        approved - current,
    )

    projected_headcount = max(
        0,
        current + hires - exits,
    )

    variance_to_approved = (
        projected_headcount - approved
    )

    return {
        "id": row.id,
        "plan_id": row.plan_id,
        "department_id": row.department_id,
        "position_id": row.position_id,

        "is_new_position": row.is_new_position,
        "proposed_position_code":
            row.proposed_position_code,
        "proposed_position_title":
            row.proposed_position_title,
        "proposed_grade":
            row.proposed_grade,
        "proposed_employment_type":
            row.proposed_employment_type,

        "hire_type": row.hire_type,
        "replacement_employee_id":
            row.replacement_employee_id,

        "current_headcount":
            current,
        "approved_headcount":
            approved,
        "vacancy":
            vacancy,

        "planned_hires":
            hires,
        "planned_exits":
            exits,
        "projected_headcount":
            projected_headcount,
        "variance_to_approved":
            variance_to_approved,

        "priority": row.priority,
        "target_hiring_date":
            row.target_hiring_date,

        "min_salary":
            _num(row.min_salary_snapshot),
        "mid_salary":
            _num(row.mid_salary_snapshot),
        "max_salary":
            _num(row.max_salary_snapshot),

        "budget_scenario":
            row.budget_scenario,
        "budgeted_monthly_salary":
            _num(row.budgeted_monthly_salary),
        "budgeted_annual_salary":
            _num(row.budgeted_annual_salary),

        "justification":
            row.justification,
        "notes":
            row.notes,
        "status":
            row.status,

        "created_at":
            row.created_at,
        "updated_at":
            row.updated_at,
    }


def _workforce_plan_payload(row):
    return {
        "id": row.id,
        "year": row.year,
        "name": row.name,
        "version": row.version,
        "status": row.status,

        "created_by":
            row.created_by,

        "submitted_by":
            row.submitted_by,
        "submitted_at":
            row.submitted_at,

        "approved_by":
            row.approved_by,
        "approved_at":
            row.approved_at,

        "frozen_at":
            row.frozen_at,

        "notes":
            row.notes,

        "created_at":
            row.created_at,
        "updated_at":
            row.updated_at,
    }


@app.post("/api/hr/workforce-plans")
async def create_workforce_plan(
    payload: HRWorkforcePlanCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.year < 2000 or payload.year > 2200:
        raise HTTPException(
            status_code=400,
            detail="Invalid workforce plan year",
        )

    if payload.version < 1:
        raise HTTPException(
            status_code=400,
            detail="Plan version must be at least 1",
        )

    existing = (
        await db.execute(
            select(HRWorkforcePlan).where(
                HRWorkforcePlan.year == payload.year,
                HRWorkforcePlan.version == payload.version,
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "A workforce plan with the same "
                "year and version already exists"
            ),
        )

    row = HRWorkforcePlan(
        year=payload.year,
        name=payload.name.strip(),
        version=payload.version,
        status="draft",
        created_by=(
            payload.created_by.strip()
            if payload.created_by
            else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.workforce.plan_created",
        details={
            "plan_id": str(row.id),
            "year": row.year,
            "version": row.version,
            "name": row.name,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _workforce_plan_payload(row)


@app.get("/api/hr/workforce-plans")
async def list_workforce_plans(
    year: int | None = None,
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRWorkforcePlan)

    if year is not None:
        query = query.where(
            HRWorkforcePlan.year == year
        )

    if status:
        query = query.where(
            HRWorkforcePlan.status
            == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                HRWorkforcePlan.year.desc(),
                HRWorkforcePlan.version.desc(),
                HRWorkforcePlan.created_at.desc(),
            )
        )
    ).scalars().all()

    return [
        _workforce_plan_payload(row)
        for row in rows
    ]


@app.put("/api/hr/workforce-plans/{plan_id}/status")
async def update_workforce_plan_status(
    plan_id: uuid.UUID,
    payload: HRWorkforcePlanStatusRequest,
    db: AsyncSession = Depends(get_db),
):
    status = payload.status.strip().lower()

    if status not in WORKFORCE_PLAN_STATUSES:
        raise HTTPException(
            status_code=400,
            detail="Invalid workforce plan status",
        )

    row = (
        await db.execute(
            select(HRWorkforcePlan).where(
                HRWorkforcePlan.id == plan_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Workforce plan not found",
        )

    current = row.status

    allowed = {
        "draft": {"submitted"},
        "submitted": {"draft", "approved"},
        "approved": {"frozen", "closed"},
        "frozen": {"approved", "closed"},
        "closed": set(),
    }

    if status != current and status not in allowed.get(current, set()):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Invalid workforce plan transition: "
                f"{current} -> {status}"
            ),
        )

    row.status = status
    actor = payload.actor.strip()

    now = datetime.now(_timezone.utc)

    if status == "submitted":
        row.submitted_by = actor
        row.submitted_at = now

    elif status == "approved":
        row.approved_by = actor
        row.approved_at = now

    elif status == "frozen":
        row.frozen_at = now

    if payload.notes:
        existing = row.notes or ""
        row.notes = (
            existing
            + "\n"
            + payload.notes.strip()
        ).strip()

    await write_audit_log(
        db,
        actor=actor,
        action="hr.workforce.plan_status_updated",
        details={
            "plan_id": str(row.id),
            "from_status": current,
            "to_status": status,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _workforce_plan_payload(row)


@app.post("/api/hr/workforce-plan-lines")
async def create_workforce_plan_line(
    payload: HRWorkforcePlanLineCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    plan = (
        await db.execute(
            select(HRWorkforcePlan).where(
                HRWorkforcePlan.id
                == payload.plan_id
            )
        )
    ).scalars().first()

    if not plan:
        raise HTTPException(
            status_code=404,
            detail="Workforce plan not found",
        )

    if plan.status not in {"draft", "submitted"}:
        raise HTTPException(
            status_code=409,
            detail=(
                "Workforce plan lines can only be "
                "changed while plan is draft or submitted"
            ),
        )

    department = (
        await db.execute(
            select(HRDepartment).where(
                HRDepartment.id
                == payload.department_id
            )
        )
    ).scalars().first()

    if not department:
        raise HTTPException(
            status_code=404,
            detail="HR Department not found",
        )

    hire_type = payload.hire_type.strip().lower()

    if hire_type not in WORKFORCE_HIRE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid hire type",
        )

    scenario = (
        payload.budget_scenario
        .strip()
        .lower()
    )

    if scenario not in WORKFORCE_BUDGET_SCENARIOS:
        raise HTTPException(
            status_code=400,
            detail="Invalid budget scenario",
        )

    if (
        payload.approved_headcount < 0
        or payload.planned_hires < 0
        or payload.planned_exits < 0
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Headcount and planning values "
                "cannot be negative"
            ),
        )

    position = None

    if payload.is_new_position:
        if payload.position_id is not None:
            raise HTTPException(
                status_code=400,
                detail=(
                    "New position request cannot reference "
                    "an existing position_id"
                ),
            )

        if not payload.proposed_position_title:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Proposed position title is required "
                    "for a new position"
                ),
            )

        min_salary = float(
            payload.min_salary or 0
        )

        mid_salary = float(
            payload.mid_salary or 0
        )

        max_salary = float(
            payload.max_salary or 0
        )

        current_headcount = 0

    else:
        if payload.position_id is None:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Existing position_id is required "
                    "unless this is a new position"
                ),
            )

        position = (
            await db.execute(
                select(HRPosition).where(
                    HRPosition.id
                    == payload.position_id
                )
            )
        ).scalars().first()

        if not position:
            raise HTTPException(
                status_code=404,
                detail="HR Position not found",
            )

        if (
            position.department_id
            and position.department_id
            != payload.department_id
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "Selected position does not belong "
                    "to the selected department"
                ),
            )

        min_salary = _num(
            position.min_salary
        )

        mid_salary = _num(
            position.mid_salary
        )

        max_salary = _num(
            position.max_salary
        )

        current_headcount = (
            await _position_current_headcount(
                db,
                position.id,
            )
        )

        duplicate = (
            await db.execute(
                select(HRWorkforcePlanLine).where(
                    HRWorkforcePlanLine.plan_id
                        == plan.id,
                    HRWorkforcePlanLine.position_id
                        == position.id,
                    HRWorkforcePlanLine.status
                        == "active",
                )
            )
        ).scalars().first()

        if duplicate:
            raise HTTPException(
                status_code=409,
                detail=(
                    "An active workforce plan line already "
                    "exists for this position"
                ),
            )

    if min_salary < 0 or mid_salary < 0 or max_salary < 0:
        raise HTTPException(
            status_code=400,
            detail="Salary ranges cannot be negative",
        )

    if max_salary and min_salary and max_salary < min_salary:
        raise HTTPException(
            status_code=400,
            detail="Max salary cannot be below min salary",
        )

    selected_monthly_salary = (
        _workforce_budget_salary(
            min_salary,
            mid_salary,
            max_salary,
            scenario,
        )
    )

    annual_budget = round(
        selected_monthly_salary
        * 12
        * int(payload.planned_hires),
        2,
    )

    row = HRWorkforcePlanLine(
        plan_id=plan.id,
        department_id=department.id,
        position_id=(
            position.id
            if position
            else None
        ),

        is_new_position=(
            payload.is_new_position
        ),

        proposed_position_code=(
            payload.proposed_position_code.strip()
            if payload.proposed_position_code
            else None
        ),

        proposed_position_title=(
            payload.proposed_position_title.strip()
            if payload.proposed_position_title
            else None
        ),

        proposed_grade=(
            payload.proposed_grade.strip()
            if payload.proposed_grade
            else None
        ),

        proposed_employment_type=(
            payload.proposed_employment_type.strip()
            if payload.proposed_employment_type
            else None
        ),

        hire_type=hire_type,

        replacement_employee_id=(
            payload.replacement_employee_id
        ),

        current_headcount_snapshot=(
            current_headcount
        ),

        approved_headcount=(
            payload.approved_headcount
        ),

        planned_hires=(
            payload.planned_hires
        ),

        planned_exits=(
            payload.planned_exits
        ),

        priority=(
            payload.priority.strip().lower()
        ),

        target_hiring_date=(
            payload.target_hiring_date
        ),

        min_salary_snapshot=min_salary,
        mid_salary_snapshot=mid_salary,
        max_salary_snapshot=max_salary,

        budget_scenario=scenario,

        budgeted_monthly_salary=(
            selected_monthly_salary
        ),

        budgeted_annual_salary=(
            annual_budget
        ),

        justification=(
            payload.justification.strip()
            if payload.justification
            else None
        ),

        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),

        status="active",
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.workforce.plan_line_created",
        details={
            "line_id": str(row.id),
            "plan_id": str(row.plan_id),
            "department_id":
                str(row.department_id),
            "position_id": (
                str(row.position_id)
                if row.position_id
                else None
            ),
            "is_new_position":
                row.is_new_position,
            "current_headcount":
                row.current_headcount_snapshot,
            "approved_headcount":
                row.approved_headcount,
            "planned_hires":
                row.planned_hires,
            "budget_scenario":
                row.budget_scenario,
            "annual_budget":
                _num(
                    row.budgeted_annual_salary
                ),
        },
    )

    await db.commit()
    await db.refresh(row)

    return _workforce_line_payload(row)


@app.get("/api/hr/workforce-plan-lines")
async def list_workforce_plan_lines(
    plan_id: uuid.UUID | None = None,
    department_id: uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRWorkforcePlanLine)

    if plan_id:
        query = query.where(
            HRWorkforcePlanLine.plan_id
            == plan_id
        )

    if department_id:
        query = query.where(
            HRWorkforcePlanLine.department_id
            == department_id
        )

    rows = (
        await db.execute(
            query.order_by(
                HRWorkforcePlanLine.priority.asc(),
                HRWorkforcePlanLine.created_at.desc(),
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        # Refresh actual headcount at read-time for
        # existing positions, while preserving the snapshot
        # on the database record for historical comparison.
        data = _workforce_line_payload(row)

        if row.position_id:
            actual_now = (
                await _position_current_headcount(
                    db,
                    row.position_id,
                )
            )

            data["actual_headcount_now"] = (
                actual_now
            )

            data["actual_vs_snapshot"] = (
                actual_now
                - row.current_headcount_snapshot
            )

            data["current_vacancy_now"] = max(
                0,
                int(row.approved_headcount or 0)
                - actual_now,
            )
        else:
            data["actual_headcount_now"] = 0
            data["actual_vs_snapshot"] = 0
            data["current_vacancy_now"] = (
                max(
                    0,
                    int(
                        row.approved_headcount
                        or 0
                    ),
                )
            )

        output.append(data)

    return output


@app.put(
    "/api/hr/workforce-plan-lines/{line_id}"
)
async def update_workforce_plan_line(
    line_id: uuid.UUID,
    payload: HRWorkforcePlanLineUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRWorkforcePlanLine).where(
                HRWorkforcePlanLine.id
                == line_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Workforce plan line not found",
        )

    plan = (
        await db.execute(
            select(HRWorkforcePlan).where(
                HRWorkforcePlan.id
                == row.plan_id
            )
        )
    ).scalars().first()

    if not plan:
        raise HTTPException(
            status_code=404,
            detail="Workforce plan not found",
        )

    if plan.status not in {
        "draft",
        "submitted",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved/frozen/closed plans "
                "cannot be edited"
            ),
        )

    values = payload.model_dump(
        exclude_unset=True
    )

    if "hire_type" in values:
        hire_type = (
            values["hire_type"]
            .strip()
            .lower()
        )

        if hire_type not in WORKFORCE_HIRE_TYPES:
            raise HTTPException(
                status_code=400,
                detail="Invalid hire type",
            )

        row.hire_type = hire_type

    if "approved_headcount" in values:
        if values["approved_headcount"] < 0:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Approved headcount "
                    "cannot be negative"
                ),
            )

        row.approved_headcount = (
            values["approved_headcount"]
        )

    if "planned_hires" in values:
        if values["planned_hires"] < 0:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Planned hires cannot "
                    "be negative"
                ),
            )

        row.planned_hires = (
            values["planned_hires"]
        )

    if "planned_exits" in values:
        if values["planned_exits"] < 0:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Planned exits cannot "
                    "be negative"
                ),
            )

        row.planned_exits = (
            values["planned_exits"]
        )

    if "priority" in values:
        row.priority = (
            values["priority"]
            .strip()
            .lower()
        )

    if "target_hiring_date" in values:
        row.target_hiring_date = (
            values["target_hiring_date"]
        )

    if "replacement_employee_id" in values:
        row.replacement_employee_id = (
            values[
                "replacement_employee_id"
            ]
        )

    if "justification" in values:
        value = values["justification"]

        row.justification = (
            value.strip()
            if value
            else None
        )

    if "notes" in values:
        value = values["notes"]

        row.notes = (
            value.strip()
            if value
            else None
        )

    if "status" in values:
        row.status = (
            values["status"]
            .strip()
            .lower()
        )

    min_salary = _num(
        row.min_salary_snapshot
    )

    mid_salary = _num(
        row.mid_salary_snapshot
    )

    max_salary = _num(
        row.max_salary_snapshot
    )

    if row.is_new_position:
        if values.get("min_salary") is not None:
            min_salary = float(
                values["min_salary"]
            )

        if values.get("mid_salary") is not None:
            mid_salary = float(
                values["mid_salary"]
            )

        if values.get("max_salary") is not None:
            max_salary = float(
                values["max_salary"]
            )

        row.min_salary_snapshot = (
            min_salary
        )
        row.mid_salary_snapshot = (
            mid_salary
        )
        row.max_salary_snapshot = (
            max_salary
        )

    if "budget_scenario" in values:
        scenario = (
            values["budget_scenario"]
            .strip()
            .lower()
        )

        if scenario not in WORKFORCE_BUDGET_SCENARIOS:
            raise HTTPException(
                status_code=400,
                detail="Invalid budget scenario",
            )

        row.budget_scenario = scenario

    selected_monthly_salary = (
        _workforce_budget_salary(
            min_salary,
            mid_salary,
            max_salary,
            row.budget_scenario,
        )
    )

    row.budgeted_monthly_salary = (
        selected_monthly_salary
    )

    row.budgeted_annual_salary = round(
        selected_monthly_salary
        * 12
        * int(row.planned_hires or 0),
        2,
    )

    # Refresh current HC snapshot while plan is editable.
    if row.position_id:
        row.current_headcount_snapshot = (
            await _position_current_headcount(
                db,
                row.position_id,
            )
        )

    await write_audit_log(
        db,
        actor="user",
        action="hr.workforce.plan_line_updated",
        details={
            "line_id": str(row.id),
            "plan_id": str(row.plan_id),
            "approved_headcount":
                row.approved_headcount,
            "planned_hires":
                row.planned_hires,
            "planned_exits":
                row.planned_exits,
            "budget_scenario":
                row.budget_scenario,
            "annual_budget":
                _num(
                    row.budgeted_annual_salary
                ),
        },
    )

    await db.commit()
    await db.refresh(row)

    return _workforce_line_payload(row)


@app.get("/api/hr/workforce-planning/summary")
async def workforce_planning_summary(
    plan_id: uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    plan = None

    if plan_id:
        plan = (
            await db.execute(
                select(HRWorkforcePlan).where(
                    HRWorkforcePlan.id
                    == plan_id
                )
            )
        ).scalars().first()

        if not plan:
            raise HTTPException(
                status_code=404,
                detail="Workforce plan not found",
            )

    else:
        plan = (
            await db.execute(
                select(HRWorkforcePlan)
                .order_by(
                    HRWorkforcePlan.year.desc(),
                    HRWorkforcePlan.version.desc(),
                    HRWorkforcePlan.created_at.desc(),
                )
            )
        ).scalars().first()

    if not plan:
        return {
            "plan": None,
            "lines": 0,
            "current_headcount": 0,
            "approved_headcount": 0,
            "planned_hires": 0,
            "planned_exits": 0,
            "vacancies": 0,
            "projected_headcount": 0,
            "new_positions": 0,
            "replacement_hires": 0,
            "annual_hiring_budget": 0,
            "budget_scenario": "mixed",
            "department_summary": [],
        }

    rows = (
        await db.execute(
            select(HRWorkforcePlanLine).where(
                HRWorkforcePlanLine.plan_id
                == plan.id,
                HRWorkforcePlanLine.status
                == "active",
            )
        )
    ).scalars().all()

    total_current = 0
    total_approved = 0
    total_hires = 0
    total_exits = 0
    total_vacancies = 0
    total_budget = 0.0

    department_data = {}

    for row in rows:
        if row.position_id:
            current = (
                await _position_current_headcount(
                    db,
                    row.position_id,
                )
            )
        else:
            current = 0

        approved = int(
            row.approved_headcount or 0
        )

        hires = int(
            row.planned_hires or 0
        )

        exits = int(
            row.planned_exits or 0
        )

        vacancy = max(
            0,
            approved - current,
        )

        projected = max(
            0,
            current + hires - exits,
        )

        budget = _num(
            row.budgeted_annual_salary
        )

        total_current += current
        total_approved += approved
        total_hires += hires
        total_exits += exits
        total_vacancies += vacancy
        total_budget += budget

        key = str(row.department_id)

        if key not in department_data:
            department_data[key] = {
                "department_id":
                    row.department_id,
                "current_headcount": 0,
                "approved_headcount": 0,
                "planned_hires": 0,
                "planned_exits": 0,
                "vacancies": 0,
                "projected_headcount": 0,
                "annual_hiring_budget": 0.0,
            }

        item = department_data[key]

        item["current_headcount"] += (
            current
        )

        item["approved_headcount"] += (
            approved
        )

        item["planned_hires"] += hires
        item["planned_exits"] += exits
        item["vacancies"] += vacancy
        item["projected_headcount"] += (
            projected
        )
        item["annual_hiring_budget"] += (
            budget
        )

    department_summary = []

    for item in department_data.values():
        item["annual_hiring_budget"] = round(
            item["annual_hiring_budget"],
            2,
        )

        department_summary.append(item)

    return {
        "plan": _workforce_plan_payload(
            plan
        ),

        "lines": len(rows),

        "current_headcount":
            total_current,

        "approved_headcount":
            total_approved,

        "planned_hires":
            total_hires,

        "planned_exits":
            total_exits,

        "vacancies":
            total_vacancies,

        "projected_headcount":
            max(
                0,
                total_current
                + total_hires
                - total_exits,
            ),

        "new_positions": sum(
            1
            for row in rows
            if row.is_new_position
        ),

        "replacement_hires": sum(
            int(row.planned_hires or 0)
            for row in rows
            if row.hire_type
            == "replacement"
        ),

        "annual_hiring_budget": round(
            total_budget,
            2,
        ),

        "budget_scenario": "mixed",

        "department_summary":
            department_summary,
    }



# ============================================================
# HR - Cost Forecast
# Dynamic forecast based on:
# Active employees/contracts + Benefits + Workforce Plan.
# ============================================================

def _forecast_planned_hire_cost(
    monthly_salary: float,
    employer_gosi_ratio: float,
    annual_benefit_per_employee: float,
    annual_other_cost_per_employee: float,
):
    monthly_salary = max(
        0.0,
        float(monthly_salary or 0),
    )

    annual_salary = monthly_salary * 12.0

    annual_employer_gosi = (
        annual_salary
        * max(
            0.0,
            float(employer_gosi_ratio or 0),
        )
    )

    annual_benefits = max(
        0.0,
        float(
            annual_benefit_per_employee
            or 0
        ),
    )

    annual_other = max(
        0.0,
        float(
            annual_other_cost_per_employee
            or 0
        ),
    )

    total = (
        annual_salary
        + annual_employer_gosi
        + annual_benefits
        + annual_other
    )

    return {
        "annual_salary": round(
            annual_salary,
            2,
        ),
        "annual_employer_gosi": round(
            annual_employer_gosi,
            2,
        ),
        "annual_benefits": round(
            annual_benefits,
            2,
        ),
        "annual_other_cost": round(
            annual_other,
            2,
        ),
        "annual_total_cost": round(
            total,
            2,
        ),
    }


def _forecast_cost_summary():
    return {
        "annual_salary": 0.0,
        "annual_employer_gosi": 0.0,
        "annual_benefits": 0.0,
        "annual_other_cost": 0.0,
        "annual_total_cost": 0.0,
    }


def _forecast_add_cost(
    target: dict,
    source: dict,
    multiplier: float = 1.0,
):
    for key in (
        "annual_salary",
        "annual_employer_gosi",
        "annual_benefits",
        "annual_other_cost",
        "annual_total_cost",
    ):
        target[key] = round(
            float(target.get(key, 0) or 0)
            + (
                float(
                    source.get(key, 0)
                    or 0
                )
                * multiplier
            ),
            2,
        )


def _forecast_variance(
    current_total: float,
    projected_total: float,
):
    amount = round(
        projected_total - current_total,
        2,
    )

    pct = (
        round(
            amount
            / current_total
            * 100,
            2,
        )
        if current_total > 0
        else None
    )

    return amount, pct


@app.get("/api/hr/cost-forecast")
async def hr_cost_forecast(
    plan_id: uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    today = date.today()

    # --------------------------------------------------------
    # Employee Master Data
    # --------------------------------------------------------

    employees = (
        await db.execute(
            select(HREmployee)
        )
    ).scalars().all()

    employee_map = {
        row.id: row
        for row in employees
    }

    # --------------------------------------------------------
    # Active contracts
    # Select latest active contract per employee.
    # --------------------------------------------------------

    contracts = (
        await db.execute(
            select(HREmploymentContract)
            .where(
                HREmploymentContract.status
                == "active"
            )
            .order_by(
                HREmploymentContract.employee_id.asc(),
                HREmploymentContract.start_date.desc(),
                HREmploymentContract.created_at.desc(),
            )
        )
    ).scalars().all()

    contract_by_employee = {}

    for contract in contracts:
        if (
            contract.employee_id
            not in contract_by_employee
        ):
            contract_by_employee[
                contract.employee_id
            ] = contract

    # --------------------------------------------------------
    # Active Benefits.
    # Benefits module is source of truth.
    # Legacy contract medical insurance is fallback only.
    # --------------------------------------------------------

    benefits = (
        await db.execute(
            select(HRBenefitEnrollment).where(
                HRBenefitEnrollment.status
                == "active"
            )
        )
    ).scalars().all()

    benefit_cost_by_employee = {}

    for benefit in benefits:
        if (
            benefit.start_date
            and benefit.start_date > today
        ):
            continue

        if (
            benefit.end_date
            and benefit.end_date < today
        ):
            continue

        employee_id = benefit.employee_id

        benefit_cost_by_employee[
            employee_id
        ] = round(
            benefit_cost_by_employee.get(
                employee_id,
                0.0,
            )
            + _num(
                benefit.annual_employer_cost
            ),
            2,
        )

    # --------------------------------------------------------
    # Current annual workforce cost.
    # --------------------------------------------------------

    current = _forecast_cost_summary()

    department_current = {}
    position_current_costs = {}

    active_employee_count = 0

    for employee_id, contract in (
        contract_by_employee.items()
    ):
        employee = employee_map.get(
            employee_id
        )

        if not employee:
            continue

        if (
            employee.employment_status
            != "active"
        ):
            continue

        monthly_cash = round(
            _num(contract.basic_salary)
            + _num(
                contract.housing_allowance
            )
            + _num(
                contract.transport_allowance
            )
            + _num(
                contract.other_fixed_allowances
            ),
            2,
        )

        annual_salary = round(
            monthly_cash * 12,
            2,
        )

        annual_gosi = round(
            _num(
                contract.employer_gosi_cost
            )
            * 12,
            2,
        )

        benefit_cost = (
            benefit_cost_by_employee.get(
                employee_id,
                0.0,
            )
        )

        # Avoid double counting:
        # legacy medical cost is used only
        # when the Benefits module has no
        # active benefit cost for employee.
        if benefit_cost <= 0:
            benefit_cost = _num(
                contract
                .medical_insurance_cost_annual
            )

        other_annual = _num(
            contract.other_annual_cost
        )

        employee_cost = {
            "annual_salary":
                annual_salary,
            "annual_employer_gosi":
                annual_gosi,
            "annual_benefits":
                round(
                    benefit_cost,
                    2,
                ),
            "annual_other_cost":
                round(
                    other_annual,
                    2,
                ),
        }

        employee_cost[
            "annual_total_cost"
        ] = round(
            annual_salary
            + annual_gosi
            + benefit_cost
            + other_annual,
            2,
        )

        _forecast_add_cost(
            current,
            employee_cost,
        )

        active_employee_count += 1

        department_id = (
            employee.department_id
        )

        if department_id:
            dept_key = str(
                department_id
            )

            if dept_key not in department_current:
                department_current[
                    dept_key
                ] = {
                    "department_id":
                        department_id,
                    "employees": 0,
                    **_forecast_cost_summary(),
                }

            department_current[
                dept_key
            ]["employees"] += 1

            _forecast_add_cost(
                department_current[
                    dept_key
                ],
                employee_cost,
            )

        position_id = employee.position_id

        if position_id:
            pos_key = str(position_id)

            if (
                pos_key
                not in position_current_costs
            ):
                position_current_costs[
                    pos_key
                ] = {
                    "position_id":
                        position_id,
                    "employees": 0,
                    "total_cost": 0.0,
                }

            position_current_costs[
                pos_key
            ]["employees"] += 1

            position_current_costs[
                pos_key
            ]["total_cost"] = round(
                position_current_costs[
                    pos_key
                ]["total_cost"]
                + employee_cost[
                    "annual_total_cost"
                ],
                2,
            )

    # --------------------------------------------------------
    # Company-level assumptions for planned hires.
    # --------------------------------------------------------

    company_gosi_ratio = (
        current["annual_employer_gosi"]
        / current["annual_salary"]
        if current["annual_salary"] > 0
        else 0.0
    )

    company_avg_benefit = (
        current["annual_benefits"]
        / active_employee_count
        if active_employee_count > 0
        else 0.0
    )

    company_avg_other = (
        current["annual_other_cost"]
        / active_employee_count
        if active_employee_count > 0
        else 0.0
    )

    company_avg_total_cost = (
        current["annual_total_cost"]
        / active_employee_count
        if active_employee_count > 0
        else 0.0
    )

    # Department assumptions.
    department_assumptions = {}

    for key, item in department_current.items():
        employees_count = int(
            item["employees"] or 0
        )

        salary_total = float(
            item["annual_salary"] or 0
        )

        department_assumptions[key] = {
            "gosi_ratio": (
                item[
                    "annual_employer_gosi"
                ]
                / salary_total
                if salary_total > 0
                else company_gosi_ratio
            ),
            "avg_benefit": (
                item["annual_benefits"]
                / employees_count
                if employees_count > 0
                else company_avg_benefit
            ),
            "avg_other": (
                item["annual_other_cost"]
                / employees_count
                if employees_count > 0
                else company_avg_other
            ),
            "avg_total_cost": (
                item["annual_total_cost"]
                / employees_count
                if employees_count > 0
                else company_avg_total_cost
            ),
        }

    # --------------------------------------------------------
    # Workforce Plan
    # --------------------------------------------------------

    plan = None

    if plan_id:
        plan = (
            await db.execute(
                select(HRWorkforcePlan).where(
                    HRWorkforcePlan.id
                    == plan_id
                )
            )
        ).scalars().first()

        if not plan:
            raise HTTPException(
                status_code=404,
                detail="Workforce plan not found",
            )

    else:
        plan = (
            await db.execute(
                select(HRWorkforcePlan)
                .order_by(
                    HRWorkforcePlan.year.desc(),
                    HRWorkforcePlan.version.desc(),
                    HRWorkforcePlan.created_at.desc(),
                )
            )
        ).scalars().first()

    plan_lines = []

    if plan:
        plan_lines = (
            await db.execute(
                select(HRWorkforcePlanLine).where(
                    HRWorkforcePlanLine.plan_id
                    == plan.id,
                    HRWorkforcePlanLine.status
                    == "active",
                )
            )
        ).scalars().all()

    scenarios = {
        "min": {
            "planned_hires":
                _forecast_cost_summary(),
            "planned_exit_reduction":
                0.0,
        },
        "mid": {
            "planned_hires":
                _forecast_cost_summary(),
            "planned_exit_reduction":
                0.0,
        },
        "max": {
            "planned_hires":
                _forecast_cost_summary(),
            "planned_exit_reduction":
                0.0,
        },
        "selected_plan": {
            "planned_hires":
                _forecast_cost_summary(),
            "planned_exit_reduction":
                0.0,
        },
    }

    department_forecast = {}

    line_details = []

    for line in plan_lines:
        dept_key = str(
            line.department_id
        )

        assumption = (
            department_assumptions.get(
                dept_key,
                {
                    "gosi_ratio":
                        company_gosi_ratio,
                    "avg_benefit":
                        company_avg_benefit,
                    "avg_other":
                        company_avg_other,
                    "avg_total_cost":
                        company_avg_total_cost,
                },
            )
        )

        planned_hires = max(
            0,
            int(
                line.planned_hires
                or 0
            ),
        )

        planned_exits = max(
            0,
            int(
                line.planned_exits
                or 0
            ),
        )

        salary_values = {
            "min": _num(
                line.min_salary_snapshot
            ),
            "mid": _num(
                line.mid_salary_snapshot
            ),
            "max": _num(
                line.max_salary_snapshot
            ),
        }

        selected_scenario = (
            line.budget_scenario
            if line.budget_scenario
            in {"min", "mid", "max"}
            else "mid"
        )

        line_scenarios = {}

        for scenario_name in (
            "min",
            "mid",
            "max",
        ):
            per_hire = (
                _forecast_planned_hire_cost(
                    salary_values[
                        scenario_name
                    ],
                    assumption[
                        "gosi_ratio"
                    ],
                    assumption[
                        "avg_benefit"
                    ],
                    assumption[
                        "avg_other"
                    ],
                )
            )

            total = {
                key: round(
                    value
                    * planned_hires,
                    2,
                )
                for key, value
                in per_hire.items()
            }

            line_scenarios[
                scenario_name
            ] = total

            _forecast_add_cost(
                scenarios[
                    scenario_name
                ]["planned_hires"],
                total,
            )

        selected_total = (
            line_scenarios[
                selected_scenario
            ]
        )

        _forecast_add_cost(
            scenarios[
                "selected_plan"
            ]["planned_hires"],
            selected_total,
        )

        # ----------------------------------------------------
        # Planned exits:
        # Existing position average first.
        # Department/company fallback otherwise.
        # ----------------------------------------------------

        exit_cost_per_employee = (
            assumption[
                "avg_total_cost"
            ]
        )

        if line.position_id:
            pos_data = (
                position_current_costs.get(
                    str(line.position_id)
                )
            )

            if (
                pos_data
                and pos_data[
                    "employees"
                ] > 0
            ):
                exit_cost_per_employee = (
                    pos_data[
                        "total_cost"
                    ]
                    / pos_data[
                        "employees"
                    ]
                )

        exit_reduction = round(
            exit_cost_per_employee
            * planned_exits,
            2,
        )

        for scenario in scenarios.values():
            scenario[
                "planned_exit_reduction"
            ] = round(
                scenario[
                    "planned_exit_reduction"
                ]
                + exit_reduction,
                2,
            )

        # Department forecast.
        if dept_key not in department_forecast:
            current_dept = (
                department_current.get(
                    dept_key,
                    {
                        "department_id":
                            line.department_id,
                        "employees": 0,
                        **_forecast_cost_summary(),
                    },
                )
            )

            department_forecast[
                dept_key
            ] = {
                "department_id":
                    line.department_id,
                "current_employees":
                    current_dept.get(
                        "employees",
                        0,
                    ),
                "current_annual_cost":
                    round(
                        current_dept.get(
                            "annual_total_cost",
                            0,
                        ),
                        2,
                    ),
                "planned_hires": 0,
                "planned_exits": 0,
                "min_hiring_cost": 0.0,
                "mid_hiring_cost": 0.0,
                "max_hiring_cost": 0.0,
                "selected_hiring_cost": 0.0,
                "planned_exit_reduction": 0.0,
            }

        dept_forecast = (
            department_forecast[
                dept_key
            ]
        )

        dept_forecast[
            "planned_hires"
        ] += planned_hires

        dept_forecast[
            "planned_exits"
        ] += planned_exits

        dept_forecast[
            "min_hiring_cost"
        ] = round(
            dept_forecast[
                "min_hiring_cost"
            ]
            + line_scenarios[
                "min"
            ]["annual_total_cost"],
            2,
        )

        dept_forecast[
            "mid_hiring_cost"
        ] = round(
            dept_forecast[
                "mid_hiring_cost"
            ]
            + line_scenarios[
                "mid"
            ]["annual_total_cost"],
            2,
        )

        dept_forecast[
            "max_hiring_cost"
        ] = round(
            dept_forecast[
                "max_hiring_cost"
            ]
            + line_scenarios[
                "max"
            ]["annual_total_cost"],
            2,
        )

        dept_forecast[
            "selected_hiring_cost"
        ] = round(
            dept_forecast[
                "selected_hiring_cost"
            ]
            + selected_total[
                "annual_total_cost"
            ],
            2,
        )

        dept_forecast[
            "planned_exit_reduction"
        ] = round(
            dept_forecast[
                "planned_exit_reduction"
            ]
            + exit_reduction,
            2,
        )

        line_details.append({
            "line_id": line.id,
            "department_id":
                line.department_id,
            "position_id":
                line.position_id,
            "is_new_position":
                line.is_new_position,
            "proposed_position_title":
                line.proposed_position_title,
            "planned_hires":
                planned_hires,
            "planned_exits":
                planned_exits,
            "selected_scenario":
                selected_scenario,
            "assumed_gosi_ratio_pct":
                round(
                    assumption[
                        "gosi_ratio"
                    ] * 100,
                    2,
                ),
            "assumed_annual_benefit":
                round(
                    assumption[
                        "avg_benefit"
                    ],
                    2,
                ),
            "assumed_annual_other_cost":
                round(
                    assumption[
                        "avg_other"
                    ],
                    2,
                ),
            "exit_cost_per_employee":
                round(
                    exit_cost_per_employee,
                    2,
                ),
            "planned_exit_reduction":
                exit_reduction,
            "min":
                line_scenarios["min"],
            "mid":
                line_scenarios["mid"],
            "max":
                line_scenarios["max"],
            "selected":
                selected_total,
        })

    # --------------------------------------------------------
    # Final scenario totals
    # --------------------------------------------------------

    scenario_output = {}

    for name, scenario in scenarios.items():
        hiring = (
            scenario["planned_hires"]
        )

        exit_reduction = float(
            scenario[
                "planned_exit_reduction"
            ]
            or 0
        )

        projected = round(
            current["annual_total_cost"]
            + hiring[
                "annual_total_cost"
            ]
            - exit_reduction,
            2,
        )

        variance_amount, variance_pct = (
            _forecast_variance(
                current[
                    "annual_total_cost"
                ],
                projected,
            )
        )

        scenario_output[name] = {
            "planned_hires":
                hiring,
            "planned_exit_reduction":
                round(
                    exit_reduction,
                    2,
                ),
            "projected_annual_cost":
                projected,
            "variance_vs_current":
                variance_amount,
            "variance_pct":
                variance_pct,
        }

    # Department projected costs.
    department_output = []

    for item in department_forecast.values():
        current_cost = float(
            item[
                "current_annual_cost"
            ]
            or 0
        )

        exit_reduction = float(
            item[
                "planned_exit_reduction"
            ]
            or 0
        )

        item["min_projected_cost"] = round(
            current_cost
            + item["min_hiring_cost"]
            - exit_reduction,
            2,
        )

        item["mid_projected_cost"] = round(
            current_cost
            + item["mid_hiring_cost"]
            - exit_reduction,
            2,
        )

        item["max_projected_cost"] = round(
            current_cost
            + item["max_hiring_cost"]
            - exit_reduction,
            2,
        )

        item[
            "selected_projected_cost"
        ] = round(
            current_cost
            + item[
                "selected_hiring_cost"
            ]
            - exit_reduction,
            2,
        )

        department_output.append(
            item
        )

    return {
        "as_of_date": today,

        "plan": (
            _workforce_plan_payload(
                plan
            )
            if plan
            else None
        ),

        "current_workforce": {
            "active_employees":
                active_employee_count,
            **current,
        },

        "current_cost_mix_pct": {
            "salary": (
                round(
                    current[
                        "annual_salary"
                    ]
                    / current[
                        "annual_total_cost"
                    ]
                    * 100,
                    2,
                )
                if current[
                    "annual_total_cost"
                ] > 0
                else 0
            ),
            "employer_gosi": (
                round(
                    current[
                        "annual_employer_gosi"
                    ]
                    / current[
                        "annual_total_cost"
                    ]
                    * 100,
                    2,
                )
                if current[
                    "annual_total_cost"
                ] > 0
                else 0
            ),
            "benefits": (
                round(
                    current[
                        "annual_benefits"
                    ]
                    / current[
                        "annual_total_cost"
                    ]
                    * 100,
                    2,
                )
                if current[
                    "annual_total_cost"
                ] > 0
                else 0
            ),
            "other": (
                round(
                    current[
                        "annual_other_cost"
                    ]
                    / current[
                        "annual_total_cost"
                    ]
                    * 100,
                    2,
                )
                if current[
                    "annual_total_cost"
                ] > 0
                else 0
            ),
        },

        "planning_assumptions": {
            "company_employer_gosi_ratio_pct":
                round(
                    company_gosi_ratio
                    * 100,
                    2,
                ),
            "company_avg_annual_benefit":
                round(
                    company_avg_benefit,
                    2,
                ),
            "company_avg_annual_other_cost":
                round(
                    company_avg_other,
                    2,
                ),
            "benefits_source": (
                "Active Benefits & Insurance records; "
                "contract medical insurance is fallback only"
            ),
            "planned_hire_gosi_method":
                "Department actual ratio, company fallback",
            "planned_hire_benefits_method":
                "Department average, company fallback",
            "planned_exit_method":
                "Current position average annual cost, "
                "department/company fallback",
            "forecast_basis":
                "Annualized run-rate",
        },

        "scenarios":
            scenario_output,

        "department_breakdown":
            department_output,

        "workforce_plan_lines":
            line_details,
    }



# ============================================================
# HR - Policies & Compliance
# ============================================================

POLICY_VERSION_STATUSES = {
    "draft",
    "review",
    "approved",
    "superseded",
    "archived",
}

POLICY_CONFLICT_SEVERITIES = {
    "low",
    "medium",
    "high",
    "critical",
}

COMPLIANCE_ITEM_STATUSES = {
    "pending",
    "in_progress",
    "completed",
    "not_applicable",
}


class HRPolicyCreateRequest(BaseModel):
    code: str
    title_ar: str
    title_en: str | None = None
    category: str = "hr_policy"
    scope: str = "all_employees"
    policy_owner: str | None = None
    description: str | None = None
    notes: str | None = None


class HRPolicyVersionCreateRequest(BaseModel):
    policy_id: uuid.UUID
    version_number: str
    effective_date: date | None = None
    review_date: date | None = None
    prepared_by: str | None = None
    change_summary: str | None = None
    content_text: str | None = None
    attachment_url: str | None = None


class HRPolicyVersionStatusRequest(BaseModel):
    status: str
    actor: str
    approval_notes: str | None = None


class HRPolicyConflictCreateRequest(BaseModel):
    source_version_id: uuid.UUID
    conflicting_version_id: uuid.UUID
    conflict_type: str = "content_conflict"
    severity: str = "medium"
    description: str
    detected_by: str = "manual"


class HRPolicyConflictResolveRequest(BaseModel):
    resolution: str
    resolved_by: str


class HRComplianceChecklistCreateRequest(BaseModel):
    code: str
    title: str
    category: str = "hr_compliance"
    frequency: str = "annual"
    responsible_owner: str | None = None
    due_date: date | None = None
    description: str | None = None
    notes: str | None = None


class HRComplianceChecklistItemCreateRequest(BaseModel):
    checklist_id: uuid.UUID
    item_order: int = 1
    title: str
    requirement_reference: str | None = None
    responsible_owner: str | None = None
    due_date: date | None = None


class HRComplianceChecklistItemUpdateRequest(BaseModel):
    status: str
    completed_by: str | None = None
    evidence_url: str | None = None
    evidence_notes: str | None = None


def _policy_payload(row):
    return {
        "id": row.id,
        "code": row.code,
        "title_ar": row.title_ar,
        "title_en": row.title_en,
        "category": row.category,
        "scope": row.scope,
        "policy_owner": row.policy_owner,
        "status": row.status,
        "description": row.description,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _policy_version_payload(row):
    today = date.today()

    review_status = "not_scheduled"
    days_to_review = None

    if row.review_date:
        days_to_review = (
            row.review_date - today
        ).days

        if days_to_review < 0:
            review_status = "overdue"
        elif days_to_review <= 60:
            review_status = "review_due"
        else:
            review_status = "current"

    return {
        "id": row.id,
        "policy_id": row.policy_id,
        "version_number": row.version_number,
        "status": row.status,
        "is_current": row.is_current,
        "effective_date": row.effective_date,
        "review_date": row.review_date,
        "review_status": review_status,
        "days_to_review": days_to_review,
        "prepared_by": row.prepared_by,
        "reviewed_by": row.reviewed_by,
        "approved_by": row.approved_by,
        "approved_at": row.approved_at,
        "approval_notes": row.approval_notes,
        "change_summary": row.change_summary,
        "content_text": row.content_text,
        "attachment_url": row.attachment_url,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _policy_conflict_payload(row):
    return {
        "id": row.id,
        "source_version_id":
            row.source_version_id,
        "conflicting_version_id":
            row.conflicting_version_id,
        "conflict_type": row.conflict_type,
        "severity": row.severity,
        "status": row.status,
        "description": row.description,
        "detected_by": row.detected_by,
        "resolution": row.resolution,
        "resolved_by": row.resolved_by,
        "resolved_at": row.resolved_at,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _compliance_checklist_payload(row):
    today = date.today()

    runtime_status = row.status
    days_remaining = None

    if row.status != "completed" and row.due_date:
        days_remaining = (
            row.due_date - today
        ).days

        if days_remaining < 0:
            runtime_status = "overdue"
        elif days_remaining <= 30:
            runtime_status = "due_soon"

    return {
        "id": row.id,
        "code": row.code,
        "title": row.title,
        "category": row.category,
        "frequency": row.frequency,
        "responsible_owner":
            row.responsible_owner,
        "due_date": row.due_date,
        "status": runtime_status,
        "stored_status": row.status,
        "days_remaining": days_remaining,
        "description": row.description,
        "notes": row.notes,
        "completed_at": row.completed_at,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _compliance_item_payload(row):
    today = date.today()

    runtime_status = row.status
    days_remaining = None

    if (
        row.status
        not in {
            "completed",
            "not_applicable",
        }
        and row.due_date
    ):
        days_remaining = (
            row.due_date - today
        ).days

        if days_remaining < 0:
            runtime_status = "overdue"
        elif days_remaining <= 14:
            runtime_status = "due_soon"

    return {
        "id": row.id,
        "checklist_id": row.checklist_id,
        "item_order": row.item_order,
        "title": row.title,
        "requirement_reference":
            row.requirement_reference,
        "responsible_owner":
            row.responsible_owner,
        "due_date": row.due_date,
        "status": runtime_status,
        "stored_status": row.status,
        "days_remaining": days_remaining,
        "evidence_url": row.evidence_url,
        "evidence_notes": row.evidence_notes,
        "completed_by": row.completed_by,
        "completed_at": row.completed_at,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _refresh_compliance_checklist_status(
    db: AsyncSession,
    checklist_id: uuid.UUID,
):
    checklist = (
        await db.execute(
            select(HRComplianceChecklist).where(
                HRComplianceChecklist.id
                == checklist_id
            )
        )
    ).scalars().first()

    if not checklist:
        return None

    items = (
        await db.execute(
            select(HRComplianceChecklistItem).where(
                HRComplianceChecklistItem.checklist_id
                == checklist_id
            )
        )
    ).scalars().all()

    applicable = [
        row
        for row in items
        if row.status != "not_applicable"
    ]

    if (
        applicable
        and all(
            row.status == "completed"
            for row in applicable
        )
    ):
        checklist.status = "completed"

        if checklist.completed_at is None:
            checklist.completed_at = datetime.now(
                _timezone.utc
            )
    else:
        checklist.status = "open"
        checklist.completed_at = None

    return checklist


# ------------------------------------------------------------
# Policy Master
# ------------------------------------------------------------

@app.post("/api/hr/policies")
async def create_hr_policy(
    payload: HRPolicyCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip().upper()

    existing = (
        await db.execute(
            select(HRPolicy).where(
                HRPolicy.code == code
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail="Policy code already exists",
        )

    row = HRPolicy(
        code=code,
        title_ar=payload.title_ar.strip(),
        title_en=(
            payload.title_en.strip()
            if payload.title_en
            else None
        ),
        category=payload.category.strip(),
        scope=payload.scope.strip(),
        policy_owner=(
            payload.policy_owner.strip()
            if payload.policy_owner
            else None
        ),
        status="active",
        description=(
            payload.description.strip()
            if payload.description
            else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.policy.created",
        details={
            "policy_id": str(row.id),
            "code": row.code,
            "title_ar": row.title_ar,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _policy_payload(row)


@app.get("/api/hr/policies")
async def list_hr_policies(
    status: str | None = None,
    category: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(HRPolicy)

    if status:
        query = query.where(
            HRPolicy.status
            == status.strip().lower()
        )

    if category:
        query = query.where(
            HRPolicy.category
            == category.strip()
        )

    rows = (
        await db.execute(
            query.order_by(
                HRPolicy.code.asc()
            )
        )
    ).scalars().all()

    return [
        _policy_payload(row)
        for row in rows
    ]


# ------------------------------------------------------------
# Policy Versions
# ------------------------------------------------------------

@app.post("/api/hr/policy-versions")
async def create_hr_policy_version(
    payload: HRPolicyVersionCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    policy = (
        await db.execute(
            select(HRPolicy).where(
                HRPolicy.id
                == payload.policy_id
            )
        )
    ).scalars().first()

    if not policy:
        raise HTTPException(
            status_code=404,
            detail="Policy not found",
        )

    duplicate = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.policy_id
                    == policy.id,
                HRPolicyVersion.version_number
                    == payload.version_number.strip(),
            )
        )
    ).scalars().first()

    if duplicate:
        raise HTTPException(
            status_code=409,
            detail=(
                "This policy version number "
                "already exists"
            ),
        )

    row = HRPolicyVersion(
        policy_id=policy.id,
        version_number=(
            payload.version_number.strip()
        ),
        status="draft",
        is_current=False,
        effective_date=payload.effective_date,
        review_date=payload.review_date,
        prepared_by=(
            payload.prepared_by.strip()
            if payload.prepared_by
            else None
        ),
        change_summary=(
            payload.change_summary.strip()
            if payload.change_summary
            else None
        ),
        content_text=payload.content_text,
        attachment_url=payload.attachment_url,
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.policy.version_created",
        details={
            "policy_id": str(policy.id),
            "version_id": str(row.id),
            "version_number":
                row.version_number,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _policy_version_payload(row)


