@app.put(
    "/api/hr/policy-versions/{version_id}/status"
)
async def update_policy_version_status(
    version_id: uuid.UUID,
    payload: HRPolicyVersionStatusRequest,
    db: AsyncSession = Depends(get_db),
):
    new_status = payload.status.strip().lower()

    if new_status not in POLICY_VERSION_STATUSES:
        raise HTTPException(
            status_code=400,
            detail="Invalid policy version status",
        )

    row = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.id
                == version_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Policy version not found",
        )

    old_status = row.status

    allowed = {
        "draft": {"review", "archived"},
        "review": {"draft", "approved", "archived"},
        "approved": {"superseded", "archived"},
        "superseded": {"archived"},
        "archived": set(),
    }

    if (
        new_status != old_status
        and new_status
        not in allowed.get(
            old_status,
            set(),
        )
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Invalid policy version transition: "
                f"{old_status} -> {new_status}"
            ),
        )

    actor = payload.actor.strip()

    if new_status == "review":
        row.status = "review"
        row.reviewed_by = actor

    elif new_status == "draft":
        row.status = "draft"

    elif new_status == "approved":
        # Supersede previous current versions
        # for the same policy.
        existing_current = (
            await db.execute(
                select(HRPolicyVersion).where(
                    HRPolicyVersion.policy_id
                        == row.policy_id,
                    HRPolicyVersion.is_current
                        == True,
                    HRPolicyVersion.id
                        != row.id,
                )
            )
        ).scalars().all()

        for previous in existing_current:
            previous.is_current = False

            if previous.status == "approved":
                previous.status = "superseded"

        row.status = "approved"
        row.is_current = True
        row.approved_by = actor
        row.approved_at = datetime.now(
            _timezone.utc
        )
        row.approval_notes = (
            payload.approval_notes.strip()
            if payload.approval_notes
            else None
        )

    elif new_status == "superseded":
        row.status = "superseded"
        row.is_current = False

    elif new_status == "archived":
        row.status = "archived"
        row.is_current = False

    await write_audit_log(
        db,
        actor=actor,
        action="hr.policy.version_status_updated",
        details={
            "policy_id":
                str(row.policy_id),
            "version_id":
                str(row.id),
            "version_number":
                row.version_number,
            "from_status":
                old_status,
            "to_status":
                row.status,
            "is_current":
                row.is_current,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _policy_version_payload(row)


