# Policy Conflicts
# ------------------------------------------------------------

@app.post("/api/hr/policy-conflicts")
async def create_policy_conflict(
    payload: HRPolicyConflictCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if (
        payload.source_version_id
        == payload.conflicting_version_id
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "A policy version cannot conflict "
                "with itself"
            ),
        )

    severity = payload.severity.strip().lower()

    if severity not in POLICY_CONFLICT_SEVERITIES:
        raise HTTPException(
            status_code=400,
            detail="Invalid conflict severity",
        )

    versions = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.id.in_(
                    [
                        payload.source_version_id,
                        payload.conflicting_version_id,
                    ]
                )
            )
        )
    ).scalars().all()

    if len(versions) != 2:
        raise HTTPException(
            status_code=404,
            detail=(
                "One or both policy versions "
                "were not found"
            ),
        )

    row = HRPolicyConflict(
        source_version_id=(
            payload.source_version_id
        ),
        conflicting_version_id=(
            payload.conflicting_version_id
        ),
        conflict_type=(
            payload.conflict_type
            .strip()
            .lower()
        ),
        severity=severity,
        status="open",
        description=(
            payload.description.strip()
        ),
        detected_by=(
            payload.detected_by
            .strip()
            .lower()
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="hr.policy.conflict_created",
        details={
            "conflict_id": str(row.id),
            "source_version_id":
                str(row.source_version_id),
            "conflicting_version_id":
                str(
                    row.conflicting_version_id
                ),
            "severity": row.severity,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _policy_conflict_payload(row)


