@app.put(
    "/api/hr/policy-conflicts/{conflict_id}/resolve"
)
async def resolve_policy_conflict(
    conflict_id: uuid.UUID,
    payload: HRPolicyConflictResolveRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            select(HRPolicyConflict).where(
                HRPolicyConflict.id
                == conflict_id
            )
        )
    ).scalars().first()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Policy conflict not found",
        )

    if row.status == "resolved":
        raise HTTPException(
            status_code=409,
            detail="Policy conflict already resolved",
        )

    row.status = "resolved"
    row.resolution = payload.resolution.strip()
    row.resolved_by = (
        payload.resolved_by.strip()
    )
    row.resolved_at = datetime.now(
        _timezone.utc
    )

    await write_audit_log(
        db,
        actor=row.resolved_by,
        action="hr.policy.conflict_resolved",
        details={
            "conflict_id": str(row.id),
            "resolution": row.resolution,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _policy_conflict_payload(row)


