# HR - AI Policy Conflict Detection
# ============================================================

async def _policy_extract_attachment_text(
    attachment: HRAttachment,
):
    """
    Extract text from a privately stored policy attachment.

    Supported for AI ingestion:
    PDF, DOCX and TXT.
    """

    from io import BytesIO

    target = _hr_attachment_storage_path(
        attachment.storage_key
    )

    if not target.exists():
        return None

    content = target.read_bytes()

    extension = (
        attachment.file_extension
        or _HRPath(
            attachment.original_file_name
        ).suffix
        or ""
    ).lower()

    try:
        if extension == ".pdf":
            from pypdf import PdfReader

            reader = PdfReader(
                BytesIO(content)
            )

            chunks = []

            for page in reader.pages:
                try:
                    chunks.append(
                        page.extract_text()
                        or ""
                    )
                except Exception:
                    pass

            text_value = "\n".join(
                chunks
            )

        elif extension == ".docx":
            from docx import Document

            document = Document(
                BytesIO(content)
            )

            text_value = "\n".join(
                paragraph.text
                for paragraph
                in document.paragraphs
            )

        elif extension == ".txt":
            text_value = content.decode(
                "utf-8",
                errors="ignore",
            )

        else:
            return None

    except Exception:
        return None

    text_value = (
        text_value.strip()
    )

    if len(text_value) < 50:
        return None

    return text_value[:200000]


async def _policy_version_analysis_text(
    db: AsyncSession,
    version: HRPolicyVersion,
):
    """
    Source-of-truth text for AI policy analysis.

    Priority:
    1. Stored content_text
    2. Latest active Unified HR policy attachment
    """

    existing_text = (
        version.content_text
        or ""
    ).strip()

    if len(existing_text) >= 50:
        return {
            "text": existing_text[:200000],
            "source": "content_text",
            "attachment_id": None,
        }

    attachments = (
        await db.execute(
            select(HRAttachment).where(
                HRAttachment.module
                    == "policies_compliance",
                HRAttachment.entity_type
                    == "policy_version",
                HRAttachment.entity_id
                    == version.id,
                HRAttachment.document_type
                    == "policy_document",
                HRAttachment.status
                    == "active",
            ).order_by(
                HRAttachment.created_at.desc()
            )
        )
    ).scalars().all()

    for attachment in attachments:
        extracted = (
            await _policy_extract_attachment_text(
                attachment
            )
        )

        if not extracted:
            continue

        # Persist extracted text so future
        # analysis does not need to parse
        # the file again.
        version.content_text = extracted

        return {
            "text": extracted,
            "source": "attachment",
            "attachment_id":
                attachment.id,
        }

    return {
        "text": None,
        "source": None,
        "attachment_id": None,
    }


def _policy_ai_conflict_type(
    value,
):
    raw = str(
        value
        or "content_conflict"
    ).strip().lower()

    raw = _hr_re.sub(
        r"[^a-z0-9_-]+",
        "_",
        raw,
    ).strip("_")

    return (
        raw[:80]
        or "content_conflict"
    )


@app.post(
    "/api/hr/policy-versions/{version_id}/analyze-conflicts"
)
async def analyze_policy_version_conflicts(
    version_id: uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    from sqlalchemy import or_ as _sa_or

    target = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.id
                    == version_id
            )
        )
    ).scalars().first()

    if not target:
        raise HTTPException(
            status_code=404,
            detail="Policy version not found",
        )

    if target.status == "archived":
        raise HTTPException(
            status_code=409,
            detail=(
                "Archived policy versions "
                "cannot be analyzed"
            ),
        )

    target_policy = (
        await db.execute(
            select(HRPolicy).where(
                HRPolicy.id
                    == target.policy_id
            )
        )
    ).scalars().first()

    if not target_policy:
        raise HTTPException(
            status_code=404,
            detail="Policy master record not found",
        )

    target_source = (
        await _policy_version_analysis_text(
            db,
            target,
        )
    )

    if not target_source["text"]:
        raise HTTPException(
            status_code=422,
            detail=(
                "No analyzable policy text found. "
                "Enter Policy Text or upload a "
                "text-based PDF, DOCX or TXT file."
            ),
        )

    # Compare only against current approved
    # versions of OTHER policies.
    comparison_versions = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.is_current
                    == True,
                HRPolicyVersion.status
                    == "approved",
                HRPolicyVersion.policy_id
                    != target.policy_id,
            ).order_by(
                HRPolicyVersion.created_at.desc()
            )
        )
    ).scalars().all()

    comparison_payload = []
    valid_version_ids = set()

    policy_ids = {
        row.policy_id
        for row in comparison_versions
    }

    policies = []

    if policy_ids:
        policies = (
            await db.execute(
                select(HRPolicy).where(
                    HRPolicy.id.in_(
                        list(policy_ids)
                    )
                )
            )
        ).scalars().all()

    policy_map = {
        row.id: row
        for row in policies
    }

    # Keep the AI context bounded.
    for version in comparison_versions[:30]:
        source = (
            await _policy_version_analysis_text(
                db,
                version,
            )
        )

        if not source["text"]:
            continue

        policy = policy_map.get(
            version.policy_id
        )

        version_id_str = str(
            version.id
        )

        valid_version_ids.add(
            version_id_str
        )

        comparison_payload.append({
            "version_id":
                version_id_str,
            "policy_code": (
                policy.code
                if policy
                else None
            ),
            "title_ar": (
                policy.title_ar
                if policy
                else None
            ),
            "title_en": (
                policy.title_en
                if policy
                else None
            ),
            "version_number":
                version.version_number,

            # Limit each comparison policy
            # to keep analysis efficient.
            "text":
                source["text"][:12000],
        })

    if not comparison_payload:
        await db.commit()

        return {
            "status": "ok",
            "version_id": target.id,
            "target_policy_code":
                target_policy.code,
            "target_text_source":
                target_source["source"],
            "comparison_versions": 0,
            "detected_conflicts": 0,
            "created_conflicts": 0,
            "skipped_existing": 0,
            "ignored_low_confidence": 0,
            "conflicts": [],
            "message": (
                "No other current approved "
                "policies with analyzable text "
                "were available for comparison."
            ),
        }

    ai_payload = {
        "target_policy": {
            "version_id":
                str(target.id),
            "policy_code":
                target_policy.code,
            "title_ar":
                target_policy.title_ar,
            "title_en":
                target_policy.title_en,
            "version_number":
                target.version_number,
            "text":
                target_source["text"][:30000],
        },
        "approved_policies":
            comparison_payload,
    }

    instructions = """
أنت محلل حوكمة وسياسات موارد بشرية.

قارن السياسة المستهدفة فقط مع السياسات المعتمدة الحالية
المقدمة لك.

المطلوب اكتشاف التعارضات الحقيقية أو التناقضات التشغيلية،
وليس مجرد اختلاف الصياغة أو مستوى التفصيل.

يعتبر تعارضًا مثلًا:
- اختلاف الاستحقاق لنفس الحالة.
- اختلاف المدة أو الحد أو العدد لنفس الإجراء.
- اختلاف جهة الاعتماد أو تسلسل الموافقات لنفس العملية.
- تعريفان متناقضان لنفس المصطلح.
- سياسة تسمح بشيء وسياسة أخرى تمنعه لنفس النطاق.
- معادلات أو طرق احتساب متناقضة.
- نطاقان متداخلان ينتجان تعليمات مختلفة لنفس الموظف.

لا تعتبر تعارضًا:
- إعادة الصياغة.
- وجود تفاصيل إضافية لا تناقض السياسة الأخرى.
- سياسات تتناول موضوعات مختلفة.
- فرق يمكن التوفيق بينه منطقيًا بدون تعارض.

استخدم فقط version_id الموجودة في approved_policies.
لا تخترع معرفات أو سياسات غير موجودة.

أعد JSON فقط بهذا الشكل:
{
  "conflicts": [
    {
      "conflicting_version_id": "",
      "conflict_type": "",
      "severity": "low|medium|high|critical",
      "confidence": 0,
      "description": ""
    }
  ]
}

قواعد:
- confidence من 0 إلى 100.
- severity يجب أن تكون إحدى القيم الأربع فقط.
- description بالعربية، واضح ومحدد، ويشرح موضع التعارض.
- إذا لم يوجد تعارض حقيقي، أعد conflicts فارغة.
"""

    ai_result = await _hr_ai_json(
        instructions,
        ai_payload,
    )

    raw_conflicts = (
        ai_result.get(
            "conflicts",
            []
        )
        if isinstance(
            ai_result,
            dict,
        )
        else []
    )

    existing_rows = (
        await db.execute(
            select(HRPolicyConflict).where(
                _sa_or(
                    HRPolicyConflict.source_version_id
                        == target.id,
                    HRPolicyConflict.conflicting_version_id
                        == target.id,
                )
            )
        )
    ).scalars().all()

    existing_open_pairs = {
        frozenset({
            str(row.source_version_id),
            str(
                row.conflicting_version_id
            ),
        })
        for row in existing_rows
        if row.status == "open"
    }

    created = []
    skipped_existing = 0
    ignored_low_confidence = 0
    valid_ai_conflicts = []

    for item in raw_conflicts:
        if not isinstance(
            item,
            dict,
        ):
            continue

        conflicting_id = str(
            item.get(
                "conflicting_version_id",
                ""
            )
        ).strip()

        if (
            conflicting_id
            not in valid_version_ids
        ):
            continue

        try:
            confidence = float(
                item.get(
                    "confidence",
                    0,
                )
                or 0
            )
        except Exception:
            confidence = 0

        confidence = max(
            0,
            min(
                100,
                confidence,
            ),
        )

        severity = str(
            item.get(
                "severity",
                "medium",
            )
        ).strip().lower()

        if (
            severity
            not in POLICY_CONFLICT_SEVERITIES
        ):
            severity = "medium"

        description = str(
            item.get(
                "description",
                "",
            )
        ).strip()

        if not description:
            continue

        normalized = {
            "conflicting_version_id":
                conflicting_id,
            "conflict_type":
                _policy_ai_conflict_type(
                    item.get(
                        "conflict_type"
                    )
                ),
            "severity":
                severity,
            "confidence":
                round(
                    confidence,
                    2,
                ),
            "description":
                description,
        }

        valid_ai_conflicts.append(
            normalized
        )

        if confidence < 70:
            ignored_low_confidence += 1
            continue

        pair = frozenset({
            str(target.id),
            conflicting_id,
        })

        if pair in existing_open_pairs:
            skipped_existing += 1
            continue

        conflict_row = HRPolicyConflict(
            source_version_id=
                target.id,
            conflicting_version_id=
                uuid.UUID(
                    conflicting_id
                ),
            conflict_type=
                normalized[
                    "conflict_type"
                ],
            severity=severity,
            status="open",
            description=(
                f"{description} "
                f"[AI confidence: "
                f"{confidence:.0f}%]"
            ),
            detected_by="ai",
        )

        db.add(
            conflict_row
        )

        await db.flush()

        existing_open_pairs.add(
            pair
        )

        created.append({
            "id":
                conflict_row.id,
            **normalized,
        })

    await write_audit_log(
        db,
        actor="agent:hr",
        action=(
            "hr.policy.ai_conflict_analysis"
        ),
        details={
            "policy_id":
                str(
                    target.policy_id
                ),
            "version_id":
                str(target.id),
            "policy_code":
                target_policy.code,
            "target_text_source":
                target_source[
                    "source"
                ],
            "comparison_versions":
                len(
                    comparison_payload
                ),
            "ai_detected":
                len(
                    valid_ai_conflicts
                ),
            "created_conflicts":
                len(created),
            "skipped_existing":
                skipped_existing,
            "ignored_low_confidence":
                ignored_low_confidence,

            # Policy text is deliberately
            # excluded from generic audit.
        },
    )

    await db.commit()

    return {
        "status": "ok",
        "version_id": target.id,
        "target_policy_code":
            target_policy.code,
        "target_text_source":
            target_source["source"],
        "comparison_versions":
            len(
                comparison_payload
            ),
        "detected_conflicts":
            len(
                valid_ai_conflicts
            ),
        "created_conflicts":
            len(created),
        "skipped_existing":
            skipped_existing,
        "ignored_low_confidence":
            ignored_low_confidence,
        "conflicts":
            valid_ai_conflicts,
        "created":
            created,
    }



