async def _get_agent_by_slug(
    db: AsyncSession,
    slug: str,
):
    return (
        await db.execute(
            select(Agent).where(
                Agent.slug == slug
            )
        )
    ).scalars().first()


async def _policy_impact_source_text(
    db: AsyncSession,
    version: HRPolicyVersion,
):
    # Reuse the source-of-truth ingestion
    # already built for AI policy analysis.
    return await _policy_version_analysis_text(
        db,
        version,
    )


@app.post(
    "/api/policy-impact/policy-versions/{version_id}/analyze"
)
async def analyze_policy_impact(
    version_id: uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    version = (
        await db.execute(
            select(HRPolicyVersion).where(
                HRPolicyVersion.id
                == version_id
            )
        )
    ).scalars().first()

    if not version:
        raise HTTPException(
            status_code=404,
            detail="Policy version not found",
        )

    if (
        version.status != "approved"
        or not version.is_current
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Policy impact analysis requires "
                "the current approved policy version."
            ),
        )

    policy = (
        await db.execute(
            select(HRPolicy).where(
                HRPolicy.id
                == version.policy_id
            )
        )
    ).scalars().first()

    if not policy:
        raise HTTPException(
            status_code=404,
            detail="Policy master record not found",
        )

    source = (
        await _policy_impact_source_text(
            db,
            version,
        )
    )

    if not source["text"]:
        raise HTTPException(
            status_code=422,
            detail=(
                "No analyzable policy text found. "
                "Enter policy text or upload a "
                "text-based policy document."
            ),
        )

    # Prevent duplicate active assessment
    # for the same approved version.
    existing = (
        await db.execute(
            select(
                PolicyImpactAssessment
            ).where(
                PolicyImpactAssessment
                .policy_version_id
                == version.id,
                PolicyImpactAssessment
                .status.in_(
                    [
                        "draft",
                        "analyzed",
                        "awaiting_decision",
                        "in_progress",
                    ]
                ),
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "An active impact assessment "
                "already exists for this policy version."
            ),
        )

    system_catalog = {
        "agents": [
            "ceo",
            "hr",
            "finance",
            "it",
            "procurement",
        ],
        "hr_modules": [
            "employee_master",
            "recruitment",
            "onboarding",
            "lifecycle",
            "leave_attendance",
            "payroll",
            "employee_payments",
            "benefits",
            "compensation",
            "performance",
            "training",
            "employee_relations",
            "final_settlement",
            "government_compliance",
            "talent",
            "workforce_planning",
            "cost_forecast",
            "policies_compliance",
            "confidential_notes",
            "calendar",
            "monthly_dashboard",
        ],
        "known_rules": {
            "payroll": (
                "Payroll contains only basic salary "
                "plus fixed allowances minus payroll "
                "deductions. Overtime and claims are "
                "outside payroll."
            ),
            "employee_payments": (
                "Payment cutoff is the 10th calendar "
                "day. Eligible items after cutoff roll "
                "to the next cycle."
            ),
            "overtime": (
                "Overtime is not linked automatically "
                "to attendance. External approval stages "
                "are manager, CEO, then final HR approval."
            ),
            "annual_leave": (
                "Full-year annual entitlement is 30 days; "
                "new hires are prorated by calendar days. "
                "Standard year-end carry forward is capped "
                "at 10 days."
            ),
            "final_settlement": (
                "Annual leave payable balance is recalculated "
                "through the actual Last Working Day."
            ),
            "benefits": (
                "Benefits are separate from payroll. "
                "Only active benefits can affect payroll "
                "employee deductions."
            ),
        },
        "safety": {
            "automatic_code_change":
                False,
            "automatic_database_change":
                False,
            "automatic_production_deploy":
                False,
            "uncertain_impact_mode":
                "manual_review",
        },
    }

    ai_payload = {
        "policy": {
            "policy_id":
                str(policy.id),
            "policy_code":
                policy.code,
            "title_ar":
                policy.title_ar,
            "title_en":
                policy.title_en,
            "scope":
                policy.scope,
            "category":
                policy.category,
            "version_id":
                str(version.id),
            "version_number":
                version.version_number,
            "effective_date": (
                version.effective_date
                .isoformat()
                if version.effective_date
                else None
            ),
            "content":
                source["text"][:50000],
        },
        "system_catalog":
            system_catalog,
    }

    instructions = """
أنت محلل Policy Impact Architecture لنظام مؤسسي متعدد الوكلاء.

حلل السياسة المعتمدة وحدد أثرها على الوكلاء والنظام.

لا تخترع أثرًا تقنيًا إذا لم تدعمه السياسة.
إذا كنت غير متأكد، استخدم manual_review.

impact_type يجب أن يكون إحدى القيم:
agent_behavior
configuration
application_code
workflow
database
calculator
reporting
integration
documentation
no_system_impact

change_type:
add
modify
remove
no_change

severity:
low
medium
high
critical

enforcement_mode:
automatic
configuration
it_task
manual_review
documentation_only

قواعد إلزامية:
- agent_behavior يمكن أن يكون automatic إذا كان مجرد تعليمات
  أو سلوك معرفي للوكيل ولا يتطلب تغيير كود.
- configuration يمكن أن يكون configuration فقط إذا كانت القيمة
  المقترحة محددة وقابلة للتحويل إلى Rule واضحة.
- application_code/workflow/database/calculator/reporting/integration
  يجب أن تكون it_task ولا يجوز اعتبارها automatic.
- لا تقترح تغيير Production أو قاعدة البيانات تلقائيًا.
- إذا تغيرت قاعدة في السياسة بينما النظام الحالي معروف بأنه يطبق
  قيمة أو Workflow مختلفة، صف current_value وproposed_value بوضوح.
- acceptance_criteria يجب أن تكون قابلة للاختبار.
- rule_candidate يُستخدم فقط لتأثير agent_behavior أو configuration
  عندما يمكن صياغة Rule واضحة.
- لا تستخدم rule_candidate للتغييرات التقنية.
- راجع تاريخ السريان بدقة:
  metadata effective_date هو التاريخ المسجل رسميًا في Policy Version.
  استخرج فقط التاريخ الذي يصرح النص بأنه تاريخ سريان هذه السياسة.
  إذا كان التاريخان مختلفين أعد effective_date_review.status = "conflict".
  لا تعتبر تاريخًا تاريخيًا أو مثالًا أو موعد مراجعة كتاريخ سريان.

أعد JSON فقط:

{
  "effective_date_review": {
    "metadata_effective_date": "YYYY-MM-DD|null",
    "policy_text_effective_date": "YYYY-MM-DD|null",
    "status": "consistent|conflict|not_found",
    "explanation": ""
  },
  "overall_risk": "low|medium|high|critical",
  "summary": "",
  "items": [
    {
      "impact_type": "",
      "domain": "hr",
      "affected_module": "",
      "affected_component": "",
      "change_type": "",
      "description": "",
      "recommended_action": "",
      "severity": "",
      "enforcement_mode": "",
      "auto_applicable": false,
      "current_value": {},
      "proposed_value": {},
      "acceptance_criteria": {
        "items": []
      },
      "rule_candidate": {
        "rule_type": "",
        "rule_key": "",
        "target_agent_slug": null,
        "target_module": null,
        "rule_value": {},
        "source_clause": ""
      }
    }
  ]
}
"""

    ai_result = await _hr_ai_json(
        instructions,
        ai_payload,
    )

    # --------------------------------------------------------
    # EFFECTIVE-DATE CONSISTENCY GUARD
    # --------------------------------------------------------
    effective_date_review = (
        ai_result.get(
            "effective_date_review",
            {},
        )
        if isinstance(
            ai_result,
            dict,
        )
        else {}
    )

    if not isinstance(
        effective_date_review,
        dict,
    ):
        effective_date_review = {}

    date_review_status = str(
        effective_date_review.get(
            "status",
            "not_found",
        )
        or "not_found"
    ).strip().lower()

    text_effective_date = (
        str(
            effective_date_review.get(
                "policy_text_effective_date",
                "",
            )
            or ""
        ).strip()
        or None
    )

    if date_review_status == "conflict":
        metadata_date = (
            version.effective_date.isoformat()
            if version.effective_date
            else "not set"
        )

        raise HTTPException(
            status_code=409,
            detail=(
                "Policy effective-date conflict detected. "
                f"Version metadata effective date: {metadata_date}. "
                f"Policy text effective date: "
                f"{text_effective_date or 'not resolved'}. "
                "Correct the Policy Version effective date or "
                "the policy text before running Impact Analysis."
            ),
        )

    raw_items = (
        ai_result.get(
            "items",
            [],
        )
        if isinstance(
            ai_result,
            dict,
        )
        else []
    )

    overall_risk = str(
        ai_result.get(
            "overall_risk",
            "medium",
        )
        if isinstance(
            ai_result,
            dict,
        )
        else "medium"
    ).strip().lower()

    if (
        overall_risk
        not in POLICY_IMPACT_SEVERITIES
    ):
        overall_risk = "medium"

    assessment = (
        PolicyImpactAssessment(
            policy_version_id=
                version.id,
            trigger_source=
                "policy_approval",
            status="awaiting_decision",
            overall_risk=
                overall_risk,
            analyzed_by=
                "agent:hr",
            analysis_summary=(
                str(
                    ai_result.get(
                        "summary",
                        "",
                    )
                ).strip()
                if isinstance(
                    ai_result,
                    dict,
                )
                else None
            ),
            requires_user_approval=
                True,
            effective_date=
                version.effective_date,
        )
    )

    db.add(assessment)
    await db.flush()

    created_items = []
    created_decisions = []

    for raw in raw_items:
        if not isinstance(
            raw,
            dict,
        ):
            continue

        impact_type = str(
            raw.get(
                "impact_type",
                "no_system_impact",
            )
        ).strip().lower()

        if (
            impact_type
            not in POLICY_IMPACT_TYPES
        ):
            impact_type = (
                "no_system_impact"
            )

        change_type = str(
            raw.get(
                "change_type",
                "modify",
            )
        ).strip().lower()

        if (
            change_type
            not in POLICY_IMPACT_CHANGE_TYPES
        ):
            change_type = "modify"

        severity = str(
            raw.get(
                "severity",
                "medium",
            )
        ).strip().lower()

        if (
            severity
            not in POLICY_IMPACT_SEVERITIES
        ):
            severity = "medium"

        enforcement_mode = str(
            raw.get(
                "enforcement_mode",
                "manual_review",
            )
        ).strip().lower()

        if (
            enforcement_mode
            not in POLICY_ENFORCEMENT_MODES
        ):
            enforcement_mode = (
                "manual_review"
            )

        # Technical impacts may never be
        # applied automatically.
        if (
            impact_type
            in POLICY_TECHNICAL_IMPACT_TYPES
        ):
            enforcement_mode = "it_task"
            auto_applicable = False
        else:
            auto_applicable = bool(
                raw.get(
                    "auto_applicable",
                    False,
                )
            )

        if (
            enforcement_mode
            not in {
                "automatic",
                "configuration",
            }
        ):
            auto_applicable = False

        description = str(
            raw.get(
                "description",
                "",
            )
        ).strip()

        if not description:
            continue

        item = PolicyImpactItem(
            assessment_id=
                assessment.id,
            impact_type=
                impact_type,
            domain=(
                str(
                    raw.get(
                        "domain",
                        "hr",
                    )
                ).strip().lower()
                or "hr"
            ),
            affected_module=(
                str(
                    raw.get(
                        "affected_module",
                        "",
                    )
                ).strip()
                or None
            ),
            affected_component=(
                str(
                    raw.get(
                        "affected_component",
                        "",
                    )
                ).strip()
                or None
            ),
            change_type=
                change_type,
            description=
                description,
            recommended_action=(
                str(
                    raw.get(
                        "recommended_action",
                        "",
                    )
                ).strip()
                or None
            ),
            severity=
                severity,
            enforcement_mode=
                enforcement_mode,
            auto_applicable=
                auto_applicable,
            current_value=(
                raw.get(
                    "current_value",
                    {},
                )
                if isinstance(
                    raw.get(
                        "current_value",
                        {},
                    ),
                    dict,
                )
                else {}
            ),
            proposed_value=(
                raw.get(
                    "proposed_value",
                    {},
                )
                if isinstance(
                    raw.get(
                        "proposed_value",
                        {},
                    ),
                    dict,
                )
                else {}
            ),
            acceptance_criteria=(
                raw.get(
                    "acceptance_criteria",
                    {},
                )
                if isinstance(
                    raw.get(
                        "acceptance_criteria",
                        {},
                    ),
                    dict,
                )
                else {}
            ),
            # Analysis is review-only.
            # No policy impact may execute before
            # an explicit user decision.
            status="awaiting_decision",
            effective_date=
                version.effective_date,
        )

        db.add(item)
        await db.flush()

        created_items.append(
            item
        )

        # ----------------------------------------------------
        # REVIEW-ONLY CHANGE DECISION
        # ----------------------------------------------------
        # Preserve the AI execution proposal, but DO NOT create
        # an Enforcement Rule, IT Task, or System Mismatch yet.
        # Those are created only after the user's explicit
        # Approve Add / Modify / Remove decision.
        rule_candidate = raw.get(
            "rule_candidate",
            {},
        )

        if not isinstance(
            rule_candidate,
            dict,
        ):
            rule_candidate = {}

        normalized_rule_candidate = {
            "rule_type": (
                str(
                    rule_candidate.get(
                        "rule_type",
                        "",
                    )
                ).strip().lower()
                or (
                    "instruction"
                    if impact_type
                    == "agent_behavior"
                    else "configuration"
                    if impact_type
                    == "configuration"
                    else None
                )
            ),
            "rule_key": (
                str(
                    rule_candidate.get(
                        "rule_key",
                        "",
                    )
                ).strip()[:180]
                or None
            ),
            "target_agent_slug": (
                str(
                    rule_candidate.get(
                        "target_agent_slug",
                        "",
                    )
                ).strip().lower()
                or None
            ),
            "target_module": (
                str(
                    rule_candidate.get(
                        "target_module",
                        "",
                    )
                ).strip().lower()
                or item.affected_module
            ),
            "rule_value": (
                rule_candidate.get(
                    "rule_value",
                    {},
                )
                if isinstance(
                    rule_candidate.get(
                        "rule_value",
                        {},
                    ),
                    dict,
                )
                else {}
            ),
            "source_clause": (
                str(
                    rule_candidate.get(
                        "source_clause",
                        "",
                    )
                ).strip()
                or item.description
            ),
        }

        decision = PolicyChangeDecision(
            impact_item_id=
                item.id,
            assessment_id=
                assessment.id,
            policy_version_id=
                version.id,
            decision="pending",
            decision_notes=None,
            execution_payload={
                "impact_type":
                    item.impact_type,
                "change_type":
                    item.change_type,
                "enforcement_mode":
                    item.enforcement_mode,
                "auto_applicable":
                    item.auto_applicable,
                "affected_module":
                    item.affected_module,
                "affected_component":
                    item.affected_component,
                "current_value":
                    item.current_value,
                "proposed_value":
                    item.proposed_value,
                "acceptance_criteria":
                    item.acceptance_criteria,
                "recommended_action":
                    item.recommended_action,
                "effective_date": (
                    version.effective_date.isoformat()
                    if version.effective_date
                    else None
                ),
                "rule_candidate":
                    normalized_rule_candidate,
            },
            status="pending",
        )

        db.add(decision)
        await db.flush()

        created_decisions.append(
            decision
        )

    await write_audit_log(
        db,
        actor="agent:hr",
        action=(
            "policy.impact_analysis.completed"
        ),
        details={
            "policy_id":
                str(policy.id),
            "policy_code":
                policy.code,
            "policy_version_id":
                str(version.id),
            "assessment_id":
                str(assessment.id),
            "overall_risk":
                overall_risk,
            "impact_items":
                len(created_items),
            "pending_change_decisions":
                len(created_decisions),
            "enforcement_rules":
                0,
            "it_tasks":
                0,
            "system_mismatches":
                0,
            "review_only":
                True,
            "execution_deferred_until_user_decision":
                True,
            "text_source":
                source["source"],
        },
    )

    await db.commit()

    # Refresh all response entities after commit.
    # Some rows receive server-side updated_at values after
    # secondary updates (for example linking an IT task),
    # and accessing those unloaded values directly in an
    # AsyncSession can otherwise trigger MissingGreenlet.
    await db.refresh(
        assessment
    )

    for row in created_items:
        await db.refresh(row)

    for row in created_decisions:
        await db.refresh(row)

    return {
        "status": "ok",
        "assessment": {
            "id":
                assessment.id,
            "policy_version_id":
                assessment.policy_version_id,
            "policy_code":
                policy.code,
            "version_number":
                version.version_number,
            "overall_risk":
                assessment.overall_risk,
            "analysis_summary":
                assessment.analysis_summary,
            "effective_date":
                assessment.effective_date,
            "status":
                assessment.status,
        },
        "impact_items": [
            _policy_impact_item_payload(
                row
            )
            for row
            in created_items
        ],
        "change_decisions": [
            _policy_change_decision_payload(
                row
            )
            for row
            in created_decisions
        ],
        # Execution is intentionally deferred until
        # the user makes an explicit change decision.
        "enforcement_rules": [],
        "it_tasks": [],
        "system_mismatches": [],
    }


@app.get(
    "/api/policy-impact/assessments"
)
async def list_policy_impact_assessments(
    policy_version_id: uuid.UUID | None = None,
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(
        PolicyImpactAssessment
    )

    if policy_version_id:
        query = query.where(
            PolicyImpactAssessment
            .policy_version_id
            == policy_version_id
        )

    if status:
        query = query.where(
            PolicyImpactAssessment.status
            == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyImpactAssessment
                .created_at.desc()
            )
        )
    ).scalars().all()

    return [
        {
            "id": row.id,
            "policy_version_id":
                row.policy_version_id,
            "trigger_source":
                row.trigger_source,
            "status": row.status,
            "overall_risk":
                row.overall_risk,
            "analyzed_by":
                row.analyzed_by,
            "analysis_summary":
                row.analysis_summary,
            "effective_date":
                row.effective_date,
            "approval_id":
                row.approval_id,
            "completed_at":
                row.completed_at,
            "created_at":
                row.created_at,
        }
        for row in rows
    ]


@app.get(
    "/api/policy-impact/items"
)
async def list_policy_impact_items(
    assessment_id: uuid.UUID | None = None,
    status: str | None = None,
    enforcement_mode: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(
        PolicyImpactItem
    )

    if assessment_id:
        query = query.where(
            PolicyImpactItem
            .assessment_id
            == assessment_id
        )

    if status:
        query = query.where(
            PolicyImpactItem.status
            == status.strip().lower()
        )

    if enforcement_mode:
        query = query.where(
            PolicyImpactItem
            .enforcement_mode
            == enforcement_mode
            .strip()
            .lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyImpactItem
                .created_at.desc()
            )
        )
    ).scalars().all()

    return [
        _policy_impact_item_payload(
            row
        )
        for row in rows
    ]


@app.get(
    "/api/policy-impact/enforcement-rules"
)
async def list_policy_enforcement_rules(
    policy_version_id: uuid.UUID | None = None,
    status: str | None = None,
    target_agent_slug: str | None = None,
    target_module: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(
        PolicyEnforcementRule
    )

    if policy_version_id:
        query = query.where(
            PolicyEnforcementRule
            .policy_version_id
            == policy_version_id
        )

    if status:
        query = query.where(
            PolicyEnforcementRule.status
            == status.strip().lower()
        )

    if target_agent_slug:
        query = query.where(
            PolicyEnforcementRule
            .target_agent_slug
            == target_agent_slug
            .strip()
            .lower()
        )

    if target_module:
        query = query.where(
            PolicyEnforcementRule
            .target_module
            == target_module
            .strip()
            .lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyEnforcementRule
                .created_at.desc()
            )
        )
    ).scalars().all()

    return [
        _policy_enforcement_rule_payload(
            row
        )
        for row in rows
    ]


