@app.get(
    "/api/policy-impact/summary"
)
async def policy_impact_summary(
    db: AsyncSession = Depends(get_db),
):
    assessments = (
        await db.execute(
            select(
                PolicyImpactAssessment
            )
        )
    ).scalars().all()

    items = (
        await db.execute(
            select(
                PolicyImpactItem
            )
        )
    ).scalars().all()

    rules = (
        await db.execute(
            select(
                PolicyEnforcementRule
            )
        )
    ).scalars().all()

    mismatches = (
        await db.execute(
            select(
                PolicySystemMismatch
            )
        )
    ).scalars().all()

    return {
        "assessments":
            len(assessments),
        "pending_impact_items":
            sum(
                1
                for row in items
                if row.status
                in {
                    "pending",
                    "ready_for_enforcement",
                }
            ),
        "pending_activation_rules":
            sum(
                1
                for row in rules
                if row.status
                == "pending_activation"
            ),
        "active_rules":
            sum(
                1
                for row in rules
                if row.status
                == "active"
            ),
        "open_mismatches":
            sum(
                1
                for row in mismatches
                if row.status
                == "open"
            ),
        "critical_mismatches":
            sum(
                1
                for row in mismatches
                if row.status
                == "open"
                and row.severity
                == "critical"
            ),
    }




# ============================================================
# Shared - Policy Enforcement Activation
# ============================================================

async def _activate_policy_enforcement_rule(
    db: AsyncSession,
    rule: PolicyEnforcementRule,
    *,
    as_of_date: date,
    actor: str,
):
    """
    Activate a policy rule only when its effective date is due.

    Future rules remain scheduled.
    When a new rule becomes active, any older active rule with
    the same logical target is superseded while preserving its
    historical effective period.
    """

    if rule.status in {
        "superseded",
        "cancelled",
        "archived",
    }:
        return {
            "rule": rule,
            "result": "ignored",
        }

    effective_from = (
        rule.effective_from
        or as_of_date
    )

    # --------------------------------------------------------
    # Future policy rule
    # --------------------------------------------------------
    if effective_from > as_of_date:
        rule.status = "scheduled"

        return {
            "rule": rule,
            "result": "scheduled",
        }

    # --------------------------------------------------------
    # Supersede previous ACTIVE rule for same logical target
    # --------------------------------------------------------
    query = select(
        PolicyEnforcementRule
    ).where(
        PolicyEnforcementRule.id
            != rule.id,
        PolicyEnforcementRule.rule_key
            == rule.rule_key,
        PolicyEnforcementRule.domain
            == rule.domain,
        PolicyEnforcementRule.target_agent_slug
            == rule.target_agent_slug,
        PolicyEnforcementRule.target_module
            == rule.target_module,
        PolicyEnforcementRule.status
            == "active",
    )

    previous_rules = (
        await db.execute(query)
    ).scalars().all()

    for previous in previous_rules:
        previous.status = "superseded"
        previous.superseded_by_rule_id = rule.id

        if effective_from:
            previous_end = (
                effective_from
                - timedelta(days=1)
            )

            if (
                previous.effective_to is None
                or previous.effective_to
                > previous_end
            ):
                previous.effective_to = previous_end

    # --------------------------------------------------------
    # Activate new rule
    # --------------------------------------------------------
    rule.status = "active"
    rule.effective_from = effective_from
    rule.activated_by = actor
    rule.activated_at = datetime.now(
        timezone.utc
    )

    # Mark source impact item as applied.
    if rule.impact_item_id:
        item = (
            await db.execute(
                select(
                    PolicyImpactItem
                ).where(
                    PolicyImpactItem.id
                        == rule.impact_item_id
                )
            )
        ).scalars().first()

        if item:
            item.status = "applied"
            item.applied_by = actor
            item.applied_at = datetime.now(
                timezone.utc
            )

    return {
        "rule": rule,
        "result": "activated",
        "superseded_count":
            len(previous_rules),
    }


async def _refresh_policy_assessment_status(
    db: AsyncSession,
    assessment: PolicyImpactAssessment,
):
    """
    Assessment is complete only when:
    - no future/scheduled safe rules remain, and
    - no open policy/system mismatch remains.
    """

    rules = (
        await db.execute(
            select(
                PolicyEnforcementRule
            ).join(
                PolicyImpactItem,
                PolicyImpactItem.id
                    == PolicyEnforcementRule
                    .impact_item_id,
            ).where(
                PolicyImpactItem.assessment_id
                    == assessment.id
            )
        )
    ).scalars().all()

    mismatches = (
        await db.execute(
            select(
                PolicySystemMismatch
            ).join(
                PolicyImpactItem,
                PolicyImpactItem.id
                    == PolicySystemMismatch
                    .impact_item_id,
            ).where(
                PolicyImpactItem.assessment_id
                    == assessment.id,
                PolicySystemMismatch.status
                    == "open",
            )
        )
    ).scalars().all()

    has_waiting_rule = any(
        row.status
        in {
            "pending_activation",
            "scheduled",
        }
        for row in rules
    )

    if (
        not has_waiting_rule
        and not mismatches
    ):
        assessment.status = "completed"
        assessment.completed_at = datetime.now(
            timezone.utc
        )
    else:
        assessment.status = "in_progress"
        assessment.completed_at = None


@app.post(
    "/api/policy-impact/assessments/{assessment_id}/activate"
)
async def activate_policy_impact_assessment(
    assessment_id: uuid.UUID,
    as_of_date: date | None = None,
    db: AsyncSession = Depends(get_db),
):
    """
    Prepare/activate all safe enforcement rules generated by
    a policy impact assessment.

    Technical changes are deliberately excluded.
    """

    effective_day = (
        as_of_date
        or date.today()
    )

    assessment = (
        await db.execute(
            select(
                PolicyImpactAssessment
            ).where(
                PolicyImpactAssessment.id
                    == assessment_id
            )
        )
    ).scalars().first()

    if not assessment:
        raise HTTPException(
            status_code=404,
            detail=(
                "Policy impact assessment "
                "not found"
            ),
        )

    version = (
        await db.execute(
            select(
                HRPolicyVersion
            ).where(
                HRPolicyVersion.id
                    == assessment
                    .policy_version_id
            )
        )
    ).scalars().first()

    if not version:
        raise HTTPException(
            status_code=404,
            detail="Policy version not found",
        )

    if (
        version.status != "approved"
        or not version.is_current
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Only the current approved "
                "policy version can activate "
                "enforcement rules."
            ),
        )

    rules = (
        await db.execute(
            select(
                PolicyEnforcementRule
            ).join(
                PolicyImpactItem,
                PolicyImpactItem.id
                    == PolicyEnforcementRule
                    .impact_item_id,
            ).where(
                PolicyImpactItem.assessment_id
                    == assessment.id,
                PolicyEnforcementRule.status.in_(
                    [
                        "pending_activation",
                        "scheduled",
                        "active",
                    ]
                ),
            ).order_by(
                PolicyEnforcementRule
                .created_at.asc()
            )
        )
    ).scalars().all()

    activated = []
    scheduled = []
    unchanged = []
    superseded_total = 0

    for rule in rules:
        # Already-active rule does not need
        # repeated activation.
        if rule.status == "active":
            unchanged.append(rule)
            continue

        result = (
            await _activate_policy_enforcement_rule(
                db,
                rule,
                as_of_date=
                    effective_day,
                actor="user",
            )
        )

        if result["result"] == "activated":
            activated.append(rule)
            superseded_total += int(
                result.get(
                    "superseded_count",
                    0,
                )
            )

        elif result["result"] == "scheduled":
            scheduled.append(rule)

        else:
            unchanged.append(rule)

    await _refresh_policy_assessment_status(
        db,
        assessment,
    )

    await write_audit_log(
        db,
        actor="user",
        action=(
            "policy.enforcement.activation"
        ),
        details={
            "assessment_id":
                str(assessment.id),
            "policy_version_id":
                str(version.id),
            "as_of_date":
                effective_day.isoformat(),
            "activated":
                len(activated),
            "scheduled":
                len(scheduled),
            "unchanged":
                len(unchanged),
            "superseded":
                superseded_total,
            "assessment_status":
                assessment.status,
        },
    )

    await db.commit()

    for row in (
        activated
        + scheduled
        + unchanged
    ):
        await db.refresh(row)

    await db.refresh(assessment)

    return {
        "status": "ok",
        "as_of_date":
            effective_day,
        "assessment_status":
            assessment.status,
        "activated_count":
            len(activated),
        "scheduled_count":
            len(scheduled),
        "unchanged_count":
            len(unchanged),
        "superseded_count":
            superseded_total,
        "activated_rules": [
            _policy_enforcement_rule_payload(
                row
            )
            for row in activated
        ],
        "scheduled_rules": [
            _policy_enforcement_rule_payload(
                row
            )
            for row in scheduled
        ],
    }


@app.post(
    "/api/policy-impact/enforcement-rules/enforce-due"
)
async def enforce_due_policy_rules(
    as_of_date: date | None = None,
    db: AsyncSession = Depends(get_db),
):
    """
    Activate all scheduled/pending policy rules whose
    effective date has arrived.

    This is safe to call repeatedly.
    """

    effective_day = (
        as_of_date
        or date.today()
    )

    due_rules = (
        await db.execute(
            select(
                PolicyEnforcementRule
            ).where(
                PolicyEnforcementRule.status.in_(
                    [
                        "pending_activation",
                        "scheduled",
                    ]
                ),
                (
                    PolicyEnforcementRule
                    .effective_from
                    .is_(None)
                    |
                    (
                        PolicyEnforcementRule
                        .effective_from
                        <= effective_day
                    )
                ),
            ).order_by(
                PolicyEnforcementRule
                .effective_from.asc(),
                PolicyEnforcementRule
                .created_at.asc(),
            )
        )
    ).scalars().all()

    activated = []
    superseded_total = 0

    assessment_ids = set()

    for rule in due_rules:
        result = (
            await _activate_policy_enforcement_rule(
                db,
                rule,
                as_of_date=
                    effective_day,
                actor=(
                    "system:policy_enforcement"
                ),
            )
        )

        if result["result"] != "activated":
            continue

        activated.append(rule)

        superseded_total += int(
            result.get(
                "superseded_count",
                0,
            )
        )

        if rule.impact_item_id:
            item = (
                await db.execute(
                    select(
                        PolicyImpactItem
                    ).where(
                        PolicyImpactItem.id
                            == rule.impact_item_id
                    )
                )
            ).scalars().first()

            if item:
                assessment_ids.add(
                    item.assessment_id
                )

    for assessment_id in assessment_ids:
        assessment = (
            await db.execute(
                select(
                    PolicyImpactAssessment
                ).where(
                    PolicyImpactAssessment.id
                        == assessment_id
                )
            )
        ).scalars().first()

        if assessment:
            await _refresh_policy_assessment_status(
                db,
                assessment,
            )

    if activated:
        await write_audit_log(
            db,
            actor=(
                "system:policy_enforcement"
            ),
            action=(
                "policy.enforcement.due_rules_activated"
            ),
            details={
                "as_of_date":
                    effective_day.isoformat(),
                "activated":
                    len(activated),
                "superseded":
                    superseded_total,
            },
        )

    await db.commit()

    return {
        "status": "ok",
        "as_of_date":
            effective_day,
        "activated_count":
            len(activated),
        "superseded_count":
            superseded_total,
    }


@app.get(
    "/api/policy-impact/effective-rules"
)
async def get_effective_policy_rules(
    as_of_date: date | None = None,
    domain: str | None = None,
    target_agent_slug: str | None = None,
    target_module: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    """
    Historical/current effective-rule resolver.

    Allows the system to determine exactly which policy
    rule governed a transaction on a given date.
    """

    effective_day = (
        as_of_date
        or date.today()
    )

    query = select(
        PolicyEnforcementRule
    ).where(
        PolicyEnforcementRule.status.in_(
            [
                "active",
                "superseded",
            ]
        ),
        (
            PolicyEnforcementRule
            .effective_from
            .is_(None)
            |
            (
                PolicyEnforcementRule
                .effective_from
                <= effective_day
            )
        ),
        (
            PolicyEnforcementRule
            .effective_to
            .is_(None)
            |
            (
                PolicyEnforcementRule
                .effective_to
                >= effective_day
            )
        ),
    )

    if domain:
        query = query.where(
            PolicyEnforcementRule.domain
                == domain.strip().lower()
        )

    if target_agent_slug:
        query = query.where(
            PolicyEnforcementRule
            .target_agent_slug
            == target_agent_slug
            .strip()
            .lower()
        )

    if target_module:
        query = query.where(
            PolicyEnforcementRule
            .target_module
            == target_module
            .strip()
            .lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyEnforcementRule
                .rule_key.asc(),
                PolicyEnforcementRule
                .effective_from.desc(),
            )
        )
    ).scalars().all()

    return {
        "as_of_date":
            effective_day,
        "count":
            len(rows),
        "rules": [
            _policy_enforcement_rule_payload(
                row
            )
            for row in rows
        ],
    }




# ============================================================
# Shared - Policy Technical Verification Workflow
# ============================================================

class PolicyTechnicalVerificationRequest(BaseModel):
    passed: bool
    verification_method: str = "manual_test"
    test_summary: str
    test_results: dict = {}
    evidence: dict = {}
    verified_by: str = "agent:it"


def _policy_technical_verification_payload(row):
    return {
        "id":
            row.id,
        "mismatch_id":
            row.mismatch_id,
        "task_id":
            row.task_id,
        "impact_item_id":
            row.impact_item_id,
        "assessment_id":
            row.assessment_id,
        "policy_version_id":
            row.policy_version_id,
        "status":
            row.status,
        "verification_method":
            row.verification_method,
        "test_summary":
            row.test_summary,
        "test_results":
            row.test_results,
        "evidence":
            row.evidence,
        "verified_by":
            row.verified_by,
        "verified_at":
            row.verified_at,
        "approval_id":
            row.approval_id,
        "final_decision_by":
            row.final_decision_by,
        "final_decision_at":
            row.final_decision_at,
        "final_decision_notes":
            row.final_decision_notes,
        "created_at":
            row.created_at,
        "updated_at":
            row.updated_at,
    }


@app.post(
    "/api/policy-impact/mismatches/{mismatch_id}/verify"
)
async def verify_policy_system_change(
    mismatch_id: uuid.UUID,
    request: PolicyTechnicalVerificationRequest,
    db: AsyncSession = Depends(get_db),
):
    """
    Record technical verification for a policy-driven IT change.

    Required workflow:
    IT Task completed
        -> technical verification
        -> if failed: task returns to in_progress
        -> if passed: user approval is created
        -> mismatch remains OPEN until final user approval
    """

    mismatch = (
        await db.execute(
            select(
                PolicySystemMismatch
            ).where(
                PolicySystemMismatch.id
                    == mismatch_id
            )
        )
    ).scalars().first()

    if not mismatch:
        raise HTTPException(
            status_code=404,
            detail=(
                "Policy/System mismatch not found"
            ),
        )

    if mismatch.status != "open":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only an open Policy/System mismatch "
                "can be technically verified."
            ),
        )

    if not mismatch.task_id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Mismatch is not linked to an IT task."
            ),
        )

    task = (
        await db.execute(
            select(Task).where(
                Task.id
                    == mismatch.task_id
            )
        )
    ).scalars().first()

    if not task:
        raise HTTPException(
            status_code=404,
            detail=(
                "Linked IT task not found"
            ),
        )

    if task.status != "completed":
        raise HTTPException(
            status_code=409,
            detail=(
                "The linked IT task must be completed "
                "before technical verification."
            ),
        )

    if not task.agent_id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Linked policy-change task is not "
                "assigned to an agent."
            ),
        )

    assigned_agent = (
        await db.execute(
            select(Agent).where(
                Agent.id == task.agent_id
            )
        )
    ).scalars().first()

    if (
        not assigned_agent
        or assigned_agent.slug != "it"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Policy technical verification requires "
                "an IT Agent task."
            ),
        )

    summary = (
        request.test_summary
        or ""
    ).strip()

    if len(summary) < 5:
        raise HTTPException(
            status_code=400,
            detail=(
                "Technical verification test summary "
                "is required."
            ),
        )

    verification_method = (
        request.verification_method
        or "manual_test"
    ).strip().lower()

    if not verification_method:
        verification_method = "manual_test"

    verified_by = (
        request.verified_by
        or "agent:it"
    ).strip()

    if not verified_by:
        verified_by = "agent:it"

    # --------------------------------------------------------
    # Resolve impact item + assessment
    # --------------------------------------------------------
    impact_item = None
    assessment = None

    if mismatch.impact_item_id:
        impact_item = (
            await db.execute(
                select(
                    PolicyImpactItem
                ).where(
                    PolicyImpactItem.id
                        == mismatch.impact_item_id
                )
            )
        ).scalars().first()

    if impact_item:
        assessment = (
            await db.execute(
                select(
                    PolicyImpactAssessment
                ).where(
                    PolicyImpactAssessment.id
                        == impact_item.assessment_id
                )
            )
        ).scalars().first()

    # --------------------------------------------------------
    # Prevent duplicate unresolved successful verification
    # --------------------------------------------------------
    existing = (
        await db.execute(
            select(
                PolicyTechnicalVerification
            ).where(
                PolicyTechnicalVerification
                    .mismatch_id
                    == mismatch.id,
                PolicyTechnicalVerification
                    .status.in_(
                        [
                            "awaiting_approval",
                            "approved",
                        ]
                    ),
            ).order_by(
                PolicyTechnicalVerification
                    .created_at.desc()
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "This mismatch already has a successful "
                "technical verification awaiting or holding "
                "final approval."
            ),
        )

    verification = (
        PolicyTechnicalVerification(
            mismatch_id=
                mismatch.id,
            task_id=
                task.id,
            impact_item_id=(
                impact_item.id
                if impact_item
                else mismatch.impact_item_id
            ),
            assessment_id=(
                assessment.id
                if assessment
                else None
            ),
            policy_version_id=
                mismatch.policy_version_id,
            status=(
                "awaiting_approval"
                if request.passed
                else "failed"
            ),
            verification_method=
                verification_method[:80],
            test_summary=
                summary,
            test_results=(
                request.test_results
                if isinstance(
                    request.test_results,
                    dict,
                )
                else {}
            ),
            evidence=(
                request.evidence
                if isinstance(
                    request.evidence,
                    dict,
                )
                else {}
            ),
            verified_by=
                verified_by[:150],
            verified_at=
                datetime.now(
                    timezone.utc
                ),
        )
    )

    db.add(verification)
    await db.flush()

    approval = None

    # ========================================================
    # FAILED VERIFICATION
    # ========================================================
    if not request.passed:
        # Completing a task is not enough.
        # Failed verification returns technical work
        # to the IT Agent.
        task.status = "in_progress"
        task.completed_at = None

        if impact_item:
            impact_item.status = "pending"

        await write_audit_log(
            db,
            actor=verified_by,
            action=(
                "policy.technical_verification.failed"
            ),
            details={
                "verification_id":
                    str(verification.id),
                "mismatch_id":
                    str(mismatch.id),
                "task_id":
                    str(task.id),
                "policy_version_id":
                    str(
                        mismatch.policy_version_id
                    ),
                "assessment_id": (
                    str(assessment.id)
                    if assessment
                    else None
                ),
                "task_status":
                    task.status,
                "mismatch_status":
                    mismatch.status,
                "verification_method":
                    verification_method,
            },
        )

    # ========================================================
    # PASSED VERIFICATION -> USER APPROVAL
    # ========================================================
    else:
        risk_level = (
            "critical"
            if mismatch.severity
                == "critical"
            else "high"
            if mismatch.severity
                == "high"
            else "medium"
            if mismatch.severity
                == "medium"
            else "low"
        )

        approval = Approval(
            agent_id=
                assigned_agent.id,
            title=(
                "Approve verified policy system change"
            ),
            description=(
                "Technical verification passed for "
                "a policy-driven system change. "
                "Final user approval is required before "
                "the Policy/System mismatch can be closed.\n\n"
                f"Module: "
                f"{mismatch.affected_module or 'N/A'}\n"
                f"Component: "
                f"{mismatch.affected_component or 'N/A'}\n"
                f"Verification: {summary}"
            ),
            action_type=(
                "policy_technical_verification_acceptance"
            ),
            risk_level=
                risk_level,
            status="pending",
            action_payload={
                "source":
                    "policy_impact_engine",
                "verification_id":
                    str(verification.id),
                "mismatch_id":
                    str(mismatch.id),
                "task_id":
                    str(task.id),
                "impact_item_id": (
                    str(impact_item.id)
                    if impact_item
                    else None
                ),
                "assessment_id": (
                    str(assessment.id)
                    if assessment
                    else None
                ),
                "policy_version_id":
                    str(
                        mismatch.policy_version_id
                    ),
                "affected_module":
                    mismatch.affected_module,
                "affected_component":
                    mismatch.affected_component,
                "verification_method":
                    verification_method,
                "test_summary":
                    summary,
            },
        )

        db.add(approval)
        await db.flush()

        verification.approval_id = (
            approval.id
        )

        # IMPORTANT:
        # Mismatch intentionally remains OPEN here.
        # Agent runtime must continue warning about it
        # until the user gives final approval.
        mismatch.status = "open"

        await write_audit_log(
            db,
            actor=verified_by,
            action=(
                "policy.technical_verification.passed"
            ),
            details={
                "verification_id":
                    str(verification.id),
                "approval_id":
                    str(approval.id),
                "mismatch_id":
                    str(mismatch.id),
                "task_id":
                    str(task.id),
                "policy_version_id":
                    str(
                        mismatch.policy_version_id
                    ),
                "assessment_id": (
                    str(assessment.id)
                    if assessment
                    else None
                ),
                "mismatch_status":
                    mismatch.status,
                "approval_status":
                    approval.status,
                "verification_method":
                    verification_method,
            },
        )

    await db.commit()

    await db.refresh(
        verification
    )
    await db.refresh(
        task
    )
    await db.refresh(
        mismatch
    )

    if impact_item:
        await db.refresh(
            impact_item
        )

    if approval:
        await db.refresh(
            approval
        )

    return {
        "status": "ok",
        "passed":
            bool(request.passed),
        "verification":
            _policy_technical_verification_payload(
                verification
            ),
        "task": {
            "id":
                task.id,
            "status":
                task.status,
            "completed_at":
                task.completed_at,
        },
        "mismatch": {
            "id":
                mismatch.id,
            "status":
                mismatch.status,
        },
        "approval": (
            {
                "id":
                    approval.id,
                "status":
                    approval.status,
                "action_type":
                    approval.action_type,
                "risk_level":
                    approval.risk_level,
            }
            if approval
            else None
        ),
    }


@app.get(
    "/api/policy-impact/technical-verifications"
)
async def list_policy_technical_verifications(
    mismatch_id: uuid.UUID | None = None,
    task_id: uuid.UUID | None = None,
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(
        PolicyTechnicalVerification
    )

    if mismatch_id:
        query = query.where(
            PolicyTechnicalVerification
                .mismatch_id
                == mismatch_id
        )

    if task_id:
        query = query.where(
            PolicyTechnicalVerification
                .task_id
                == task_id
        )

    if status:
        query = query.where(
            PolicyTechnicalVerification
                .status
                == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyTechnicalVerification
                    .created_at.desc()
            ).limit(200)
        )
    ).scalars().all()

    return [
        _policy_technical_verification_payload(
            row
        )
        for row in rows
    ]




# ============================================================
# Shared - Policy Technical Verification Final Approval
# ============================================================

async def _apply_policy_technical_approval_decision(
    db: AsyncSession,
    approval: Approval,
    *,
    approved: bool,
    decision_reason: str | None,
):
    """
    Execute the final user decision for a successfully verified
    policy-driven technical change.

    APPROVE:
    - verification -> approved
    - mismatch -> resolved
    - assessment status recalculated
    - approval.executed_at recorded

    REJECT:
    - verification -> rejected
    - mismatch remains open
    - IT task -> in_progress
    - impact item -> pending
    """

    payload = (
        approval.action_payload
        if isinstance(
            approval.action_payload,
            dict,
        )
        else {}
    )

    required = {
        "verification_id",
        "mismatch_id",
        "task_id",
        "policy_version_id",
    }

    missing = [
        key
        for key in required
        if not payload.get(key)
    ]

    if missing:
        raise HTTPException(
            status_code=409,
            detail=(
                "Policy technical approval payload "
                "is incomplete: "
                + ", ".join(sorted(missing))
            ),
        )

    def parse_uuid(
        value,
        field_name,
    ):
        try:
            return uuid.UUID(
                str(value)
            )
        except (
            ValueError,
            TypeError,
            AttributeError,
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Invalid UUID in policy technical "
                    f"approval payload: {field_name}"
                ),
            )

    verification_id = parse_uuid(
        payload["verification_id"],
        "verification_id",
    )

    mismatch_id = parse_uuid(
        payload["mismatch_id"],
        "mismatch_id",
    )

    task_id = parse_uuid(
        payload["task_id"],
        "task_id",
    )

    policy_version_id = parse_uuid(
        payload["policy_version_id"],
        "policy_version_id",
    )

    verification = (
        await db.execute(
            select(
                PolicyTechnicalVerification
            ).where(
                PolicyTechnicalVerification.id
                    == verification_id
            )
        )
    ).scalars().first()

    if not verification:
        raise HTTPException(
            status_code=404,
            detail=(
                "Policy technical verification "
                "linked to this approval was not found."
            ),
        )

    mismatch = (
        await db.execute(
            select(
                PolicySystemMismatch
            ).where(
                PolicySystemMismatch.id
                    == mismatch_id
            )
        )
    ).scalars().first()

    if not mismatch:
        raise HTTPException(
            status_code=404,
            detail=(
                "Policy/System mismatch linked "
                "to this approval was not found."
            ),
        )

    task = (
        await db.execute(
            select(Task).where(
                Task.id == task_id
            )
        )
    ).scalars().first()

    if not task:
        raise HTTPException(
            status_code=404,
            detail=(
                "IT task linked to this approval "
                "was not found."
            ),
        )

    # --------------------------------------------------------
    # Cross-link integrity guards
    # --------------------------------------------------------
    if verification.approval_id != approval.id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Verification is not linked to "
                "this approval."
            ),
        )

    if verification.mismatch_id != mismatch.id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Verification/mismatch linkage "
                "does not match."
            ),
        )

    if verification.task_id != task.id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Verification/task linkage "
                "does not match."
            ),
        )

    if (
        verification.policy_version_id
        != policy_version_id
        or mismatch.policy_version_id
        != policy_version_id
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Policy version linkage does not match."
            ),
        )

    if verification.status != "awaiting_approval":
        raise HTTPException(
            status_code=409,
            detail=(
                "Technical verification is no longer "
                "awaiting final approval."
            ),
        )

    now = datetime.now(
        timezone.utc
    )

    # --------------------------------------------------------
    # Resolve optional linked impact item + assessment
    # --------------------------------------------------------
    impact_item = None
    assessment = None

    if verification.impact_item_id:
        impact_item = (
            await db.execute(
                select(
                    PolicyImpactItem
                ).where(
                    PolicyImpactItem.id
                        == verification.impact_item_id
                )
            )
        ).scalars().first()

    assessment_id = (
        verification.assessment_id
        or (
            impact_item.assessment_id
            if impact_item
            else None
        )
    )

    if assessment_id:
        assessment = (
            await db.execute(
                select(
                    PolicyImpactAssessment
                ).where(
                    PolicyImpactAssessment.id
                        == assessment_id
                )
            )
        ).scalars().first()

    # ========================================================
    # USER APPROVED VERIFIED TECHNICAL CHANGE
    # ========================================================
    if approved:
        verification.status = "approved"
        verification.final_decision_by = "user"
        verification.final_decision_at = now
        verification.final_decision_notes = (
            decision_reason
        )

        mismatch.status = "resolved"
        mismatch.resolution_notes = (
            decision_reason
            or (
                "Technical implementation verified "
                "and accepted by final user approval."
            )
        )
        mismatch.resolved_by = "user"
        mismatch.resolved_at = now

        if impact_item:
            impact_item.status = "verified"
            impact_item.applied_by = "user"
            impact_item.applied_at = now

        # Approval now represents an executed internal
        # compliance decision, not merely a decision record.
        approval.executed_at = now

        if assessment:
            await _refresh_policy_assessment_status(
                db,
                assessment,
            )

        await write_audit_log(
            db,
            actor="user",
            action=(
                "policy.technical_change.final_approved"
            ),
            details={
                "approval_id":
                    str(approval.id),
                "verification_id":
                    str(verification.id),
                "mismatch_id":
                    str(mismatch.id),
                "task_id":
                    str(task.id),
                "impact_item_id": (
                    str(impact_item.id)
                    if impact_item
                    else None
                ),
                "assessment_id": (
                    str(assessment.id)
                    if assessment
                    else None
                ),
                "policy_version_id":
                    str(policy_version_id),
                "mismatch_status":
                    mismatch.status,
                "verification_status":
                    verification.status,
                "assessment_status": (
                    assessment.status
                    if assessment
                    else None
                ),
            },
        )

    # ========================================================
    # USER REJECTED VERIFIED TECHNICAL CHANGE
    # ========================================================
    else:
        verification.status = "rejected"
        verification.final_decision_by = "user"
        verification.final_decision_at = now
        verification.final_decision_notes = (
            decision_reason
        )

        # Mismatch intentionally remains OPEN.
        mismatch.status = "open"
        mismatch.resolution_notes = None
        mismatch.resolved_by = None
        mismatch.resolved_at = None

        # Reopen implementation work.
        task.status = "in_progress"
        task.completed_at = None

        if impact_item:
            impact_item.status = "pending"
            impact_item.applied_by = None
            impact_item.applied_at = None

        if assessment:
            await _refresh_policy_assessment_status(
                db,
                assessment,
            )

        await write_audit_log(
            db,
            actor="user",
            action=(
                "policy.technical_change.final_rejected"
            ),
            details={
                "approval_id":
                    str(approval.id),
                "verification_id":
                    str(verification.id),
                "mismatch_id":
                    str(mismatch.id),
                "task_id":
                    str(task.id),
                "impact_item_id": (
                    str(impact_item.id)
                    if impact_item
                    else None
                ),
                "assessment_id": (
                    str(assessment.id)
                    if assessment
                    else None
                ),
                "policy_version_id":
                    str(policy_version_id),
                "task_status":
                    task.status,
                "mismatch_status":
                    mismatch.status,
                "verification_status":
                    verification.status,
                "assessment_status": (
                    assessment.status
                    if assessment
                    else None
                ),
            },
        )



# ============================================================
# Shared - Policy Change Decision Execution
# ============================================================

POLICY_CHANGE_DECISIONS = {
    "approve_add",
    "approve_modify",
    "approve_remove",
    "keep_existing",
    "ignore",
}

# Configuration rules may only bypass IT when the target
# application module is explicitly wired to consume that
# PolicyEnforcementRule at runtime.
#
# Empty by design for now. Agent-behavior rules are already
# consumed dynamically by chat_with_agent(), but HR calculators
# and operational modules are not yet generic rule consumers.
POLICY_DIRECT_CONFIGURATION_RULE_KEYS = set()


class PolicyChangeDecisionRequest(BaseModel):
    decision: str
    notes: str | None = None


async def _refresh_policy_change_assessment_status(
    db: AsyncSession,
    assessment: PolicyImpactAssessment,
):
    """
    A policy assessment may not progress to enforcement/completion
    while any Change Decision is still pending.
    """

    decisions = (
        await db.execute(
            select(
                PolicyChangeDecision
            ).where(
                PolicyChangeDecision.assessment_id
                    == assessment.id
            )
        )
    ).scalars().all()

    if any(
        row.decision == "pending"
        or row.status == "pending"
        for row in decisions
    ):
        assessment.status = "awaiting_decision"
        assessment.completed_at = None
        return

    # Once all user decisions are made, reuse the existing
    # enforcement/mismatch completion rules.
    await _refresh_policy_assessment_status(
        db,
        assessment,
    )


async def _create_policy_it_change(
    db: AsyncSession,
    *,
    policy: HRPolicy,
    version: HRPolicyVersion,
    assessment: PolicyImpactAssessment,
    item: PolicyImpactItem,
):
    """
    Create IT Task + Policy/System Mismatch only AFTER
    explicit user approval of the proposed change.
    """

    it_agent = await _get_agent_by_slug(
        db,
        "it",
    )

    acceptance = (
        item.acceptance_criteria
        if isinstance(
            item.acceptance_criteria,
            dict,
        )
        else {}
    )

    criteria_items = acceptance.get(
        "items",
        [],
    )

    if not isinstance(
        criteria_items,
        list,
    ):
        criteria_items = []

    criteria_text = "\n".join(
        f"- {str(value)}"
        for value in criteria_items
    )

    task = Task(
        agent_id=(
            it_agent.id
            if it_agent
            else None
        ),
        title=(
            f"Policy Change: "
            f"{policy.code} — "
            f"{item.affected_module or item.impact_type}"
        )[:255],
        description=(
            f"User-approved policy change from "
            f"version {version.version_number} requires "
            f"technical implementation.\n\n"
            f"Impact: {item.description}\n\n"
            f"Recommended action: "
            f"{item.recommended_action or 'Review and implement'}"
            + (
                "\n\nAcceptance Criteria:\n"
                + criteria_text
                if criteria_text
                else ""
            )
        ),
        status="pending",
        priority=(
            "critical"
            if item.severity == "critical"
            else "high"
            if item.severity == "high"
            else "normal"
        ),
        payload={
            "source":
                "policy_impact_engine",
            "policy_id":
                str(policy.id),
            "policy_code":
                policy.code,
            "policy_version_id":
                str(version.id),
            "policy_version":
                version.version_number,
            "impact_assessment_id":
                str(assessment.id),
            "impact_item_id":
                str(item.id),
            "impact_type":
                item.impact_type,
            "change_type":
                item.change_type,
            "affected_module":
                item.affected_module,
            "affected_component":
                item.affected_component,
            "current_value":
                item.current_value,
            "proposed_value":
                item.proposed_value,
            "acceptance_criteria":
                item.acceptance_criteria,
            "effective_date": (
                version.effective_date.isoformat()
                if version.effective_date
                else None
            ),
        },
    )

    db.add(task)
    await db.flush()

    item.task_id = task.id
    item.status = "pending"

    mismatch = PolicySystemMismatch(
        policy_version_id=
            version.id,
        impact_item_id=
            item.id,
        task_id=
            task.id,
        mismatch_type=
            "policy_system_mismatch",
        domain=
            item.domain,
        affected_module=
            item.affected_module,
        affected_component=
            item.affected_component,
        description=(
            "User approved this policy change, "
            "but the required technical system behavior "
            "is not yet verified as implemented. "
            + item.description
        ),
        expected_behavior=(
            item.recommended_action
            or item.description
        ),
        current_behavior=(
            str(item.current_value)
            if item.current_value
            else (
                "Current system behavior requires "
                "technical verification."
            )
        ),
        severity=
            item.severity,
        status="open",
        detected_by=
            "agent:hr",
        effective_date=
            version.effective_date,
    )

    db.add(mismatch)
    await db.flush()

    return task, mismatch


@app.get(
    "/api/policy-impact/change-decisions"
)
async def list_policy_change_decisions(
    assessment_id: uuid.UUID | None = None,
    policy_version_id: uuid.UUID | None = None,
    decision: str | None = None,
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = select(
        PolicyChangeDecision
    )

    if assessment_id:
        query = query.where(
            PolicyChangeDecision.assessment_id
                == assessment_id
        )

    if policy_version_id:
        query = query.where(
            PolicyChangeDecision.policy_version_id
                == policy_version_id
        )

    if decision:
        query = query.where(
            PolicyChangeDecision.decision
                == decision.strip().lower()
        )

    if status:
        query = query.where(
            PolicyChangeDecision.status
                == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                PolicyChangeDecision.created_at.asc()
            )
        )
    ).scalars().all()

    return [
        _policy_change_decision_payload(
            row
        )
        for row in rows
    ]


@app.post(
    "/api/policy-impact/change-decisions/{decision_id}/decide"
)
async def decide_policy_change(
    decision_id: uuid.UUID,
    request: PolicyChangeDecisionRequest,
    db: AsyncSession = Depends(get_db),
):
    requested_decision = (
        request.decision
        or ""
    ).strip().lower()

    if requested_decision not in POLICY_CHANGE_DECISIONS:
        raise HTTPException(
            status_code=400,
            detail=(
                "Invalid decision. Allowed: "
                "approve_add, approve_modify, approve_remove, "
                "keep_existing, ignore."
            ),
        )

    decision = (
        await db.execute(
            select(
                PolicyChangeDecision
            ).where(
                PolicyChangeDecision.id
                    == decision_id
            )
        )
    ).scalars().first()

    if not decision:
        raise HTTPException(
            status_code=404,
            detail="Policy change decision not found",
        )

    if (
        decision.decision != "pending"
        or decision.status != "pending"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "This policy change has already "
                "received a user decision."
            ),
        )

    item = (
        await db.execute(
            select(
                PolicyImpactItem
            ).where(
                PolicyImpactItem.id
                    == decision.impact_item_id
            )
        )
    ).scalars().first()

    if not item:
        raise HTTPException(
            status_code=404,
            detail="Policy impact item not found",
        )

    assessment = (
        await db.execute(
            select(
                PolicyImpactAssessment
            ).where(
                PolicyImpactAssessment.id
                    == decision.assessment_id
            )
        )
    ).scalars().first()

    if not assessment:
        raise HTTPException(
            status_code=404,
            detail="Policy impact assessment not found",
        )

    version = (
        await db.execute(
            select(
                HRPolicyVersion
            ).where(
                HRPolicyVersion.id
                    == decision.policy_version_id
            )
        )
    ).scalars().first()

    if not version:
        raise HTTPException(
            status_code=404,
            detail="Policy version not found",
        )

    policy = (
        await db.execute(
            select(HRPolicy).where(
                HRPolicy.id == version.policy_id
            )
        )
    ).scalars().first()

    if not policy:
        raise HTTPException(
            status_code=404,
            detail="Policy master record not found",
        )

    if (
        version.status != "approved"
        or not version.is_current
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Change decisions can only execute "
                "against the current approved policy version."
            ),
        )

    # --------------------------------------------------------
    # Prevent accidental approval action mismatch.
    # --------------------------------------------------------
    expected_approval = {
        "add": "approve_add",
        "modify": "approve_modify",
        "remove": "approve_remove",
    }.get(
        item.change_type
    )

    if (
        requested_decision.startswith("approve_")
        and expected_approval
        and requested_decision != expected_approval
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                f"This impact is classified as "
                f"'{item.change_type}'. Use "
                f"'{expected_approval}' or choose "
                f"keep_existing / ignore."
            ),
        )

    if (
        item.change_type == "no_change"
        and requested_decision.startswith(
            "approve_"
        )
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "A no_change impact cannot be approved "
                "as Add/Modify/Remove."
            ),
        )

    now = datetime.now(
        timezone.utc
    )

    notes = (
        request.notes.strip()
        if request.notes
        else None
    )

    decision.decision = (
        requested_decision
    )
    decision.decision_notes = notes
    decision.decided_by = "user"
    decision.decided_at = now

    created_rule = None
    created_task = None
    created_mismatch = None
    enforcement_result = None

    # ========================================================
    # KEEP EXISTING
    # ========================================================
    if requested_decision == "keep_existing":
        decision.status = "executed"
        decision.executed_at = now

        item.status = "kept_existing"

    # ========================================================
    # IGNORE
    # ========================================================
    elif requested_decision == "ignore":
        decision.status = "executed"
        decision.executed_at = now

        item.status = "ignored"

    # ========================================================
    # USER APPROVED CHANGE
    # ========================================================
    else:
        payload = (
            decision.execution_payload
            if isinstance(
                decision.execution_payload,
                dict,
            )
            else {}
        )

        rule_candidate = payload.get(
            "rule_candidate",
            {},
        )

        if not isinstance(
            rule_candidate,
            dict,
        ):
            rule_candidate = {}

        rule_key = str(
            rule_candidate.get(
                "rule_key",
                "",
            )
            or ""
        ).strip()

        # Direct runtime rule support is capability-based.
        #
        # Agent behavior is already consumed by the dynamic
        # policy context injected into every Agent.
        direct_agent_rule = (
            item.impact_type == "agent_behavior"
            and item.enforcement_mode == "automatic"
            and item.auto_applicable
            and bool(rule_key)
        )

        # Application configuration is NOT considered directly
        # enforceable until that exact rule key is registered as
        # a real runtime configuration consumer.
        direct_configuration_rule = (
            item.impact_type == "configuration"
            and item.enforcement_mode == "configuration"
            and item.auto_applicable
            and bool(rule_key)
            and rule_key
                in POLICY_DIRECT_CONFIGURATION_RULE_KEYS
        )

        safe_rule_mode = (
            direct_agent_rule
            or direct_configuration_rule
        )

        # Effective dates are controlled exclusively by the
        # approved Policy Version metadata. AI-extracted dates
        # inside rule_value must never create a second timeline.
        raw_rule_value = (
            rule_candidate.get(
                "rule_value",
                {},
            )
            if isinstance(
                rule_candidate.get(
                    "rule_value",
                    {},
                ),
                dict,
            )
            else {}
        )

        sanitized_rule_value = dict(
            raw_rule_value
        )

        sanitized_rule_value.pop(
            "effective_date",
            None,
        )

        sanitized_rule_value.pop(
            "effective_date_in_text",
            None,
        )

        # ----------------------------------------------------
        # SAFE ADD / MODIFY RULE
        # ----------------------------------------------------
        if (
            safe_rule_mode
            and requested_decision
            in {
                "approve_add",
                "approve_modify",
            }
            and rule_key
        ):
            rule_type = str(
                rule_candidate.get(
                    "rule_type",
                    "",
                )
                or (
                    "instruction"
                    if item.impact_type
                    == "agent_behavior"
                    else "configuration"
                )
            ).strip().lower()

            created_rule = PolicyEnforcementRule(
                policy_version_id=
                    version.id,
                impact_item_id=
                    item.id,
                rule_type=
                    rule_type[:50],
                rule_key=
                    rule_key[:180],
                domain=
                    item.domain,
                target_agent_slug=(
                    str(
                        rule_candidate.get(
                            "target_agent_slug",
                            "",
                        )
                        or ""
                    ).strip().lower()
                    or None
                ),
                target_module=(
                    str(
                        rule_candidate.get(
                            "target_module",
                            "",
                        )
                        or ""
                    ).strip().lower()
                    or item.affected_module
                ),
                rule_value=
                    sanitized_rule_value,
                source_clause=(
                    str(
                        rule_candidate.get(
                            "source_clause",
                            "",
                        )
                        or ""
                    ).strip()
                    or item.description
                ),
                status=
                    "pending_activation",
                effective_from=
                    version.effective_date,
            )

            db.add(created_rule)
            await db.flush()

            item.status = (
                "ready_for_enforcement"
            )

            activation = (
                await _activate_policy_enforcement_rule(
                    db,
                    created_rule,
                    as_of_date=date.today(),
                    actor="user",
                )
            )

            enforcement_result = (
                activation.get(
                    "result"
                )
            )

        # ----------------------------------------------------
        # SAFE REMOVE RULE
        # ----------------------------------------------------
        elif (
            safe_rule_mode
            and requested_decision
                == "approve_remove"
            and rule_key
        ):
            # A removal marker preserves historical rule history.
            # When effective, it supersedes the previous active rule.
            created_rule = PolicyEnforcementRule(
                policy_version_id=
                    version.id,
                impact_item_id=
                    item.id,
                rule_type="removal",
                rule_key=
                    rule_key[:180],
                domain=
                    item.domain,
                target_agent_slug=(
                    str(
                        rule_candidate.get(
                            "target_agent_slug",
                            "",
                        )
                        or ""
                    ).strip().lower()
                    or None
                ),
                target_module=(
                    str(
                        rule_candidate.get(
                            "target_module",
                            "",
                        )
                        or ""
                    ).strip().lower()
                    or item.affected_module
                ),
                rule_value={
                    "removed": True,
                    "action": "remove",
                },
                source_clause=(
                    str(
                        rule_candidate.get(
                            "source_clause",
                            "",
                        )
                        or ""
                    ).strip()
                    or item.description
                ),
                status=
                    "pending_activation",
                effective_from=
                    version.effective_date,
            )

            db.add(created_rule)
            await db.flush()

            item.status = (
                "ready_for_enforcement"
            )

            activation = (
                await _activate_policy_enforcement_rule(
                    db,
                    created_rule,
                    as_of_date=date.today(),
                    actor="user",
                )
            )

            enforcement_result = (
                activation.get(
                    "result"
                )
            )

        # ----------------------------------------------------
        # TECHNICAL CHANGE
        # ----------------------------------------------------
        elif (
            item.enforcement_mode == "it_task"
            or item.impact_type
            in POLICY_TECHNICAL_IMPACT_TYPES

            # Configuration changes that the application cannot
            # consume dynamically must become controlled IT work.
            or (
                item.impact_type == "configuration"
                and not safe_rule_mode
            )

            or (
                requested_decision
                == "approve_remove"
                and not rule_key
            )
        ):
            (
                created_task,
                created_mismatch,
            ) = await _create_policy_it_change(
                db,
                policy=policy,
                version=version,
                assessment=assessment,
                item=item,
            )

        # ----------------------------------------------------
        # DOCUMENTATION / MANUAL REVIEW / NO SYSTEM IMPACT
        # ----------------------------------------------------
        else:
            # Never record an approved Agent/Configuration
            # change as successful when no execution path exists.
            if (
                requested_decision.startswith(
                    "approve_"
                )
                and item.impact_type
                in {
                    "agent_behavior",
                    "configuration",
                }
            ):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Approved policy impact has no safe "
                        "execution path. Edit the proposal or "
                        "use Keep Existing / Ignore."
                    ),
                )

            item.status = "accepted"

        decision.status = "executed"
        decision.executed_at = now

    # --------------------------------------------------------
    # Recalculate assessment after this user decision.
    # --------------------------------------------------------
    await _refresh_policy_change_assessment_status(
        db,
        assessment,
    )

    await write_audit_log(
        db,
        actor="user",
        action="policy.change_decision.executed",
        details={
            "decision_id":
                str(decision.id),
            "assessment_id":
                str(assessment.id),
            "policy_id":
                str(policy.id),
            "policy_code":
                policy.code,
            "policy_version_id":
                str(version.id),
            "impact_item_id":
                str(item.id),
            "impact_type":
                item.impact_type,
            "change_type":
                item.change_type,
            "user_decision":
                requested_decision,
            "enforcement_mode":
                item.enforcement_mode,
            "rule_created":
                bool(created_rule),
            "rule_activation_result":
                enforcement_result,
            "it_task_created":
                bool(created_task),
            "mismatch_created":
                bool(created_mismatch),
            "assessment_status":
                assessment.status,
        },
    )

    await db.commit()

    await db.refresh(decision)
    await db.refresh(item)
    await db.refresh(assessment)

    if created_rule:
        await db.refresh(
            created_rule
        )

    if created_task:
        await db.refresh(
            created_task
        )

    if created_mismatch:
        await db.refresh(
            created_mismatch
        )

    return {
        "status": "ok",
        "decision":
            _policy_change_decision_payload(
                decision
            ),
        "impact_item":
            _policy_impact_item_payload(
                item
            ),
        "assessment": {
            "id":
                assessment.id,
            "status":
                assessment.status,
            "overall_risk":
                assessment.overall_risk,
            "completed_at":
                assessment.completed_at,
        },
        "enforcement_rule": (
            _policy_enforcement_rule_payload(
                created_rule
            )
            if created_rule
            else None
        ),
        "rule_activation_result":
            enforcement_result,
        "it_task": (
            {
                "id":
                    created_task.id,
                "title":
                    created_task.title,
                "status":
                    created_task.status,
                "priority":
                    created_task.priority,
            }
            if created_task
            else None
        ),
        "system_mismatch": (
            _policy_mismatch_payload(
                created_mismatch
            )
            if created_mismatch
            else None
        ),
    }



# ============================================================
# Shared - Policy Impact Proposal Editing
# ============================================================

class PolicyImpactProposalUpdateRequest(BaseModel):
    impact_type: str | None = None
    change_type: str | None = None
    affected_module: str | None = None
    affected_component: str | None = None
    description: str | None = None
    recommended_action: str | None = None
    severity: str | None = None
    enforcement_mode: str | None = None
    auto_applicable: bool | None = None
    current_value: dict | None = None
    proposed_value: dict | None = None
    acceptance_criteria: dict | None = None


@app.put(
    "/api/policy-impact/change-decisions/{decision_id}/proposal"
)
async def update_policy_impact_proposal(
    decision_id: uuid.UUID,
    request: PolicyImpactProposalUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    """
    Human review/edit of an AI-generated policy impact proposal.

    Editing is allowed ONLY while the related Change Decision
    is still pending. No rule, IT task or mismatch is created here.
    """

    decision = (
        await db.execute(
            select(
                PolicyChangeDecision
            ).where(
                PolicyChangeDecision.id
                    == decision_id
            )
        )
    ).scalars().first()

    if not decision:
        raise HTTPException(
            status_code=404,
            detail="Policy change decision not found",
        )

    if (
        decision.decision != "pending"
        or decision.status != "pending"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Only a pending policy impact proposal "
                "can be edited."
            ),
        )

    item = (
        await db.execute(
            select(
                PolicyImpactItem
            ).where(
                PolicyImpactItem.id
                    == decision.impact_item_id
            )
        )
    ).scalars().first()

    if not item:
        raise HTTPException(
            status_code=404,
            detail="Policy impact item not found",
        )

    changes = request.model_dump(
        exclude_unset=True
    )

    before = {
        "impact_type":
            item.impact_type,
        "change_type":
            item.change_type,
        "affected_module":
            item.affected_module,
        "affected_component":
            item.affected_component,
        "description":
            item.description,
        "recommended_action":
            item.recommended_action,
        "severity":
            item.severity,
        "enforcement_mode":
            item.enforcement_mode,
        "auto_applicable":
            item.auto_applicable,
        "current_value":
            item.current_value,
        "proposed_value":
            item.proposed_value,
        "acceptance_criteria":
            item.acceptance_criteria,
    }

    # --------------------------------------------------------
    # Validate controlled enums
    # --------------------------------------------------------
    if "impact_type" in changes:
        value = (
            changes["impact_type"]
            or ""
        ).strip().lower()

        if value not in POLICY_IMPACT_TYPES:
            raise HTTPException(
                status_code=400,
                detail="Invalid impact_type",
            )

        item.impact_type = value

    if "change_type" in changes:
        value = (
            changes["change_type"]
            or ""
        ).strip().lower()

        if value not in POLICY_IMPACT_CHANGE_TYPES:
            raise HTTPException(
                status_code=400,
                detail="Invalid change_type",
            )

        item.change_type = value

    if "severity" in changes:
        value = (
            changes["severity"]
            or ""
        ).strip().lower()

        if value not in POLICY_IMPACT_SEVERITIES:
            raise HTTPException(
                status_code=400,
                detail="Invalid severity",
            )

        item.severity = value

    if "enforcement_mode" in changes:
        value = (
            changes["enforcement_mode"]
            or ""
        ).strip().lower()

        if value not in POLICY_ENFORCEMENT_MODES:
            raise HTTPException(
                status_code=400,
                detail="Invalid enforcement_mode",
            )

        item.enforcement_mode = value

    # --------------------------------------------------------
    # Normal editable fields
    # --------------------------------------------------------
    if "affected_module" in changes:
        item.affected_module = (
            (changes["affected_module"] or "").strip()
            or None
        )

    if "affected_component" in changes:
        item.affected_component = (
            (changes["affected_component"] or "").strip()
            or None
        )

    if "description" in changes:
        description = (
            changes["description"]
            or ""
        ).strip()

        if len(description) < 5:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Impact description must contain "
                    "at least 5 characters."
                ),
            )

        item.description = description

    if "recommended_action" in changes:
        item.recommended_action = (
            (changes["recommended_action"] or "").strip()
            or None
        )

    if "current_value" in changes:
        item.current_value = (
            changes["current_value"]
            if isinstance(
                changes["current_value"],
                dict,
            )
            else {}
        )

    if "proposed_value" in changes:
        item.proposed_value = (
            changes["proposed_value"]
            if isinstance(
                changes["proposed_value"],
                dict,
            )
            else {}
        )

    if "acceptance_criteria" in changes:
        item.acceptance_criteria = (
            changes["acceptance_criteria"]
            if isinstance(
                changes["acceptance_criteria"],
                dict,
            )
            else {}
        )

    if "auto_applicable" in changes:
        item.auto_applicable = bool(
            changes["auto_applicable"]
        )

    # --------------------------------------------------------
    # Safety normalization
    # --------------------------------------------------------
    # Technical impacts can NEVER be automatically enforced.
    if (
        item.impact_type
        in POLICY_TECHNICAL_IMPACT_TYPES
    ):
        item.enforcement_mode = "it_task"
        item.auto_applicable = False

    elif item.impact_type in {
        "documentation",
        "no_system_impact",
    }:
        if (
            item.enforcement_mode
            not in {
                "documentation_only",
                "manual_review",
            }
        ):
            item.enforcement_mode = (
                "documentation_only"
            )

        item.auto_applicable = False

    elif item.impact_type not in {
        "agent_behavior",
        "configuration",
    }:
        item.auto_applicable = False

    # --------------------------------------------------------
    # Sync execution proposal used AFTER user approval.
    # --------------------------------------------------------
    payload = (
        dict(decision.execution_payload)
        if isinstance(
            decision.execution_payload,
            dict,
        )
        else {}
    )

    payload.update({
        "impact_type":
            item.impact_type,
        "change_type":
            item.change_type,
        "enforcement_mode":
            item.enforcement_mode,
        "auto_applicable":
            item.auto_applicable,
        "affected_module":
            item.affected_module,
        "affected_component":
            item.affected_component,
        "current_value":
            item.current_value,
        "proposed_value":
            item.proposed_value,
        "acceptance_criteria":
            item.acceptance_criteria,
        "recommended_action":
            item.recommended_action,
    })

    # Preserve AI rule proposal, but keep its module aligned
    # with the reviewed human proposal.
    rule_candidate = payload.get(
        "rule_candidate",
        {},
    )

    if isinstance(
        rule_candidate,
        dict,
    ):
        rule_candidate = dict(
            rule_candidate
        )

        rule_candidate[
            "target_module"
        ] = item.affected_module

        payload[
            "rule_candidate"
        ] = rule_candidate

    decision.execution_payload = payload

    await write_audit_log(
        db,
        actor="user",
        action=(
            "policy.impact_proposal.updated"
        ),
        details={
            "decision_id":
                str(decision.id),
            "impact_item_id":
                str(item.id),
            "assessment_id":
                str(decision.assessment_id),
            "policy_version_id":
                str(
                    decision.policy_version_id
                ),
            "changed_fields":
                sorted(
                    changes.keys()
                ),
            "before":
                before,
            "after": {
                "impact_type":
                    item.impact_type,
                "change_type":
                    item.change_type,
                "affected_module":
                    item.affected_module,
                "affected_component":
                    item.affected_component,
                "description":
                    item.description,
                "recommended_action":
                    item.recommended_action,
                "severity":
                    item.severity,
                "enforcement_mode":
                    item.enforcement_mode,
                "auto_applicable":
                    item.auto_applicable,
                "current_value":
                    item.current_value,
                "proposed_value":
                    item.proposed_value,
                "acceptance_criteria":
                    item.acceptance_criteria,
            },
        },
    )

    await db.commit()

    await db.refresh(item)
    await db.refresh(decision)

    return {
        "status": "ok",
        "impact_item":
            _policy_impact_item_payload(
                item
            ),
        "decision":
            _policy_change_decision_payload(
                decision
            ),
    }

