def _fin_decimal(value):
    try:
        result = _fin_Decimal(str(value or 0)).quantize(
            _fin_Decimal("0.01")
        )
    except (_fin_InvalidOperation, ValueError, TypeError) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid monetary amount: {value}",
        ) from exc

    if result < 0:
        raise HTTPException(
            status_code=400,
            detail="Debit and credit amounts cannot be negative",
        )

    return result


def _fin_default_normal_balance(account_type):
    return (
        "debit"
        if account_type in {
            "asset",
            "expense",
        }
        else "credit"
    )


def _fin_account_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "name_ar": row.name_ar,
        "name_en": row.name_en,
        "account_type": row.account_type,
        "normal_balance": row.normal_balance,
        "parent_id": (
            str(row.parent_id)
            if row.parent_id
            else None
        ),
        "currency": row.currency,
        "allow_posting": row.allow_posting,
        "is_active": row.is_active,
        "system_code": row.system_code,
        "account_metadata": row.account_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _fin_period_payload(row, approval=None):
    return {
        "id": str(row.id),
        "period_key": row.period_key,
        "year": row.year,
        "month": row.month,
        "start_date": row.start_date,
        "end_date": row.end_date,
        "status": row.status,
        "close_approval_id": (
            str(row.close_approval_id)
            if row.close_approval_id
            else None
        ),
        "close_approval_status": (
            approval.status
            if approval
            else None
        ),
        "closed_by": row.closed_by,
        "closed_at": row.closed_at,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _fin_period_approval(db, period):
    if not period.close_approval_id:
        return None

    return (
        await db.execute(
            _fin_select(Approval).where(
                Approval.id
                == period.close_approval_id
            )
        )
    ).scalars().first()


async def _fin_get_period_for_date(db, journal_date):
    period = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.start_date
                <= journal_date,
                FinanceAccountingPeriod.end_date
                >= journal_date,
            )
        )
    ).scalars().first()

    if period is None:
        raise HTTPException(
            status_code=409,
            detail=(
                "No accounting period exists for the journal date"
            ),
        )

    if period.status != "open":
        raise HTTPException(
            status_code=409,
            detail=(
                f"Accounting period {period.period_key} is {period.status}"
            ),
        )

    return period


async def _fin_get_journal(db, journal_id, lock=False):
    query = _fin_select(
        FinanceJournalEntry
    ).where(
        FinanceJournalEntry.id
        == journal_id
    )

    if lock:
        query = query.with_for_update()

    row = (
        await db.execute(query)
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Journal entry not found",
        )

    return row


async def _fin_journal_lines(db, journal_id):
    return (
        await db.execute(
            _fin_select(
                FinanceJournalLine
            ).where(
                FinanceJournalLine.journal_entry_id
                == journal_id
            ).order_by(
                FinanceJournalLine.line_number.asc()
            )
        )
    ).scalars().all()


async def _fin_validate_lines(db, lines):
    if len(lines) < 2:
        raise HTTPException(
            status_code=400,
            detail="A journal entry requires at least two lines",
        )

    normalized = []
    total_debit = _fin_Decimal("0.00")
    total_credit = _fin_Decimal("0.00")

    for index, line in enumerate(
        lines,
        start=1,
    ):
        debit = _fin_decimal(
            line.debit
        )
        credit = _fin_decimal(
            line.credit
        )

        if debit > 0 and credit > 0:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"Line {index} cannot contain both debit and credit"
                ),
            )

        if debit == 0 and credit == 0:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"Line {index} must contain either debit or credit"
                ),
            )

        account = (
            await db.execute(
                _fin_select(
                    FinanceAccount
                ).where(
                    FinanceAccount.id
                    == line.account_id
                )
            )
        ).scalars().first()

        if account is None:
            raise HTTPException(
                status_code=404,
                detail=(
                    f"Account not found for line {index}"
                ),
            )

        if not account.is_active:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Account {account.code} is inactive"
                ),
            )

        if not account.allow_posting:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Account {account.code} is a header/non-posting account"
                ),
            )

        total_debit += debit
        total_credit += credit

        normalized.append({
            "line_number": index,
            "account_id": account.id,
            "description": (
                line.description.strip()
                if line.description
                else None
            ),
            "debit": debit,
            "credit": credit,
            "cost_center": (
                line.cost_center.strip()
                if line.cost_center
                else None
            ),
            "department_code": (
                line.department_code.strip()
                if line.department_code
                else None
            ),
            "line_metadata": (
                line.line_metadata
                if isinstance(
                    line.line_metadata,
                    dict,
                )
                else {}
            ),
        })

    if (
        total_debit == 0
        or total_credit == 0
    ):
        raise HTTPException(
            status_code=400,
            detail="Journal totals must be greater than zero",
        )

    if abs(
        total_debit - total_credit
    ) > _FIN_TOLERANCE:
        raise HTTPException(
            status_code=400,
            detail=(
                "Journal is not balanced: "
                f"debit={total_debit} credit={total_credit}"
            ),
        )

    return normalized, total_debit, total_credit


async def _fin_journal_payload(db, row):
    lines = await _fin_journal_lines(
        db,
        row.id,
    )

    approval = None

    if row.approval_id:
        approval = (
            await db.execute(
                _fin_select(
                    Approval
                ).where(
                    Approval.id
                    == row.approval_id
                )
            )
        ).scalars().first()

    total_debit = sum(
        (
            _fin_Decimal(str(line.debit))
            for line in lines
        ),
        _fin_Decimal("0.00"),
    )
    total_credit = sum(
        (
            _fin_Decimal(str(line.credit))
            for line in lines
        ),
        _fin_Decimal("0.00"),
    )

    return {
        "id": str(row.id),
        "entry_number": row.entry_number,
        "journal_date": row.journal_date,
        "period_id": str(row.period_id),
        "description": row.description,
        "reference": row.reference,
        "source_type": row.source_type,
        "source_id": row.source_id,
        "currency": row.currency,
        "status": row.status,
        "approval_id": (
            str(row.approval_id)
            if row.approval_id
            else None
        ),
        "approval_status": (
            approval.status
            if approval
            else None
        ),
        "created_by": row.created_by,
        "submitted_at": row.submitted_at,
        "posted_at": row.posted_at,
        "posted_by": row.posted_by,
        "reversal_of_id": (
            str(row.reversal_of_id)
            if row.reversal_of_id
            else None
        ),
        "journal_metadata":
            row.journal_metadata or {},
        "total_debit": float(total_debit),
        "total_credit": float(total_credit),
        "balanced": (
            abs(
                total_debit
                - total_credit
            )
            <= _FIN_TOLERANCE
        ),
        "lines": [
            {
                "id": str(line.id),
                "line_number":
                    line.line_number,
                "account_id":
                    str(line.account_id),
                "description":
                    line.description,
                "debit":
                    float(line.debit),
                "credit":
                    float(line.credit),
                "cost_center":
                    line.cost_center,
                "department_code":
                    line.department_code,
                "line_metadata":
                    line.line_metadata
                    or {},
            }
            for line in lines
        ],
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _fin_replace_lines(
    db,
    journal,
    line_requests,
):
    normalized, total_debit, total_credit = (
        await _fin_validate_lines(
            db,
            line_requests,
        )
    )

    existing = await _fin_journal_lines(
        db,
        journal.id,
    )

    for line in existing:
        await db.delete(line)

    await db.flush()

    for item in normalized:
        db.add(
            FinanceJournalLine(
                journal_entry_id=
                    journal.id,
                **item,
            )
        )

    await db.flush()

    return total_debit, total_credit


async def _fin_account_cycle_check(
    db,
    account_id,
    parent_id,
):
    if parent_id is None:
        return

    if account_id is not None and parent_id == account_id:
        raise HTTPException(
            status_code=400,
            detail="An account cannot be its own parent",
        )

    visited = set()
    current_id = parent_id

    while current_id:
        if current_id in visited:
            raise HTTPException(
                status_code=409,
                detail="Account hierarchy contains a cycle",
            )

        visited.add(current_id)

        if (
            account_id is not None
            and current_id == account_id
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Account parent would create a hierarchy cycle"
                ),
            )

        parent = (
            await db.execute(
                _fin_select(
                    FinanceAccount
                ).where(
                    FinanceAccount.id
                    == current_id
                )
            )
        ).scalars().first()

        if parent is None:
            raise HTTPException(
                status_code=404,
                detail="Parent account not found",
            )

        current_id = parent.parent_id


@app.get("/api/finance/accounts")
async def list_finance_accounts(
    active_only: bool = False,
    db: AsyncSession = Depends(get_db),
):
    query = _fin_select(
        FinanceAccount
    )

    if active_only:
        query = query.where(
            FinanceAccount.is_active.is_(
                True
            )
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceAccount.code.asc()
            )
        )
    ).scalars().all()

    return [
        _fin_account_payload(row)
        for row in rows
    ]


@app.post("/api/finance/accounts")
async def create_finance_account(
    payload: FinanceAccountCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip()
    name_ar = payload.name_ar.strip()
    account_type = (
        payload.account_type
        .strip()
        .lower()
    )

    if not code or not name_ar:
        raise HTTPException(
            status_code=400,
            detail="Account code and Arabic name are required",
        )

    if account_type not in _FIN_ACCOUNT_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid account type",
        )

    normal_balance = (
        payload.normal_balance.strip().lower()
        if payload.normal_balance
        else _fin_default_normal_balance(
            account_type
        )
    )

    if normal_balance not in _FIN_NORMAL_BALANCES:
        raise HTTPException(
            status_code=400,
            detail="Invalid normal balance",
        )

    await _fin_account_cycle_check(
        db,
        None,
        payload.parent_id,
    )

    duplicate = (
        await db.execute(
            _fin_select(
                FinanceAccount
            ).where(
                FinanceAccount.code
                == code
            )
        )
    ).scalars().first()

    if duplicate:
        raise HTTPException(
            status_code=409,
            detail="Account code already exists",
        )

    row = FinanceAccount(
        code=code,
        name_ar=name_ar,
        name_en=(
            payload.name_en.strip()
            if payload.name_en
            else None
        ),
        account_type=account_type,
        normal_balance=normal_balance,
        parent_id=payload.parent_id,
        currency=(
            payload.currency.strip().upper()
            or "SAR"
        ),
        allow_posting=
            payload.allow_posting,
        is_active=
            payload.is_active,
        system_code=(
            payload.system_code.strip()
            if payload.system_code
            else None
        ),
        account_metadata=(
            payload.account_metadata
            if isinstance(
                payload.account_metadata,
                dict,
            )
            else {}
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="finance.account.created",
        details={
            "account_id": str(row.id),
            "code": row.code,
            "account_type":
                row.account_type,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _fin_account_payload(
        row
    )


@app.put(
    "/api/finance/accounts/{account_id}"
)
async def update_finance_account(
    account_id: _fin_uuid.UUID,
    payload: FinanceAccountUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _fin_select(
                FinanceAccount
            ).where(
                FinanceAccount.id
                == account_id
            )
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Finance account not found",
        )

    values = payload.model_dump(
        exclude_unset=True
    )

    if "parent_id" in values:
        await _fin_account_cycle_check(
            db,
            row.id,
            values["parent_id"],
        )

    if "code" in values:
        new_code = (
            values["code"] or ""
        ).strip()

        if not new_code:
            raise HTTPException(
                status_code=400,
                detail="Account code cannot be empty",
            )

        duplicate = (
            await db.execute(
                _fin_select(
                    FinanceAccount
                ).where(
                    FinanceAccount.code
                    == new_code,
                    FinanceAccount.id
                    != row.id,
                )
            )
        ).scalars().first()

        if duplicate:
            raise HTTPException(
                status_code=409,
                detail="Account code already exists",
            )

        row.code = new_code

    if "name_ar" in values:
        name_ar = (
            values["name_ar"]
            or ""
        ).strip()

        if not name_ar:
            raise HTTPException(
                status_code=400,
                detail="Arabic account name cannot be empty",
            )

        row.name_ar = name_ar

    if "name_en" in values:
        row.name_en = (
            values["name_en"].strip()
            if values["name_en"]
            else None
        )

    if "account_type" in values:
        account_type = (
            values["account_type"]
            .strip()
            .lower()
        )

        if account_type not in _FIN_ACCOUNT_TYPES:
            raise HTTPException(
                status_code=400,
                detail="Invalid account type",
            )

        row.account_type = account_type

    if "normal_balance" in values:
        normal_balance = (
            values["normal_balance"]
            .strip()
            .lower()
        )

        if normal_balance not in _FIN_NORMAL_BALANCES:
            raise HTTPException(
                status_code=400,
                detail="Invalid normal balance",
            )

        row.normal_balance = normal_balance

    for field in (
        "parent_id",
        "allow_posting",
        "is_active",
        "account_metadata",
    ):
        if field in values:
            setattr(
                row,
                field,
                values[field],
            )

    if "currency" in values:
        row.currency = (
            values["currency"]
            .strip()
            .upper()
        )

    if "system_code" in values:
        row.system_code = (
            values["system_code"].strip()
            if values["system_code"]
            else None
        )

    await write_audit_log(
        db,
        actor="user",
        action="finance.account.updated",
        details={
            "account_id": str(row.id),
            "code": row.code,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _fin_account_payload(
        row
    )


