        ("112000", "البنوك", "Bank", "asset", "110000", True),
        ("113000", "الذمم المدينة", "Accounts Receivable", "asset", "110000", True),
        ("114000", "ضريبة القيمة المضافة القابلة للاسترداد", "VAT Recoverable", "asset", "110000", True),
        ("200000", "الالتزامات", "Liabilities", "liability", None, False),
        ("210000", "الالتزامات المتداولة", "Current Liabilities", "liability", "200000", False),
        ("211000", "الذمم الدائنة", "Accounts Payable", "liability", "210000", True),
