        ("220000", "مصروفات مستحقة", "Accrued Expenses", "liability", "200000", True),
        ("300000", "حقوق الملكية", "Equity", "equity", None, False),
        ("310000", "رأس المال", "Capital", "equity", "300000", True),
        ("320000", "الأرباح المبقاة", "Retained Earnings", "equity", "300000", True),
