@app.get("/api/finance/periods")
async def list_finance_periods(
    year: int | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _fin_select(
        FinanceAccountingPeriod
    )

    if year is not None:
        query = query.where(
            FinanceAccountingPeriod.year
            == year
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceAccountingPeriod.start_date.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        output.append(
            _fin_period_payload(
                row,
                await _fin_period_approval(
                    db,
                    row,
                ),
            )
        )

    return output


@app.post("/api/finance/periods")
async def create_finance_period(
    payload: FinancePeriodCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if (
        payload.year < 2000
        or payload.year > 2200
        or payload.month < 1
        or payload.month > 12
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid accounting period",
        )

    status = (
        payload.status.strip().lower()
    )

    if status != "open":
        raise HTTPException(
            status_code=400,
            detail="New periods must be created open",
        )

    period_key = (
        f"{payload.year:04d}-"
        f"{payload.month:02d}"
    )

    existing = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.period_key
                == period_key
            )
        )
    ).scalars().first()

    if existing:
        raise HTTPException(
            status_code=409,
            detail="Accounting period already exists",
        )

    last_day = (
        _fin_calendar.monthrange(
            payload.year,
            payload.month,
        )[1]
    )

    row = FinanceAccountingPeriod(
        period_key=period_key,
        year=payload.year,
        month=payload.month,
        start_date=_fin_date(
            payload.year,
            payload.month,
            1,
        ),
        end_date=_fin_date(
            payload.year,
            payload.month,
            last_day,
        ),
        status="open",
        notes=(
            payload.notes.strip()
            if payload.notes
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="finance.period.created",
        details={
            "period_id": str(row.id),
            "period_key":
                row.period_key,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _fin_period_payload(
        row
    )


@app.post(
    "/api/finance/periods/initialize-year/{year}"
)
async def initialize_finance_year(
    year: int,
    db: AsyncSession = Depends(get_db),
):
    if year < 2000 or year > 2200:
        raise HTTPException(
            status_code=400,
            detail="Invalid year",
        )

    existing_rows = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.year
                == year
            )
        )
    ).scalars().all()

    existing_months = {
        row.month
        for row in existing_rows
    }

    created = []

    for month in range(
        1,
        13,
    ):
        if month in existing_months:
            continue

        last_day = (
            _fin_calendar.monthrange(
                year,
                month,
            )[1]
        )

        row = FinanceAccountingPeriod(
            period_key=(
                f"{year:04d}-{month:02d}"
            ),
            year=year,
            month=month,
            start_date=_fin_date(
                year,
                month,
                1,
            ),
            end_date=_fin_date(
                year,
                month,
                last_day,
            ),
            status="open",
        )

        db.add(row)
        created.append(row)

    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="finance.year.initialized",
        details={
            "year": year,
            "created_periods":
                len(created),
        },
    )

    await db.commit()

    return {
        "year": year,
        "created_periods":
            len(created),
        "existing_periods":
            len(existing_rows),
    }


@app.post(
    "/api/finance/periods/{period_id}/request-close-approval"
)
async def request_finance_period_close_approval(
    period_id: _fin_uuid.UUID,
    payload: FinancePeriodCloseApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    period = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.id
                == period_id
            )
        )
    ).scalars().first()

    if period is None:
        raise HTTPException(
            status_code=404,
            detail="Accounting period not found",
        )

    if period.status != "open":
        raise HTTPException(
            status_code=409,
            detail="Only an open period can be closed",
        )

    unresolved = await db.scalar(
        _fin_select(
            _fin_func.count()
        ).select_from(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.period_id
            == period.id,
            FinanceJournalEntry.status.in_(
                [
                    "draft",
                    "pending_approval",
                    "rejected",
                ]
            ),
        )
    )

    if unresolved:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Period contains {unresolved} unposted journal entries"
            ),
        )

    existing_approval = (
        await _fin_period_approval(
            db,
            period,
        )
    )

    if (
        existing_approval
        and existing_approval.status
        in {
            "pending",
            "approved",
        }
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Close approval already {existing_approval.status}"
            ),
        )

    finance_agent = (
        await db.execute(
            _fin_select(
                Agent
            ).where(
                Agent.slug == "finance",
                Agent.enabled.is_(True),
            )
        )
    ).scalars().first()

    approval = Approval(
        agent_id=(
            finance_agent.id
            if finance_agent
            else None
        ),
        title=(
            f"Close accounting period {period.period_key}"
        ),
        description=(
            "Approve final closing of the accounting period. "
            "Posted journals remain immutable."
        ),
        action_type="finance_period_close",
        risk_level="high",
        status="pending",
        action_payload={
            "period_id":
                str(period.id),
            "period_key":
                period.period_key,
            "notes":
                payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    period.close_approval_id = (
        approval.id
    )

    await write_audit_log(
        db,
        actor=payload.requested_by,
        action="finance.period.close_approval_requested",
        details={
            "period_id":
                str(period.id),
            "approval_id":
                str(approval.id),
        },
    )

    await db.commit()
    await db.refresh(period)
    await db.refresh(approval)

    return {
        "period": _fin_period_payload(
            period,
            approval,
        ),
        "approval_id":
            str(approval.id),
        "approval_status":
            approval.status,
    }


@app.post(
    "/api/finance/periods/{period_id}/close"
)
async def close_finance_period(
    period_id: _fin_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    period = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.id
                == period_id
            ).with_for_update()
        )
    ).scalars().first()

    if period is None:
        raise HTTPException(
            status_code=404,
            detail="Accounting period not found",
        )

    if period.status == "closed":
        return _fin_period_payload(
            period,
            await _fin_period_approval(
                db,
                period,
            ),
        )

    approval = await _fin_period_approval(
        db,
        period,
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_period_close"
        or str(
            (
                approval.action_payload
                or {}
            ).get(
                "period_id"
            )
            or ""
        )
        != str(period.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved period-close authorization is required"
            ),
        )

    unresolved = await db.scalar(
        _fin_select(
            _fin_func.count()
        ).select_from(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.period_id
            == period.id,
            FinanceJournalEntry.status
            != "posted",
        )
    )

    if unresolved:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Period contains {unresolved} journals that are not posted"
            ),
        )

    now = _fin_datetime.now(
        _fin_timezone.utc
    )

    period.status = "closed"
    period.closed_by = "user"
    period.closed_at = now
    approval.executed_at = now

    await write_audit_log(
        db,
        actor="user",
        action="finance.period.closed",
        details={
            "period_id":
                str(period.id),
            "period_key":
                period.period_key,
            "approval_id":
                str(approval.id),
        },
    )

    await db.commit()
    await db.refresh(period)
    await db.refresh(approval)

    return _fin_period_payload(
        period,
        approval,
    )


@app.get("/api/finance/journals")
async def list_finance_journals(
    status: str | None = None,
    period_id: _fin_uuid.UUID | None = None,
    limit: int = 200,
    db: AsyncSession = Depends(get_db),
):
    limit = max(
        1,
        min(
            int(limit),
            1000,
        ),
    )

    query = _fin_select(
        FinanceJournalEntry
    )

    if status:
        query = query.where(
            FinanceJournalEntry.status
            == status.strip().lower()
        )

    if period_id:
        query = query.where(
            FinanceJournalEntry.period_id
            == period_id
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceJournalEntry.journal_date.desc(),
                FinanceJournalEntry.created_at.desc(),
            ).limit(limit)
        )
    ).scalars().all()

    return [
        await _fin_journal_payload(
            db,
            row,
        )
        for row in rows
    ]


