@app.post("/api/finance/journals")
async def create_finance_journal(
    payload: FinanceJournalCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    description = (
        payload.description.strip()
    )

    if not description:
        raise HTTPException(
            status_code=400,
            detail="Journal description is required",
        )

    period = await _fin_get_period_for_date(
        db,
        payload.journal_date,
    )

    normalized, total_debit, total_credit = (
        await _fin_validate_lines(
            db,
            payload.lines,
        )
    )

    entry_number = (
        "JE-"
        + payload.journal_date.strftime(
            "%Y%m%d"
        )
        + "-"
        + _fin_uuid.uuid4().hex[
            :8
        ].upper()
    )

    row = FinanceJournalEntry(
        entry_number=entry_number,
        journal_date=
            payload.journal_date,
        period_id=period.id,
        description=description,
        reference=(
            payload.reference.strip()
            if payload.reference
            else None
        ),
        source_type=(
            payload.source_type.strip().lower()
            or "manual"
        ),
        source_id=(
            payload.source_id.strip()
            if payload.source_id
            else None
        ),
        currency=(
            payload.currency.strip().upper()
            or "SAR"
        ),
        status="draft",
        created_by=(
            payload.created_by.strip()
            or "user"
        ),
        journal_metadata=(
            payload.journal_metadata
            if isinstance(
                payload.journal_metadata,
                dict,
            )
            else {}
        ),
    )

    db.add(row)
    await db.flush()

    for item in normalized:
        db.add(
            FinanceJournalLine(
                journal_entry_id=
                    row.id,
                **item,
            )
        )

    await db.flush()

    await write_audit_log(
        db,
        actor=row.created_by,
        action="finance.journal.created",
        details={
            "journal_id":
                str(row.id),
            "entry_number":
                row.entry_number,
            "period_key":
                period.period_key,
            "total_debit":
                str(total_debit),
            "total_credit":
                str(total_credit),
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _fin_journal_payload(
        db,
        row,
    )


@app.put(
    "/api/finance/journals/{journal_id}"
)
async def update_finance_journal(
    journal_id: _fin_uuid.UUID,
    payload: FinanceJournalUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await _fin_get_journal(
        db,
        journal_id,
        lock=True,
    )

    approval = None

    if row.approval_id:
        approval = (
            await db.execute(
                _fin_select(
                    Approval
                ).where(
                    Approval.id
                    == row.approval_id
                )
            )
        ).scalars().first()

    if (
        row.status
        == "pending_approval"
        and approval
        and approval.status == "rejected"
    ):
        row.status = "rejected"

    if row.status not in _FIN_JOURNAL_EDITABLE_STATUSES:
        raise HTTPException(
            status_code=409,
            detail=(
                "Only draft or rejected journals can be edited"
            ),
        )

    values = payload.model_dump(
        exclude_unset=True
    )

    if "journal_date" in values:
        period = await _fin_get_period_for_date(
            db,
            values["journal_date"],
        )
        row.journal_date = (
            values["journal_date"]
        )
        row.period_id = (
            period.id
        )
    else:
        period = (
            await db.execute(
                _fin_select(
                    FinanceAccountingPeriod
                ).where(
                    FinanceAccountingPeriod.id
                    == row.period_id
                )
            )
        ).scalars().first()

        if (
            period is None
            or period.status != "open"
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Journal period is not open"
                ),
            )

    if "description" in values:
        description = (
            values["description"]
            or ""
        ).strip()

        if not description:
            raise HTTPException(
                status_code=400,
                detail="Journal description is required",
            )

        row.description = description

    for field in (
        "reference",
        "source_id",
    ):
        if field in values:
            value = values[field]
            setattr(
                row,
                field,
                value.strip()
                if value
                else None,
            )

    if "source_type" in values:
        row.source_type = (
            values["source_type"]
            .strip()
            .lower()
        )

    if "currency" in values:
        row.currency = (
            values["currency"]
            .strip()
            .upper()
        )

    if "journal_metadata" in values:
        row.journal_metadata = (
            values["journal_metadata"]
            or {}
        )

    if values.get("lines") is not None:
        await _fin_replace_lines(
            db,
            row,
            payload.lines,
        )

    if row.status == "rejected":
        row.status = "draft"
        row.approval_id = None
        row.submitted_at = None

    await write_audit_log(
        db,
        actor="user",
        action="finance.journal.updated",
        details={
            "journal_id":
                str(row.id),
            "entry_number":
                row.entry_number,
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _fin_journal_payload(
        db,
        row,
    )


@app.post(
    "/api/finance/journals/{journal_id}/request-approval"
)
async def request_finance_journal_approval(
    journal_id: _fin_uuid.UUID,
    payload: FinanceJournalApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await _fin_get_journal(
        db,
        journal_id,
        lock=True,
    )

    old_approval = None

    if row.approval_id:
        old_approval = (
            await db.execute(
                _fin_select(
                    Approval
                ).where(
                    Approval.id
                    == row.approval_id
                )
            )
        ).scalars().first()

    if (
        row.status
        == "pending_approval"
        and old_approval
        and old_approval.status == "rejected"
    ):
        row.status = "rejected"

    if row.status not in _FIN_JOURNAL_EDITABLE_STATUSES:
        raise HTTPException(
            status_code=409,
            detail=(
                "Only a draft or rejected journal can request approval"
            ),
        )

    period = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.id
                == row.period_id
            )
        )
    ).scalars().first()

    if (
        period is None
        or period.status != "open"
    ):
        raise HTTPException(
            status_code=409,
            detail="Journal accounting period is not open",
        )

    lines = await _fin_journal_lines(
        db,
        row.id,
    )

    line_requests = [
        FinanceJournalLineRequest(
            account_id=line.account_id,
            description=line.description,
            debit=float(line.debit),
            credit=float(line.credit),
            cost_center=line.cost_center,
            department_code=line.department_code,
            line_metadata=line.line_metadata or {},
        )
        for line in lines
    ]

    _, total_debit, total_credit = (
        await _fin_validate_lines(
            db,
            line_requests,
        )
    )

    finance_agent = (
        await db.execute(
            _fin_select(
                Agent
            ).where(
                Agent.slug == "finance",
                Agent.enabled.is_(True),
            )
        )
    ).scalars().first()

    approval = Approval(
        agent_id=(
            finance_agent.id
            if finance_agent
            else None
        ),
        title=(
            f"Post journal {row.entry_number}"
        ),
        description=(
            f"{row.description} | "
            f"Debit {total_debit} {row.currency} | "
            f"Credit {total_credit} {row.currency}"
        ),
        action_type="finance_journal_posting",
        risk_level="high",
        status="pending",
        action_payload={
            "journal_id":
                str(row.id),
            "entry_number":
                row.entry_number,
            "journal_date":
                row.journal_date.isoformat(),
            "period_id":
                str(row.period_id),
            "total_debit":
                str(total_debit),
            "total_credit":
                str(total_credit),
            "currency":
                row.currency,
            "notes":
                payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"
    row.submitted_at = (
        _fin_datetime.now(
            _fin_timezone.utc
        )
    )

    await write_audit_log(
        db,
        actor=payload.requested_by,
        action="finance.journal.approval_requested",
        details={
            "journal_id":
                str(row.id),
            "approval_id":
                str(approval.id),
            "entry_number":
                row.entry_number,
            "total":
                str(total_debit),
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _fin_journal_payload(
        db,
        row,
    )


@app.post(
    "/api/finance/journals/{journal_id}/post"
)
async def post_finance_journal(
    journal_id: _fin_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await _fin_get_journal(
        db,
        journal_id,
        lock=True,
    )

    if row.status == "posted":
        return await _fin_journal_payload(
            db,
            row,
        )

    if not row.approval_id:
        raise HTTPException(
            status_code=409,
            detail="Journal approval is required before posting",
        )

    approval = (
        await db.execute(
            _fin_select(
                Approval
            ).where(
                Approval.id
                == row.approval_id
            )
        )
    ).scalars().first()

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "finance_journal_posting"
        or str(
            (
                approval.action_payload
                or {}
            ).get(
                "journal_id"
            )
            or ""
        )
        != str(row.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved journal-posting authorization is required"
            ),
        )

    period = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            ).where(
                FinanceAccountingPeriod.id
                == row.period_id
            )
        )
    ).scalars().first()

    if (
        period is None
        or period.status != "open"
    ):
        raise HTTPException(
            status_code=409,
            detail="Journal accounting period is not open",
        )

    lines = await _fin_journal_lines(
        db,
        row.id,
    )

    line_requests = [
        FinanceJournalLineRequest(
            account_id=line.account_id,
            description=line.description,
            debit=float(line.debit),
            credit=float(line.credit),
            cost_center=line.cost_center,
            department_code=line.department_code,
            line_metadata=line.line_metadata or {},
        )
        for line in lines
    ]

    await _fin_validate_lines(
        db,
        line_requests,
    )

    now = _fin_datetime.now(
        _fin_timezone.utc
    )

    row.status = "posted"
    row.posted_at = now
    row.posted_by = "user"
    approval.executed_at = now

    await write_audit_log(
        db,
        actor="user",
        action="finance.journal.posted",
        details={
            "journal_id":
                str(row.id),
            "entry_number":
                row.entry_number,
            "approval_id":
                str(approval.id),
            "period_id":
                str(row.period_id),
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _fin_journal_payload(
        db,
        row,
    )


@app.get(
    "/api/finance/trial-balance"
)
async def finance_trial_balance(
    from_date: _fin_date | None = None,
    to_date: _fin_date | None = None,
    db: AsyncSession = Depends(get_db),
):
    accounts = (
        await db.execute(
            _fin_select(
                FinanceAccount
            ).order_by(
                FinanceAccount.code.asc()
            )
        )
    ).scalars().all()

    journal_query = (
        _fin_select(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.status
            == "posted"
        )
    )

    if from_date:
        journal_query = journal_query.where(
            FinanceJournalEntry.journal_date
            >= from_date
        )

    if to_date:
        journal_query = journal_query.where(
            FinanceJournalEntry.journal_date
            <= to_date
        )

    journals = (
        await db.execute(
            journal_query
        )
    ).scalars().all()

    journal_ids = [
        row.id
        for row in journals
    ]

    totals = {}

    if journal_ids:
        lines = (
            await db.execute(
                _fin_select(
                    FinanceJournalLine
                ).where(
                    FinanceJournalLine.journal_entry_id.in_(
                        journal_ids
                    )
                )
            )
        ).scalars().all()

        for line in lines:
            item = totals.setdefault(
                line.account_id,
                {
                    "debit":
                        _fin_Decimal("0.00"),
                    "credit":
                        _fin_Decimal("0.00"),
                },
            )

            item["debit"] += (
                _fin_Decimal(
                    str(line.debit)
                )
            )
            item["credit"] += (
                _fin_Decimal(
                    str(line.credit)
                )
            )

    rows = []
    grand_debit = _fin_Decimal("0.00")
    grand_credit = _fin_Decimal("0.00")

    for account in accounts:
        item = totals.get(
            account.id,
            {
                "debit":
                    _fin_Decimal("0.00"),
                "credit":
                    _fin_Decimal("0.00"),
            },
        )

        debit = item["debit"]
        credit = item["credit"]

        if debit == 0 and credit == 0:
            continue

        raw_balance = debit - credit

        balance = (
            raw_balance
            if account.normal_balance
            == "debit"
            else -raw_balance
        )

        grand_debit += debit
        grand_credit += credit

        rows.append({
            "account_id":
                str(account.id),
            "code":
                account.code,
            "name_ar":
                account.name_ar,
            "name_en":
                account.name_en,
            "account_type":
                account.account_type,
            "normal_balance":
                account.normal_balance,
            "debit":
                float(debit),
            "credit":
                float(credit),
            "balance":
                float(balance),
        })

    return {
        "from_date": from_date,
        "to_date": to_date,
        "total_debit":
            float(grand_debit),
        "total_credit":
            float(grand_credit),
        "balanced": (
            abs(
                grand_debit
                - grand_credit
            )
            <= _FIN_TOLERANCE
        ),
        "rows": rows,
    }


@app.get(
    "/api/finance/accounts/{account_id}/ledger"
)
async def finance_account_ledger(
    account_id: _fin_uuid.UUID,
    from_date: _fin_date | None = None,
    to_date: _fin_date | None = None,
    db: AsyncSession = Depends(get_db),
):
    account = (
        await db.execute(
            _fin_select(
                FinanceAccount
            ).where(
                FinanceAccount.id
                == account_id
            )
        )
    ).scalars().first()

    if account is None:
        raise HTTPException(
            status_code=404,
            detail="Finance account not found",
        )

    journal_query = (
        _fin_select(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.status
            == "posted"
        )
    )

    if from_date:
        journal_query = journal_query.where(
            FinanceJournalEntry.journal_date
            >= from_date
        )

    if to_date:
        journal_query = journal_query.where(
            FinanceJournalEntry.journal_date
            <= to_date
        )

    journals = (
        await db.execute(
            journal_query
        )
    ).scalars().all()

    journal_by_id = {
        row.id: row
        for row in journals
    }

    journal_ids = list(
        journal_by_id.keys()
    )

    output = []
    running = _fin_Decimal("0.00")

    if journal_ids:
        lines = (
            await db.execute(
                _fin_select(
                    FinanceJournalLine
                ).where(
                    FinanceJournalLine.account_id
                    == account.id,
                    FinanceJournalLine.journal_entry_id.in_(
                        journal_ids
                    ),
                ).order_by(
                    FinanceJournalLine.created_at.asc()
                )
            )
        ).scalars().all()

        lines = sorted(
            lines,
            key=lambda line: (
                journal_by_id[
                    line.journal_entry_id
                ].journal_date,
                line.created_at,
                line.line_number,
            ),
        )

        for line in lines:
            debit = _fin_Decimal(
                str(line.debit)
            )
            credit = _fin_Decimal(
                str(line.credit)
            )

            delta = (
                debit - credit
                if account.normal_balance
                == "debit"
                else credit - debit
            )

            running += delta

            journal = journal_by_id[
                line.journal_entry_id
            ]

            output.append({
                "journal_id":
                    str(journal.id),
                "entry_number":
                    journal.entry_number,
                "journal_date":
                    journal.journal_date,
                "reference":
                    journal.reference,
                "journal_description":
                    journal.description,
                "line_description":
                    line.description,
                "debit":
                    float(debit),
                "credit":
                    float(credit),
                "running_balance":
                    float(running),
            })

    return {
        "account":
            _fin_account_payload(
                account
            ),
        "from_date":
            from_date,
        "to_date":
            to_date,
        "ending_balance":
            float(running),
        "entries":
            output,
    }


@app.get("/api/finance/summary")
async def finance_summary(
    db: AsyncSession = Depends(get_db),
):
    accounts = (
        await db.execute(
            _fin_select(
                FinanceAccount
            )
        )
    ).scalars().all()

    periods = (
        await db.execute(
            _fin_select(
                FinanceAccountingPeriod
            )
        )
    ).scalars().all()

    journals = (
        await db.execute(
            _fin_select(
                FinanceJournalEntry
            )
        )
    ).scalars().all()

    by_status = {}

    for row in journals:
        by_status[row.status] = (
            by_status.get(
                row.status,
                0,
            )
            + 1
        )

    open_periods = [
        row
        for row in periods
        if row.status == "open"
    ]

    current_period = None
    today = _fin_date.today()

    for row in periods:
        if (
            row.start_date
            <= today
            <= row.end_date
        ):
            current_period = row
            break

    trial = await finance_trial_balance(
        from_date=None,
        to_date=None,
        db=db,
    )

    return {
        "accounts": {
            "total": len(accounts),
            "active": sum(
                1
                for row in accounts
                if row.is_active
            ),
            "posting": sum(
                1
                for row in accounts
                if (
                    row.is_active
                    and row.allow_posting
                )
            ),
        },
        "periods": {
            "total": len(periods),
            "open": len(open_periods),
            "closed": sum(
                1
                for row in periods
                if row.status
                == "closed"
            ),
            "current": (
                _fin_period_payload(
                    current_period
                )
                if current_period
                else None
            ),
        },
        "journals": {
            "total": len(journals),
            "by_status": by_status,
        },
        "ledger": {
            "total_debit":
                trial["total_debit"],
            "total_credit":
                trial["total_credit"],
            "balanced":
                trial["balanced"],
        },
    }

# ============================================================
# Finance - AP / AR API
# ============================================================
import uuid as _far_uuid
from datetime import datetime as _far_datetime, timezone as _far_timezone
from decimal import Decimal as _far_Decimal, ROUND_HALF_UP as _far_ROUND_HALF_UP

from pydantic import BaseModel as _FarBaseModel
from sqlalchemy import select as _far_select, func as _far_func

from .models import (
    FinanceVendor,
    FinanceCustomer,
    FinanceBill,
    FinanceBillLine,
    FinanceInvoice,
    FinanceInvoiceLine,
    FinanceBillPayment,
    FinanceInvoiceReceipt,
)

_FAR_ZERO = _far_Decimal("0.00")
_FAR_Q2 = _far_Decimal("0.01")
_FAR_Q4 = _far_Decimal("0.0001")


class FinanceVendorRequest(_FarBaseModel):
    code: str
    name_ar: str
    name_en: str | None = None
    vat_number: str | None = None
    cr_number: str | None = None
    email: str | None = None
    phone: str | None = None
    iban: str | None = None
    payment_terms_days: int = 30
    default_expense_account_id: _far_uuid.UUID | None = None
    is_active: bool = True
    vendor_metadata: dict = {}


class FinanceCustomerRequest(_FarBaseModel):
    code: str
    name_ar: str
    name_en: str | None = None
    vat_number: str | None = None
    cr_number: str | None = None
    email: str | None = None
    phone: str | None = None
    payment_terms_days: int = 30
    credit_limit: float = 0
    default_revenue_account_id: _far_uuid.UUID | None = None
    is_active: bool = True
    customer_metadata: dict = {}


class FinanceBillLineRequest(_FarBaseModel):
    description: str
    expense_account_id: _far_uuid.UUID
    quantity: float = 1
    unit_price: float
    vat_rate: float = 0
    line_metadata: dict = {}


class FinanceBillCreateRequest(_FarBaseModel):
    vendor_id: _far_uuid.UUID
    bill_number: str
    bill_date: _fin_date
    due_date: _fin_date
    currency: str = "SAR"
    payable_account_id: _far_uuid.UUID
    input_vat_account_id: _far_uuid.UUID | None = None
    reference: str | None = None
    notes: str | None = None
    created_by: str = "user"
    bill_metadata: dict = {}
    lines: list[FinanceBillLineRequest]


class FinanceInvoiceLineRequest(_FarBaseModel):
    description: str
    revenue_account_id: _far_uuid.UUID
    quantity: float = 1
    unit_price: float
    vat_rate: float = 0
    line_metadata: dict = {}


class FinanceInvoiceCreateRequest(_FarBaseModel):
    customer_id: _far_uuid.UUID
    invoice_number: str | None = None
    invoice_date: _fin_date
    due_date: _fin_date
    currency: str = "SAR"
    receivable_account_id: _far_uuid.UUID
    output_vat_account_id: _far_uuid.UUID | None = None
    reference: str | None = None
    notes: str | None = None
    created_by: str = "user"
    invoice_metadata: dict = {}
    lines: list[FinanceInvoiceLineRequest]


class FinanceApprovalRequest(_FarBaseModel):
    requested_by: str = "user"
    notes: str | None = None


class FinanceBillPaymentCreateRequest(_FarBaseModel):
    payment_date: _fin_date
    amount: float
    bank_account_id: _far_uuid.UUID
    reference: str | None = None
    created_by: str = "user"


class FinanceInvoiceReceiptCreateRequest(_FarBaseModel):
    receipt_date: _fin_date
    amount: float
    bank_account_id: _far_uuid.UUID
    reference: str | None = None
    created_by: str = "user"


def _far_money(value):
    return _far_Decimal(str(value or 0)).quantize(
        _FAR_Q2,
        rounding=_far_ROUND_HALF_UP,
    )


def _far_rate(value):
    rate = _far_Decimal(str(value or 0)).quantize(
        _FAR_Q4,
        rounding=_far_ROUND_HALF_UP,
    )
    if rate < 0 or rate > 100:
        raise HTTPException(
            status_code=400,
            detail="VAT rate must be between 0 and 100",
        )
    return rate


async def _far_finance_agent(db):
    return (
        await db.execute(
            _far_select(Agent).where(
                Agent.slug == "finance",
                Agent.enabled.is_(True),
            )
        )
    ).scalars().first()


async def _far_account(db, account_id, expected_type=None):
    account = (
        await db.execute(
            _far_select(FinanceAccount).where(
                FinanceAccount.id == account_id
            )
        )
    ).scalars().first()

    if account is None:
        raise HTTPException(
            status_code=404,
            detail="Finance account not found",
        )

    if not account.is_active or not account.allow_posting:
        raise HTTPException(
            status_code=409,
            detail=f"Account {account.code} is not available for posting",
        )

    if expected_type and account.account_type != expected_type:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Account {account.code} must be type {expected_type}"
            ),
        )

    return account


async def _far_period_for_date(db, value):
    return await _fin_get_period_for_date(db, value)


def _far_vendor_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "name_ar": row.name_ar,
        "name_en": row.name_en,
        "vat_number": row.vat_number,
        "cr_number": row.cr_number,
        "email": row.email,
        "phone": row.phone,
        "iban": row.iban,
        "payment_terms_days": row.payment_terms_days,
        "default_expense_account_id": (
            str(row.default_expense_account_id)
            if row.default_expense_account_id
            else None
        ),
        "is_active": row.is_active,
        "vendor_metadata": row.vendor_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _far_customer_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "name_ar": row.name_ar,
        "name_en": row.name_en,
        "vat_number": row.vat_number,
        "cr_number": row.cr_number,
        "email": row.email,
        "phone": row.phone,
        "payment_terms_days": row.payment_terms_days,
        "credit_limit": float(row.credit_limit or 0),
        "default_revenue_account_id": (
            str(row.default_revenue_account_id)
            if row.default_revenue_account_id
            else None
        ),
        "is_active": row.is_active,
        "customer_metadata": row.customer_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _far_bill_payload(db, row):
    lines = (
        await db.execute(
            _far_select(FinanceBillLine)
            .where(FinanceBillLine.bill_id == row.id)
            .order_by(FinanceBillLine.line_number.asc())
        )
    ).scalars().all()

    approval = None
    if row.approval_id:
        approval = (
            await db.execute(
                _far_select(Approval).where(
                    Approval.id == row.approval_id
                )
            )
        ).scalars().first()

    balance = _far_money(row.total_amount) - _far_money(row.amount_paid)

    return {
        "id": str(row.id),
        "vendor_id": str(row.vendor_id),
        "bill_number": row.bill_number,
        "bill_date": row.bill_date,
        "due_date": row.due_date,
        "currency": row.currency,
        "subtotal": float(row.subtotal),
        "vat_amount": float(row.vat_amount),
        "total_amount": float(row.total_amount),
        "amount_paid": float(row.amount_paid),
        "balance_due": float(max(balance, _FAR_ZERO)),
        "status": row.status,
        "payable_account_id": str(row.payable_account_id),
        "input_vat_account_id": (
            str(row.input_vat_account_id)
            if row.input_vat_account_id else None
        ),
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else None,
        "journal_entry_id": (
            str(row.journal_entry_id)
            if row.journal_entry_id else None
        ),
        "reference": row.reference,
        "notes": row.notes,
        "lines": [
            {
                "id": str(line.id),
                "line_number": line.line_number,
                "description": line.description,
                "expense_account_id": str(line.expense_account_id),
                "quantity": float(line.quantity),
                "unit_price": float(line.unit_price),
                "vat_rate": float(line.vat_rate),
                "net_amount": float(line.net_amount),
                "vat_amount": float(line.vat_amount),
                "total_amount": float(line.total_amount),
            }
            for line in lines
        ],
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _far_invoice_payload(db, row):
    lines = (
        await db.execute(
            _far_select(FinanceInvoiceLine)
            .where(FinanceInvoiceLine.invoice_id == row.id)
            .order_by(FinanceInvoiceLine.line_number.asc())
        )
    ).scalars().all()

    approval = None
    if row.approval_id:
        approval = (
            await db.execute(
                _far_select(Approval).where(
                    Approval.id == row.approval_id
                )
            )
        ).scalars().first()

    balance = _far_money(row.total_amount) - _far_money(row.amount_collected)

    return {
        "id": str(row.id),
        "customer_id": str(row.customer_id),
        "invoice_number": row.invoice_number,
        "invoice_date": row.invoice_date,
        "due_date": row.due_date,
        "currency": row.currency,
        "subtotal": float(row.subtotal),
        "vat_amount": float(row.vat_amount),
        "total_amount": float(row.total_amount),
        "amount_collected": float(row.amount_collected),
        "balance_due": float(max(balance, _FAR_ZERO)),
        "status": row.status,
        "receivable_account_id": str(row.receivable_account_id),
        "output_vat_account_id": (
            str(row.output_vat_account_id)
            if row.output_vat_account_id else None
        ),
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else None,
        "journal_entry_id": (
            str(row.journal_entry_id)
            if row.journal_entry_id else None
        ),
        "reference": row.reference,
        "notes": row.notes,
        "lines": [
            {
                "id": str(line.id),
                "line_number": line.line_number,
                "description": line.description,
                "revenue_account_id": str(line.revenue_account_id),
                "quantity": float(line.quantity),
                "unit_price": float(line.unit_price),
                "vat_rate": float(line.vat_rate),
                "net_amount": float(line.net_amount),
                "vat_amount": float(line.vat_amount),
                "total_amount": float(line.total_amount),
            }
            for line in lines
        ],
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _far_calculate_lines(lines):
    if not lines:
        raise HTTPException(
            status_code=400,
            detail="At least one line is required",
        )

    normalized = []
    subtotal = _FAR_ZERO
    vat_total = _FAR_ZERO

    for index, line in enumerate(lines, start=1):
        qty = _far_Decimal(str(line.quantity or 0))
        unit = _far_Decimal(str(line.unit_price or 0))
        rate = _far_rate(line.vat_rate)

        if qty <= 0:
            raise HTTPException(
                status_code=400,
                detail=f"Line {index}: quantity must be greater than zero",
            )

        if unit < 0:
            raise HTTPException(
                status_code=400,
                detail=f"Line {index}: unit price cannot be negative",
            )

        description = line.description.strip()
        if not description:
            raise HTTPException(
                status_code=400,
                detail=f"Line {index}: description is required",
            )

        net = (qty * unit).quantize(
            _FAR_Q2,
            rounding=_far_ROUND_HALF_UP,
        )
        vat = (net * rate / _far_Decimal("100")).quantize(
            _FAR_Q2,
            rounding=_far_ROUND_HALF_UP,
        )
        total = net + vat

        subtotal += net
        vat_total += vat

        normalized.append({
            "line_number": index,
            "description": description,
            "quantity": qty,
            "unit_price": unit,
            "vat_rate": rate,
            "net_amount": net,
            "vat_amount": vat,
            "total_amount": total,
            "line_metadata": (
                line.line_metadata
                if isinstance(line.line_metadata, dict)
                else {}
            ),
        })

    return normalized, subtotal, vat_total, subtotal + vat_total


async def _far_create_posted_journal(
    db,
    *,
    journal_date,
    description,
    reference,
    source_type,
    source_id,
    currency,
    approval,
    debit_lines,
    credit_lines,
):
    period = await _far_period_for_date(db, journal_date)

    all_lines = debit_lines + credit_lines
    total_debit = sum(
        (_far_money(x.get("debit")) for x in all_lines),
        _FAR_ZERO,
    )
    total_credit = sum(
        (_far_money(x.get("credit")) for x in all_lines),
        _FAR_ZERO,
    )

    if total_debit <= 0 or total_debit != total_credit:
        raise HTTPException(
            status_code=409,
            detail="Generated accounting entry is not balanced",
        )

    entry = FinanceJournalEntry(
        entry_number=(
            "JE-"
            + journal_date.strftime("%Y%m%d")
            + "-"
            + _far_uuid.uuid4().hex[:8].upper()
        ),
        journal_date=journal_date,
        period_id=period.id,
        description=description,
        reference=reference,
        source_type=source_type,
        source_id=str(source_id),
        currency=currency,
        status="posted",
        approval_id=approval.id,
        created_by="finance",
        submitted_at=approval.created_at,
        posted_at=_far_datetime.now(_far_timezone.utc),
        posted_by="user",
        journal_metadata={
            "source_type": source_type,
            "source_id": str(source_id),
        },
    )
    db.add(entry)
    await db.flush()

    for index, line in enumerate(all_lines, start=1):
        db.add(
            FinanceJournalLine(
                journal_entry_id=entry.id,
                line_number=index,
                account_id=line["account_id"],
                description=line.get("description"),
                debit=_far_money(line.get("debit")),
                credit=_far_money(line.get("credit")),
                line_metadata=line.get("line_metadata") or {},
            )
        )

    await db.flush()
    return entry


