@app.post("/api/finance/bills")
async def create_finance_bill(
    payload: FinanceBillCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    vendor = await db.get(FinanceVendor, payload.vendor_id)
    if vendor is None or not vendor.is_active:
        raise HTTPException(status_code=409, detail="Vendor is not available")

    duplicate = (
        await db.execute(
            _far_select(FinanceBill).where(
                FinanceBill.vendor_id == payload.vendor_id,
                FinanceBill.bill_number == payload.bill_number.strip(),
            )
        )
    ).scalars().first()
    if duplicate:
        raise HTTPException(status_code=409, detail="Vendor bill number already exists")

    if payload.due_date < payload.bill_date:
        raise HTTPException(status_code=400, detail="Bill due date cannot precede bill date")

    await _far_period_for_date(db, payload.bill_date)
    await _far_account(db, payload.payable_account_id, "liability")

    normalized, subtotal, vat_total, total = _far_calculate_lines(payload.lines)

    if vat_total > 0:
        if payload.input_vat_account_id is None:
            raise HTTPException(
                status_code=400,
                detail="Input VAT account is required when bill VAT is greater than zero",
            )
        await _far_account(db, payload.input_vat_account_id, "asset")

    for source_line in payload.lines:
        line_account = await _far_account(
            db,
            source_line.expense_account_id,
        )
        if line_account.account_type not in {"expense", "asset"}:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Bill line account {line_account.code} "
                    "must be an expense or asset posting account"
                ),
            )

    row = FinanceBill(
        vendor_id=payload.vendor_id,
        bill_number=payload.bill_number.strip(),
        bill_date=payload.bill_date,
        due_date=payload.due_date,
        currency=payload.currency.strip().upper() or "SAR",
        subtotal=subtotal,
        vat_amount=vat_total,
        total_amount=total,
        amount_paid=0,
        status="draft",
        payable_account_id=payload.payable_account_id,
        input_vat_account_id=payload.input_vat_account_id,
        reference=payload.reference.strip() if payload.reference else None,
        notes=payload.notes.strip() if payload.notes else None,
        bill_metadata=payload.bill_metadata or {},
        created_by=payload.created_by.strip() or "user",
    )
    db.add(row)
    await db.flush()

    for source_line, item in zip(payload.lines, normalized):
        db.add(
            FinanceBillLine(
                bill_id=row.id,
                expense_account_id=source_line.expense_account_id,
                **item,
            )
        )

    await db.flush()
    await write_audit_log(
        db,
        actor=row.created_by,
        action="finance.bill.created",
        details={
            "bill_id": str(row.id),
            "vendor_id": str(row.vendor_id),
            "bill_number": row.bill_number,
            "total_amount": str(total),
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _far_bill_payload(db, row)


@app.post("/api/finance/bills/{bill_id}/request-approval")
async def request_finance_bill_approval(
    bill_id: _far_uuid.UUID,
    payload: FinanceApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(FinanceBill, bill_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Bill not found")

    if row.status == "pending_approval" and row.approval_id:
        previous_approval = await db.get(Approval, row.approval_id)
        if previous_approval and previous_approval.status == "rejected":
            row.status = "rejected"

    if row.status not in {"draft", "rejected"}:
        raise HTTPException(status_code=409, detail="Only draft or rejected bills can request approval")

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=finance_agent.id if finance_agent else None,
        title=f"Post AP bill {row.bill_number}",
        description=f"Vendor bill total {row.total_amount} {row.currency}",
        action_type="finance_bill_posting",
        risk_level="high",
        status="pending",
        action_payload={
            "bill_id": str(row.id),
            "bill_number": row.bill_number,
            "total_amount": str(row.total_amount),
            "currency": row.currency,
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()
    row.approval_id = approval.id
    row.status = "pending_approval"
    await write_audit_log(
        db,
        actor=payload.requested_by,
        action="finance.bill.approval_requested",
        details={"bill_id": str(row.id), "approval_id": str(approval.id)},
    )
    await db.commit()
    await db.refresh(row)
    await db.refresh(approval)
    return await _far_bill_payload(db, row)


@app.post("/api/finance/bills/{bill_id}/post")
async def post_finance_bill(
    bill_id: _far_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _far_select(FinanceBill)
            .where(FinanceBill.id == bill_id)
            .with_for_update()
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(status_code=404, detail="Bill not found")

    if row.status in {"posted", "partially_paid", "paid"}:
        return await _far_bill_payload(db, row)

    approval = await db.get(Approval, row.approval_id) if row.approval_id else None
    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_bill_posting"
        or str((approval.action_payload or {}).get("bill_id") or "") != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved bill-posting authorization is required")

    lines = (
        await db.execute(
            _far_select(FinanceBillLine)
            .where(FinanceBillLine.bill_id == row.id)
            .order_by(FinanceBillLine.line_number.asc())
        )
    ).scalars().all()

    debit_lines = []
    for line in lines:
        debit_lines.append({
            "account_id": line.expense_account_id,
            "description": line.description,
            "debit": line.net_amount,
            "credit": 0,
        })

    if _far_money(row.vat_amount) > 0:
        if not row.input_vat_account_id:
            raise HTTPException(status_code=409, detail="Bill VAT account is missing")
        debit_lines.append({
            "account_id": row.input_vat_account_id,
            "description": f"Input VAT - {row.bill_number}",
            "debit": row.vat_amount,
            "credit": 0,
        })

    credit_lines = [{
        "account_id": row.payable_account_id,
        "description": f"Accounts payable - {row.bill_number}",
        "debit": 0,
        "credit": row.total_amount,
    }]

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.bill_date,
        description=f"AP Bill {row.bill_number}",
        reference=row.reference or row.bill_number,
        source_type="finance_bill",
        source_id=row.id,
        currency=row.currency,
        approval=approval,
        debit_lines=debit_lines,
        credit_lines=credit_lines,
    )

    row.journal_entry_id = entry.id
    row.status = "posted"
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.bill.posted",
        details={
            "bill_id": str(row.id),
            "journal_entry_id": str(entry.id),
            "total_amount": str(row.total_amount),
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _far_bill_payload(db, row)


