@app.post("/api/finance/invoices")
async def create_finance_invoice(
    payload: FinanceInvoiceCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    customer = await db.get(FinanceCustomer, payload.customer_id)
    if customer is None or not customer.is_active:
        raise HTTPException(status_code=409, detail="Customer is not available")

    if payload.due_date < payload.invoice_date:
        raise HTTPException(status_code=400, detail="Invoice due date cannot precede invoice date")

    await _far_period_for_date(db, payload.invoice_date)
    await _far_account(db, payload.receivable_account_id, "asset")

    normalized, subtotal, vat_total, total = _far_calculate_lines(payload.lines)

    if vat_total > 0:
        if payload.output_vat_account_id is None:
            raise HTTPException(
                status_code=400,
                detail="Output VAT account is required when invoice VAT is greater than zero",
            )
        await _far_account(db, payload.output_vat_account_id, "liability")

    for source_line in payload.lines:
        await _far_account(db, source_line.revenue_account_id, "revenue")

    invoice_number = (
        payload.invoice_number.strip()
        if payload.invoice_number
        else "INV-" + payload.invoice_date.strftime("%Y%m%d") + "-" + _far_uuid.uuid4().hex[:8].upper()
    )

    duplicate = (
        await db.execute(
            _far_select(FinanceInvoice).where(
                FinanceInvoice.invoice_number == invoice_number
            )
        )
    ).scalars().first()
    if duplicate:
        raise HTTPException(status_code=409, detail="Invoice number already exists")

    row = FinanceInvoice(
        customer_id=payload.customer_id,
        invoice_number=invoice_number,
        invoice_date=payload.invoice_date,
        due_date=payload.due_date,
        currency=payload.currency.strip().upper() or "SAR",
        subtotal=subtotal,
        vat_amount=vat_total,
        total_amount=total,
        amount_collected=0,
        status="draft",
        receivable_account_id=payload.receivable_account_id,
        output_vat_account_id=payload.output_vat_account_id,
        reference=payload.reference.strip() if payload.reference else None,
        notes=payload.notes.strip() if payload.notes else None,
        invoice_metadata=payload.invoice_metadata or {},
        created_by=payload.created_by.strip() or "user",
    )
    db.add(row)
    await db.flush()

    for source_line, item in zip(payload.lines, normalized):
        db.add(
            FinanceInvoiceLine(
                invoice_id=row.id,
                revenue_account_id=source_line.revenue_account_id,
                **item,
            )
        )

    await db.flush()
    await write_audit_log(
        db,
        actor=row.created_by,
        action="finance.invoice.created",
        details={
            "invoice_id": str(row.id),
            "customer_id": str(row.customer_id),
            "invoice_number": row.invoice_number,
            "total_amount": str(total),
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _far_invoice_payload(db, row)


@app.post("/api/finance/invoices/{invoice_id}/request-approval")
async def request_finance_invoice_approval(
    invoice_id: _far_uuid.UUID,
    payload: FinanceApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(FinanceInvoice, invoice_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Invoice not found")

    if row.status == "pending_approval" and row.approval_id:
        previous_approval = await db.get(Approval, row.approval_id)
        if previous_approval and previous_approval.status == "rejected":
            row.status = "rejected"

    if row.status not in {"draft", "rejected"}:
        raise HTTPException(status_code=409, detail="Only draft or rejected invoices can request approval")

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=finance_agent.id if finance_agent else None,
        title=f"Post AR invoice {row.invoice_number}",
        description=f"Customer invoice total {row.total_amount} {row.currency}",
        action_type="finance_invoice_posting",
        risk_level="high",
        status="pending",
        action_payload={
            "invoice_id": str(row.id),
            "invoice_number": row.invoice_number,
            "total_amount": str(row.total_amount),
            "currency": row.currency,
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()
    row.approval_id = approval.id
    row.status = "pending_approval"
    await write_audit_log(
        db,
        actor=payload.requested_by,
        action="finance.invoice.approval_requested",
        details={"invoice_id": str(row.id), "approval_id": str(approval.id)},
    )
    await db.commit()
    await db.refresh(row)
    await db.refresh(approval)
    return await _far_invoice_payload(db, row)


@app.post("/api/finance/invoices/{invoice_id}/post")
async def post_finance_invoice(
    invoice_id: _far_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _far_select(FinanceInvoice)
            .where(FinanceInvoice.id == invoice_id)
            .with_for_update()
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(status_code=404, detail="Invoice not found")

    if row.status in {"posted", "partially_collected", "collected"}:
        return await _far_invoice_payload(db, row)

    approval = await db.get(Approval, row.approval_id) if row.approval_id else None
    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_invoice_posting"
        or str((approval.action_payload or {}).get("invoice_id") or "") != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved invoice-posting authorization is required")

    lines = (
        await db.execute(
            _far_select(FinanceInvoiceLine)
            .where(FinanceInvoiceLine.invoice_id == row.id)
            .order_by(FinanceInvoiceLine.line_number.asc())
        )
    ).scalars().all()

    debit_lines = [{
        "account_id": row.receivable_account_id,
        "description": f"Accounts receivable - {row.invoice_number}",
        "debit": row.total_amount,
        "credit": 0,
    }]

    credit_lines = []
    for line in lines:
        credit_lines.append({
            "account_id": line.revenue_account_id,
            "description": line.description,
            "debit": 0,
            "credit": line.net_amount,
        })

    if _far_money(row.vat_amount) > 0:
        if not row.output_vat_account_id:
            raise HTTPException(status_code=409, detail="Invoice VAT account is missing")
        credit_lines.append({
            "account_id": row.output_vat_account_id,
            "description": f"Output VAT - {row.invoice_number}",
            "debit": 0,
            "credit": row.vat_amount,
        })

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.invoice_date,
        description=f"AR Invoice {row.invoice_number}",
        reference=row.reference or row.invoice_number,
        source_type="finance_invoice",
        source_id=row.id,
        currency=row.currency,
        approval=approval,
        debit_lines=debit_lines,
        credit_lines=credit_lines,
    )

    row.journal_entry_id = entry.id
    row.status = "posted"
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.invoice.posted",
        details={
            "invoice_id": str(row.id),
            "journal_entry_id": str(entry.id),
            "total_amount": str(row.total_amount),
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _far_invoice_payload(db, row)


