@app.post("/api/finance/bills/{bill_id}/payments")
async def create_finance_bill_payment(
    bill_id: _far_uuid.UUID,
    payload: FinanceBillPaymentCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    bill = await db.get(FinanceBill, bill_id)
    if bill is None:
        raise HTTPException(status_code=404, detail="Bill not found")
    if bill.status not in {"posted", "partially_paid"}:
        raise HTTPException(status_code=409, detail="Only posted bills can be paid")

    amount = _far_money(payload.amount)
    balance = _far_money(bill.total_amount) - _far_money(bill.amount_paid)
    if amount <= 0 or amount > balance:
        raise HTTPException(status_code=400, detail="Payment amount exceeds bill balance or is invalid")

    await _far_account(db, payload.bank_account_id, "asset")
    await _far_period_for_date(db, payload.payment_date)

    row = FinanceBillPayment(
        bill_id=bill.id,
        payment_date=payload.payment_date,
        amount=amount,
        bank_account_id=payload.bank_account_id,
        reference=payload.reference.strip() if payload.reference else None,
        status="draft",
        created_by=payload.created_by.strip() or "user",
    )
    db.add(row)
    await db.flush()
    await db.commit()
    await db.refresh(row)

    return {
        "id": str(row.id),
        "bill_id": str(row.bill_id),
        "payment_date": row.payment_date,
        "amount": float(row.amount),
        "status": row.status,
    }


