@app.post("/api/finance/bill-payments/{payment_id}/apply")
async def apply_finance_bill_payment(
    payment_id: _far_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _far_select(FinanceBillPayment)
            .where(FinanceBillPayment.id == payment_id)
            .with_for_update()
        )
    ).scalars().first()
    if row is None:
        raise HTTPException(status_code=404, detail="Bill payment not found")
    if row.status == "applied":
        return {"id": str(row.id), "status": row.status}

    bill = (
        await db.execute(
            _far_select(FinanceBill)
            .where(FinanceBill.id == row.bill_id)
            .with_for_update()
        )
    ).scalars().first()
    approval = await db.get(Approval, row.approval_id) if row.approval_id else None

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_bill_payment"
        or str((approval.action_payload or {}).get("payment_id") or "") != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved payment authorization is required")

    balance = _far_money(bill.total_amount) - _far_money(bill.amount_paid)
    amount = _far_money(row.amount)
    if amount <= 0 or amount > balance:
        raise HTTPException(status_code=409, detail="Payment no longer fits the current bill balance")

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.payment_date,
        description=f"AP Payment {bill.bill_number}",
        reference=row.reference or bill.bill_number,
        source_type="finance_bill_payment",
        source_id=row.id,
        currency=bill.currency,
        approval=approval,
        debit_lines=[{
            "account_id": bill.payable_account_id,
            "description": f"Settle AP - {bill.bill_number}",
            "debit": amount,
            "credit": 0,
        }],
        credit_lines=[{
            "account_id": row.bank_account_id,
            "description": f"Bank payment - {bill.bill_number}",
            "debit": 0,
            "credit": amount,
        }],
    )

    bill.amount_paid = _far_money(bill.amount_paid) + amount
    bill.status = (
        "paid"
        if _far_money(bill.amount_paid) >= _far_money(bill.total_amount)
        else "partially_paid"
    )
    row.status = "applied"
    row.journal_entry_id = entry.id
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.bill_payment.applied",
        details={
            "payment_id": str(row.id),
            "bill_id": str(bill.id),
            "amount": str(amount),
            "journal_entry_id": str(entry.id),
        },
    )
    await db.commit()
    return {
        "id": str(row.id),
        "status": row.status,
        "bill_status": bill.status,
        "bill_amount_paid": float(bill.amount_paid),
        "journal_entry_id": str(entry.id),
    }


