@app.get("/api/finance/ap-ar-summary")
async def finance_ap_ar_summary(
    db: AsyncSession = Depends(get_db),
):
    vendors = (
        await db.execute(_far_select(FinanceVendor))
    ).scalars().all()
    customers = (
        await db.execute(_far_select(FinanceCustomer))
    ).scalars().all()
    bills = (
        await db.execute(_far_select(FinanceBill))
    ).scalars().all()
    invoices = (
        await db.execute(_far_select(FinanceInvoice))
    ).scalars().all()

    ap_outstanding = sum(
        (
            _far_money(row.total_amount) - _far_money(row.amount_paid)
            for row in bills
            if row.status in {"posted", "partially_paid"}
        ),
        _FAR_ZERO,
    )
    ar_outstanding = sum(
        (
            _far_money(row.total_amount) - _far_money(row.amount_collected)
            for row in invoices
            if row.status in {"posted", "partially_collected"}
        ),
        _FAR_ZERO,
    )

    return {
        "vendors": {
            "total": len(vendors),
            "active": sum(1 for row in vendors if row.is_active),
        },
        "customers": {
            "total": len(customers),
            "active": sum(1 for row in customers if row.is_active),
        },
        "bills": {
            "total": len(bills),
            "outstanding_amount": float(ap_outstanding),
            "open_count": sum(
                1
                for row in bills
                if row.status in {"posted", "partially_paid"}
            ),
        },
        "invoices": {
            "total": len(invoices),
            "outstanding_amount": float(ar_outstanding),
            "open_count": sum(
                1
                for row in invoices
                if row.status in {"posted", "partially_collected"}
            ),
        },
    }

# ============================================================
# Finance - Cash, Bank, Expenses, Budget & Forecast API
# ============================================================
import uuid as _f3_uuid
from datetime import datetime as _f3_datetime, timezone as _f3_timezone
from decimal import Decimal as _f3_Decimal, ROUND_HALF_UP as _f3_ROUND_HALF_UP

from pydantic import BaseModel as _F3BaseModel
from sqlalchemy import select as _f3_select, func as _f3_func

from .models import (
    FinanceBankAccount,
    FinanceBankStatementLine,
    FinanceBankReconciliation,
    FinanceExpense,
    FinanceBudget,
    FinanceBudgetLine,
    FinanceForecast,
    FinanceForecastLine,
)

_F3_ZERO = _f3_Decimal("0.00")
_F3_Q2 = _f3_Decimal("0.01")


class FinanceBankAccountCreateRequest(_F3BaseModel):
    code: str
    bank_name: str
    account_name: str | None = None
    iban: str | None = None
    currency: str = "SAR"
    gl_account_id: _f3_uuid.UUID
    opening_balance: float = 0
    is_active: bool = True
    bank_metadata: dict = {}


class FinanceBankStatementLineCreateRequest(_F3BaseModel):
    bank_account_id: _f3_uuid.UUID
    transaction_date: _fin_date
    value_date: _fin_date | None = None
    description: str
    reference: str | None = None
    amount: float
    external_id: str | None = None
    notes: str | None = None


