    expense_account_id: _f3_uuid.UUID
    payment_account_id: _f3_uuid.UUID
    input_vat_account_id: _f3_uuid.UUID | None = None
    subtotal: float
    vat_rate: float = 0
    currency: str = "SAR"
    reference: str | None = None
    cost_center: str | None = None
    department_code: str | None = None
