@app.post("/api/finance/bank-accounts")
async def create_finance_bank_account(
    payload: FinanceBankAccountCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip()
    bank_name = payload.bank_name.strip()

    if not code or not bank_name:
        raise HTTPException(status_code=400, detail="Bank code and bank name are required")

    existing = (
        await db.execute(
            _f3_select(FinanceBankAccount).where(
                FinanceBankAccount.code == code
            )
        )
    ).scalars().first()
    if existing:
        raise HTTPException(status_code=409, detail="Bank account code already exists")

    gl = await _far_account(db, payload.gl_account_id, "asset")

    row = FinanceBankAccount(
        code=code,
        bank_name=bank_name,
        account_name=payload.account_name.strip() if payload.account_name else None,
        iban=payload.iban.replace(" ", "").upper() if payload.iban else None,
        currency=payload.currency.strip().upper() or "SAR",
        gl_account_id=gl.id,
        opening_balance=_f3_money(payload.opening_balance),
        is_active=payload.is_active,
        bank_metadata=payload.bank_metadata or {},
    )
    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="finance.bank_account.created",
        details={"bank_account_id": str(row.id), "code": row.code},
    )
    await db.commit()
    await db.refresh(row)
    return _f3_bank_payload(row)


