@app.post("/api/finance/bank-statement-lines")
async def create_finance_bank_statement_line(
    payload: FinanceBankStatementLineCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    bank = await _f3_bank_account(db, payload.bank_account_id)
    if not bank.is_active:
        raise HTTPException(status_code=409, detail="Bank account is inactive")

    description = payload.description.strip()
    if not description:
        raise HTTPException(status_code=400, detail="Statement line description is required")

    if payload.external_id:
        duplicate = (
            await db.execute(
                _f3_select(FinanceBankStatementLine).where(
                    FinanceBankStatementLine.bank_account_id == bank.id,
                    FinanceBankStatementLine.external_id == payload.external_id.strip(),
                )
            )
        ).scalars().first()
        if duplicate:
            raise HTTPException(status_code=409, detail="Statement external_id already exists for this bank account")

    amount = _f3_money(payload.amount)
    if amount == 0:
        raise HTTPException(status_code=400, detail="Statement line amount cannot be zero")

    row = FinanceBankStatementLine(
        bank_account_id=bank.id,
        transaction_date=payload.transaction_date,
        value_date=payload.value_date,
        description=description,
        reference=payload.reference.strip() if payload.reference else None,
        amount=amount,
        external_id=payload.external_id.strip() if payload.external_id else None,
        status="unmatched",
        notes=payload.notes.strip() if payload.notes else None,
    )
    db.add(row)
    await db.commit()
    await db.refresh(row)
    return _f3_statement_payload(row)


@app.post("/api/finance/bank-statement-lines/{line_id}/match")
async def match_finance_bank_statement_line(
    line_id: _f3_uuid.UUID,
    payload: FinanceBankStatementMatchRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(FinanceBankStatementLine, line_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Bank statement line not found")
    if row.status == "matched":
        return _f3_statement_payload(row)
    if row.status == "ignored":
        raise HTTPException(status_code=409, detail="Ignored statement line cannot be matched")

    bank = await _f3_bank_account(db, row.bank_account_id)
    journal_line = await db.get(FinanceJournalLine, payload.journal_line_id)
    if journal_line is None:
        raise HTTPException(status_code=404, detail="Journal line not found")
    if journal_line.account_id != bank.gl_account_id:
        raise HTTPException(status_code=409, detail="Journal line does not belong to this bank GL account")

    journal = await db.get(FinanceJournalEntry, journal_line.journal_entry_id)
    if journal is None or journal.status != "posted":
        raise HTTPException(status_code=409, detail="Only posted journal lines can be reconciled")

    expected = _f3_money(journal_line.debit) - _f3_money(journal_line.credit)
    if abs(expected - _f3_money(row.amount)) > _F3_Q2:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Statement amount {row.amount} does not match journal movement {expected}"
            ),
        )

    already = (
        await db.execute(
            _f3_select(FinanceBankStatementLine).where(
                FinanceBankStatementLine.matched_journal_line_id == journal_line.id,
                FinanceBankStatementLine.id != row.id,
                FinanceBankStatementLine.status == "matched",
            )
        )
    ).scalars().first()
    if already:
        raise HTTPException(status_code=409, detail="Journal line is already matched to another statement line")

    row.status = "matched"
    row.matched_journal_line_id = journal_line.id
    row.matched_at = _f3_datetime.now(_f3_timezone.utc)

    await write_audit_log(
        db,
        actor="user",
        action="finance.bank_statement.matched",
        details={
            "statement_line_id": str(row.id),
            "journal_line_id": str(journal_line.id),
        },
    )
    await db.commit()
    await db.refresh(row)
    return _f3_statement_payload(row)


@app.post("/api/finance/bank-statement-lines/{line_id}/ignore")
async def ignore_finance_bank_statement_line(
    line_id: _f3_uuid.UUID,
    payload: FinanceBankStatementIgnoreRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(FinanceBankStatementLine, line_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Bank statement line not found")
    if row.status == "matched":
        raise HTTPException(status_code=409, detail="Matched statement line cannot be ignored")

    reason = payload.notes.strip()
    if not reason:
        raise HTTPException(status_code=400, detail="Ignore reason is required")

    row.status = "ignored"
    row.notes = reason
    row.matched_journal_line_id = None
    row.matched_at = None
    await db.commit()
    await db.refresh(row)
    return _f3_statement_payload(row)


