@app.post("/api/finance/bank-reconciliations")
async def create_finance_bank_reconciliation(
    payload: FinanceBankReconciliationCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.statement_to < payload.statement_from:
        raise HTTPException(status_code=400, detail="Statement end date cannot precede start date")

    bank = await _f3_bank_account(db, payload.bank_account_id)
    if not bank.is_active:
        raise HTTPException(status_code=409, detail="Bank account is inactive")

    row = FinanceBankReconciliation(
        bank_account_id=bank.id,
        statement_from=payload.statement_from,
        statement_to=payload.statement_to,
        statement_ending_balance=_f3_money(payload.statement_ending_balance),
        status="draft",
        created_by=payload.created_by.strip() or "user",
        notes=payload.notes.strip() if payload.notes else None,
    )
    db.add(row)
    await db.flush()
    await write_audit_log(
        db,
        actor=row.created_by,
        action="finance.bank_reconciliation.created",
        details={"reconciliation_id": str(row.id), "bank_account_id": str(bank.id)},
    )
    await db.commit()
    await db.refresh(row)
    return await _f3_reconciliation_snapshot(db, row)


@app.post("/api/finance/bank-reconciliations/{reconciliation_id}/request-approval")
async def request_finance_bank_reconciliation_approval(
    reconciliation_id: _f3_uuid.UUID,
    payload: FinanceApprovalRequestF3,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(FinanceBankReconciliation, reconciliation_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Bank reconciliation not found")

    if row.status == "pending_approval" and row.approval_id:
        previous = await db.get(Approval, row.approval_id)
        if previous and previous.status == "rejected":
            row.status = "draft"

    if row.status != "draft":
        raise HTTPException(status_code=409, detail="Only draft reconciliation can request approval")

    snapshot = await _f3_reconciliation_snapshot(db, row)
    if abs(_f3_money(snapshot["difference"])) > _F3_Q2:
        raise HTTPException(status_code=409, detail="Reconciliation difference must be zero before approval")
    if snapshot["unmatched_count"]:
        raise HTTPException(status_code=409, detail="All statement lines must be matched or ignored before approval")

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=finance_agent.id if finance_agent else None,
        title=f"Complete bank reconciliation {row.statement_to}",
        description=(
            f"Bank reconciliation difference 0.00 for bank account {row.bank_account_id}"
        ),
        action_type="finance_bank_reconciliation",
        risk_level="high",
        status="pending",
        action_payload={
            "reconciliation_id": str(row.id),
            "bank_account_id": str(row.bank_account_id),
            "statement_to": row.statement_to.isoformat(),
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()
    row.approval_id = approval.id
    row.status = "pending_approval"
    await db.commit()
    await db.refresh(row)
    return await _f3_reconciliation_snapshot(db, row)


@app.post("/api/finance/bank-reconciliations/{reconciliation_id}/complete")
async def complete_finance_bank_reconciliation(
    reconciliation_id: _f3_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _f3_select(FinanceBankReconciliation)
            .where(FinanceBankReconciliation.id == reconciliation_id)
            .with_for_update()
        )
    ).scalars().first()
    if row is None:
        raise HTTPException(status_code=404, detail="Bank reconciliation not found")
    if row.status == "completed":
        return await _f3_reconciliation_snapshot(db, row)

    approval = await db.get(Approval, row.approval_id) if row.approval_id else None
    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_bank_reconciliation"
        or str((approval.action_payload or {}).get("reconciliation_id") or "") != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved reconciliation authorization is required")

    snapshot = await _f3_reconciliation_snapshot(db, row)
    if abs(_f3_money(snapshot["difference"])) > _F3_Q2 or snapshot["unmatched_count"]:
        raise HTTPException(status_code=409, detail="Reconciliation is no longer complete")

    now = _f3_datetime.now(_f3_timezone.utc)
    row.status = "completed"
    row.completed_at = now
    approval.executed_at = now

    await write_audit_log(
        db,
        actor="user",
        action="finance.bank_reconciliation.completed",
        details={"reconciliation_id": str(row.id), "approval_id": str(approval.id)},
    )
    await db.commit()
    await db.refresh(row)
    return await _f3_reconciliation_snapshot(db, row)


