@app.post("/api/finance/expenses/{expense_id}/post")
async def post_finance_expense(
    expense_id: _f3_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _f3_select(FinanceExpense)
            .where(FinanceExpense.id == expense_id)
            .with_for_update()
        )
    ).scalars().first()
    if row is None:
        raise HTTPException(status_code=404, detail="Expense not found")
    if row.status == "posted":
        approval = await db.get(Approval, row.approval_id) if row.approval_id else None
        return _f3_expense_payload(row, approval)

    approval = await db.get(Approval, row.approval_id) if row.approval_id else None
    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_expense_posting"
        or str((approval.action_payload or {}).get("expense_id") or "") != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved expense-posting authorization is required")

    debit_lines = [{
        "account_id": row.expense_account_id,
        "description": row.description,
        "debit": row.subtotal,
        "credit": 0,
        "line_metadata": {
            "cost_center": row.cost_center,
            "department_code": row.department_code,
        },
    }]

    if _f3_money(row.vat_amount) > 0:
        debit_lines.append({
            "account_id": row.input_vat_account_id,
            "description": f"Input VAT - {row.description}",
            "debit": row.vat_amount,
            "credit": 0,
        })

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.expense_date,
        description=f"Cash Expense - {row.description}",
        reference=row.reference,
        source_type="finance_expense",
        source_id=row.id,
        currency=row.currency,
        approval=approval,
        debit_lines=debit_lines,
        credit_lines=[{
            "account_id": row.payment_account_id,
            "description": row.description,
            "debit": 0,
            "credit": row.total_amount,
        }],
    )

    row.journal_entry_id = entry.id
    row.status = "posted"
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.expense.posted",
        details={"expense_id": str(row.id), "journal_entry_id": str(entry.id)},
    )
    await db.commit()
    await db.refresh(row)
    return _f3_expense_payload(row, approval)


