@app.post("/api/finance/budgets/{budget_id}/activate")
async def activate_finance_budget(
    budget_id: _f3_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    budget = await db.get(FinanceBudget, budget_id)
    if budget is None:
        raise HTTPException(status_code=404, detail="Budget not found")
    if budget.status == "approved" and budget.is_current:
        approval = await db.get(Approval, budget.approval_id) if budget.approval_id else None
        return _f3_plan_payload(budget, "budget", approval)

    approval = await db.get(Approval, budget.approval_id) if budget.approval_id else None
    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "finance_budget_approval"
        or str((approval.action_payload or {}).get("budget_id") or "") != str(budget.id)
    ):
        raise HTTPException(status_code=409, detail="Approved budget authorization is required")

    other_rows = (
        await db.execute(
            _f3_select(FinanceBudget).where(
                FinanceBudget.year == budget.year,
                FinanceBudget.id != budget.id,
                FinanceBudget.is_current.is_(True),
            )
        )
    ).scalars().all()
    for other in other_rows:
        other.is_current = False

    budget.status = "approved"
    budget.is_current = True
    approval.executed_at = _f3_datetime.now(_f3_timezone.utc)
    await db.commit()
    await db.refresh(budget)
    return _f3_plan_payload(budget, "budget", approval)


@app.get("/api/finance/budget-vs-actual")
async def finance_budget_vs_actual(
    budget_id: _f3_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    budget = await db.get(FinanceBudget, budget_id)
    if budget is None:
        raise HTTPException(status_code=404, detail="Budget not found")

    lines = await _f3_plan_lines(
        db, FinanceBudgetLine, FinanceBudgetLine.budget_id, budget.id
    )
    budget_map = {}
    for x in lines:
        key = (x.account_id, x.month)
        budget_map[key] = budget_map.get(key, _F3_ZERO) + _f3_money(x.amount)

    journals = (
        await db.execute(
            _f3_select(FinanceJournalEntry).where(
                FinanceJournalEntry.status == "posted",
                FinanceJournalEntry.journal_date >= _fin_date(budget.year, 1, 1),
                FinanceJournalEntry.journal_date <= _fin_date(budget.year, 12, 31),
            )
        )
    ).scalars().all()

    journal_ids = [x.id for x in journals]
    journal_map = {x.id: x for x in journals}
    actual_map = {}

    if journal_ids:
        journal_lines = (
            await db.execute(
                _f3_select(FinanceJournalLine).where(
                    FinanceJournalLine.journal_entry_id.in_(journal_ids)
                )
            )
        ).scalars().all()

        account_ids = list({x.account_id for x in journal_lines})
        account_rows = (
            await db.execute(
                _f3_select(FinanceAccount).where(FinanceAccount.id.in_(account_ids))
            )
        ).scalars().all() if account_ids else []
        account_map = {x.id: x for x in account_rows}

        for line in journal_lines:
            account = account_map.get(line.account_id)
            if account is None or account.account_type not in {"revenue", "expense"}:
                continue
            month = journal_map[line.journal_entry_id].journal_date.month
            raw = _f3_money(line.debit) - _f3_money(line.credit)
            amount = raw if account.normal_balance == "debit" else -raw
            key = (line.account_id, month)
            actual_map[key] = actual_map.get(key, _F3_ZERO) + amount

    keys = sorted(set(budget_map) | set(actual_map), key=lambda x: (str(x[0]), x[1]))
    account_ids = list({key[0] for key in keys})
    account_rows = (
        await db.execute(
            _f3_select(FinanceAccount).where(FinanceAccount.id.in_(account_ids))
        )
    ).scalars().all() if account_ids else []
    account_map = {x.id: x for x in account_rows}

    rows = []
    for account_id, month in keys:
        budget_amount = budget_map.get((account_id, month), _F3_ZERO)
        actual_amount = actual_map.get((account_id, month), _F3_ZERO)
        rows.append({
            "account_id": str(account_id),
            "account_code": account_map.get(account_id).code if account_map.get(account_id) else None,
            "account_name_ar": account_map.get(account_id).name_ar if account_map.get(account_id) else None,
            "month": month,
            "budget": float(budget_amount),
            "actual": float(actual_amount),
            "variance": float(budget_amount - actual_amount),
        })

    return {
        "budget": _f3_plan_payload(budget, "budget"),
        "rows": rows,
        "total_budget": float(sum(budget_map.values(), _F3_ZERO)),
        "total_actual": float(sum(actual_map.values(), _F3_ZERO)),
    }


