@app.get("/api/finance/batch3-summary")
async def finance_batch3_summary(
    db: AsyncSession = Depends(get_db),
):
    bank_accounts = (
        await db.execute(_f3_select(FinanceBankAccount))
    ).scalars().all()
    reconciliations = (
        await db.execute(_f3_select(FinanceBankReconciliation))
    ).scalars().all()
    expenses = (
        await db.execute(_f3_select(FinanceExpense))
    ).scalars().all()
    budgets = (
        await db.execute(_f3_select(FinanceBudget))
    ).scalars().all()
    forecasts = (
        await db.execute(_f3_select(FinanceForecast))
    ).scalars().all()

    return {
        "bank_accounts": {
            "total": len(bank_accounts),
            "active": sum(1 for x in bank_accounts if x.is_active),
        },
        "reconciliations": {
            "total": len(reconciliations),
            "completed": sum(1 for x in reconciliations if x.status == "completed"),
        },
        "expenses": {
            "total": len(expenses),
            "posted": sum(1 for x in expenses if x.status == "posted"),
            "posted_amount": float(sum(
                (_f3_money(x.total_amount) for x in expenses if x.status == "posted"),
                _F3_ZERO,
            )),
        },
        "budgets": {
            "total": len(budgets),
            "current": sum(1 for x in budgets if x.is_current),
        },
        "forecasts": {
            "total": len(forecasts),
            "current": sum(1 for x in forecasts if x.is_current),
        },
    }

# ============================================================
# Finance - Bank Reconciliation Match Candidates
# ============================================================
@app.get("/api/finance/bank-accounts/{bank_account_id}/match-candidates")
async def finance_bank_match_candidates(
    bank_account_id: _f3_uuid.UUID,
    from_date: _fin_date | None = None,
    to_date: _fin_date | None = None,
    db: AsyncSession = Depends(get_db),
):
    bank = await _f3_bank_account(db, bank_account_id)

    query = (
        _f3_select(FinanceJournalLine, FinanceJournalEntry)
        .join(
            FinanceJournalEntry,
            FinanceJournalEntry.id == FinanceJournalLine.journal_entry_id,
        )
        .where(
            FinanceJournalLine.account_id == bank.gl_account_id,
            FinanceJournalEntry.status == "posted",
        )
    )

    if from_date is not None:
        query = query.where(FinanceJournalEntry.journal_date >= from_date)
    if to_date is not None:
        query = query.where(FinanceJournalEntry.journal_date <= to_date)

    rows = (
        await db.execute(
            query.order_by(
                FinanceJournalEntry.journal_date.desc(),
                FinanceJournalEntry.entry_number.desc(),
                FinanceJournalLine.line_number.asc(),
            )
        )
    ).all()

    matched_ids = set(
        (
            await db.execute(
                _f3_select(
                    FinanceBankStatementLine.matched_journal_line_id
                ).where(
                    FinanceBankStatementLine.matched_journal_line_id.is_not(None),
                    FinanceBankStatementLine.status == "matched",
                )
            )
        ).scalars().all()
    )

    result = []
    for line, entry in rows:
        result.append({
            "journal_line_id": str(line.id),
            "journal_entry_id": str(entry.id),
            "entry_number": entry.entry_number,
            "journal_date": entry.journal_date,
            "description": line.description or entry.description,
            "reference": entry.reference,
            "source_type": entry.source_type,
            "source_id": entry.source_id,
            "debit": float(line.debit or 0),
            "credit": float(line.credit or 0),
            "amount": float(
                _f3_money(line.debit) - _f3_money(line.credit)
            ),
            "matched": line.id in matched_ids,
        })

    return result

# ============================================================
# Finance Batch 4 - Reporting, Aging, VAT & Close Control
# ============================================================
import calendar as _f4_calendar
from datetime import date as _f4_date, timedelta as _f4_timedelta
from decimal import Decimal as _f4_Decimal

from sqlalchemy import select as _f4_select, func as _f4_func


def _f4_money(value):
    return _f4_Decimal(str(value or 0)).quantize(_F3_Q2)


async def _f4_account_balances(
    db,
    *,
    from_date=None,
    to_date=None,
    account_types=None,
):
    stmt = (
        _f4_select(
            FinanceAccount.id,
            FinanceAccount.code,
            FinanceAccount.name_ar,
            FinanceAccount.name_en,
            FinanceAccount.account_type,
            FinanceAccount.normal_balance,
            _f4_func.coalesce(
                _f4_func.sum(FinanceJournalLine.debit), 0
            ).label("debit"),
            _f4_func.coalesce(
                _f4_func.sum(FinanceJournalLine.credit), 0
            ).label("credit"),
        )
        .join(
            FinanceJournalLine,
            FinanceJournalLine.account_id == FinanceAccount.id,
        )
        .join(
            FinanceJournalEntry,
            FinanceJournalEntry.id
            == FinanceJournalLine.journal_entry_id,
        )
        .where(FinanceJournalEntry.status == "posted")
    )

    if from_date is not None:
        stmt = stmt.where(
            FinanceJournalEntry.journal_date >= from_date
        )

    if to_date is not None:
        stmt = stmt.where(
            FinanceJournalEntry.journal_date <= to_date
        )

    if account_types:
        stmt = stmt.where(
            FinanceAccount.account_type.in_(list(account_types))
        )

    stmt = (
        stmt.group_by(
            FinanceAccount.id,
            FinanceAccount.code,
            FinanceAccount.name_ar,
            FinanceAccount.name_en,
            FinanceAccount.account_type,
            FinanceAccount.normal_balance,
        )
        .order_by(FinanceAccount.code.asc())
    )

    rows = (await db.execute(stmt)).all()
    output = []

    for row in rows:
        debit = _f4_money(row.debit)
        credit = _f4_money(row.credit)
        balance = (
            debit - credit
            if row.normal_balance == "debit"
            else credit - debit
        )

        output.append({
            "account_id": str(row.id),
            "code": row.code,
            "name_ar": row.name_ar,
            "name_en": row.name_en,
            "account_type": row.account_type,
            "normal_balance": row.normal_balance,
            "debit": float(debit),
            "credit": float(credit),
            "balance": float(balance),
        })

    return output


def _f4_aging_bucket(days_overdue):
    if days_overdue <= 0:
        return "current"
    if days_overdue <= 30:
        return "1_30"
    if days_overdue <= 60:
        return "31_60"
    if days_overdue <= 90:
        return "61_90"
    return "90_plus"


@app.get("/api/finance/reports/profit-loss")
async def finance_report_profit_loss(
    from_date: _fin_date,
    to_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    if to_date < from_date:
        raise HTTPException(
            status_code=400,
            detail="Report end date cannot precede start date",
        )

    rows = await _f4_account_balances(
        db,
        from_date=from_date,
        to_date=to_date,
        account_types={"revenue", "expense"},
    )

    revenues = [
        x for x in rows
        if x["account_type"] == "revenue"
    ]
    expenses = [
        x for x in rows
        if x["account_type"] == "expense"
    ]

    total_revenue = sum(
        (_f4_money(x["balance"]) for x in revenues),
        _F3_ZERO,
    )
    total_expense = sum(
        (_f4_money(x["balance"]) for x in expenses),
        _F3_ZERO,
    )

    return {
        "from_date": from_date,
        "to_date": to_date,
        "revenues": revenues,
        "expenses": expenses,
        "total_revenue": float(total_revenue),
        "total_expense": float(total_expense),
        "net_profit": float(total_revenue - total_expense),
    }


@app.get("/api/finance/reports/balance-sheet")
async def finance_report_balance_sheet(
    as_of_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    balance_rows = await _f4_account_balances(
        db,
        to_date=as_of_date,
        account_types={"asset", "liability", "equity"},
    )

    pnl_rows = await _f4_account_balances(
        db,
        to_date=as_of_date,
        account_types={"revenue", "expense"},
    )

    assets = [
        x for x in balance_rows
        if x["account_type"] == "asset"
    ]
    liabilities = [
        x for x in balance_rows
        if x["account_type"] == "liability"
    ]
    equity = [
        x for x in balance_rows
        if x["account_type"] == "equity"
    ]

    total_assets = sum(
        (_f4_money(x["balance"]) for x in assets),
        _F3_ZERO,
    )
    total_liabilities = sum(
        (_f4_money(x["balance"]) for x in liabilities),
        _F3_ZERO,
    )
    total_equity = sum(
        (_f4_money(x["balance"]) for x in equity),
        _F3_ZERO,
    )

    revenue = sum(
        (
            _f4_money(x["balance"])
            for x in pnl_rows
            if x["account_type"] == "revenue"
        ),
        _F3_ZERO,
    )
    expense = sum(
        (
            _f4_money(x["balance"])
            for x in pnl_rows
            if x["account_type"] == "expense"
        ),
        _F3_ZERO,
    )
    unclosed_earnings = revenue - expense
    liabilities_and_equity = (
        total_liabilities
        + total_equity
        + unclosed_earnings
    )
    difference = total_assets - liabilities_and_equity

    return {
        "as_of_date": as_of_date,
        "assets": assets,
        "liabilities": liabilities,
        "equity": equity,
        "total_assets": float(total_assets),
        "total_liabilities": float(total_liabilities),
        "total_equity_before_unclosed_earnings": float(
            total_equity
        ),
        "unclosed_earnings": float(unclosed_earnings),
        "total_liabilities_and_equity": float(
            liabilities_and_equity
        ),
        "balance_difference": float(difference),
        "balanced": abs(difference) <= _F3_Q2,
    }


@app.get("/api/finance/reports/cash-position")
async def finance_report_cash_position(
    as_of_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    banks = (
        await db.execute(
            _f4_select(FinanceBankAccount)
            .where(FinanceBankAccount.is_active.is_(True))
            .order_by(FinanceBankAccount.code.asc())
        )
    ).scalars().all()

    rows = []
    total = _F3_ZERO

    for bank in banks:
        ledger = await finance_account_ledger(
            account_id=bank.gl_account_id,
            from_date=None,
            to_date=as_of_date,
            db=db,
        )
        movement = _f4_money(
            ledger.get("ending_balance", 0)
        )
        balance = (
            _f4_money(bank.opening_balance)
            + movement
        )
        total += balance

        rows.append({
            "bank_account_id": str(bank.id),
            "code": bank.code,
            "bank_name": bank.bank_name,
            "account_name": bank.account_name,
            "currency": bank.currency,
            "opening_balance": float(bank.opening_balance),
            "gl_movement": float(movement),
            "balance": float(balance),
            "gl_account_id": str(bank.gl_account_id),
        })

    return {
        "as_of_date": as_of_date,
        "banks": rows,
        "total_cash_position": float(total),
    }


@app.get("/api/finance/reports/cash-movement")
async def finance_report_cash_movement(
    from_date: _fin_date,
    to_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    if to_date < from_date:
        raise HTTPException(
            status_code=400,
            detail="Report end date cannot precede start date",
        )

    banks = (
        await db.execute(
            _f4_select(FinanceBankAccount)
            .where(FinanceBankAccount.is_active.is_(True))
        )
    ).scalars().all()

    bank_gl_ids = {x.gl_account_id for x in banks}
    if not bank_gl_ids:
        return {
            "from_date": from_date,
            "to_date": to_date,
            "opening_cash": 0.0,
            "inflows": 0.0,
            "outflows": 0.0,
            "net_movement": 0.0,
            "closing_cash": 0.0,
            "by_source": [],
        }

    opening_report = await finance_report_cash_position(
        as_of_date=from_date - _f4_timedelta(days=1),
        db=db,
    )
    opening_cash = _f4_money(
        opening_report["total_cash_position"]
    )

    rows = (
        await db.execute(
            _f4_select(
                FinanceJournalLine,
                FinanceJournalEntry,
            )
            .join(
                FinanceJournalEntry,
                FinanceJournalEntry.id
                == FinanceJournalLine.journal_entry_id,
            )
            .where(
                FinanceJournalEntry.status == "posted",
                FinanceJournalEntry.journal_date >= from_date,
                FinanceJournalEntry.journal_date <= to_date,
                FinanceJournalLine.account_id.in_(
                    list(bank_gl_ids)
                ),
            )
            .order_by(
                FinanceJournalEntry.journal_date.asc(),
                FinanceJournalEntry.entry_number.asc(),
            )
        )
    ).all()

    source_map = {}
    inflows = _F3_ZERO
    outflows = _F3_ZERO

    for line, entry in rows:
        movement = (
            _f4_money(line.debit)
            - _f4_money(line.credit)
        )

        if movement > 0:
            inflows += movement
        elif movement < 0:
            outflows += -movement

        source = entry.source_type or "manual_journal"
        source_map[source] = (
            source_map.get(source, _F3_ZERO)
            + movement
        )

    net = inflows - outflows

    return {
        "from_date": from_date,
        "to_date": to_date,
        "opening_cash": float(opening_cash),
        "inflows": float(inflows),
        "outflows": float(outflows),
        "net_movement": float(net),
        "closing_cash": float(opening_cash + net),
        "by_source": [
            {
                "source_type": key,
                "net_movement": float(value),
            }
            for key, value in sorted(source_map.items())
        ],
        "note": (
            "Operational cash movement is based on registered "
            "bank GL accounts and posted journals; it is not an "
            "IFRS classification of operating/investing/financing."
        ),
    }


@app.get("/api/finance/reports/ap-aging")
async def finance_report_ap_aging(
    as_of_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    bills = (
        await db.execute(
            _f4_select(FinanceBill).where(
                FinanceBill.bill_date <= as_of_date,
                FinanceBill.status.in_(
                    ["posted", "partially_paid", "paid"]
                ),
            )
        )
    ).scalars().all()

    vendor_ids = list({x.vendor_id for x in bills})
    vendors = (
        await db.execute(
            _f4_select(FinanceVendor).where(
                FinanceVendor.id.in_(vendor_ids)
            )
        )
    ).scalars().all() if vendor_ids else []
    vendor_map = {x.id: x for x in vendors}

    payments = (
        await db.execute(
            _f4_select(
                FinanceBillPayment.bill_id,
                _f4_func.coalesce(
                    _f4_func.sum(FinanceBillPayment.amount),
                    0,
                ).label("paid"),
            )
            .where(
                FinanceBillPayment.status == "applied",
                FinanceBillPayment.payment_date <= as_of_date,
            )
            .group_by(FinanceBillPayment.bill_id)
        )
    ).all()
    paid_map = {
        row.bill_id: _f4_money(row.paid)
        for row in payments
    }

    buckets = {
        "current": _F3_ZERO,
        "1_30": _F3_ZERO,
        "31_60": _F3_ZERO,
        "61_90": _F3_ZERO,
        "90_plus": _F3_ZERO,
    }
    rows = []

    for bill in bills:
        balance = (
            _f4_money(bill.total_amount)
            - paid_map.get(bill.id, _F3_ZERO)
        )
        if balance <= 0:
            continue

        days_overdue = (
            as_of_date - bill.due_date
        ).days
        bucket = _f4_aging_bucket(days_overdue)
        buckets[bucket] += balance

        vendor = vendor_map.get(bill.vendor_id)

        rows.append({
            "bill_id": str(bill.id),
            "bill_number": bill.bill_number,
            "vendor_id": str(bill.vendor_id),
            "vendor_name": (
                vendor.name_ar
                if vendor else str(bill.vendor_id)
            ),
            "bill_date": bill.bill_date,
            "due_date": bill.due_date,
            "days_overdue": max(days_overdue, 0),
            "bucket": bucket,
            "currency": bill.currency,
            "total_amount": float(bill.total_amount),
            "paid_as_of": float(
                paid_map.get(bill.id, _F3_ZERO)
            ),
            "outstanding": float(balance),
        })

    return {
        "as_of_date": as_of_date,
        "rows": rows,
        "buckets": {
            key: float(value)
            for key, value in buckets.items()
        },
        "total_outstanding": float(
            sum(buckets.values(), _F3_ZERO)
        ),
    }


@app.get("/api/finance/reports/ar-aging")
async def finance_report_ar_aging(
    as_of_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    invoices = (
        await db.execute(
            _f4_select(FinanceInvoice).where(
                FinanceInvoice.invoice_date <= as_of_date,
                FinanceInvoice.status.in_(
                    [
                        "posted",
                        "partially_collected",
                        "collected",
                    ]
                ),
            )
        )
    ).scalars().all()

    customer_ids = list({
        x.customer_id for x in invoices
    })
    customers = (
        await db.execute(
            _f4_select(FinanceCustomer).where(
                FinanceCustomer.id.in_(customer_ids)
            )
        )
    ).scalars().all() if customer_ids else []
    customer_map = {x.id: x for x in customers}

    receipts = (
        await db.execute(
            _f4_select(
                FinanceInvoiceReceipt.invoice_id,
                _f4_func.coalesce(
                    _f4_func.sum(
                        FinanceInvoiceReceipt.amount
                    ),
                    0,
                ).label("collected"),
            )
            .where(
                FinanceInvoiceReceipt.status == "applied",
                FinanceInvoiceReceipt.receipt_date
                <= as_of_date,
            )
            .group_by(
                FinanceInvoiceReceipt.invoice_id
            )
        )
    ).all()
    receipt_map = {
        row.invoice_id: _f4_money(row.collected)
        for row in receipts
    }

    buckets = {
        "current": _F3_ZERO,
        "1_30": _F3_ZERO,
        "31_60": _F3_ZERO,
        "61_90": _F3_ZERO,
        "90_plus": _F3_ZERO,
    }
    rows = []

    for invoice in invoices:
        balance = (
            _f4_money(invoice.total_amount)
            - receipt_map.get(
                invoice.id,
                _F3_ZERO,
            )
        )
        if balance <= 0:
            continue

        days_overdue = (
            as_of_date - invoice.due_date
        ).days
        bucket = _f4_aging_bucket(days_overdue)
        buckets[bucket] += balance

        customer = customer_map.get(
            invoice.customer_id
        )

        rows.append({
            "invoice_id": str(invoice.id),
            "invoice_number": invoice.invoice_number,
            "customer_id": str(invoice.customer_id),
            "customer_name": (
                customer.name_ar
                if customer else str(invoice.customer_id)
            ),
            "invoice_date": invoice.invoice_date,
            "due_date": invoice.due_date,
            "days_overdue": max(days_overdue, 0),
            "bucket": bucket,
            "currency": invoice.currency,
            "total_amount": float(invoice.total_amount),
            "collected_as_of": float(
                receipt_map.get(
                    invoice.id,
                    _F3_ZERO,
                )
            ),
            "outstanding": float(balance),
        })

    return {
        "as_of_date": as_of_date,
        "rows": rows,
        "buckets": {
            key: float(value)
            for key, value in buckets.items()
        },
        "total_outstanding": float(
            sum(buckets.values(), _F3_ZERO)
        ),
    }


@app.get("/api/finance/reports/vat-summary")
async def finance_report_vat_summary(
    from_date: _fin_date,
    to_date: _fin_date,
    db: AsyncSession = Depends(get_db),
):
    if to_date < from_date:
        raise HTTPException(
            status_code=400,
            detail="Report end date cannot precede start date",
        )

    bills = (
        await db.execute(
            _f4_select(FinanceBill).where(
                FinanceBill.bill_date >= from_date,
                FinanceBill.bill_date <= to_date,
                FinanceBill.status.in_(
                    ["posted", "partially_paid", "paid"]
                ),
            )
        )
    ).scalars().all()

    expenses = (
        await db.execute(
            _f4_select(FinanceExpense).where(
                FinanceExpense.expense_date >= from_date,
                FinanceExpense.expense_date <= to_date,
                FinanceExpense.status == "posted",
            )
        )
    ).scalars().all()

    invoices = (
        await db.execute(
            _f4_select(FinanceInvoice).where(
                FinanceInvoice.invoice_date >= from_date,
                FinanceInvoice.invoice_date <= to_date,
                FinanceInvoice.status.in_(
                    [
                        "posted",
                        "partially_collected",
                        "collected",
                    ]
                ),
            )
        )
    ).scalars().all()

    bill_input = sum(
        (_f4_money(x.vat_amount) for x in bills),
        _F3_ZERO,
    )
    expense_input = sum(
        (_f4_money(x.vat_amount) for x in expenses),
        _F3_ZERO,
    )
    output_vat = sum(
        (_f4_money(x.vat_amount) for x in invoices),
        _F3_ZERO,
    )
    input_vat = bill_input + expense_input
    net = output_vat - input_vat

    return {
        "from_date": from_date,
        "to_date": to_date,
        "input_vat": {
            "bills": float(bill_input),
            "cash_expenses": float(expense_input),
            "total": float(input_vat),
        },
        "output_vat": {
            "invoices": float(output_vat),
            "total": float(output_vat),
        },
        "net_vat_payable": float(net),
        "position": (
            "payable"
            if net > 0
            else "recoverable"
            if net < 0
            else "zero"
        ),
        "source_counts": {
            "bills": len(bills),
            "expenses": len(expenses),
            "invoices": len(invoices),
        },
        "note": (
            "Operational VAT summary is derived from posted "
            "finance source documents. It is not a submitted "
            "ZATCA return."
        ),
    }


@app.get("/api/finance/reports/close-readiness")
async def finance_report_close_readiness(
    year: int,
    month: int,
    db: AsyncSession = Depends(get_db),
):
    if month < 1 or month > 12:
        raise HTTPException(
            status_code=400,
            detail="Month must be between 1 and 12",
        )

    last_day = _f4_calendar.monthrange(
        year, month
    )[1]
    start_date = _fin_date(year, month, 1)
    end_date = _fin_date(year, month, last_day)

    period = (
        await db.execute(
            _f4_select(FinanceAccountingPeriod).where(
                FinanceAccountingPeriod.year == year,
                FinanceAccountingPeriod.month == month,
            )
        )
    ).scalars().first()

    if period is None:
        return {
            "year": year,
            "month": month,
            "period_found": False,
            "ready_to_close": False,
            "already_closed": False,
            "blockers": [
                {
                    "code": "period_missing",
                    "count": 1,
                    "message": (
                        "Accounting period does not exist."
                    ),
                }
            ],
        }

    unposted_journals = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.journal_date >= start_date,
            FinanceJournalEntry.journal_date <= end_date,
            FinanceJournalEntry.status != "posted",
        )
    )

    unresolved_bills = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            FinanceBill
        ).where(
            FinanceBill.bill_date >= start_date,
            FinanceBill.bill_date <= end_date,
            FinanceBill.status.in_(
                ["draft", "pending_approval", "rejected"]
            ),
        )
    )

    unresolved_invoices = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            FinanceInvoice
        ).where(
            FinanceInvoice.invoice_date >= start_date,
            FinanceInvoice.invoice_date <= end_date,
            FinanceInvoice.status.in_(
                ["draft", "pending_approval", "rejected"]
            ),
        )
    )

    unresolved_expenses = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            FinanceExpense
        ).where(
            FinanceExpense.expense_date >= start_date,
            FinanceExpense.expense_date <= end_date,
            FinanceExpense.status.in_(
                ["draft", "pending_approval", "rejected"]
            ),
        )
    )

    unmatched_statement_lines = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            FinanceBankStatementLine
        ).where(
            FinanceBankStatementLine.transaction_date
            >= start_date,
            FinanceBankStatementLine.transaction_date
            <= end_date,
            FinanceBankStatementLine.status == "unmatched",
        )
    )

    active_banks = (
        await db.execute(
            _f4_select(FinanceBankAccount).where(
                FinanceBankAccount.is_active.is_(True)
            )
        )
    ).scalars().all()

    completed_recons = (
        await db.execute(
            _f4_select(
                FinanceBankReconciliation
            ).where(
                FinanceBankReconciliation.status
                == "completed",
                FinanceBankReconciliation.statement_from
                <= start_date,
                FinanceBankReconciliation.statement_to
                >= end_date,
            )
        )
    ).scalars().all()

    reconciled_bank_ids = {
        x.bank_account_id for x in completed_recons
    }
    missing_reconciliations = [
        x for x in active_banks
        if x.id not in reconciled_bank_ids
    ]

    pending_finance_approvals = (
        await db.execute(
            _f4_select(Approval).where(
                Approval.status == "pending",
                Approval.action_type.like("finance_%"),
            )
        )
    ).scalars().all()

    checks = {
        "unposted_journals": int(
            unposted_journals or 0
        ),
        "unresolved_bills": int(
            unresolved_bills or 0
        ),
        "unresolved_invoices": int(
            unresolved_invoices or 0
        ),
        "unresolved_expenses": int(
            unresolved_expenses or 0
        ),
        "unmatched_bank_statement_lines": int(
            unmatched_statement_lines or 0
        ),
        "missing_bank_reconciliations": len(
            missing_reconciliations
        ),
        "pending_finance_approvals": len(
            pending_finance_approvals
        ),
    }

    blockers = [
        {
            "code": key,
            "count": value,
            "message": key.replace("_", " "),
        }
        for key, value in checks.items()
        if value > 0
    ]

    already_closed = period.status == "closed"
    ready = (
        period.status == "open"
        and not blockers
    )

    return {
        "year": year,
        "month": month,
        "period_found": True,
        "period_id": str(period.id),
        "period_status": period.status,
        "start_date": start_date,
        "end_date": end_date,
        "already_closed": already_closed,
        "ready_to_close": ready,
        "checks": checks,
        "missing_bank_reconciliation_accounts": [
            {
                "id": str(x.id),
                "code": x.code,
                "bank_name": x.bank_name,
            }
            for x in missing_reconciliations
        ],
        "blockers": blockers,
        "note": (
            "This endpoint is advisory. Period closing still "
            "uses the existing explicit close-approval workflow."
        ),
    }


@app.get("/api/finance/reports/dashboard")
async def finance_report_dashboard(
    as_of_date: _fin_date | None = None,
    db: AsyncSession = Depends(get_db),
):
    date_value = as_of_date or _f4_date.today()
    year_start = _fin_date(
        date_value.year, 1, 1
    )

    pnl = await finance_report_profit_loss(
        from_date=year_start,
        to_date=date_value,
        db=db,
    )
    cash = await finance_report_cash_position(
        as_of_date=date_value,
        db=db,
    )
    ap = await finance_report_ap_aging(
        as_of_date=date_value,
        db=db,
    )
    ar = await finance_report_ar_aging(
        as_of_date=date_value,
        db=db,
    )

    pending_approvals = await db.scalar(
        _f4_select(
            _f4_func.count()
        ).select_from(
            Approval
        ).where(
            Approval.status == "pending",
            Approval.action_type.like("finance_%"),
        )
    )

    return {
        "as_of_date": date_value,
        "year_to_date": {
            "revenue": pnl["total_revenue"],
            "expense": pnl["total_expense"],
            "net_profit": pnl["net_profit"],
        },
        "cash_position": cash["total_cash_position"],
        "ap_outstanding": ap["total_outstanding"],
        "ar_outstanding": ar["total_outstanding"],
        "pending_finance_approvals": int(
            pending_approvals or 0
        ),
    }

# ============================================================
# Finance Batch 5 - Fixed Assets, Depreciation & Accruals API
# ============================================================
import calendar as _f5_calendar
import uuid as _f5_uuid
from datetime import datetime as _f5_datetime, timezone as _f5_timezone
from decimal import Decimal as _f5_Decimal, ROUND_HALF_UP as _f5_ROUND_HALF_UP

from pydantic import BaseModel as _F5BaseModel
from sqlalchemy import select as _f5_select, func as _f5_func

from .models import (
    FinanceFixedAsset,
    FinanceDepreciationRun,
    FinanceDepreciationLine,
    FinanceAccrual,
)

_F5_ZERO = _f5_Decimal("0.00")
_F5_Q2 = _f5_Decimal("0.01")


class FinanceFixedAssetCreateRequest(_F5BaseModel):
    code: str
    name_ar: str
    name_en: str | None = None
    category: str | None = None
    acquisition_date: _fin_date
    placed_in_service_date: _fin_date
    acquisition_cost: float
    salvage_value: float = 0
    useful_life_months: int
    depreciation_method: str = "straight_line"
    asset_account_id: _f5_uuid.UUID
    accumulated_depreciation_account_id: _f5_uuid.UUID
    depreciation_expense_account_id: _f5_uuid.UUID
    vendor_id: _f5_uuid.UUID | None = None
    serial_number: str | None = None
    location: str | None = None
    notes: str | None = None
    asset_metadata: dict = {}


class FinanceDepreciationRunCreateRequest(_F5BaseModel):
    year: int
    month: int
    created_by: str = "user"
    notes: str | None = None


class FinanceApprovalRequestF5(_F5BaseModel):
    requested_by: str = "user"
    notes: str | None = None


class FinanceAccrualCreateRequest(_F5BaseModel):
    code: str
    description: str
    accrual_date: _fin_date
    reversal_date: _fin_date
    amount: float
    currency: str = "SAR"
    expense_account_id: _f5_uuid.UUID
    accrued_liability_account_id: _f5_uuid.UUID
    reference: str | None = None
    department_code: str | None = None
    cost_center: str | None = None
    created_by: str = "user"
    notes: str | None = None
    accrual_metadata: dict = {}


def _f5_money(value):
    return _f5_Decimal(str(value or 0)).quantize(
        _F5_Q2,
        rounding=_f5_ROUND_HALF_UP,
    )


def _f5_asset_payload(row, accumulated=None):
    depreciable = (
        _f5_money(row.acquisition_cost)
        - _f5_money(row.salvage_value)
    )
    accumulated_value = (
        _f5_money(accumulated)
        if accumulated is not None
        else _F5_ZERO
    )
    net_book_value = (
        _f5_money(row.acquisition_cost)
        - accumulated_value
    )

    return {
        "id": str(row.id),
        "code": row.code,
        "name_ar": row.name_ar,
        "name_en": row.name_en,
        "category": row.category,
        "acquisition_date": row.acquisition_date,
        "placed_in_service_date": row.placed_in_service_date,
        "acquisition_cost": float(row.acquisition_cost),
        "salvage_value": float(row.salvage_value),
        "depreciable_amount": float(depreciable),
        "useful_life_months": row.useful_life_months,
        "depreciation_method": row.depreciation_method,
        "asset_account_id": str(row.asset_account_id),
        "accumulated_depreciation_account_id": str(
            row.accumulated_depreciation_account_id
        ),
        "depreciation_expense_account_id": str(
            row.depreciation_expense_account_id
        ),
        "vendor_id": str(row.vendor_id) if row.vendor_id else None,
        "status": row.status,
        "serial_number": row.serial_number,
        "location": row.location,
        "accumulated_depreciation": float(accumulated_value),
        "net_book_value": float(net_book_value),
        "notes": row.notes,
        "asset_metadata": row.asset_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _f5_posted_asset_depreciation(db, asset_id):
    value = await db.scalar(
        _f5_select(
            _f5_func.coalesce(
                _f5_func.sum(FinanceDepreciationLine.amount),
                0,
            )
        )
        .select_from(FinanceDepreciationLine)
        .join(
            FinanceDepreciationRun,
            FinanceDepreciationRun.id
            == FinanceDepreciationLine.run_id,
        )
        .where(
            FinanceDepreciationLine.asset_id == asset_id,
            FinanceDepreciationRun.status == "posted",
        )
    )
    return _f5_money(value)


async def _f5_run_payload(db, row):
    lines = (
        await db.execute(
            _f5_select(FinanceDepreciationLine)
            .where(FinanceDepreciationLine.run_id == row.id)
            .order_by(FinanceDepreciationLine.created_at.asc())
        )
    ).scalars().all()

    approval = (
        await db.get(Approval, row.approval_id)
        if row.approval_id else None
    )

    return {
        "id": str(row.id),
        "year": row.year,
        "month": row.month,
        "run_date": row.run_date,
        "status": row.status,
        "total_depreciation": float(row.total_depreciation),
        "approval_id": (
            str(row.approval_id)
            if row.approval_id else None
        ),
        "approval_status": (
            approval.status if approval else None
        ),
        "journal_entry_id": (
            str(row.journal_entry_id)
            if row.journal_entry_id else None
        ),
        "created_by": row.created_by,
        "notes": row.notes,
        "line_count": len(lines),
        "lines": [
            {
                "id": str(line.id),
                "asset_id": str(line.asset_id),
                "amount": float(line.amount),
                "accumulated_before": float(
                    line.accumulated_before
                ),
                "accumulated_after": float(
                    line.accumulated_after
                ),
            }
            for line in lines
        ],
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _f5_accrual_payload(row, approval=None, reversal_approval=None):
    return {
        "id": str(row.id),
        "code": row.code,
        "description": row.description,
        "accrual_date": row.accrual_date,
        "reversal_date": row.reversal_date,
        "amount": float(row.amount),
        "currency": row.currency,
        "expense_account_id": str(row.expense_account_id),
        "accrued_liability_account_id": str(
            row.accrued_liability_account_id
        ),
        "status": row.status,
        "approval_id": (
            str(row.approval_id)
            if row.approval_id else None
        ),
        "approval_status": (
            approval.status if approval else None
        ),
        "journal_entry_id": (
            str(row.journal_entry_id)
            if row.journal_entry_id else None
        ),
        "reversal_approval_id": (
            str(row.reversal_approval_id)
            if row.reversal_approval_id else None
        ),
        "reversal_approval_status": (
            reversal_approval.status
            if reversal_approval else None
        ),
        "reversal_journal_entry_id": (
            str(row.reversal_journal_entry_id)
            if row.reversal_journal_entry_id else None
        ),
        "reference": row.reference,
        "department_code": row.department_code,
        "cost_center": row.cost_center,
        "created_by": row.created_by,
        "notes": row.notes,
        "accrual_metadata": row.accrual_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


@app.get("/api/finance/fixed-assets")
async def list_finance_fixed_assets(
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _f5_select(FinanceFixedAsset)
    if status:
        query = query.where(
            FinanceFixedAsset.status == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(FinanceFixedAsset.code.asc())
        )
    ).scalars().all()

    output = []
    for row in rows:
        accumulated = await _f5_posted_asset_depreciation(
            db, row.id
        )
        output.append(
            _f5_asset_payload(row, accumulated)
        )
    return output


@app.post("/api/finance/fixed-assets")
async def create_finance_fixed_asset(
    payload: FinanceFixedAssetCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip()
    name_ar = payload.name_ar.strip()

    if not code or not name_ar:
        raise HTTPException(
            status_code=400,
            detail="Asset code and Arabic name are required",
        )

    existing = (
        await db.execute(
            _f5_select(FinanceFixedAsset).where(
                FinanceFixedAsset.code == code
            )
        )
    ).scalars().first()
    if existing:
        raise HTTPException(
            status_code=409,
            detail="Fixed asset code already exists",
        )

    if payload.placed_in_service_date < payload.acquisition_date:
        raise HTTPException(
            status_code=400,
            detail=(
                "Placed-in-service date cannot precede "
                "acquisition date"
            ),
        )

    cost = _f5_money(payload.acquisition_cost)
    salvage = _f5_money(payload.salvage_value)

    if cost <= 0:
        raise HTTPException(
            status_code=400,
            detail="Acquisition cost must be greater than zero",
        )
    if salvage < 0 or salvage >= cost:
        raise HTTPException(
            status_code=400,
            detail="Salvage value must be >= 0 and less than cost",
        )
    if payload.useful_life_months <= 0:
        raise HTTPException(
            status_code=400,
            detail="Useful life must be greater than zero",
        )
    if payload.depreciation_method != "straight_line":
        raise HTTPException(
            status_code=400,
            detail="Only straight_line depreciation is supported",
        )

    await _far_account(
        db, payload.asset_account_id, "asset"
    )
    await _far_account(
        db,
        payload.accumulated_depreciation_account_id,
        "asset",
    )
    await _far_account(
        db,
        payload.depreciation_expense_account_id,
        "expense",
    )

    if payload.vendor_id:
        vendor = await db.get(
            FinanceVendor, payload.vendor_id
        )
        if vendor is None:
            raise HTTPException(
                status_code=404,
                detail="Vendor not found",
            )

    row = FinanceFixedAsset(
        code=code,
        name_ar=name_ar,
        name_en=(
            payload.name_en.strip()
            if payload.name_en else None
        ),
        category=(
            payload.category.strip()
            if payload.category else None
        ),
        acquisition_date=payload.acquisition_date,
        placed_in_service_date=payload.placed_in_service_date,
        acquisition_cost=cost,
        salvage_value=salvage,
        useful_life_months=payload.useful_life_months,
        depreciation_method=payload.depreciation_method,
        asset_account_id=payload.asset_account_id,
        accumulated_depreciation_account_id=(
            payload.accumulated_depreciation_account_id
        ),
        depreciation_expense_account_id=(
            payload.depreciation_expense_account_id
        ),
        vendor_id=payload.vendor_id,
        status="active",
        serial_number=(
            payload.serial_number.strip()
            if payload.serial_number else None
        ),
        location=(
            payload.location.strip()
            if payload.location else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes else None
        ),
        asset_metadata=payload.asset_metadata or {},
    )
    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="finance.fixed_asset.created",
        details={
            "asset_id": str(row.id),
            "code": row.code,
            "acquisition_cost": str(cost),
        },
    )

    await db.commit()
    await db.refresh(row)
    return _f5_asset_payload(row, _F5_ZERO)


@app.get("/api/finance/depreciation-runs")
async def list_finance_depreciation_runs(
    year: int | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _f5_select(FinanceDepreciationRun)
    if year is not None:
        query = query.where(
            FinanceDepreciationRun.year == year
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceDepreciationRun.year.desc(),
                FinanceDepreciationRun.month.desc(),
            )
        )
    ).scalars().all()

    return [
        await _f5_run_payload(db, row)
        for row in rows
    ]


@app.post("/api/finance/depreciation-runs")
async def create_finance_depreciation_run(
    payload: FinanceDepreciationRunCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.month < 1 or payload.month > 12:
        raise HTTPException(
            status_code=400,
            detail="Month must be between 1 and 12",
        )

    existing = (
        await db.execute(
            _f5_select(FinanceDepreciationRun).where(
                FinanceDepreciationRun.year
                == payload.year,
                FinanceDepreciationRun.month
                == payload.month,
                FinanceDepreciationRun.status.in_(
                    ["draft", "pending_approval", "posted"]
                ),
            )
        )
    ).scalars().first()
    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "Depreciation run already exists "
                "for this month"
            ),
        )

    last_day = _f5_calendar.monthrange(
        payload.year, payload.month
    )[1]
    run_date = _fin_date(
        payload.year, payload.month, last_day
    )

    await _fin_get_period_for_date(db, run_date)

    assets = (
        await db.execute(
            _f5_select(FinanceFixedAsset).where(
                FinanceFixedAsset.status == "active",
                FinanceFixedAsset.placed_in_service_date
                <= run_date,
            )
        )
    ).scalars().all()

    run = FinanceDepreciationRun(
        year=payload.year,
        month=payload.month,
        run_date=run_date,
        status="draft",
        total_depreciation=0,
        created_by=payload.created_by.strip() or "user",
        notes=(
            payload.notes.strip()
            if payload.notes else None
        ),
    )
    db.add(run)
    await db.flush()

    total = _F5_ZERO

    for asset in assets:
        depreciable = (
            _f5_money(asset.acquisition_cost)
            - _f5_money(asset.salvage_value)
        )
        accumulated = await _f5_posted_asset_depreciation(
            db, asset.id
        )

        remaining = depreciable - accumulated
        if remaining <= 0:
            continue

        monthly = (
            depreciable
            / _f5_Decimal(
                str(asset.useful_life_months)
            )
        ).quantize(
            _F5_Q2,
            rounding=_f5_ROUND_HALF_UP,
        )
        amount = min(monthly, remaining)

        if amount <= 0:
            continue

        db.add(
            FinanceDepreciationLine(
                run_id=run.id,
                asset_id=asset.id,
                amount=amount,
                accumulated_before=accumulated,
                accumulated_after=accumulated + amount,
            )
        )
        total += amount

    if total <= 0:
        await db.rollback()
        raise HTTPException(
            status_code=409,
            detail=(
                "No depreciable fixed assets are eligible "
                "for this run"
            ),
        )

    run.total_depreciation = total

    await write_audit_log(
        db,
        actor=run.created_by,
        action="finance.depreciation_run.created",
        details={
            "run_id": str(run.id),
            "year": run.year,
            "month": run.month,
            "total_depreciation": str(total),
        },
    )

    await db.commit()
    await db.refresh(run)
    return await _f5_run_payload(db, run)


@app.post("/api/finance/depreciation-runs/{run_id}/request-approval")
async def request_finance_depreciation_approval(
    run_id: _f5_uuid.UUID,
    payload: FinanceApprovalRequestF5,
    db: AsyncSession = Depends(get_db),
):
    run = await db.get(
        FinanceDepreciationRun, run_id
    )
    if run is None:
        raise HTTPException(
            status_code=404,
            detail="Depreciation run not found",
        )

    if run.status == "pending_approval" and run.approval_id:
        previous = await db.get(
            Approval, run.approval_id
        )
        if previous and previous.status == "rejected":
            run.status = "draft"

    if run.status != "draft":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only draft depreciation run can "
                "request approval"
            ),
        )

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=(
            finance_agent.id
            if finance_agent else None
        ),
        title=(
            f"Post depreciation "
            f"{run.year}-{run.month:02d}"
        ),
        description=(
            f"Monthly depreciation total "
            f"{run.total_depreciation} SAR"
        ),
        action_type="finance_depreciation_posting",
        risk_level="high",
        status="pending",
        action_payload={
            "run_id": str(run.id),
            "year": run.year,
            "month": run.month,
            "total_depreciation": str(
                run.total_depreciation
            ),
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()

    run.approval_id = approval.id
    run.status = "pending_approval"

    await db.commit()
    await db.refresh(run)
    return await _f5_run_payload(db, run)


@app.post("/api/finance/depreciation-runs/{run_id}/post")
async def post_finance_depreciation_run(
    run_id: _f5_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    run = (
        await db.execute(
            _f5_select(FinanceDepreciationRun)
            .where(
                FinanceDepreciationRun.id == run_id
            )
            .with_for_update()
        )
    ).scalars().first()

    if run is None:
        raise HTTPException(
            status_code=404,
            detail="Depreciation run not found",
        )

    if run.status == "posted":
        return await _f5_run_payload(db, run)

    approval = (
        await db.get(Approval, run.approval_id)
        if run.approval_id else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "finance_depreciation_posting"
        or str(
            (approval.action_payload or {}).get(
                "run_id"
            ) or ""
        )
        != str(run.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved depreciation-posting "
                "authorization is required"
            ),
        )

    lines = (
        await db.execute(
            _f5_select(FinanceDepreciationLine)
            .where(
                FinanceDepreciationLine.run_id
                == run.id
            )
        )
    ).scalars().all()

    if not lines:
        raise HTTPException(
            status_code=409,
            detail="Depreciation run has no lines",
        )

    asset_ids = list({
        line.asset_id for line in lines
    })
    assets = (
        await db.execute(
            _f5_select(FinanceFixedAsset).where(
                FinanceFixedAsset.id.in_(asset_ids)
            )
        )
    ).scalars().all()
    asset_map = {
        asset.id: asset for asset in assets
    }

    debit_lines = []
    credit_lines = []

    for line in lines:
        asset = asset_map.get(line.asset_id)
        if asset is None:
            raise HTTPException(
                status_code=409,
                detail="Depreciation asset is missing",
            )

        debit_lines.append({
            "account_id": (
                asset.depreciation_expense_account_id
            ),
            "description": (
                f"Depreciation - {asset.code}"
            ),
            "debit": line.amount,
            "credit": 0,
            "line_metadata": {
                "asset_id": str(asset.id),
                "asset_code": asset.code,
            },
        })
        credit_lines.append({
            "account_id": (
                asset.accumulated_depreciation_account_id
            ),
            "description": (
                f"Accumulated depreciation - "
                f"{asset.code}"
            ),
            "debit": 0,
            "credit": line.amount,
            "line_metadata": {
                "asset_id": str(asset.id),
                "asset_code": asset.code,
            },
        })

    entry = await _far_create_posted_journal(
        db,
        journal_date=run.run_date,
        description=(
            f"Depreciation "
            f"{run.year}-{run.month:02d}"
        ),
        reference=(
            f"DEP-{run.year}-{run.month:02d}"
        ),
        source_type="finance_depreciation",
        source_id=run.id,
        currency="SAR",
        approval=approval,
        debit_lines=debit_lines,
        credit_lines=credit_lines,
    )

    run.status = "posted"
    run.journal_entry_id = entry.id
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.depreciation_run.posted",
        details={
            "run_id": str(run.id),
            "journal_entry_id": str(entry.id),
            "total_depreciation": str(
                run.total_depreciation
            ),
        },
    )

    await db.commit()
    await db.refresh(run)
    return await _f5_run_payload(db, run)


@app.get("/api/finance/accruals")
async def list_finance_accruals(
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _f5_select(FinanceAccrual)
    if status:
        query = query.where(
            FinanceAccrual.status == status.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceAccrual.accrual_date.desc(),
                FinanceAccrual.created_at.desc(),
            )
        )
    ).scalars().all()

    output = []
    for row in rows:
        approval = (
            await db.get(Approval, row.approval_id)
            if row.approval_id else None
        )
        reversal_approval = (
            await db.get(
                Approval, row.reversal_approval_id
            )
            if row.reversal_approval_id else None
        )
        output.append(
            _f5_accrual_payload(
                row,
                approval,
                reversal_approval,
            )
        )

    return output


@app.post("/api/finance/accruals")
async def create_finance_accrual(
    payload: FinanceAccrualCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = payload.code.strip()
    description = payload.description.strip()

    if not code or not description:
        raise HTTPException(
            status_code=400,
            detail=(
                "Accrual code and description are required"
            ),
        )

    duplicate = (
        await db.execute(
            _f5_select(FinanceAccrual).where(
                FinanceAccrual.code == code
            )
        )
    ).scalars().first()
    if duplicate:
        raise HTTPException(
            status_code=409,
            detail="Accrual code already exists",
        )

    if payload.reversal_date <= payload.accrual_date:
        raise HTTPException(
            status_code=400,
            detail=(
                "Reversal date must be after accrual date"
            ),
        )

    amount = _f5_money(payload.amount)
    if amount <= 0:
        raise HTTPException(
            status_code=400,
            detail="Accrual amount must be greater than zero",
        )

    await _fin_get_period_for_date(
        db, payload.accrual_date
    )
    await _far_account(
        db, payload.expense_account_id, "expense"
    )
    await _far_account(
        db,
        payload.accrued_liability_account_id,
        "liability",
    )

    row = FinanceAccrual(
        code=code,
        description=description,
        accrual_date=payload.accrual_date,
        reversal_date=payload.reversal_date,
        amount=amount,
        currency=payload.currency.strip().upper() or "SAR",
        expense_account_id=payload.expense_account_id,
        accrued_liability_account_id=(
            payload.accrued_liability_account_id
        ),
        status="draft",
        reference=(
            payload.reference.strip()
            if payload.reference else None
        ),
        department_code=(
            payload.department_code.strip()
            if payload.department_code else None
        ),
        cost_center=(
            payload.cost_center.strip()
            if payload.cost_center else None
        ),
        created_by=payload.created_by.strip() or "user",
        notes=(
            payload.notes.strip()
            if payload.notes else None
        ),
        accrual_metadata=payload.accrual_metadata or {},
    )
    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor=row.created_by,
        action="finance.accrual.created",
        details={
            "accrual_id": str(row.id),
            "code": row.code,
            "amount": str(amount),
        },
    )

    await db.commit()
    await db.refresh(row)
    return _f5_accrual_payload(row)


@app.post("/api/finance/accruals/{accrual_id}/request-approval")
async def request_finance_accrual_approval(
    accrual_id: _f5_uuid.UUID,
    payload: FinanceApprovalRequestF5,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        FinanceAccrual, accrual_id
    )
    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Accrual not found",
        )

    if row.status == "pending_approval" and row.approval_id:
        previous = await db.get(
            Approval, row.approval_id
        )
        if previous and previous.status == "rejected":
            row.status = "rejected"

    if row.status not in {"draft", "rejected"}:
        raise HTTPException(
            status_code=409,
            detail=(
                "Only draft or rejected accrual can "
                "request approval"
            ),
        )

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=(
            finance_agent.id
            if finance_agent else None
        ),
        title=f"Post accrual {row.code}",
        description=(
            f"{row.description} | "
            f"{row.amount} {row.currency}"
        ),
        action_type="finance_accrual_posting",
        risk_level="high",
        status="pending",
        action_payload={
            "accrual_id": str(row.id),
            "code": row.code,
            "amount": str(row.amount),
            "currency": row.currency,
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)
    return _f5_accrual_payload(
        row, approval
    )


@app.post("/api/finance/accruals/{accrual_id}/post")
async def post_finance_accrual(
    accrual_id: _f5_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _f5_select(FinanceAccrual)
            .where(FinanceAccrual.id == accrual_id)
            .with_for_update()
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Accrual not found",
        )

    if row.status in {"posted", "reversed"}:
        approval = (
            await db.get(Approval, row.approval_id)
            if row.approval_id else None
        )
        reversal_approval = (
            await db.get(
                Approval, row.reversal_approval_id
            )
            if row.reversal_approval_id else None
        )
        return _f5_accrual_payload(
            row,
            approval,
            reversal_approval,
        )

    approval = (
        await db.get(Approval, row.approval_id)
        if row.approval_id else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "finance_accrual_posting"
        or str(
            (approval.action_payload or {}).get(
                "accrual_id"
            ) or ""
        )
        != str(row.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved accrual-posting authorization "
                "is required"
            ),
        )

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.accrual_date,
        description=f"Accrual - {row.code}",
        reference=row.reference or row.code,
        source_type="finance_accrual",
        source_id=row.id,
        currency=row.currency,
        approval=approval,
        debit_lines=[{
            "account_id": row.expense_account_id,
            "description": row.description,
            "debit": row.amount,
            "credit": 0,
            "line_metadata": {
                "department_code": row.department_code,
                "cost_center": row.cost_center,
            },
        }],
        credit_lines=[{
            "account_id": (
                row.accrued_liability_account_id
            ),
            "description": row.description,
            "debit": 0,
            "credit": row.amount,
        }],
    )

    row.status = "posted"
    row.journal_entry_id = entry.id
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.accrual.posted",
        details={
            "accrual_id": str(row.id),
            "journal_entry_id": str(entry.id),
        },
    )

    await db.commit()
    await db.refresh(row)
    return _f5_accrual_payload(
        row, approval
    )


@app.post("/api/finance/accruals/{accrual_id}/request-reversal-approval")
async def request_finance_accrual_reversal_approval(
    accrual_id: _f5_uuid.UUID,
    payload: FinanceApprovalRequestF5,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        FinanceAccrual, accrual_id
    )
    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Accrual not found",
        )

    if row.status == "reversed":
        reversal_approval = (
            await db.get(
                Approval, row.reversal_approval_id
            )
            if row.reversal_approval_id else None
        )
        approval = (
            await db.get(Approval, row.approval_id)
            if row.approval_id else None
        )
        return _f5_accrual_payload(
            row,
            approval,
            reversal_approval,
        )

    if row.status != "posted":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only posted accrual can request reversal"
            ),
        )

    if row.reversal_approval_id:
        previous = await db.get(
            Approval, row.reversal_approval_id
        )
        if previous and previous.status == "pending":
            return _f5_accrual_payload(
                row,
                await db.get(Approval, row.approval_id),
                previous,
            )

    await _fin_get_period_for_date(
        db, row.reversal_date
    )

    finance_agent = await _far_finance_agent(db)
    approval = Approval(
        agent_id=(
            finance_agent.id
            if finance_agent else None
        ),
        title=f"Reverse accrual {row.code}",
        description=(
            f"Reverse {row.amount} {row.currency} "
            f"on {row.reversal_date}"
        ),
        action_type="finance_accrual_reversal",
        risk_level="high",
        status="pending",
        action_payload={
            "accrual_id": str(row.id),
            "reversal_date": (
                row.reversal_date.isoformat()
            ),
            "amount": str(row.amount),
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()

    row.reversal_approval_id = approval.id

    await db.commit()
    await db.refresh(row)

    original_approval = (
        await db.get(Approval, row.approval_id)
        if row.approval_id else None
    )

    return _f5_accrual_payload(
        row,
        original_approval,
        approval,
    )


@app.post("/api/finance/accruals/{accrual_id}/reverse")
async def reverse_finance_accrual(
    accrual_id: _f5_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = (
        await db.execute(
            _f5_select(FinanceAccrual)
            .where(FinanceAccrual.id == accrual_id)
            .with_for_update()
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Accrual not found",
        )

    if row.status == "reversed":
        approval = (
            await db.get(Approval, row.approval_id)
            if row.approval_id else None
        )
        reversal_approval = (
            await db.get(
                Approval, row.reversal_approval_id
            )
            if row.reversal_approval_id else None
        )
        return _f5_accrual_payload(
            row,
            approval,
            reversal_approval,
        )

    if row.status != "posted":
        raise HTTPException(
            status_code=409,
            detail="Only posted accrual can be reversed",
        )

    approval = (
        await db.get(
            Approval, row.reversal_approval_id
        )
        if row.reversal_approval_id else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "finance_accrual_reversal"
        or str(
            (approval.action_payload or {}).get(
                "accrual_id"
            ) or ""
        )
        != str(row.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved accrual-reversal authorization "
                "is required"
            ),
        )

    entry = await _far_create_posted_journal(
        db,
        journal_date=row.reversal_date,
        description=(
            f"Accrual Reversal - {row.code}"
        ),
        reference=row.reference or row.code,
        source_type="finance_accrual_reversal",
        source_id=row.id,
        currency=row.currency,
        approval=approval,
        debit_lines=[{
            "account_id": (
                row.accrued_liability_account_id
            ),
            "description": row.description,
            "debit": row.amount,
            "credit": 0,
        }],
        credit_lines=[{
            "account_id": row.expense_account_id,
            "description": row.description,
            "debit": 0,
            "credit": row.amount,
            "line_metadata": {
                "department_code": row.department_code,
                "cost_center": row.cost_center,
            },
        }],
    )

    row.status = "reversed"
    row.reversal_journal_entry_id = entry.id
    approval.executed_at = entry.posted_at

    await write_audit_log(
        db,
        actor="user",
        action="finance.accrual.reversed",
        details={
            "accrual_id": str(row.id),
            "journal_entry_id": str(entry.id),
        },
    )

    await db.commit()
    await db.refresh(row)

    original_approval = (
        await db.get(Approval, row.approval_id)
        if row.approval_id else None
    )

    return _f5_accrual_payload(
        row,
        original_approval,
        approval,
    )


@app.get("/api/finance/batch5-summary")
async def finance_batch5_summary(
    db: AsyncSession = Depends(get_db),
):
    assets = (
        await db.execute(
            _f5_select(FinanceFixedAsset)
        )
    ).scalars().all()
    runs = (
        await db.execute(
            _f5_select(FinanceDepreciationRun)
        )
    ).scalars().all()
    accruals = (
        await db.execute(
            _f5_select(FinanceAccrual)
        )
    ).scalars().all()

    total_cost = sum(
        (
            _f5_money(x.acquisition_cost)
            for x in assets
            if x.status == "active"
        ),
        _F5_ZERO,
    )

    total_accumulated = _F5_ZERO
    for asset in assets:
        total_accumulated += (
            await _f5_posted_asset_depreciation(
                db, asset.id
            )
        )

    return {
        "fixed_assets": {
            "total": len(assets),
            "active": sum(
                1 for x in assets
                if x.status == "active"
            ),
            "acquisition_cost": float(total_cost),
            "accumulated_depreciation": float(
                total_accumulated
            ),
            "net_book_value": float(
                total_cost - total_accumulated
            ),
        },
        "depreciation_runs": {
            "total": len(runs),
            "posted": sum(
                1 for x in runs
                if x.status == "posted"
            ),
            "posted_amount": float(
                sum(
                    (
                        _f5_money(
                            x.total_depreciation
                        )
                        for x in runs
                        if x.status == "posted"
                    ),
                    _F5_ZERO,
                )
            ),
        },
        "accruals": {
            "total": len(accruals),
            "open": sum(
                1 for x in accruals
                if x.status == "posted"
            ),
            "reversed": sum(
                1 for x in accruals
                if x.status == "reversed"
            ),
            "open_amount": float(
                sum(
                    (
                        _f5_money(x.amount)
                        for x in accruals
                        if x.status == "posted"
                    ),
                    _F5_ZERO,
                )
            ),
        },
    }

