_DI_FINANCE_HEADER_MAPS = {}
for _di_fin_adapter, _di_fin_fields in _DI_FINANCE_ALIASES.items():
    _map = {}
    for _field, _aliases in _di_fin_fields.items():
        for _alias in _aliases:
            _map[_di_header_key(_alias)] = _field
    _DI_FINANCE_HEADER_MAPS[_di_fin_adapter] = _map


def _di_finance_canonical_field(adapter, header):
    key = _di_header_key(header)
    mapping = _DI_FINANCE_HEADER_MAPS.get(adapter, {})
    if key in mapping:
        return mapping[key]
    underscored = key.replace(" ", "_")
    if underscored in _DI_FINANCE_ALIASES.get(adapter, {}):
        return underscored
    return None


def _di_finance_normalize_record(adapter, record):
    normalized = {}
    unknown_headers = []

    for header, value in record.items():
        field = _di_finance_canonical_field(adapter, header)
        if not field:
            if value not in (None, ""):
                unknown_headers.append(str(header))
            continue
        normalized[field] = value

    return normalized, unknown_headers


def _di_finance_issue(issues, field, message, severity="error"):
    issues.append({
        "severity": severity,
        "field": field,
        "message": message,
    })


def _di_finance_status(issues):
    errors = [x for x in issues if x.get("severity") == "error"]
    warnings = [x for x in issues if x.get("severity") == "warning"]
    return (
        "error"
        if errors
        else "warning"
        if warnings
        else "valid"
    ), {
        "items": issues,
        "error_count": len(errors),
        "warning_count": len(warnings),
    }


def _di_finance_decimal(value, field, issues, default=None):
    if value in (None, ""):
        return default
    try:
        return _di_Decimal(_di_parse_decimal(value))
    except Exception as exc:
        _di_finance_issue(issues, field, str(exc))
        return default


def _di_finance_rate(value, field, issues):
    raw = _di_finance_decimal(value, field, issues, _di_Decimal("0"))
    if raw is None:
        raw = _di_Decimal("0")
    if raw < 0 or raw > 100:
        _di_finance_issue(
            issues,
            field,
            "VAT rate must be between 0 and 100",
        )
        return _di_Decimal("0")
    return raw


async def _di_finance_reference_maps(db):
    accounts = (
        await db.execute(
            _di_select(FinanceAccount)
        )
    ).scalars().all()

    vendors = (
        await db.execute(
            _di_select(FinanceVendor)
        )
    ).scalars().all()

    customers = (
        await db.execute(
            _di_select(FinanceCustomer)
        )
    ).scalars().all()

    banks = (
        await db.execute(
            _di_select(FinanceBankAccount)
        )
    ).scalars().all()

    account_lookup = {}
    for row in accounts:
        for value in (
            row.code,
            row.system_code,
            row.name_ar,
            row.name_en,
        ):
            if value:
                account_lookup[str(value).strip().casefold()] = row

    vendor_lookup = {}
    for row in vendors:
        for value in (
            row.code,
            row.name_ar,
            row.name_en,
            row.vat_number,
            row.cr_number,
        ):
            if value:
                vendor_lookup[str(value).strip().casefold()] = row

    customer_lookup = {}
    for row in customers:
        for value in (
            row.code,
            row.name_ar,
            row.name_en,
            row.vat_number,
            row.cr_number,
        ):
            if value:
                customer_lookup[str(value).strip().casefold()] = row

    bank_lookup = {}
    for row in banks:
        for value in (
            row.code,
            row.bank_name,
            row.account_name,
            row.iban,
        ):
            if value:
                bank_lookup[str(value).replace(" ", "").strip().casefold()] = row
                bank_lookup[str(value).strip().casefold()] = row

    return {
        "accounts": account_lookup,
        "vendors": vendor_lookup,
        "customers": customer_lookup,
        "banks": bank_lookup,
    }


def _di_finance_lookup(refs, collection, value):
    if value in (None, ""):
        return None
    text = str(value).strip()
    lookup = refs.get(collection, {})
    return (
        lookup.get(text.casefold())
        or lookup.get(text.replace(" ", "").casefold())
    )


async def _di_finance_open_period_issue(db, date_text, field, issues):
    if not date_text:
        return
    try:
        await _fin_get_period_for_date(
            db,
            _fin_date.fromisoformat(date_text),
        )
    except HTTPException as exc:
        _di_finance_issue(
            issues,
            field,
            str(exc.detail),
        )


def _di_finance_group_key(adapter, normalized, row_number):
    if adapter == "finance_vendor_bill_import":
        return (
            str(normalized.get("vendor_code") or "").strip().casefold(),
            str(normalized.get("bill_number") or "").strip().casefold(),
        ) if normalized.get("bill_number") else ("__row__", row_number)

    if adapter == "finance_customer_invoice_import":
        return (
            str(normalized.get("customer_code") or "").strip().casefold(),
            str(normalized.get("invoice_number") or "").strip().casefold(),
        ) if normalized.get("invoice_number") else ("__row__", row_number)

    return ("__row__", row_number)


def _di_finance_group_rows(adapter, sheet):
    groups = {}
    for source in sheet["rows"]:
        normalized, unknown = _di_finance_normalize_record(
            adapter,
            source["data"],
        )
        item = {
            "source_row_number": source["source_row_number"],
            "source_data": source["data"],
            "normalized": normalized,
            "unknown_headers": unknown,
        }
        key = _di_finance_group_key(
            adapter,
            normalized,
            source["source_row_number"],
        )
        groups.setdefault(key, []).append(item)
    return list(groups.values())


def _di_finance_check_group_consistency(group, fields, issues):
    for field in fields:
        values = {
            str(item["normalized"].get(field)).strip()
            for item in group
            if item["normalized"].get(field) not in (None, "")
        }
        if len(values) > 1:
            _di_finance_issue(
                issues,
                field,
                f"Conflicting values across grouped rows: {sorted(values)}",
            )


async def _di_validate_vendor_bill_group(db, group):
    refs = await _di_finance_reference_maps(db)
    issues = []
    first = group[0]["normalized"]

    _di_finance_check_group_consistency(
        group,
        (
            "vendor_code",
            "bill_number",
            "bill_date",
            "due_date",
            "currency",
            "payable_account_code",
            "input_vat_account_code",
            "reference",
        ),
        issues,
    )

    vendor = _di_finance_lookup(
        refs,
        "vendors",
        first.get("vendor_code"),
    )
    if vendor is None:
        _di_finance_issue(
            issues,
            "vendor_code",
            "Vendor not found",
        )
    elif not vendor.is_active:
        _di_finance_issue(
            issues,
            "vendor_code",
            "Vendor is inactive",
        )

    bill_number = str(
        first.get("bill_number") or ""
    ).strip()
    if not bill_number:
        _di_finance_issue(
            issues,
            "bill_number",
            "Vendor bill number is required",
        )

    bill_date = None
    due_date = None
    try:
        bill_date = _di_parse_date(first.get("bill_date"))
    except ValueError as exc:
        _di_finance_issue(issues, "bill_date", str(exc))

    try:
        due_date = _di_parse_date(first.get("due_date"))
    except ValueError as exc:
        _di_finance_issue(issues, "due_date", str(exc))

    if not bill_date:
        _di_finance_issue(
            issues,
            "bill_date",
            "Bill date is required",
        )
    if not due_date:
        _di_finance_issue(
            issues,
            "due_date",
            "Due date is required",
        )

    if bill_date and due_date:
        if _fin_date.fromisoformat(due_date) < _fin_date.fromisoformat(bill_date):
            _di_finance_issue(
                issues,
                "due_date",
                "Bill due date cannot precede bill date",
            )
        await _di_finance_open_period_issue(
            db,
            bill_date,
            "bill_date",
            issues,
        )

    payable = _di_finance_lookup(
        refs,
        "accounts",
        first.get("payable_account_code"),
    )
    if payable is None:
        _di_finance_issue(
            issues,
            "payable_account_code",
            "Accounts payable account not found",
        )
    elif (
        not payable.is_active
        or not payable.allow_posting
        or payable.account_type != "liability"
    ):
        _di_finance_issue(
            issues,
            "payable_account_code",
            "Payable account must be an active posting liability account",
        )

    input_vat = _di_finance_lookup(
        refs,
        "accounts",
        first.get("input_vat_account_code"),
    )
    if input_vat is not None and (
        not input_vat.is_active
        or not input_vat.allow_posting
        or input_vat.account_type != "asset"
    ):
        _di_finance_issue(
            issues,
            "input_vat_account_code",
            "Input VAT account must be an active posting asset account",
        )

    mapped_lines = []
    subtotal = _di_Decimal("0")
    vat_total = _di_Decimal("0")

    for item in group:
        source = item["normalized"]
        line_no = item["source_row_number"]
        description = str(
            source.get("line_description") or ""
        ).strip()
        if not description:
            _di_finance_issue(
                issues,
                "line_description",
                f"Line description is required (source row {line_no})",
            )

        account = _di_finance_lookup(
            refs,
            "accounts",
            source.get("line_account_code"),
        )
        if account is None:
            _di_finance_issue(
                issues,
                "line_account_code",
                f"Line account not found (source row {line_no})",
            )
        elif (
            not account.is_active
            or not account.allow_posting
            or account.account_type not in {"expense", "asset"}
        ):
            _di_finance_issue(
                issues,
                "line_account_code",
                (
                    "Bill line account must be an active posting "
                    f"expense or asset account (source row {line_no})"
                ),
            )

        quantity = _di_finance_decimal(
            source.get("quantity"),
            "quantity",
            issues,
            _di_Decimal("1"),
        )
        if quantity is None:
            quantity = _di_Decimal("1")
        if quantity <= 0:
            _di_finance_issue(
                issues,
                "quantity",
                f"Quantity must be greater than zero (source row {line_no})",
            )
            quantity = _di_Decimal("1")

        unit_price = _di_finance_decimal(
            source.get("unit_price"),
            "unit_price",
            issues,
            None,
        )
        line_amount = _di_finance_decimal(
            source.get("line_amount"),
            "line_amount",
            issues,
            None,
        )
        if unit_price is None and line_amount is not None:
            unit_price = (
                line_amount / quantity
            )
        if unit_price is None:
            _di_finance_issue(
                issues,
                "unit_price",
                f"Unit price or line amount is required (source row {line_no})",
            )
            unit_price = _di_Decimal("0")
        if unit_price < 0:
            _di_finance_issue(
                issues,
                "unit_price",
                f"Unit price cannot be negative (source row {line_no})",
            )

        vat_rate = _di_finance_rate(
            source.get("vat_rate"),
            "vat_rate",
            issues,
        )

        net = (
            quantity * unit_price
        ).quantize(
            _FAR_Q2,
            rounding=_far_ROUND_HALF_UP,
        )
        vat_amount = (
            net * vat_rate / _di_Decimal("100")
        ).quantize(
            _FAR_Q2,
            rounding=_far_ROUND_HALF_UP,
        )
        total = net + vat_amount

        subtotal += net
        vat_total += vat_amount

        mapped_lines.append({
            "description": description,
            "expense_account_id": (
                str(account.id)
                if account else None
            ),
            "expense_account_code": (
                account.code
                if account else None
            ),
            "quantity": str(quantity),
            "unit_price": str(unit_price),
            "vat_rate": str(vat_rate),
            "net_amount": str(net),
            "vat_amount": str(vat_amount),
            "total_amount": str(total),
            "source_row_number": line_no,
        })

    if vat_total > 0 and input_vat is None:
        _di_finance_issue(
            issues,
            "input_vat_account_code",
            "Input VAT account is required because bill VAT is greater than zero",
        )

    if vendor and bill_number:
        duplicate = (
            await db.execute(
                _di_select(FinanceBill).where(
                    FinanceBill.vendor_id == vendor.id,
                    FinanceBill.bill_number == bill_number,
                )
            )
        ).scalars().first()
        if duplicate:
            _di_finance_issue(
                issues,
                "bill_number",
                "Vendor bill number already exists",
            )

    currency = str(
        first.get("currency") or "SAR"
    ).strip().upper() or "SAR"

    mapped = {
        "vendor": {
            "id": str(vendor.id) if vendor else None,
            "code": vendor.code if vendor else None,
            "name_ar": vendor.name_ar if vendor else None,
        },
        "bill": {
            "vendor_id": str(vendor.id) if vendor else None,
            "bill_number": bill_number,
            "bill_date": bill_date,
            "due_date": due_date,
            "currency": currency,
            "payable_account_id": str(payable.id) if payable else None,
            "payable_account_code": payable.code if payable else None,
            "input_vat_account_id": str(input_vat.id) if input_vat else None,
            "input_vat_account_code": input_vat.code if input_vat else None,
            "reference": (
                str(first.get("reference")).strip()
                if first.get("reference") not in (None, "")
                else None
            ),
            "notes": (
                str(first.get("notes")).strip()
                if first.get("notes") not in (None, "")
                else None
            ),
            "subtotal": str(subtotal.quantize(_FAR_Q2)),
            "vat_amount": str(vat_total.quantize(_FAR_Q2)),
            "total_amount": str((subtotal + vat_total).quantize(_FAR_Q2)),
            "lines": mapped_lines,
        },
    }

    status, issue_payload = _di_finance_status(issues)
    unknown = sorted({
        header
        for item in group
        for header in item["unknown_headers"]
    })
    if unknown:
        issue_payload["unknown_headers"] = unknown

    external_key = (
        f"{vendor.code}:{bill_number}"
        if vendor and bill_number
        else bill_number or None
    )
    return mapped, status, issue_payload, external_key


