class FinanceHRAccountMappingRequest(_FinBaseModel):
    key: str
    account_id: _fin_uuid.UUID | None = None
    actor: str = "user"


def _hfi_money(value):
    return _fin_Decimal(str(value or 0)).quantize(
        _fin_Decimal("0.01")
    )


def _hfi_source_key(source_type, source_id):
    return (
        str(source_type).strip().lower(),
        str(source_id).strip(),
    )


async def _hfi_existing_source_journal(
    db,
    source_type,
    source_id,
):
    rows = (
        await db.execute(
            _fin_select(
                FinanceJournalEntry
            ).where(
                FinanceJournalEntry.source_type
                == str(source_type).strip().lower(),
                FinanceJournalEntry.source_id
                == str(source_id).strip(),
            ).order_by(
                FinanceJournalEntry.created_at.asc()
            )
        )
    ).scalars().all()

    if len(rows) > 1:
        raise HTTPException(
            status_code=409,
            detail=(
                "Multiple finance journals exist for "
                f"{source_type}:{source_id}. "
                "Manual review is required."
            ),
        )

    return rows[0] if rows else None


async def _hfi_all_mapping_accounts(db):
    rows = (
        await db.execute(
            _fin_select(
                FinanceAccount
            ).order_by(
                FinanceAccount.code.asc()
            )
        )
    ).scalars().all()

    mapping = {}

    for account in rows:
        metadata = (
            account.account_metadata
            if isinstance(
                account.account_metadata,
                dict,
            )
            else {}
        )

        keys = metadata.get(
            "hr_integration_keys"
        ) or []

        if not isinstance(keys, list):
            keys = []

        # Optional convenience fallback:
        # system_code may equal a mapping key.
        if account.system_code:
            system_key = (
                str(account.system_code)
                .strip()
                .lower()
            )
            if (
                system_key
                in _HFI_ACCOUNT_SPECS
                and system_key not in keys
            ):
                keys = [
                    *keys,
                    system_key,
                ]

        for raw_key in keys:
            key = (
                str(raw_key)
                .strip()
                .lower()
            )

            if key not in _HFI_ACCOUNT_SPECS:
                continue

            if (
                key in mapping
                and mapping[key].id
                != account.id
            ):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "HR-Finance account mapping "
                        f"'{key}' is assigned to "
                        "multiple accounts"
                    ),
                )

            mapping[key] = account

    return mapping


async def _hfi_mapping_account(
    db,
    key,
    *,
    required=True,
):
    key = (
        str(key)
        .strip()
        .lower()
    )

    spec = _HFI_ACCOUNT_SPECS.get(key)

    if spec is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "Unknown HR-Finance account "
                f"mapping key: {key}"
            ),
        )

    mapping = await _hfi_all_mapping_accounts(
        db
    )
    account = mapping.get(key)

    if account is None:
        if required:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Missing HR-Finance account "
                    f"mapping: {key}"
                ),
            )
        return None

    if (
        not account.is_active
        or not account.allow_posting
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Mapped account {account.code} "
                "must be active and allow posting"
            ),
        )

    allowed_types = spec["types"]

    if (
        account.account_type
        not in allowed_types
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Mapped account {account.code} "
                f"for {key} must have type in "
                f"{sorted(allowed_types)}"
            ),
        )

    return account


def _hfi_account_payload(
    key,
    account,
):
    spec = _HFI_ACCOUNT_SPECS[key]

    return {
        "key": key,
        "label": spec["label"],
        "allowed_account_types":
            sorted(spec["types"]),
        "mapped": account is not None,
        "account": (
            {
                "id": str(account.id),
                "code": account.code,
                "name_ar": account.name_ar,
                "name_en": account.name_en,
                "account_type":
                    account.account_type,
                "is_active":
                    account.is_active,
                "allow_posting":
                    account.allow_posting,
            }
            if account
            else None
        ),
    }


async def _hfi_mapping_status(db):
    mapping = await _hfi_all_mapping_accounts(
        db
    )

    items = [
        _hfi_account_payload(
            key,
            mapping.get(key),
        )
        for key in _HFI_ACCOUNT_SPECS
    ]

    return {
        "total_keys": len(items),
        "mapped_keys": sum(
            1 for x in items
            if x["mapped"]
        ),
        "missing_keys": [
            x["key"]
            for x in items
            if not x["mapped"]
        ],
        "items": items,
    }


def _hfi_journal_date_payload(value):
    return (
        value.isoformat()
        if value is not None
        else None
    )


async def _hfi_journal_payload(
    db,
    journal,
    *,
    created=None,
):
    lines = (
        await db.execute(
            _fin_select(
                FinanceJournalLine,
                FinanceAccount,
            ).join(
                FinanceAccount,
                FinanceAccount.id
                == FinanceJournalLine.account_id,
            ).where(
                FinanceJournalLine.journal_entry_id
                == journal.id
            ).order_by(
                FinanceJournalLine.line_number.asc()
            )
        )
    ).all()

    total_debit = sum(
        (
            _hfi_money(line.debit)
            for line, account in lines
        ),
        _fin_Decimal("0.00"),
    )

    total_credit = sum(
        (
            _hfi_money(line.credit)
            for line, account in lines
        ),
        _fin_Decimal("0.00"),
    )

    payload = {
        "id": str(journal.id),
        "entry_number":
            journal.entry_number,
        "journal_date":
            journal.journal_date,
        "period_id":
            str(journal.period_id),
        "description":
            journal.description,
        "reference":
            journal.reference,
        "source_type":
            journal.source_type,
        "source_id":
            journal.source_id,
        "currency":
            journal.currency,
        "status":
            journal.status,
        "approval_id": (
            str(journal.approval_id)
            if journal.approval_id
            else None
        ),
        "created_by":
            journal.created_by,
        "journal_metadata":
            journal.journal_metadata
            or {},
        "total_debit":
            float(total_debit),
        "total_credit":
            float(total_credit),
        "balanced":
            abs(
                total_debit
                - total_credit
            )
            <= _FIN_TOLERANCE,
        "lines": [
            {
                "id": str(line.id),
                "line_number":
                    line.line_number,
                "account_id":
                    str(account.id),
                "account_code":
                    account.code,
                "account_name_ar":
                    account.name_ar,
                "description":
                    line.description,
                "debit":
                    float(
                        _hfi_money(
                            line.debit
                        )
                    ),
                "credit":
                    float(
                        _hfi_money(
                            line.credit
                        )
                    ),
                "cost_center":
                    line.cost_center,
                "department_code":
                    line.department_code,
                "line_metadata":
                    line.line_metadata
                    or {},
            }
            for line, account
            in lines
        ],
    }

    if created is not None:
        payload["created"] = bool(
            created
        )

    return payload


async def _hfi_create_draft_journal(
    db,
    *,
    journal_date,
    description,
    reference,
    source_type,
    source_id,
    currency,
    lines,
    metadata,
):
    source_type = (
        str(source_type)
        .strip()
        .lower()
    )
    source_id = str(source_id).strip()

    existing = (
        await _hfi_existing_source_journal(
            db,
            source_type,
            source_id,
        )
    )

    if existing:
        return await _hfi_journal_payload(
            db,
            existing,
            created=False,
        )

    if not lines:
        raise HTTPException(
            status_code=409,
            detail=(
                "HR source does not produce "
                "any accounting lines"
            ),
        )

    period = await _far_period_for_date(
        db,
        journal_date,
    )

    total_debit = sum(
        (
            _hfi_money(
                line.get("debit")
            )
            for line in lines
        ),
        _fin_Decimal("0.00"),
    )
    total_credit = sum(
        (
            _hfi_money(
                line.get("credit")
            )
            for line in lines
        ),
        _fin_Decimal("0.00"),
    )

    if (
        total_debit <= 0
        or abs(
            total_debit
            - total_credit
        )
        > _FIN_TOLERANCE
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Generated HR accounting draft "
                "is not balanced"
            ),
        )

    entry = FinanceJournalEntry(
        entry_number=(
            "JE-HR-"
            + journal_date.strftime(
                "%Y%m%d"
            )
            + "-"
            + _fin_uuid.uuid4()
            .hex[:8]
            .upper()
        ),
        journal_date=journal_date,
        period_id=period.id,
        description=
            str(description).strip(),
        reference=(
            str(reference).strip()[:150]
            if reference
            else None
        ),
        source_type=source_type,
        source_id=source_id,
        currency=(
            str(currency or "SAR")
            .strip()
            .upper()
            or "SAR"
        ),
        status="draft",
        approval_id=None,
        created_by=
            "finance_hr_integration",
        journal_metadata={
            **(
                metadata
                if isinstance(
                    metadata,
                    dict,
                )
                else {}
            ),
            "source_domain": "hr",
            "integration": (
                "finance_batch_7"
            ),
            "posting_mode":
                "draft_only",
            "external_payment_executed":
                False,
        },
    )
    db.add(entry)
    await db.flush()

    for index, item in enumerate(
        lines,
        start=1,
    ):
        debit = _hfi_money(
            item.get("debit")
        )
        credit = _hfi_money(
            item.get("credit")
        )

        if (
            debit < 0
            or credit < 0
            or (
                debit > 0
                and credit > 0
            )
            or (
                debit == 0
                and credit == 0
            )
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Invalid generated HR "
                    f"journal line {index}"
                ),
            )

        account = await db.get(
            FinanceAccount,
            item["account_id"],
        )

        if (
            account is None
            or not account.is_active
            or not account.allow_posting
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Generated HR journal line "
                    f"{index} references an "
                    "invalid posting account"
                ),
            )

        db.add(
            FinanceJournalLine(
                journal_entry_id=
                    entry.id,
                line_number=index,
                account_id=account.id,
                description=
                    item.get(
                        "description"
                    ),
                debit=debit,
                credit=credit,
                cost_center=
                    item.get(
                        "cost_center"
                    ),
                department_code=
                    item.get(
                        "department_code"
                    ),
                line_metadata=(
                    item.get(
                        "line_metadata"
                    )
                    or {}
                ),
            )
        )

    await db.flush()

    await write_audit_log(
        db,
        actor="finance",
        action=(
            "finance.hr_integration."
            "draft_journal_created"
        ),
        details={
            "journal_id":
                str(entry.id),
            "source_type":
                source_type,
            "source_id":
                source_id,
            "journal_date":
                journal_date.isoformat(),
            "total_debit":
                str(total_debit),
            "total_credit":
                str(total_credit),
            "posting_executed":
                False,
            "payment_executed":
                False,
        },
    )

    await db.commit()
    await db.refresh(entry)

    return await _hfi_journal_payload(
        db,
        entry,
        created=True,
    )


def _hfi_payment_expense_key(
    payment_type,
):
    value = (
        str(payment_type or "")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )

    aliases = {
        "overtime":
            "employee_payment_overtime_expense",
        "business_trip":
            "employee_payment_business_trip_expense",
        "business_travel":
            "employee_payment_business_trip_expense",
        "trip":
            "employee_payment_business_trip_expense",
        "reimbursement":
            "employee_payment_reimbursement_expense",
        "reimbursements":
            "employee_payment_reimbursement_expense",
        "compensation":
            "employee_payment_compensation_expense",
        "ticket":
            "employee_payment_ticket_expense",
        "tickets":
            "employee_payment_ticket_expense",
        "air_ticket":
            "employee_payment_ticket_expense",
        "air_tickets":
            "employee_payment_ticket_expense",
        "other":
            "employee_payment_other_expense",
        "others":
            "employee_payment_other_expense",
    }

    return aliases.get(
        value,
        "employee_payment_other_expense",
    )


@app.get(
    "/api/finance/hr-integration/account-mappings"
)
async def finance_hr_account_mappings(
    db: AsyncSession = Depends(get_db),
):
    return await _hfi_mapping_status(
        db
    )


@app.put(
    "/api/finance/hr-integration/account-mappings"
)
async def update_finance_hr_account_mapping(
    payload: FinanceHRAccountMappingRequest,
    db: AsyncSession = Depends(get_db),
):
    key = (
        payload.key
        .strip()
        .lower()
    )

    if key not in _HFI_ACCOUNT_SPECS:
        raise HTTPException(
            status_code=400,
            detail=(
                "Unknown HR-Finance account "
                f"mapping key: {key}"
            ),
        )

    accounts = (
        await db.execute(
            _fin_select(
                FinanceAccount
            )
        )
    ).scalars().all()

    target = None

    if payload.account_id:
        target = await db.get(
            FinanceAccount,
            payload.account_id,
        )

        if target is None:
            raise HTTPException(
                status_code=404,
                detail=(
                    "Finance account not found"
                ),
            )

        spec = _HFI_ACCOUNT_SPECS[
            key
        ]

        if (
            target.account_type
            not in spec["types"]
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Account {target.code} "
                    f"must have type in "
                    f"{sorted(spec['types'])}"
                ),
            )

        if (
            not target.is_active
            or not target.allow_posting
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Mapped account must be "
                    "active and allow posting"
                ),
            )

    for account in accounts:
        metadata = dict(
            account.account_metadata
            or {}
        )
        keys = metadata.get(
            "hr_integration_keys"
        ) or []

        if not isinstance(keys, list):
            keys = []

        normalized = [
            str(item)
            .strip()
            .lower()
            for item in keys
            if str(item).strip()
        ]

        new_keys = [
            item
            for item in normalized
            if item != key
        ]

        if (
            target is not None
            and account.id
            == target.id
            and key not in new_keys
        ):
            new_keys.append(key)

        if new_keys != normalized:
            metadata[
                "hr_integration_keys"
            ] = new_keys
            account.account_metadata = (
                metadata
            )

    await write_audit_log(
        db,
        actor=(
            payload.actor.strip()
            or "user"
        ),
        action=(
            "finance.hr_integration."
            "account_mapping_updated"
        ),
        details={
            "mapping_key": key,
            "account_id": (
                str(target.id)
                if target
                else None
            ),
            "account_code": (
                target.code
                if target
                else None
            ),
        },
    )

    await db.commit()

    return await _hfi_mapping_status(
        db
    )


@app.post(
    "/api/finance/hr-integration/payroll/"
    "{cycle_id}/draft-journal"
)
async def finance_hr_payroll_draft_journal(
    cycle_id: _fin_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    cycle = await db.get(
        HRPayrollCycle,
        cycle_id,
    )

    if cycle is None:
        raise HTTPException(
            status_code=404,
            detail="Payroll cycle not found",
        )

    if cycle.status != "closed":
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll cycle must be closed "
                "after HR approval before "
                "Finance draft generation"
            ),
        )

    existing = (
        await _hfi_existing_source_journal(
            db,
            "hr_payroll_cycle",
            cycle.id,
        )
    )

    if existing:
        return await _hfi_journal_payload(
            db,
            existing,
            created=False,
        )

    approval = None

    if cycle.approval_id:
        approval = await db.get(
            Approval,
            cycle.approval_id,
        )

    if (
        approval is None
        or approval.status != "approved"
    ):
        approval = (
            await _latest_payroll_approval(
                db,
                str(cycle.id),
            )
        )

    if (
        approval is None
        or approval.status != "approved"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved HR payroll "
                "authorization is required"
            ),
        )

    entries = (
        await db.execute(
            _fin_select(
                HRPayrollEntry
            ).where(
                HRPayrollEntry.cycle_id
                == cycle.id
            )
        )
    ).scalars().all()

    if not entries:
        raise HTTPException(
            status_code=409,
            detail=(
                "Payroll cycle has no entries"
            ),
        )

    salary_total = _fin_Decimal(
        "0.00"
    )
    employee_gosi_total = (
        _fin_Decimal("0.00")
    )
    other_deductions_total = (
        _fin_Decimal("0.00")
    )
    employer_gosi_total = (
        _fin_Decimal("0.00")
    )
    benefit_total = _fin_Decimal(
        "0.00"
    )
    net_total = _fin_Decimal(
        "0.00"
    )

    excluded_nonzero = []

    for entry in entries:
        basic = _hfi_money(
            entry.basic_salary
        )
        housing = _hfi_money(
            entry.housing_allowance
        )
        transport = _hfi_money(
            entry.transport_allowance
        )
        fixed_other = _hfi_money(
            entry.other_fixed_allowances
        )
        overtime = _hfi_money(
            entry.overtime_amount
        )
        other_earnings = _hfi_money(
            entry.other_earnings
        )
        employee_gosi = _hfi_money(
            entry.employee_gosi_deduction
        )
        other_deductions = _hfi_money(
            entry.other_deductions
        )
        employer_gosi = _hfi_money(
            entry.employer_gosi_cost
        )
        benefit_cost = _hfi_money(
            entry.benefit_cost_monthly
        )
        stored_net = _hfi_money(
            entry.net_pay
        )

        if (
            overtime > 0
            or other_earnings > 0
        ):
            excluded_nonzero.append(
                {
                    "entry_id":
                        str(entry.id),
                    "employee_id":
                        str(
                            entry.employee_id
                        ),
                    "overtime_amount":
                        str(overtime),
                    "other_earnings":
                        str(other_earnings),
                }
            )

        core_gross = (
            basic
            + housing
            + transport
            + fixed_other
        )

        expected_net = (
            core_gross
            - employee_gosi
            - other_deductions
        )

        if (
            expected_net < 0
            or abs(
                expected_net
                - stored_net
            )
            > _FIN_TOLERANCE
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Payroll entry does not "
                    "match the payroll-only "
                    "accounting rule. "
                    f"Entry {entry.id} requires "
                    "manual review."
                ),
            )

        salary_total += core_gross
        employee_gosi_total += (
            employee_gosi
        )
        other_deductions_total += (
            other_deductions
        )
        employer_gosi_total += (
            employer_gosi
        )
        benefit_total += benefit_cost
        net_total += stored_net

    if excluded_nonzero:
        raise HTTPException(
            status_code=409,
            detail={
                "message": (
                    "Payroll contains overtime "
                    "or other earnings. These "
                    "must remain in Employee "
                    "Payments & Claims and cannot "
                    "be bridged through payroll."
                ),
                "entries":
                    excluded_nonzero,
            },
        )

    journal_date = _fin_date(
        cycle.year,
        cycle.month,
        _fin_calendar.monthrange(
            cycle.year,
            cycle.month,
        )[1],
    )

    lines = []

    salary_account = (
        await _hfi_mapping_account(
            db,
            "payroll_salary_expense",
        )
    )
    payroll_payable = (
        await _hfi_mapping_account(
            db,
            "payroll_payable",
        )
    )

    if salary_total > 0:
        lines.append({
            "account_id":
                salary_account.id,
            "description": (
                f"Payroll salary and fixed "
                f"allowances "
                f"{cycle.year}-"
                f"{cycle.month:02d}"
            ),
            "debit":
                salary_total,
            "credit": 0,
        })

    if employer_gosi_total > 0:
        gosi_expense = (
            await _hfi_mapping_account(
                db,
                "payroll_gosi_expense",
            )
        )
        lines.append({
            "account_id":
                gosi_expense.id,
            "description":
                "Employer GOSI expense",
            "debit":
                employer_gosi_total,
            "credit": 0,
        })

    if benefit_total > 0:
        benefit_expense = (
            await _hfi_mapping_account(
                db,
                "payroll_benefit_expense",
            )
        )
        lines.append({
            "account_id":
                benefit_expense.id,
            "description":
                "Employer benefit cost",
            "debit":
                benefit_total,
            "credit": 0,
        })

    if net_total > 0:
        lines.append({
            "account_id":
                payroll_payable.id,
            "description":
                "Net payroll payable",
            "debit": 0,
            "credit":
                net_total,
        })

    gosi_payable_total = (
        employee_gosi_total
        + employer_gosi_total
    )

    if gosi_payable_total > 0:
        gosi_payable = (
            await _hfi_mapping_account(
                db,
                "payroll_gosi_payable",
            )
        )
        lines.append({
            "account_id":
                gosi_payable.id,
            "description":
                "Employee + employer GOSI payable",
            "debit": 0,
            "credit":
                gosi_payable_total,
        })

    if other_deductions_total > 0:
        deductions_payable = (
            await _hfi_mapping_account(
                db,
                "payroll_deductions_payable",
            )
        )
        lines.append({
            "account_id":
                deductions_payable.id,
            "description":
                "Payroll other deductions payable",
            "debit": 0,
            "credit":
                other_deductions_total,
        })

    if benefit_total > 0:
        benefit_payable = (
            await _hfi_mapping_account(
                db,
                "payroll_benefit_payable",
            )
        )
        lines.append({
            "account_id":
                benefit_payable.id,
            "description":
                "Employer benefit payable",
            "debit": 0,
            "credit":
                benefit_total,
        })

    return await _hfi_create_draft_journal(
        db,
        journal_date=journal_date,
        description=(
            f"HR Payroll "
            f"{cycle.year}-"
            f"{cycle.month:02d}"
        ),
        reference=(
            f"HR-PAYROLL-"
            f"{cycle.year}-"
            f"{cycle.month:02d}"
        ),
        source_type=
            "hr_payroll_cycle",
        source_id=cycle.id,
        currency="SAR",
        lines=lines,
        metadata={
            "hr_module": "payroll",
            "hr_cycle_id":
                str(cycle.id),
            "hr_approval_id":
                str(approval.id),
            "employee_count":
                len(entries),
            "totals": {
                "salary_fixed_allowances":
                    str(salary_total),
                "employee_gosi":
                    str(
                        employee_gosi_total
                    ),
                "other_deductions":
                    str(
                        other_deductions_total
                    ),
                "employer_gosi":
                    str(
                        employer_gosi_total
                    ),
                "employer_benefits":
                    str(benefit_total),
                "net_pay":
                    str(net_total),
            },
            "payroll_only_rule": True,
            "overtime_and_claims_excluded":
                True,
            "benefit_employee_deductions_note":
                (
                    "Employee benefit deductions "
                    "remain within HR PayrollEntry."
                    "other_deductions because the "
                    "source stores this value as an "
                    "aggregate."
                ),
        },
    )


@app.post(
    "/api/finance/hr-integration/"
    "employee-payments/{request_id}/"
    "draft-journal"
)
async def finance_hr_employee_payment_draft_journal(
    request_id: _fin_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        HREmployeePaymentRequest,
        request_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail=(
                "Employee payment request "
                "not found"
            ),
        )

    if row.status not in {
        "approved",
        "paid",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Employee payment must be "
                "finally approved before "
                "Finance draft generation"
            ),
        )

    existing = (
        await _hfi_existing_source_journal(
            db,
            "hr_employee_payment",
            row.id,
        )
    )

    if existing:
        return await _hfi_journal_payload(
            db,
            existing,
            created=False,
        )

    amount = _hfi_money(
        row.amount
    )

    if amount <= 0:
        raise HTTPException(
            status_code=409,
            detail=(
                "Employee payment amount "
                "must be greater than zero"
            ),
        )

    if (
        row.payment_type == "overtime"
        and (
            getattr(
                row,
                "manager_approval_status",
                None,
            )
            != "approved"
            or getattr(
                row,
                "ceo_approval_status",
                None,
            )
            != "approved"
            or getattr(
                row,
                "final_approval_status",
                None,
            )
            != "approved"
        )
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Overtime requires Manager, "
                "CEO and Final HR approval "
                "before Finance integration"
            ),
        )

    expense_key = (
        _hfi_payment_expense_key(
            row.payment_type
        )
    )

    expense_account = (
        await _hfi_mapping_account(
            db,
            expense_key,
        )
    )
    payable_account = (
        await _hfi_mapping_account(
            db,
            "employee_payments_payable",
        )
    )

    approval_date = (
        row.approved_at.date()
        if row.approved_at
        else row.request_date
    )

    return await _hfi_create_draft_journal(
        db,
        journal_date=
            approval_date,
        description=(
            "HR Employee Payment - "
            + str(
                row.payment_type
            )
        ),
        reference=(
            row.payment_reference
            or (
                "HR-PAYMENT-"
                + str(row.id)[:8]
            )
        ),
        source_type=
            "hr_employee_payment",
        source_id=row.id,
        currency=row.currency,
        lines=[
            {
                "account_id":
                    expense_account.id,
                "description": (
                    row.description
                    or (
                        "Employee payment "
                        + str(
                            row.payment_type
                        )
                    )
                ),
                "debit": amount,
                "credit": 0,
                "line_metadata": {
                    "employee_id":
                        str(
                            row.employee_id
                        ),
                    "payment_type":
                        row.payment_type,
                    "source_type":
                        row.source_type,
                    "source_id": (
                        str(row.source_id)
                        if row.source_id
                        else None
                    ),
                },
            },
            {
                "account_id":
                    payable_account.id,
                "description":
                    "Employee payment payable",
                "debit": 0,
                "credit": amount,
                "line_metadata": {
                    "employee_id":
                        str(
                            row.employee_id
                        ),
                },
            },
        ],
        metadata={
            "hr_module":
                "employee_payments",
            "hr_payment_request_id":
                str(row.id),
            "employee_id":
                str(row.employee_id),
            "payment_type":
                row.payment_type,
            "hr_source_type":
                row.source_type,
            "hr_source_id": (
                str(row.source_id)
                if row.source_id
                else None
            ),
            "hr_status":
                row.status,
            "hr_paid_at": (
                row.paid_at.isoformat()
                if row.paid_at
                else None
            ),
            "hr_payment_reference":
                row.payment_reference,
            "payment_journal_created":
                False,
            "payment_note": (
                "This bridge recognizes the "
                "approved expense/payable only. "
                "It does not infer a bank account "
                "or create a bank payment entry."
            ),
        },
    )


@app.post(
    "/api/finance/hr-integration/"
    "final-settlements/{settlement_id}/"
    "draft-journal"
)
async def finance_hr_final_settlement_draft_journal(
    settlement_id: _fin_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        HRFinalSettlement,
        settlement_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail=(
                "Final settlement not found"
            ),
        )

    if row.status not in {
        "approved",
        "paid",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Final settlement must be "
                "approved before Finance "
                "draft generation"
            ),
        )

    if not row.approved_at:
        raise HTTPException(
            status_code=409,
            detail=(
                "Final settlement approval "
                "timestamp is required"
            ),
        )

    existing = (
        await _hfi_existing_source_journal(
            db,
            "hr_final_settlement",
            row.id,
        )
    )

    if existing:
        return await _hfi_journal_payload(
            db,
            existing,
            created=False,
        )

    components = [
        (
            "final_salary_expense",
            "Salary due",
            _hfi_money(
                row.salary_due_amount
            ),
        ),
        (
            "final_eosb_expense",
            "End-of-service benefit",
            _hfi_money(
                row.eosb_amount
            ),
        ),
        (
            "final_leave_encashment_expense",
            "Leave encashment",
            _hfi_money(
                row.leave_encashment_amount
            ),
        ),
        (
            "final_notice_compensation_expense",
            "Notice compensation",
            _hfi_money(
                row.notice_compensation_amount
            ),
        ),
        (
            "final_article77_compensation_expense",
            "Article 77 compensation",
            _hfi_money(
                row.article_77_compensation_amount
            ),
        ),
        (
            "final_other_entitlements_expense",
            "Other entitlements",
            _hfi_money(
                row.other_entitlements
            ),
        ),
    ]

    gross_components = sum(
        (
            amount
            for key, label, amount
            in components
        ),
        _fin_Decimal("0.00"),
    )
    stored_gross = _hfi_money(
        row.gross_settlement
    )
    deductions = _hfi_money(
        row.deductions
    )
    net = _hfi_money(
        row.net_settlement
    )

    if (
        abs(
            gross_components
            - stored_gross
        )
        > _FIN_TOLERANCE
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Final settlement components "
                "do not match gross_settlement. "
                "Manual HR review is required."
            ),
        )

    if (
        abs(
            (
                stored_gross
                - deductions
            )
            - net
        )
        > _FIN_TOLERANCE
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Final settlement gross minus "
                "deductions does not match "
                "net_settlement"
            ),
        )

    if net < 0:
        raise HTTPException(
            status_code=409,
            detail=(
                "Final settlement net amount "
                "cannot be negative"
            ),
        )

    lines = []

    for key, label, amount in components:
        if amount <= 0:
            continue

        account = (
            await _hfi_mapping_account(
                db,
                key,
            )
        )

        lines.append({
            "account_id":
                account.id,
            "description":
                label,
            "debit":
                amount,
            "credit": 0,
            "line_metadata": {
                "employee_id":
                    str(
                        row.employee_id
                    ),
                "settlement_id":
                    str(row.id),
            },
        })

    if deductions > 0:
        deductions_account = (
            await _hfi_mapping_account(
                db,
                "final_settlement_deductions_offset",
            )
        )

        lines.append({
            "account_id":
                deductions_account.id,
            "description":
                "Final settlement deductions",
            "debit": 0,
            "credit":
                deductions,
            "line_metadata": {
                "employee_id":
                    str(
                        row.employee_id
                    ),
                "settlement_id":
                    str(row.id),
            },
        })

    if net > 0:
        payable = (
            await _hfi_mapping_account(
                db,
                "final_settlement_payable",
            )
        )

        lines.append({
            "account_id":
                payable.id,
            "description":
                "Final settlement net payable",
            "debit": 0,
            "credit":
                net,
            "line_metadata": {
                "employee_id":
                    str(
                        row.employee_id
                    ),
                "settlement_id":
                    str(row.id),
            },
        })

    return await _hfi_create_draft_journal(
        db,
        journal_date=
            row.last_working_day,
        description=(
            "HR Final Settlement - "
            + str(row.employee_id)
        ),
        reference=(
            row.payment_reference
            or (
                "HR-FINAL-"
                + str(row.id)[:8]
            )
        ),
        source_type=
            "hr_final_settlement",
        source_id=row.id,
        currency="SAR",
        lines=lines,
        metadata={
            "hr_module":
                "final_settlement",
            "settlement_id":
                str(row.id),
            "employee_id":
                str(row.employee_id),
            "contract_id":
                str(row.contract_id),
            "last_working_day":
                row.last_working_day
                .isoformat(),
            "termination_initiator":
                row.termination_initiator,
            "termination_reason":
                row.termination_reason,
            "approved_by":
                row.approved_by,
            "approved_at":
                row.approved_at.isoformat(),
            "hr_status":
                row.status,
            "hr_paid_at": (
                row.paid_at.isoformat()
                if row.paid_at
                else None
            ),
            "hr_payment_reference":
                row.payment_reference,
            "calculation_version":
                row.calculation_version,
            "totals": {
                "gross_settlement":
                    str(stored_gross),
                "deductions":
                    str(deductions),
                "net_settlement":
                    str(net),
            },
            "payment_journal_created":
                False,
            "payment_note": (
                "This bridge recognizes final "
                "settlement expense/payable only. "
                "No bank payment is inferred or "
                "executed."
            ),
        },
    )


@app.get(
    "/api/finance/hr-integration/journals"
)
async def list_finance_hr_integration_journals(
    source_type: str | None = None,
    limit: int = 100,
    db: AsyncSession = Depends(get_db),
):
    limit = max(
        1,
        min(
            int(limit),
            500,
        ),
    )

    query = (
        _fin_select(
            FinanceJournalEntry
        ).where(
            FinanceJournalEntry.source_type.in_(
                [
                    "hr_payroll_cycle",
                    "hr_employee_payment",
                    "hr_final_settlement",
                ]
            )
        )
    )

    if source_type:
        normalized = (
            source_type
            .strip()
            .lower()
        )

        if normalized not in {
            "hr_payroll_cycle",
            "hr_employee_payment",
            "hr_final_settlement",
        }:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Invalid HR integration "
                    "source_type"
                ),
            )

        query = query.where(
            FinanceJournalEntry.source_type
            == normalized
        )

    rows = (
        await db.execute(
            query.order_by(
                FinanceJournalEntry
                .created_at.desc()
            ).limit(limit)
        )
    ).scalars().all()

    return [
        await _hfi_journal_payload(
            db,
            row,
        )
        for row in rows
    ]


@app.get(
    "/api/finance/hr-integration/summary"
)
async def finance_hr_integration_summary(
    db: AsyncSession = Depends(get_db),
):
    payroll_cycles = (
        await db.execute(
            _fin_select(
                HRPayrollCycle
            ).where(
                HRPayrollCycle.status
                == "closed"
            ).order_by(
                HRPayrollCycle.year.desc(),
                HRPayrollCycle.month.desc(),
            )
        )
    ).scalars().all()

    payments = (
        await db.execute(
            _fin_select(
                HREmployeePaymentRequest
            ).where(
                HREmployeePaymentRequest
                .status.in_(
                    [
                        "approved",
                        "paid",
                    ]
                )
            ).order_by(
                HREmployeePaymentRequest
                .approved_at.desc()
                .nullslast(),
                HREmployeePaymentRequest
                .created_at.desc(),
            )
        )
    ).scalars().all()

    settlements = (
        await db.execute(
            _fin_select(
                HRFinalSettlement
            ).where(
                HRFinalSettlement.status
                .in_(
                    [
                        "approved",
                        "paid",
                    ]
                )
            ).order_by(
                HRFinalSettlement
                .last_working_day.desc()
            )
        )
    ).scalars().all()

    integration_journals = (
        await db.execute(
            _fin_select(
                FinanceJournalEntry
            ).where(
                FinanceJournalEntry.source_type.in_(
                    [
                        "hr_payroll_cycle",
                        "hr_employee_payment",
                        "hr_final_settlement",
                    ]
                )
            )
        )
    ).scalars().all()

    journal_keys = {
        _hfi_source_key(
            row.source_type,
            row.source_id,
        )
        for row in integration_journals
    }

    payroll_items = [
        {
            "id": str(row.id),
            "year": row.year,
            "month": row.month,
            "status": row.status,
            "has_finance_journal": (
                _hfi_source_key(
                    "hr_payroll_cycle",
                    row.id,
                )
                in journal_keys
            ),
        }
        for row in payroll_cycles
    ]

    payment_items = [
        {
            "id": str(row.id),
            "employee_id":
                str(row.employee_id),
            "payment_type":
                row.payment_type,
            "amount":
                float(
                    _hfi_money(
                        row.amount
                    )
                ),
            "currency":
                row.currency,
            "status":
                row.status,
            "approved_at":
                row.approved_at,
            "has_finance_journal": (
                _hfi_source_key(
                    "hr_employee_payment",
                    row.id,
                )
                in journal_keys
            ),
        }
        for row in payments
    ]

    settlement_items = [
        {
            "id": str(row.id),
            "employee_id":
                str(row.employee_id),
            "last_working_day":
                row.last_working_day,
            "net_settlement":
                float(
                    _hfi_money(
                        row.net_settlement
                    )
                ),
            "status":
                row.status,
            "has_finance_journal": (
                _hfi_source_key(
                    "hr_final_settlement",
                    row.id,
                )
                in journal_keys
            ),
        }
        for row in settlements
    ]

    mapping_status = (
        await _hfi_mapping_status(
            db
        )
    )

    return {
        "payroll": {
            "eligible_closed_cycles":
                len(payroll_items),
            "without_finance_journal":
                sum(
                    1
                    for item
                    in payroll_items
                    if not item[
                        "has_finance_journal"
                    ]
                ),
            "items":
                payroll_items[:50],
        },
        "employee_payments": {
            "eligible_approved_or_paid":
                len(payment_items),
            "without_finance_journal":
                sum(
                    1
                    for item
                    in payment_items
                    if not item[
                        "has_finance_journal"
                    ]
                ),
            "items":
                payment_items[:100],
        },
        "final_settlements": {
            "eligible_approved_or_paid":
                len(settlement_items),
            "without_finance_journal":
                sum(
                    1
                    for item
                    in settlement_items
                    if not item[
                        "has_finance_journal"
                    ]
                ),
            "items":
                settlement_items[:50],
        },
        "generated_journals": {
            "total":
                len(
                    integration_journals
                ),
            "draft":
                sum(
                    1
                    for row
                    in integration_journals
                    if row.status
                    == "draft"
                ),
            "pending_approval":
                sum(
                    1
                    for row
                    in integration_journals
                    if row.status
                    == "pending_approval"
                ),
            "posted":
                sum(
                    1
                    for row
                    in integration_journals
                    if row.status
                    == "posted"
                ),
        },
        "account_mappings":
            mapping_status,
        "benefits_accounting_note": (
            "Employer monthly benefit cost is "
            "recognized through the payroll "
            "bridge. Employee benefit deductions "
            "remain within PayrollEntry."
            "other_deductions because the source "
            "stores deductions as an aggregate. "
            "Standalone benefit enrollment does "
            "not create a second journal, which "
            "prevents double counting."
        ),
        "safety": {
            "draft_journals_only": True,
            "automatic_posting": False,
            "automatic_payment": False,
            "automatic_bank_transfer": False,
            "idempotency_key": (
                "FinanceJournalEntry."
                "source_type + source_id"
            ),
        },
    }

# ============================================================
# Procurement Batch 8 - Purchase-to-Pay Foundation API
# PR -> approval -> PO -> critical approval/issue -> receipt ->
# confirmed receipt -> Finance AP bill DRAFT only.
# Supplier master is FinanceVendor. No duplicate supplier table.
# ============================================================

import uuid as _p8_uuid
from datetime import (
    date as _p8_date,
    datetime as _p8_datetime,
    timedelta as _p8_timedelta,
    timezone as _p8_timezone,
)
from decimal import Decimal as _P8Decimal, InvalidOperation as _P8InvalidOperation

from pydantic import BaseModel as _P8BaseModel, Field as _P8Field
from sqlalchemy import select as _p8_select

from .models import (
    Agent as _P8Agent,
    Approval as _P8Approval,
    FinanceAccount as _P8FinanceAccount,
    FinanceBill as _P8FinanceBill,
    FinanceBillLine as _P8FinanceBillLine,
    FinanceBillPayment as _P8FinanceBillPayment,
    FinanceVendor as _P8FinanceVendor,
    ProcurementPurchaseOrder as _P8PurchaseOrder,
    ProcurementPurchaseOrderLine as _P8PurchaseOrderLine,
    ProcurementPurchaseRequest as _P8PurchaseRequest,
    ProcurementPurchaseRequestLine as _P8PurchaseRequestLine,
    ProcurementReceipt as _P8Receipt,
    ProcurementReceiptLine as _P8ReceiptLine,
)

_P8_MARKER = "PROCUREMENT PURCHASE-TO-PAY BATCH 8 v1"
_P8_ZERO = _P8Decimal("0.00")
_P8_Q2 = _P8Decimal("0.01")
_P8_Q4 = _P8Decimal("0.0001")

_P8_AGENT_PROMPT = """
You are the Procurement Agent for Talal Enclave, a private single-user AI system.

Support purchase requests, purchase orders, supplier selection, receipt tracking,
three-way matching, procurement controls, spend visibility and procurement reporting.

FinanceVendor is the authoritative supplier master. Do not create or assume a
separate supplier database.

Never issue a purchase order, accept goods/services, create an AP obligation,
initiate a payment, execute a bank transfer, or make an external financial
commitment without explicit human action and the required approval workflow.

A confirmed procurement receipt may create only a DRAFT Finance AP bill.
Finance approval/posting and payment-record workflows remain separate and mandatory.
Never auto-post accounting entries and never execute bank payments.
""".strip()


class _P8ApprovalRequest(_P8BaseModel):
    requested_by: str = "user"
    notes: str | None = None


class _P8PRLineInput(_P8BaseModel):
    description: str
    quantity: float = 1
    estimated_unit_price: float = 0
    vat_rate: float = 0
    account_id: _p8_uuid.UUID | None = None
    cost_center: str | None = None
    line_metadata: dict = _P8Field(default_factory=dict)


class _P8PRCreateRequest(_P8BaseModel):
    requested_by: str
    department_code: str | None = None
    request_date: _p8_date = _P8Field(default_factory=_p8_date.today)
    needed_by: _p8_date | None = None
    purpose: str
    preferred_vendor_id: _p8_uuid.UUID | None = None
    currency: str = "SAR"
    notes: str | None = None
    request_metadata: dict = _P8Field(default_factory=dict)
    lines: list[_P8PRLineInput]


class _P8POLineInput(_P8BaseModel):
    purchase_request_line_id: _p8_uuid.UUID
    account_id: _p8_uuid.UUID | None = None
    quantity: float | None = None
    unit_price: float | None = None
    vat_rate: float | None = None
    description: str | None = None
    cost_center: str | None = None
    line_metadata: dict = _P8Field(default_factory=dict)


class _P8POCreateRequest(_P8BaseModel):
    vendor_id: _p8_uuid.UUID
    order_date: _p8_date = _P8Field(default_factory=_p8_date.today)
    expected_delivery_date: _p8_date | None = None
    notes: str | None = None
    po_metadata: dict = _P8Field(default_factory=dict)
    lines: list[_P8POLineInput] | None = None


class _P8POIssueRequest(_P8BaseModel):
    issued_by: str = "user"


class _P8ReceiptLineInput(_P8BaseModel):
    purchase_order_line_id: _p8_uuid.UUID
    quantity_received: float
    line_metadata: dict = _P8Field(default_factory=dict)


class _P8ReceiptCreateRequest(_P8BaseModel):
    receipt_type: str = "goods"
    receipt_date: _p8_date = _P8Field(default_factory=_p8_date.today)
    received_by: str = "user"
    notes: str | None = None
    receipt_metadata: dict = _P8Field(default_factory=dict)
    lines: list[_P8ReceiptLineInput]


class _P8BillFromReceiptRequest(_P8BaseModel):
    bill_number: str
    bill_date: _p8_date = _P8Field(default_factory=_p8_date.today)
    due_date: _p8_date | None = None
    payable_account_id: _p8_uuid.UUID
    input_vat_account_id: _p8_uuid.UUID | None = None
    reference: str | None = None
    notes: str | None = None
    created_by: str = "procurement"


def _p8_money(value):
    try:
        out = _P8Decimal(str(value or 0)).quantize(_P8_Q2)
    except (_P8InvalidOperation, TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"Invalid amount: {value}") from exc
    if out < 0:
        raise HTTPException(status_code=400, detail="Amounts cannot be negative")
    return out


def _p8_qty(value):
    try:
        out = _P8Decimal(str(value or 0)).quantize(_P8_Q4)
    except (_P8InvalidOperation, TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"Invalid quantity: {value}") from exc
    if out <= 0:
        raise HTTPException(status_code=400, detail="Quantity must be greater than zero")
    return out


def _p8_rate(value):
    try:
        out = _P8Decimal(str(value or 0)).quantize(_P8_Q4)
    except (_P8InvalidOperation, TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"Invalid VAT rate: {value}") from exc
    if out < 0 or out > 1:
        raise HTTPException(status_code=400, detail="VAT rate must be between 0 and 1")
    return out


def _p8_calc(quantity, unit_price, vat_rate):
    qty = _p8_qty(quantity)
    price = _p8_money(unit_price)
    rate = _p8_rate(vat_rate)
    net = (qty * price).quantize(_P8_Q2)
    vat = (net * rate).quantize(_P8_Q2)
    return qty, price, rate, net, vat, net + vat


def _p8_number(prefix, day):
    return f"{prefix}-{day.strftime('%Y%m%d')}-{_p8_uuid.uuid4().hex[:8].upper()}"


async def _p8_agent(db, create=False):
    row = (
        await db.execute(
            _p8_select(_P8Agent).where(_P8Agent.slug == "procurement")
        )
    ).scalar_one_or_none()

    if row is None and create:
        row = _P8Agent(
            slug="procurement",
            name_en="Procurement Agent",
            name_ar="وكيل المشتريات",
            role="Procurement & Purchase-to-Pay Operations",
            system_prompt=_P8_AGENT_PROMPT,
            enabled=True,
        )
        db.add(row)
        await db.flush()

    return row


async def _p8_vendor(db, vendor_id):
    row = await db.get(_P8FinanceVendor, vendor_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Vendor not found")
    if not row.is_active:
        raise HTTPException(status_code=409, detail="Vendor is inactive")
    return row


async def _p8_account(db, account_id, allowed_types, label):
    row = await db.get(_P8FinanceAccount, account_id)
    if row is None:
        raise HTTPException(status_code=404, detail=f"{label} account not found")
    if not row.is_active or not row.allow_posting:
        raise HTTPException(
            status_code=409,
            detail=f"{label} account must be active and allow posting",
        )
    if row.account_type not in allowed_types:
        raise HTTPException(
            status_code=409,
            detail=f"{label} account type must be one of {sorted(allowed_types)}",
        )
    return row


async def _p8_approval(db, approval_id):
    return await db.get(_P8Approval, approval_id) if approval_id else None


async def _p8_pr_lines(db, pr_id):
    return (
        await db.execute(
            _p8_select(_P8PurchaseRequestLine)
            .where(_P8PurchaseRequestLine.purchase_request_id == pr_id)
            .order_by(_P8PurchaseRequestLine.line_number.asc())
        )
    ).scalars().all()


async def _p8_po_lines(db, po_id):
    return (
        await db.execute(
            _p8_select(_P8PurchaseOrderLine)
            .where(_P8PurchaseOrderLine.purchase_order_id == po_id)
            .order_by(_P8PurchaseOrderLine.line_number.asc())
        )
    ).scalars().all()


async def _p8_receipt_lines(db, receipt_id):
    return (
        await db.execute(
            _p8_select(_P8ReceiptLine)
            .where(_P8ReceiptLine.receipt_id == receipt_id)
            .order_by(_P8ReceiptLine.line_number.asc())
        )
    ).scalars().all()


async def _p8_pr_payload(db, row):
    approval = await _p8_approval(db, row.approval_id)
    lines = await _p8_pr_lines(db, row.id)
    return {
        "id": str(row.id),
        "request_number": row.request_number,
        "requested_by": row.requested_by,
        "department_code": row.department_code,
        "request_date": row.request_date,
        "needed_by": row.needed_by,
        "purpose": row.purpose,
        "preferred_vendor_id": str(row.preferred_vendor_id) if row.preferred_vendor_id else None,
        "currency": row.currency,
        "estimated_subtotal": float(row.estimated_subtotal or 0),
        "estimated_vat_amount": float(row.estimated_vat_amount or 0),
        "estimated_total": float(row.estimated_total or 0),
        "status": row.status,
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else "not_requested",
        "notes": row.notes,
        "request_metadata": row.request_metadata or {},
        "lines": [
            {
                "id": str(x.id),
                "line_number": x.line_number,
                "description": x.description,
                "quantity": float(x.quantity),
                "estimated_unit_price": float(x.estimated_unit_price),
                "vat_rate": float(x.vat_rate),
                "estimated_net_amount": float(x.estimated_net_amount),
                "estimated_vat_amount": float(x.estimated_vat_amount),
                "estimated_total_amount": float(x.estimated_total_amount),
                "account_id": str(x.account_id) if x.account_id else None,
                "cost_center": x.cost_center,
            }
            for x in lines
        ],
    }


async def _p8_po_payload(db, row):
    approval = await _p8_approval(db, row.approval_id)
    lines = await _p8_po_lines(db, row.id)
    return {
        "id": str(row.id),
        "po_number": row.po_number,
        "purchase_request_id": str(row.purchase_request_id),
        "vendor_id": str(row.vendor_id),
        "order_date": row.order_date,
        "expected_delivery_date": row.expected_delivery_date,
        "currency": row.currency,
        "subtotal": float(row.subtotal or 0),
        "vat_amount": float(row.vat_amount or 0),
        "total_amount": float(row.total_amount or 0),
        "status": row.status,
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else "not_requested",
        "issued_at": row.issued_at,
        "issued_by": row.issued_by,
        "notes": row.notes,
        "po_metadata": row.po_metadata or {},
        "lines": [
            {
                "id": str(x.id),
                "purchase_request_line_id": (
                    str(x.purchase_request_line_id) if x.purchase_request_line_id else None
                ),
                "line_number": x.line_number,
                "description": x.description,
                "account_id": str(x.account_id),
                "quantity": float(x.quantity),
                "unit_price": float(x.unit_price),
                "vat_rate": float(x.vat_rate),
                "net_amount": float(x.net_amount),
                "vat_amount": float(x.vat_amount),
                "total_amount": float(x.total_amount),
                "received_quantity": float(x.received_quantity or 0),
                "remaining_quantity": float(
                    _P8Decimal(str(x.quantity or 0))
                    - _P8Decimal(str(x.received_quantity or 0))
                ),
                "cost_center": x.cost_center,
            }
            for x in lines
        ],
    }


async def _p8_receipt_payload(db, row):
    lines = await _p8_receipt_lines(db, row.id)
    bill = await db.get(_P8FinanceBill, row.finance_bill_id) if row.finance_bill_id else None
    return {
        "id": str(row.id),
        "receipt_number": row.receipt_number,
        "purchase_order_id": str(row.purchase_order_id),
        "receipt_type": row.receipt_type,
        "receipt_date": row.receipt_date,
        "status": row.status,
        "received_by": row.received_by,
        "notes": row.notes,
        "finance_bill_id": str(row.finance_bill_id) if row.finance_bill_id else None,
        "finance_bill": (
            {
                "id": str(bill.id),
                "bill_number": bill.bill_number,
                "status": bill.status,
                "total_amount": float(bill.total_amount or 0),
                "amount_paid": float(bill.amount_paid or 0),
            }
            if bill
            else None
        ),
        "confirmed_at": row.confirmed_at,
        "lines": [
            {
                "id": str(x.id),
                "purchase_order_line_id": str(x.purchase_order_line_id),
                "line_number": x.line_number,
                "description": x.description,
                "quantity_received": float(x.quantity_received),
            }
            for x in lines
        ],
    }


