@app.post("/api/procurement/purchase-requests/{request_id}/request-approval")
async def request_procurement_purchase_request_approval(
    request_id: _p8_uuid.UUID,
    payload: _P8ApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(_P8PurchaseRequest, request_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Purchase request not found")

    existing = await _p8_approval(db, row.approval_id)
    if existing and existing.status in {"pending", "approved"}:
        return await _p8_pr_payload(db, row)

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="Purchase request cannot enter approval in its current status",
        )

    agent = await _p8_agent(db, create=True)
    if not agent.enabled:
        raise HTTPException(status_code=409, detail="Procurement Agent is disabled")

    approval = _P8Approval(
        agent_id=agent.id,
        title=f"اعتماد طلب شراء {row.request_number}",
        description=(
            f"Purchase Request {row.request_number}; estimated total "
            f"{float(row.estimated_total):,.2f} {row.currency}"
        ),
        action_type="procurement_purchase_request_approval",
        risk_level="high",
        status="pending",
        action_payload={
            "purchase_request_id": str(row.id),
            "request_number": row.request_number,
            "estimated_total": float(row.estimated_total),
            "currency": row.currency,
            "notes": payload.notes,
        },
    )
    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await write_audit_log(
        db,
        actor=payload.requested_by.strip() or "user",
        action="procurement.purchase_request.approval_requested",
        details={
            "purchase_request_id": str(row.id),
            "approval_id": str(approval.id),
        },
    )

    await db.commit()
    await db.refresh(row)
    return await _p8_pr_payload(db, row)


@app.post("/api/procurement/purchase-requests/{request_id}/purchase-order")
async def create_procurement_purchase_order(
    request_id: _p8_uuid.UUID,
    payload: _P8POCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    pr = await db.get(_P8PurchaseRequest, request_id)
    if pr is None:
        raise HTTPException(status_code=404, detail="Purchase request not found")

    existing = (
        await db.execute(
            _p8_select(_P8PurchaseOrder).where(
                _P8PurchaseOrder.purchase_request_id == pr.id
            )
        )
    ).scalar_one_or_none()
    if existing:
        return await _p8_po_payload(db, existing)

    approval = await _p8_approval(db, pr.approval_id)
    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Approved purchase request is required before PO creation",
        )

    vendor = await _p8_vendor(db, payload.vendor_id)

    if (
        payload.expected_delivery_date
        and payload.expected_delivery_date < payload.order_date
    ):
        raise HTTPException(
            status_code=400,
            detail="expected_delivery_date cannot be before order_date",
        )

    pr_lines = await _p8_pr_lines(db, pr.id)
    if not pr_lines:
        raise HTTPException(status_code=409, detail="Purchase request has no lines")

    overrides = {}
    if payload.lines is not None:
        for item in payload.lines:
            key = str(item.purchase_request_line_id)
            if key in overrides:
                raise HTTPException(
                    status_code=400,
                    detail="Duplicate purchase request line in PO payload",
                )
            overrides[key] = item

        if set(overrides) != {str(x.id) for x in pr_lines}:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Foundation mode requires one PO covering all PR lines "
                    "exactly once"
                ),
            )

    po = _P8PurchaseOrder(
        po_number=_p8_number("PO", payload.order_date),
        purchase_request_id=pr.id,
        vendor_id=vendor.id,
        order_date=payload.order_date,
        expected_delivery_date=payload.expected_delivery_date,
        currency=pr.currency,
        status="draft",
        notes=payload.notes,
        po_metadata={
            **(payload.po_metadata or {}),
            "source_purchase_request_id": str(pr.id),
            "source_purchase_request_number": pr.request_number,
            "external_dispatch_executed": False,
        },
    )
    db.add(po)
    await db.flush()

    subtotal = _P8_ZERO
    vat_total = _P8_ZERO

    for index, pr_line in enumerate(pr_lines, start=1):
        item = overrides.get(str(pr_line.id))
        account_id = (
            item.account_id if item and item.account_id else pr_line.account_id
        )
        if not account_id:
            raise HTTPException(
                status_code=409,
                detail=f"Finance expense/asset account required for PR line {index}",
            )

        await _p8_account(
            db,
            account_id,
            {"expense", "asset"},
            f"PO line {index}",
        )

        qty = _p8_qty(
            item.quantity
            if item and item.quantity is not None
            else pr_line.quantity
        )
        requested_qty = _p8_qty(pr_line.quantity)

        if qty != requested_qty:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Foundation mode requires PO quantity to equal "
                    f"requested quantity for PR line {index}"
                ),
            )

        price = (
            item.unit_price
            if item and item.unit_price is not None
            else pr_line.estimated_unit_price
        )
        rate = (
            item.vat_rate
            if item and item.vat_rate is not None
            else pr_line.vat_rate
        )
        qty, price, rate, net, vat, total = _p8_calc(qty, price, rate)

        db.add(
            _P8PurchaseOrderLine(
                purchase_order_id=po.id,
                purchase_request_line_id=pr_line.id,
                line_number=index,
                description=(
                    item.description.strip()
                    if item and item.description
                    else pr_line.description
                ),
                account_id=account_id,
                quantity=qty,
                unit_price=price,
                vat_rate=rate,
                net_amount=net,
                vat_amount=vat,
                total_amount=total,
                received_quantity=0,
                cost_center=(
                    item.cost_center.strip()
                    if item and item.cost_center
                    else pr_line.cost_center
                ),
                line_metadata=(item.line_metadata if item else {}) or {},
            )
        )
        subtotal += net
        vat_total += vat

    if subtotal + vat_total <= 0:
        raise HTTPException(
            status_code=409,
            detail="Purchase order total must be greater than zero",
        )

    po.subtotal = subtotal
    po.vat_amount = vat_total
    po.total_amount = subtotal + vat_total
    pr.status = "converted_to_po"

    await write_audit_log(
        db,
        actor="user",
        action="procurement.purchase_order.created",
        details={
            "purchase_order_id": str(po.id),
            "po_number": po.po_number,
            "purchase_request_id": str(pr.id),
            "vendor_id": str(vendor.id),
            "total_amount": str(po.total_amount),
            "external_commitment_executed": False,
        },
    )

    await db.commit()
    await db.refresh(po)
    return await _p8_po_payload(db, po)


@app.get("/api/procurement/purchase-orders")
async def list_procurement_purchase_orders(
    status: str | None = None,
    vendor_id: _p8_uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _p8_select(_P8PurchaseOrder)
    if status:
        query = query.where(_P8PurchaseOrder.status == status.strip().lower())
    if vendor_id:
        query = query.where(_P8PurchaseOrder.vendor_id == vendor_id)

    rows = (
        await db.execute(
            query.order_by(
                _P8PurchaseOrder.order_date.desc(),
                _P8PurchaseOrder.created_at.desc(),
            )
        )
    ).scalars().all()
    return [await _p8_po_payload(db, x) for x in rows]


