@app.post("/api/procurement/rfqs/{rfq_id}/open")
async def open_procurement_rfq(
    rfq_id: _p9_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(_P9RFQ, rfq_id)
    if row is None:
        raise HTTPException(status_code=404, detail="RFQ not found")

    if row.status == "open":
        return await _p9_rfq_payload(db, row)
    if row.status != "draft":
        raise HTTPException(status_code=409, detail="Only draft RFQs can be opened")

    invited = await _p9_rfq_vendors(db, row.id)
    if not invited:
        raise HTTPException(status_code=409, detail="RFQ has no invited vendors")

    now = _p9_datetime.now(_p9_timezone.utc)
    row.status = "open"
    row.opened_at = now
    row.rfq_metadata = {
        **(row.rfq_metadata or {}),
        "external_communication_executed": False,
        "opened_for_internal_tracking": True,
    }

    for item in invited:
        item.invited_at = now

    await write_audit_log(
        db,
        actor="user",
        action="procurement.rfq.opened",
        details={
            "rfq_id": str(row.id),
            "vendor_count": len(invited),
            "external_communication_executed": False,
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _p9_rfq_payload(db, row)


@app.post("/api/procurement/rfqs/{rfq_id}/close")
async def close_procurement_rfq(
    rfq_id: _p9_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(_P9RFQ, rfq_id)
    if row is None:
        raise HTTPException(status_code=404, detail="RFQ not found")
    if row.status == "closed":
        return await _p9_rfq_payload(db, row)
    if row.status != "open":
        raise HTTPException(status_code=409, detail="Only open RFQs can be closed")

    quote_count = await db.scalar(
        _p9_select(_p9_func.count())
        .select_from(_P9Quotation)
        .where(_P9Quotation.rfq_id == row.id)
    )
    if not quote_count:
        raise HTTPException(
            status_code=409,
            detail="RFQ cannot be closed without at least one quotation",
        )

    row.status = "closed"
    row.closed_at = _p9_datetime.now(_p9_timezone.utc)

    await write_audit_log(
        db,
        actor="user",
        action="procurement.rfq.closed",
        details={
            "rfq_id": str(row.id),
            "quotation_count": int(quote_count or 0),
        },
    )
    await db.commit()
    await db.refresh(row)
    return await _p9_rfq_payload(db, row)


@app.post("/api/procurement/rfqs/{rfq_id}/quotations")
async def create_procurement_quotation(
    rfq_id: _p9_uuid.UUID,
    payload: _P9QuotationCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    rfq = await db.get(_P9RFQ, rfq_id)
    if rfq is None:
        raise HTTPException(status_code=404, detail="RFQ not found")
    if rfq.status != "open":
        raise HTTPException(status_code=409, detail="RFQ must be open to accept quotations")

    vendor = await _p8_vendor(db, payload.vendor_id)

    invitation = (
        await db.execute(
            _p9_select(_P9RFQVendor).where(
                _P9RFQVendor.rfq_id == rfq.id,
                _P9RFQVendor.vendor_id == vendor.id,
            )
        )
    ).scalars().first()

    if invitation is None:
        raise HTTPException(status_code=409, detail="Vendor was not invited to this RFQ")

    existing = (
        await db.execute(
            _p9_select(_P9Quotation).where(
                _P9Quotation.rfq_id == rfq.id,
                _P9Quotation.vendor_id == vendor.id,
            )
        )
    ).scalars().first()
    if existing:
        raise HTTPException(
            status_code=409,
            detail="A quotation already exists for this vendor and RFQ",
        )

    if payload.valid_until and payload.valid_until < payload.quote_date:
        raise HTTPException(
            status_code=400,
            detail="valid_until cannot be before quote_date",
        )
    if payload.delivery_days is not None and payload.delivery_days < 0:
        raise HTTPException(status_code=400, detail="delivery_days cannot be negative")
    if payload.payment_terms_days is not None and payload.payment_terms_days < 0:
        raise HTTPException(status_code=400, detail="payment_terms_days cannot be negative")

    pr_lines = await _p8_pr_lines(db, rfq.purchase_request_id)
    pr_map = {str(line.id): line for line in pr_lines}

    if not payload.lines:
        raise HTTPException(status_code=400, detail="Quotation requires lines")

    supplied_ids = [str(line.purchase_request_line_id) for line in payload.lines]
    if len(set(supplied_ids)) != len(supplied_ids):
        raise HTTPException(status_code=400, detail="Duplicate PR line in quotation")
    if set(supplied_ids) != set(pr_map):
        raise HTTPException(
            status_code=409,
            detail="Quotation must cover every purchase request line exactly once",
        )

    quote = _P9Quotation(
        quotation_number=_p8_number("QT", payload.quote_date),
        rfq_id=rfq.id,
        vendor_id=vendor.id,
        vendor_quote_reference=(
            payload.vendor_quote_reference.strip()
            if payload.vendor_quote_reference
            else None
        ),
        quote_date=payload.quote_date,
        valid_until=payload.valid_until,
        currency=rfq.currency,
        delivery_days=payload.delivery_days,
        payment_terms_days=payload.payment_terms_days,
        warranty_terms=payload.warranty_terms,
        status="submitted",
        notes=payload.notes,
        quote_metadata={
            **(payload.quote_metadata or {}),
            "source": "procurement_batch_9",
        },
    )
    db.add(quote)
    await db.flush()

    subtotal = _P9Decimal("0.00")
    vat_total = _P9Decimal("0.00")

    for index, item in enumerate(payload.lines, start=1):
        pr_line = pr_map[str(item.purchase_request_line_id)]
        requested_qty = _p8_qty(pr_line.quantity)
        quoted_qty = _p8_qty(item.quantity)

        if requested_qty != quoted_qty:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Quotation quantity must equal requested quantity "
                    f"for PR line {pr_line.line_number}"
                ),
            )

        qty, price, rate, net, vat, total = _p8_calc(
            quoted_qty,
            item.unit_price,
            item.vat_rate,
        )

        db.add(
            _P9QuotationLine(
                quotation_id=quote.id,
                purchase_request_line_id=pr_line.id,
                line_number=index,
                description=(
                    item.description.strip()
                    if item.description
                    else pr_line.description
                ),
                quantity=qty,
                unit_price=price,
                vat_rate=rate,
                net_amount=net,
                vat_amount=vat,
                total_amount=total,
                line_metadata=item.line_metadata or {},
            )
        )
        subtotal += net
        vat_total += vat

    if subtotal + vat_total <= 0:
        raise HTTPException(status_code=409, detail="Quotation total must be greater than zero")

    quote.subtotal = subtotal
    quote.vat_amount = vat_total
    quote.total_amount = subtotal + vat_total
    invitation.status = "quoted"

    await write_audit_log(
        db,
        actor="user",
        action="procurement.quotation.created",
        details={
            "quotation_id": str(quote.id),
            "rfq_id": str(rfq.id),
            "vendor_id": str(vendor.id),
            "total_amount": str(quote.total_amount),
        },
    )

    await db.commit()
    await db.refresh(quote)
    return await _p9_quote_payload(db, quote)


