@app.get("/api/procurement/rfqs/{rfq_id}/comparison")
async def procurement_rfq_comparison(
    rfq_id: _p9_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    rfq = await db.get(_P9RFQ, rfq_id)
    if rfq is None:
        raise HTTPException(status_code=404, detail="RFQ not found")

    quotes = (
        await db.execute(
            _p9_select(_P9Quotation)
            .where(
                _P9Quotation.rfq_id == rfq.id,
                _P9Quotation.status.in_(["submitted", "selected", "not_selected"]),
            )
            .order_by(_P9Quotation.total_amount.asc())
        )
    ).scalars().all()

    if not quotes:
        return {
            "rfq_id": str(rfq.id),
            "rfq_number": rfq.rfq_number,
            "quotation_count": 0,
            "rows": [],
        }

    lowest_total = min(_P9Decimal(str(x.total_amount or 0)) for x in quotes)
    delivery_values = [x.delivery_days for x in quotes if x.delivery_days is not None]
    shortest_delivery = min(delivery_values) if delivery_values else None

    vendor_ids = [x.vendor_id for x in quotes]
    qmap = await _p9_qualification_map(db, vendor_ids)
    vendors = (
        await db.execute(
            _p9_select(_P8FinanceVendor).where(
                _P8FinanceVendor.id.in_(vendor_ids)
            )
        )
    ).scalars().all()
    vmap = {x.id: x for x in vendors}

    rows = []
    for quote in quotes:
        total = _P9Decimal(str(quote.total_amount or 0))
        delta = total - lowest_total
        pct = (
            float((delta / lowest_total) * 100)
            if lowest_total > 0
            else 0.0
        )
        vendor = vmap.get(quote.vendor_id)
        rows.append({
            "quotation_id": str(quote.id),
            "quotation_number": quote.quotation_number,
            "vendor_id": str(quote.vendor_id),
            "vendor_code": vendor.code if vendor else None,
            "vendor_name": (
                vendor.name_ar or vendor.name_en
                if vendor
                else None
            ),
            "total_amount": float(total),
            "currency": quote.currency,
            "difference_from_lowest": float(delta),
            "difference_from_lowest_pct": round(pct, 2),
            "is_lowest_total": total == lowest_total,
            "delivery_days": quote.delivery_days,
            "is_shortest_delivery": (
                shortest_delivery is not None
                and quote.delivery_days == shortest_delivery
            ),
            "payment_terms_days": quote.payment_terms_days,
            "warranty_terms": quote.warranty_terms,
            "qualification": _p9_qualification_payload(qmap.get(quote.vendor_id)),
            "status": quote.status,
        })

    return {
        "rfq_id": str(rfq.id),
        "rfq_number": rfq.rfq_number,
        "quotation_count": len(rows),
        "lowest_total": float(lowest_total),
        "shortest_delivery_days": shortest_delivery,
        "rows": rows,
        "note": (
            "Comparison is descriptive only. Supplier selection requires "
            "an explicit award decision and approval."
        ),
    }


@app.post("/api/procurement/rfqs/{rfq_id}/award/request-approval")
async def request_procurement_supplier_award_approval(
    rfq_id: _p9_uuid.UUID,
    payload: _P9AwardRequest,
    db: AsyncSession = Depends(get_db),
):
    rfq = await db.get(_P9RFQ, rfq_id)
    if rfq is None:
        raise HTTPException(status_code=404, detail="RFQ not found")

    if rfq.status not in {"open", "closed"}:
        raise HTTPException(
            status_code=409,
            detail="RFQ must be open or closed before supplier award",
        )

    quote = await db.get(_P9Quotation, payload.selected_quotation_id)
    if quote is None or quote.rfq_id != rfq.id:
        raise HTTPException(status_code=409, detail="Quotation does not belong to RFQ")

    existing = (
        await db.execute(
            _p9_select(_P9AwardDecision).where(
                _P9AwardDecision.rfq_id == rfq.id
            )
        )
    ).scalars().first()

    if existing:
        existing_approval = await _p8_approval(db, existing.approval_id)

        if existing.status == "executed":
            return await _p9_award_payload(db, existing)

        if existing_approval and existing_approval.status in {"pending", "approved"}:
            if existing.selected_quotation_id == quote.id:
                return await _p9_award_payload(db, existing)

            raise HTTPException(
                status_code=409,
                detail="An active supplier award already exists for this RFQ",
            )

    agent = await _p8_agent(db, create=True)

    approval = _P8Approval(
        agent_id=agent.id,
        title=f"اعتماد ترسية {rfq.rfq_number}",
        description=(
            f"Supplier award for RFQ {rfq.rfq_number}; "
            f"quotation {quote.quotation_number}; "
            f"total {float(quote.total_amount):,.2f} {quote.currency}. "
            "Award approval does not issue a PO or execute payment."
        ),
        action_type="procurement_supplier_award",
        risk_level="high",
        status="pending",
        action_payload={
            "rfq_id": str(rfq.id),
            "quotation_id": str(quote.id),
            "vendor_id": str(quote.vendor_id),
            "total_amount": float(quote.total_amount),
            "currency": quote.currency,
            "rationale": payload.rationale,
            "purchase_order_created": False,
            "external_commitment_executed": False,
        },
    )
    db.add(approval)
    await db.flush()

    if existing is None:
        award = _P9AwardDecision(
            rfq_id=rfq.id,
            selected_quotation_id=quote.id,
            approval_id=approval.id,
            status="pending_approval",
            rationale=payload.rationale,
            award_metadata={
                "purchase_order_created": False,
                "external_commitment_executed": False,
            },
        )
        db.add(award)
    else:
        award = existing
        award.selected_quotation_id = quote.id
        award.approval_id = approval.id
        award.status = "pending_approval"
        award.rationale = payload.rationale
        award.decided_by = None
        award.decided_at = None
        award.award_metadata = {
            "purchase_order_created": False,
            "external_commitment_executed": False,
        }

    await write_audit_log(
        db,
        actor=payload.requested_by.strip() or "user",
        action="procurement.award.approval_requested",
        details={
            "rfq_id": str(rfq.id),
            "quotation_id": str(quote.id),
            "approval_id": str(approval.id),
            "risk_level": "high",
        },
    )
    await db.commit()
    await db.refresh(award)
    return await _p9_award_payload(db, award)


@app.post("/api/procurement/rfqs/{rfq_id}/award/execute")
async def execute_procurement_supplier_award(
    rfq_id: _p9_uuid.UUID,
    payload: _P9AwardExecuteRequest,
    db: AsyncSession = Depends(get_db),
):
    rfq = await db.get(_P9RFQ, rfq_id)
    if rfq is None:
        raise HTTPException(status_code=404, detail="RFQ not found")

    award = (
        await db.execute(
            _p9_select(_P9AwardDecision).where(
                _P9AwardDecision.rfq_id == rfq.id
            )
        )
    ).scalars().first()

    if award is None:
        raise HTTPException(status_code=409, detail="Supplier award not found")

    if award.status == "executed":
        return await _p9_award_payload(db, award)

    approval = await _p8_approval(db, award.approval_id)
    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Approved supplier-award authorization is required",
        )

    selected = await db.get(_P9Quotation, award.selected_quotation_id)
    if selected is None:
        raise HTTPException(status_code=409, detail="Selected quotation is missing")

    quotes = (
        await db.execute(
            _p9_select(_P9Quotation).where(
                _P9Quotation.rfq_id == rfq.id
            )
        )
    ).scalars().all()

    for quote in quotes:
        quote.status = "selected" if quote.id == selected.id else "not_selected"

    now = _p9_datetime.now(_p9_timezone.utc)
    award.status = "executed"
    award.decided_by = payload.decided_by.strip() or "user"
    award.decided_at = now
    award.award_metadata = {
        **(award.award_metadata or {}),
        "purchase_order_created": False,
        "external_commitment_executed": False,
    }
    rfq.status = "awarded"
    rfq.closed_at = rfq.closed_at or now
    approval.executed_at = now

    await write_audit_log(
        db,
        actor=award.decided_by,
        action="procurement.award.executed",
        details={
            "rfq_id": str(rfq.id),
            "quotation_id": str(selected.id),
            "vendor_id": str(selected.vendor_id),
            "purchase_order_created": False,
            "external_commitment_executed": False,
        },
    )
    await db.commit()
    await db.refresh(award)
    return await _p9_award_payload(db, award)


@app.post("/api/procurement/rfqs/{rfq_id}/create-purchase-order")
async def create_purchase_order_from_awarded_rfq(
    rfq_id: _p9_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    rfq = await db.get(_P9RFQ, rfq_id)
    if rfq is None:
        raise HTTPException(status_code=404, detail="RFQ not found")

    award = (
        await db.execute(
            _p9_select(_P9AwardDecision).where(
                _P9AwardDecision.rfq_id == rfq.id
            )
        )
    ).scalars().first()

    if award is None or award.status != "executed":
        raise HTTPException(
            status_code=409,
            detail="Executed supplier award is required before PO creation",
        )

    existing_po = (
        await db.execute(
            _p9_select(_P8PurchaseOrder).where(
                _P8PurchaseOrder.purchase_request_id == rfq.purchase_request_id
            )
        )
    ).scalars().first()

    if existing_po:
        return await _p8_po_payload(db, existing_po)

    quote = await db.get(_P9Quotation, award.selected_quotation_id)
    if quote is None:
        raise HTTPException(status_code=409, detail="Selected quotation is missing")

    vendor = await _p8_vendor(db, quote.vendor_id)
    pr = await db.get(_P8PurchaseRequest, rfq.purchase_request_id)
    if pr is None:
        raise HTTPException(status_code=409, detail="Source purchase request is missing")

    qlines = await _p9_quote_lines(db, quote.id)
    pr_lines = await _p8_pr_lines(db, pr.id)
    pr_map = {line.id: line for line in pr_lines}

    po = _P8PurchaseOrder(
        po_number=_p8_number("PO", _p9_date.today()),
        purchase_request_id=pr.id,
        vendor_id=vendor.id,
        order_date=_p9_date.today(),
        expected_delivery_date=(
            _p9_date.today()
            + _p9_timedelta(days=int(quote.delivery_days))
            if quote.delivery_days is not None
            else None
        ),
        currency=quote.currency,
        subtotal=quote.subtotal,
        vat_amount=quote.vat_amount,
        total_amount=quote.total_amount,
        status="draft",
        approval_id=None,
        notes=f"Created from awarded RFQ {rfq.rfq_number}",
        po_metadata={
            "source": "procurement_batch_9_award",
            "rfq_id": str(rfq.id),
            "rfq_number": rfq.rfq_number,
            "quotation_id": str(quote.id),
            "quotation_number": quote.quotation_number,
            "supplier_award_id": str(award.id),
            "external_dispatch_executed": False,
        },
    )
    db.add(po)
    await db.flush()

    for index, qline in enumerate(qlines, start=1):
        pr_line = pr_map.get(qline.purchase_request_line_id)
        if pr_line is None or not pr_line.account_id:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Every awarded PR line requires a Finance expense/asset "
                    "account before PO creation"
                ),
            )

        await _p8_account(
            db,
            pr_line.account_id,
            {"expense", "asset"},
            f"PO line {index}",
        )

        db.add(
            _P8PurchaseOrderLine(
                purchase_order_id=po.id,
                purchase_request_line_id=pr_line.id,
                line_number=index,
                description=qline.description,
                account_id=pr_line.account_id,
                quantity=qline.quantity,
                unit_price=qline.unit_price,
                vat_rate=qline.vat_rate,
                net_amount=qline.net_amount,
                vat_amount=qline.vat_amount,
                total_amount=qline.total_amount,
                received_quantity=0,
                cost_center=pr_line.cost_center,
                line_metadata={
                    "source_quotation_line_id": str(qline.id),
                    "source_rfq_id": str(rfq.id),
                },
            )
        )

    pr.status = "converted_to_po"
    award.award_metadata = {
        **(award.award_metadata or {}),
        "purchase_order_created": True,
        "purchase_order_id": str(po.id),
        "external_commitment_executed": False,
    }

    await write_audit_log(
        db,
        actor="user",
        action="procurement.award.purchase_order_created",
        details={
            "rfq_id": str(rfq.id),
            "award_id": str(award.id),
            "purchase_order_id": str(po.id),
            "po_status": "draft",
            "automatic_issue": False,
            "external_commitment_executed": False,
        },
    )

    await db.commit()
    await db.refresh(po)
    return await _p8_po_payload(db, po)


@app.get("/api/procurement/batch9/summary")
async def procurement_batch9_summary(
    db: AsyncSession = Depends(get_db),
):
    rfqs = (await db.execute(_p9_select(_P9RFQ))).scalars().all()
    quotes = (await db.execute(_p9_select(_P9Quotation))).scalars().all()
    awards = (await db.execute(_p9_select(_P9AwardDecision))).scalars().all()
    quals = (
        await db.execute(_p9_select(_P9SupplierQualification))
    ).scalars().all()
    pos = (
        await db.execute(_p9_select(_P8PurchaseOrder))
    ).scalars().all()

    vendor_ids = list({po.vendor_id for po in pos})
    vendors = (
        await db.execute(
            _p9_select(_P8FinanceVendor).where(
                _P8FinanceVendor.id.in_(vendor_ids)
            )
        )
    ).scalars().all() if vendor_ids else []
    vmap = {x.id: x for x in vendors}

    by_vendor = {}
    for po in pos:
        item = by_vendor.setdefault(
            str(po.vendor_id),
            {
                "vendor_id": str(po.vendor_id),
                "vendor_name": (
                    vmap[po.vendor_id].name_ar or vmap[po.vendor_id].name_en
                    if po.vendor_id in vmap
                    else None
                ),
                "po_count": 0,
                "po_value": 0.0,
            },
        )
        item["po_count"] += 1
        item["po_value"] += float(po.total_amount or 0)

    today = _p9_date.today()
    overdue = [
        po
        for po in pos
        if po.expected_delivery_date
        and po.expected_delivery_date < today
        and po.status in {"issued", "partially_received"}
    ]

    open_pos = [
        po
        for po in pos
        if po.status in {"issued", "partially_received"}
    ]

    pr_ids = list({po.purchase_request_id for po in pos})
    prs = (
        await db.execute(
            _p9_select(_P8PurchaseRequest).where(
                _P8PurchaseRequest.id.in_(pr_ids)
            )
        )
    ).scalars().all() if pr_ids else []
    prmap = {x.id: x for x in prs}

    estimated_total = sum(
        _P9Decimal(str(prmap[po.purchase_request_id].estimated_total or 0))
        for po in pos
        if po.purchase_request_id in prmap
    )
    po_total = sum(
        _P9Decimal(str(po.total_amount or 0))
        for po in pos
    )

    active_attachments = await db.scalar(
        _p9_select(_p9_func.count())
        .select_from(_P9Attachment)
        .where(
            _P9Attachment.module == "procurement",
            _P9Attachment.status == "active",
        )
    )

    def status_counts(rows):
        out = {}
        for row in rows:
            out[row.status] = out.get(row.status, 0) + 1
        return out

    return {
        "rfqs": {
            "total": len(rfqs),
            "by_status": status_counts(rfqs),
        },
        "quotations": {
            "total": len(quotes),
            "by_status": status_counts(quotes),
        },
        "awards": {
            "total": len(awards),
            "by_status": status_counts(awards),
        },
        "supplier_qualification": {
            "total_reviewed": len(quals),
            "by_status": status_counts(quals),
        },
        "delivery": {
            "open_purchase_orders": len(open_pos),
            "overdue_purchase_orders": len(overdue),
            "overdue": [
                {
                    "purchase_order_id": str(po.id),
                    "po_number": po.po_number,
                    "vendor_id": str(po.vendor_id),
                    "expected_delivery_date": po.expected_delivery_date,
                    "status": po.status,
                    "outstanding_days": (
                        today - po.expected_delivery_date
                    ).days,
                }
                for po in overdue
            ],
        },
        "spend": {
            "purchase_order_total": float(po_total),
            "estimated_pr_total": float(estimated_total),
            "variance_vs_pr_estimate": float(po_total - estimated_total),
            "by_vendor": sorted(
                by_vendor.values(),
                key=lambda x: x["po_value"],
                reverse=True,
            ),
        },
        "attachments": {
            "active_procurement_files": int(active_attachments or 0),
            "storage_service": "shared_hr_attachment_service",
        },
        "print": {
            "purchase_order_route": "/procurement/po/{id}/print",
            "browser_save_as_pdf": True,
        },
        "safety": {
            "automatic_supplier_award": False,
            "automatic_po_creation": False,
            "automatic_po_issue": False,
            "automatic_external_communication": False,
            "automatic_finance_posting": False,
            "automatic_payment": False,
            "automatic_bank_transfer": False,
        },
    }

# ============================================================
# Company Control Center - Phase 2 API
# Authority matrix is reference-only until formally activated.
# Proposed financial limits are NEVER auto-enforced here.
# ============================================================
from pydantic import BaseModel as _CCBaseModel
from sqlalchemy import (
    func as _cc_func,
    or_ as _cc_or,
    select as _cc_select,
)

from .models import (
    CompanyAuthorityLimit,
    CompanyAuthorityRole,
    CompanyAuthorityRule,
    CompanyProfile,
)

_COMPANY_AUTHORITY_SOURCE_VERSION = (
    "Enclave_Delegation_of_Authority_RACI_Matrix_AR_v1.0"
)
_COMPANY_AUTHORITY_SOURCE_CHECKSUM = (
    "710b2337633f2ddd93448643352286c80de28971a044dc158dedc5b45cd12ed4"
)

_CC_VAT_STATUSES = {
    "unverified",
    "registered",
    "not_registered",
}


class CompanyProfileUpdateRequest(_CCBaseModel):
    legal_name_ar: str | None = None
    city: str | None = None
    timezone: str | None = None
    vat_status: str | None = None
    vat_number: str | None = None


class CompanyAuthorityRoleUpdateRequest(_CCBaseModel):
    incumbent_name: str | None = None
    delegate_name: str | None = None


def _company_profile_payload(row):
    return {
        "id": str(row.id),
        "profile_key": row.profile_key,
        "legal_name_en": row.legal_name_en,
        "legal_name_ar": row.legal_name_ar,
        "commercial_registration_no":
            row.commercial_registration_no,
        "city": row.city,
        "country_code": row.country_code,
        "base_currency": row.base_currency,
        "timezone": row.timezone,
        "vat_status": row.vat_status,
        "vat_number": row.vat_number,
        "status": row.status,
        "profile_metadata": row.profile_metadata or {},
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _company_role_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "name_ar": row.name_ar,
        "scope_ar": row.scope_ar,
        "incumbent_name": row.incumbent_name,
        "delegate_name": row.delegate_name,
        "notes": row.notes,
        "source_version": row.source_version,
        "status": row.status,
    }


def _company_rule_payload(row):
    return {
        "id": str(row.id),
        "source_version": row.source_version,
        "source_row_number": row.source_row_number,
        "domain": row.domain,
        "activity": row.activity,
        "authority_condition": row.authority_condition,
        "raci": row.raci or {},
        "target_sla": row.target_sla,
        "notes": row.notes,
        "validation_status": row.validation_status,
        "status": row.status,
        "enforcement_enabled": row.enforcement_enabled,
    }


def _company_limit_payload(row):
    return {
        "id": str(row.id),
        "source_version": row.source_version,
        "source_row_number": row.source_row_number,
        "domain": row.domain,
        "band_or_case": row.band_or_case,
        "method_or_condition": row.method_or_condition,
        "responsible": row.responsible,
        "consulted": row.consulted,
        "accountable": row.accountable,
        "escalation": row.escalation,
        "required_documents": row.required_documents,
        "source_status": row.source_status,
        "approval_notes": row.approval_notes,
        "enforcement_enabled": row.enforcement_enabled,
    }


async def _company_primary_profile(db):
    row = (
        await db.execute(
            _cc_select(CompanyProfile).where(
                CompanyProfile.profile_key == "primary"
            )
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Company profile is not initialized",
        )

    return row


@app.get("/api/company/profile")
async def get_company_profile(
    db: AsyncSession = Depends(get_db),
):
    return _company_profile_payload(
        await _company_primary_profile(db)
    )


@app.put("/api/company/profile")
async def update_company_profile(
    payload: CompanyProfileUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await _company_primary_profile(db)

    values = payload.model_dump(
        exclude_unset=True
    )

    if "vat_status" in values:
        status = (
            str(values["vat_status"] or "")
            .strip()
            .lower()
        )

        if status not in _CC_VAT_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid VAT status",
            )

        values["vat_status"] = status

    target_vat_status = values.get(
        "vat_status",
        row.vat_status,
    )

    target_vat_number = values.get(
        "vat_number",
        row.vat_number,
    )

    if isinstance(target_vat_number, str):
        target_vat_number = (
            target_vat_number.strip()
            or None
        )
        values["vat_number"] = target_vat_number

    if (
        target_vat_status == "registered"
        and not target_vat_number
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "VAT number is required when "
                "VAT status is registered"
            ),
        )

    if (
        target_vat_status != "registered"
        and target_vat_number
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "VAT number cannot be stored unless "
                "VAT status is registered"
            ),
        )

    for field in (
        "legal_name_ar",
        "city",
        "timezone",
    ):
        if field in values:
            value = values[field]
            values[field] = (
                value.strip()
                if isinstance(value, str)
                and value.strip()
                else None
            )

    before = _company_profile_payload(row)

    for key, value in values.items():
        setattr(row, key, value)

    await write_audit_log(
        db,
        actor="user",
        action="company.profile.updated",
        details={
            "company_profile_id": str(row.id),
            "changed_fields": sorted(
                values.keys()
            ),
            "before": {
                key: before.get(key)
                for key in values.keys()
            },
        },
    )

    await db.commit()
    await db.refresh(row)

    return _company_profile_payload(row)


