@app.put(
    "/api/company/authority/roles/{role_code}"
)
async def update_company_authority_role(
    role_code: str,
    payload: CompanyAuthorityRoleUpdateRequest,
    db: AsyncSession = Depends(get_db),
):
    code = role_code.strip().upper()

    row = (
        await db.execute(
            _cc_select(
                CompanyAuthorityRole
            ).where(
                CompanyAuthorityRole.code
                == code
            )
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Authority role not found",
        )

    values = payload.model_dump(
        exclude_unset=True
    )

    for field in (
        "incumbent_name",
        "delegate_name",
    ):
        if field in values:
            value = values[field]
            values[field] = (
                value.strip()
                if isinstance(value, str)
                and value.strip()
                else None
            )

    for key, value in values.items():
        setattr(row, key, value)

    await write_audit_log(
        db,
        actor="user",
        action=(
            "company.authority."
            "role_assignment_updated"
        ),
        details={
            "role_code": code,
            "changed_fields":
                sorted(values.keys()),
        },
    )

    await db.commit()
    await db.refresh(row)

    return _company_role_payload(row)


@app.get("/api/company/authority/rules")
async def list_company_authority_rules(
    domain: str | None = None,
    q: str | None = None,
    limit: int = 250,
    db: AsyncSession = Depends(get_db),
):
    limit = max(
        1,
        min(
            int(limit),
            500,
        ),
    )

    query = _cc_select(
        CompanyAuthorityRule
    )

    if domain:
        query = query.where(
            CompanyAuthorityRule.domain
            == domain.strip()
        )

    if q and q.strip():
        pattern = (
            "%"
            + q.strip()
            + "%"
        )

        query = query.where(
            _cc_or(
                CompanyAuthorityRule.activity
                .ilike(pattern),
                CompanyAuthorityRule
                .authority_condition
                .ilike(pattern),
                CompanyAuthorityRule.notes
                .ilike(pattern),
            )
        )

    rows = (
        await db.execute(
            query.order_by(
                CompanyAuthorityRule
                .source_row_number.asc()
            ).limit(limit)
        )
    ).scalars().all()

    return [
        _company_rule_payload(row)
        for row in rows
    ]


