@app.get("/api/company/authority/summary")
async def company_authority_summary(
    db: AsyncSession = Depends(get_db),
):
    total_rules = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityRule
            )
        )
        or 0
    )

    total_limits = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityLimit
            )
        )
        or 0
    )

    total_roles = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityRole
            )
        )
        or 0
    )

    assigned_roles = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityRole
            ).where(
                CompanyAuthorityRole
                .incumbent_name.is_not(None)
            )
        )
        or 0
    )

    enabled_rules = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityRule
            ).where(
                CompanyAuthorityRule
                .enforcement_enabled
                .is_(True)
            )
        )
        or 0
    )

    enabled_limits = int(
        await db.scalar(
            _cc_select(
                _cc_func.count()
            ).select_from(
                CompanyAuthorityLimit
            ).where(
                CompanyAuthorityLimit
                .enforcement_enabled
                .is_(True)
            )
        )
        or 0
    )

    domains = (
        await db.execute(
            _cc_select(
                CompanyAuthorityRule.domain
            )
            .distinct()
            .order_by(
                CompanyAuthorityRule
                .domain.asc()
            )
        )
    ).scalars().all()

    return {
        "source_version":
            _COMPANY_AUTHORITY_SOURCE_VERSION,
        "source_checksum":
            _COMPANY_AUTHORITY_SOURCE_CHECKSUM,
        "rules": {
            "total": total_rules,
            "domains": domains,
            "enforcement_enabled":
                enabled_rules,
        },
        "roles": {
            "total": total_roles,
            "assigned": assigned_roles,
            "unassigned":
                max(0, total_roles - assigned_roles),
        },
        "proposed_limits": {
            "total": total_limits,
            "enforcement_enabled":
                enabled_limits,
        },
        "safety": {
            "authority_matrix_mode":
                "reference_only",
            "automatic_approval_routing":
                False,
            "proposed_financial_limits_enforced":
                False,
            "current_workflow_approvals_changed":
                False,
        },
        "document_numbering": {
            "centralized_registry_enabled":
                False,
            "existing_module_numbering_changed":
                False,
            "status":
                "pending_dedicated_numbering_integration",
        },
    }


