# ============================================================
# Sales & CRM - Phase 1A API
# Policy-grounded; no external or financial side effects.
# ============================================================
import uuid as _sal_uuid
from datetime import date as _sal_date
from decimal import (
    Decimal as _SalDecimal,
    InvalidOperation as _SalInvalidOperation,
)

from pydantic import BaseModel as _SalBaseModel
from sqlalchemy import (
    select as _sal_select,
)

from .models import (
    SalesAccount,
    SalesContact,
    SalesOpportunity,
    SalesOpportunityStageHistory,
)

_SALES_POLICY_SOURCE = (
    "EN-SAL-POL-001 / EN-SAL-GD-001 v1.0 draft"
)

_SALES_STAGES = {
    0: ("عميل محتمل", "Prospect", 0),
    1: ("Lead مسجل", "Registered Lead", 10),
    2: ("فرصة مؤهلة", "Qualified Opportunity", 20),
    3: ("اكتشاف مكتمل", "Discovery Complete", 35),
    4: ("تصميم الحل والجدوى", "Solution Design & Feasibility", 50),
    5: ("عرض مقدم", "Proposal Submitted", 65),
    6: ("تفاوض ومشتريات", "Negotiation & Procurement", 80),
    7: ("اختيار نهائي", "Final Selection", 90),
    8: ("مغلقة - فوز", "Closed Won", 100),
    9: ("مغلقة - خسارة", "Closed Lost", 0),
}

_SALES_ACCOUNT_TYPES = {
    "prospect",
    "customer",
    "partner",
    "government",
}

_SALES_OPPORTUNITY_TYPES = {
    "new_business",
    "renewal",
    "expansion",
    "partnership",
    "government_tender",
}

_SALES_FORECAST_CATEGORIES = {
    "pipeline",
    "best_case",
    "commit",
}


def _sal_money(value):
    try:
        result = _SalDecimal(
            str(value or 0)
        ).quantize(
            _SalDecimal("0.01")
        )
    except (
        _SalInvalidOperation,
        ValueError,
        TypeError,
    ) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid monetary amount: {value}",
        ) from exc

    if result < 0:
        raise HTTPException(
            status_code=400,
            detail="Monetary amounts cannot be negative",
        )

    return result


def _sal_profitability(
    contract_value_ex_vat,
    discount_amount,
    direct_cost,
):
    contract_value = _sal_money(
        contract_value_ex_vat
    )
    discount = _sal_money(
        discount_amount
    )
    cost = _sal_money(
        direct_cost
    )

    if discount > contract_value:
        raise HTTPException(
            status_code=409,
            detail=(
                "Discount cannot exceed "
                "contract value"
            ),
        )

    net = contract_value - discount
    profit = net - cost

    margin = (
        (
            profit
            / net
            * _SalDecimal("100")
        ).quantize(
            _SalDecimal("0.0001")
        )
        if net > 0
        else _SalDecimal("0.0000")
    )

    return {
        "net_revenue_ex_vat": net,
        "gross_profit": profit,
        "gross_margin_pct": margin,
    }


def _sal_stage_payload(stage):
    item = _SALES_STAGES.get(stage)

    if item is None:
        raise HTTPException(
            status_code=400,
            detail="Invalid sales pipeline stage",
        )

    name_ar, name_en, probability = item

    return {
        "stage": stage,
        "name_ar": name_ar,
        "name_en": name_en,
        "probability_pct": probability,
    }


def _sal_account_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "name": row.name,
        "sector": row.sector,
        "account_type": row.account_type,
        "tier": row.tier,
        "owner_name": row.owner_name,
        "source": row.source,
        "status": row.status,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


def _sal_opportunity_payload(row):
    weighted = (
        _sal_money(
            row.period_value_ex_vat
        )
        * _SalDecimal(
            str(row.probability_pct or 0)
        )
        / _SalDecimal("100")
    ).quantize(
        _SalDecimal("0.01")
    )

    return {
        "id": str(row.id),
        "code": row.code,
        "account_id": str(row.account_id),
        "name": row.name,
        "owner_name": row.owner_name,
        "opportunity_type": row.opportunity_type,
        "stage": row.stage,
        "stage_name_ar":
            _SALES_STAGES[row.stage][0],
        "probability_pct": row.probability_pct,
        "forecast_category":
            row.forecast_category,
        "total_contract_value_ex_vat":
            float(
                _sal_money(
                    row.total_contract_value_ex_vat
                )
            ),
        "period_value_ex_vat":
            float(
                _sal_money(
                    row.period_value_ex_vat
                )
            ),
        "weighted_pipeline_value":
            float(weighted),
        "discount_amount":
            float(
                _sal_money(row.discount_amount)
            ),
        "direct_cost_estimate":
            float(
                _sal_money(
                    row.direct_cost_estimate
                )
            ),
        "net_revenue_ex_vat":
            float(
                _sal_money(
                    row.net_revenue_ex_vat
                )
            ),
        "gross_profit":
            float(
                _sal_money(
                    row.gross_profit
                )
            ),
        "gross_margin_pct":
            float(row.gross_margin_pct or 0),
        "expected_close_date":
            row.expected_close_date,
        "next_step": row.next_step,
        "next_step_date": row.next_step_date,
        "need_summary": row.need_summary,
        "decision_maker":
            row.decision_maker,
        "budget_status":
            row.budget_status,
        "buying_process":
            row.buying_process,
        "scope_summary":
            row.scope_summary,
        "binding_document_reference":
            row.binding_document_reference,
        "loss_reason":
            row.loss_reason,
        "status": row.status,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


