@app.post("/api/sales/accounts")
async def create_sales_account(
    payload: SalesAccountCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    name = payload.name.strip()

    if not name:
        raise HTTPException(
            status_code=400,
            detail="Account name is required",
        )

    account_type = (
        payload.account_type
        .strip()
        .lower()
    )

    if account_type not in _SALES_ACCOUNT_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid sales account type",
        )

    tier = (
        payload.tier.strip().upper()
        if payload.tier
        else None
    )

    if tier not in {
        None,
        "A",
        "B",
        "C",
    }:
        raise HTTPException(
            status_code=400,
            detail="Tier must be A, B or C",
        )

    row = SalesAccount(
        code=(
            "ACC-"
            + _sal_uuid.uuid4().hex[:8].upper()
        ),
        name=name,
        sector=(
            payload.sector.strip()
            if payload.sector
            and payload.sector.strip()
            else None
        ),
        account_type=account_type,
        tier=tier,
        owner_name=(
            payload.owner_name.strip()
            if payload.owner_name
            and payload.owner_name.strip()
            else None
        ),
        source=(
            payload.source.strip()
            if payload.source
            and payload.source.strip()
            else None
        ),
        status="active",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        account_metadata={
            "source_policy":
                _SALES_POLICY_SOURCE,
        },
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="sales.account.created",
        details={
            "account_id":
                str(row.id),
            "account_code":
                row.code,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _sal_account_payload(row)


