@app.post("/api/sales/opportunities")
async def create_sales_opportunity(
    payload: SalesOpportunityCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    account = await db.get(
        SalesAccount,
        payload.account_id,
    )

    if account is None:
        raise HTTPException(
            status_code=404,
            detail="Sales account not found",
        )

    opportunity_type = (
        payload.opportunity_type
        .strip()
        .lower()
    )

    if (
        opportunity_type
        not in _SALES_OPPORTUNITY_TYPES
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid opportunity type",
        )

    forecast = (
        payload.forecast_category
        .strip()
        .lower()
    )

    if (
        forecast
        not in _SALES_FORECAST_CATEGORIES
    ):
        raise HTTPException(
            status_code=400,
            detail="Invalid forecast category",
        )

    total_value = _sal_money(
        payload.total_contract_value_ex_vat
    )
    period_value = _sal_money(
        payload.period_value_ex_vat
    )

    if period_value > total_value:
        raise HTTPException(
            status_code=409,
            detail=(
                "Period value cannot exceed "
                "total contract value"
            ),
        )

    profitability = _sal_profitability(
        total_value,
        payload.discount_amount,
        payload.direct_cost_estimate,
    )

    name = payload.name.strip()

    if not name:
        raise HTTPException(
            status_code=400,
            detail="Opportunity name is required",
        )

    row = SalesOpportunity(
        code=(
            "OPP-"
            + _sal_uuid.uuid4().hex[:8].upper()
        ),
        account_id=account.id,
        name=name,
        owner_name=(
            payload.owner_name.strip()
            if payload.owner_name
            and payload.owner_name.strip()
            else None
        ),
        opportunity_type=opportunity_type,
        stage=0,
        probability_pct=0,
        forecast_category=forecast,
        total_contract_value_ex_vat=
            total_value,
        period_value_ex_vat=
            period_value,
        discount_amount=
            _sal_money(
                payload.discount_amount
            ),
        direct_cost_estimate=
            _sal_money(
                payload.direct_cost_estimate
            ),
        net_revenue_ex_vat=
            profitability[
                "net_revenue_ex_vat"
            ],
        gross_profit=
            profitability[
                "gross_profit"
            ],
        gross_margin_pct=
            profitability[
                "gross_margin_pct"
            ],
        expected_close_date=
            payload.expected_close_date,
        next_step=(
            payload.next_step.strip()
            if payload.next_step
            and payload.next_step.strip()
            else None
        ),
        next_step_date=
            payload.next_step_date,
        need_summary=(
            payload.need_summary.strip()
            if payload.need_summary
            and payload.need_summary.strip()
            else None
        ),
        decision_maker=(
            payload.decision_maker.strip()
            if payload.decision_maker
            and payload.decision_maker.strip()
            else None
        ),
        budget_status=(
            payload.budget_status.strip()
            if payload.budget_status
            and payload.budget_status.strip()
            else None
        ),
        buying_process=(
            payload.buying_process.strip()
            if payload.buying_process
            and payload.buying_process.strip()
            else None
        ),
        scope_summary=(
            payload.scope_summary.strip()
            if payload.scope_summary
            and payload.scope_summary.strip()
            else None
        ),
        status="open",
        opportunity_metadata={
            "source_policy":
                _SALES_POLICY_SOURCE,
        },
    )

    db.add(row)
    await db.flush()

    db.add(
        SalesOpportunityStageHistory(
            opportunity_id=row.id,
            from_stage=None,
            to_stage=0,
            evidence="Opportunity created",
            changed_by="user",
        )
    )

    await db.commit()
    await db.refresh(row)

    return _sal_opportunity_payload(row)


@app.post(
    "/api/sales/opportunities/{opportunity_id}/stage"
)
async def update_sales_opportunity_stage(
    opportunity_id: _sal_uuid.UUID,
    payload: SalesOpportunityStageRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        SalesOpportunity,
        opportunity_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Sales opportunity not found",
        )

    target = payload.stage

    if target not in _SALES_STAGES:
        raise HTTPException(
            status_code=400,
            detail="Invalid pipeline stage",
        )

    evidence = (
        payload.evidence.strip()
        if payload.evidence
        and payload.evidence.strip()
        else None
    )

    if 2 <= target <= 7 and not evidence:
        raise HTTPException(
            status_code=409,
            detail=(
                "Evidence is required for "
                "qualified/advanced stage movement"
            ),
        )

    binding_reference = (
        payload.binding_document_reference.strip()
        if payload.binding_document_reference
        and payload.binding_document_reference.strip()
        else row.binding_document_reference
    )

    loss_reason = (
        payload.loss_reason.strip()
        if payload.loss_reason
        and payload.loss_reason.strip()
        else row.loss_reason
    )

    if target == 8 and not binding_reference:
        raise HTTPException(
            status_code=409,
            detail=(
                "Closed Won requires a binding "
                "contract or purchase-order reference"
            ),
        )

    if target == 9 and not loss_reason:
        raise HTTPException(
            status_code=409,
            detail=(
                "Closed Lost requires a "
                "documented loss reason"
            ),
        )

    old_stage = row.stage

    row.stage = target
    row.probability_pct = (
        _SALES_STAGES[target][2]
    )
    row.binding_document_reference = (
        binding_reference
    )
    row.loss_reason = loss_reason

    if payload.next_step is not None:
        row.next_step = (
            payload.next_step.strip()
            or None
        )

    if payload.next_step_date is not None:
        row.next_step_date = (
            payload.next_step_date
        )

    if target == 8:
        row.status = "won"
        row.forecast_category = "commit"
    elif target == 9:
        row.status = "lost"
    else:
        row.status = "open"

    db.add(
        SalesOpportunityStageHistory(
            opportunity_id=row.id,
            from_stage=old_stage,
            to_stage=target,
            evidence=evidence,
            changed_by=(
                payload.changed_by.strip()
                or "user"
            ),
        )
    )

    await write_audit_log(
        db,
        actor=(
            payload.changed_by.strip()
            or "user"
        ),
        action="sales.opportunity.stage_changed",
        details={
            "opportunity_id":
                str(row.id),
            "from_stage":
                old_stage,
            "to_stage":
                target,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _sal_opportunity_payload(row)


