@app.get("/api/sales/summary")
async def sales_summary(
    db: AsyncSession = Depends(get_db),
):
    accounts = (
        await db.execute(
            _sal_select(SalesAccount)
        )
    ).scalars().all()

    opportunities = (
        await db.execute(
            _sal_select(
                SalesOpportunity
            )
        )
    ).scalars().all()

    open_rows = [
        row
        for row in opportunities
        if row.status == "open"
    ]

    qualified = [
        row
        for row in open_rows
        if 2 <= row.stage <= 7
    ]

    unweighted = sum(
        (
            _sal_money(
                row.period_value_ex_vat
            )
            for row in qualified
        ),
        _SalDecimal("0.00"),
    )

    weighted = sum(
        (
            (
                _sal_money(
                    row.period_value_ex_vat
                )
                * _SalDecimal(
                    str(
                        row.probability_pct
                        or 0
                    )
                )
                / _SalDecimal("100")
            ).quantize(
                _SalDecimal("0.01")
            )
            for row in qualified
        ),
        _SalDecimal("0.00"),
    )

    today = _sal_date.today()

    return {
        "accounts": {
            "total": len(accounts),
        },
        "opportunities": {
            "total": len(opportunities),
            "open": len(open_rows),
            "won": sum(
                1
                for row in opportunities
                if row.status == "won"
            ),
            "lost": sum(
                1
                for row in opportunities
                if row.status == "lost"
            ),
            "without_next_step": sum(
                1
                for row in open_rows
                if not row.next_step
            ),
            "overdue_next_step": sum(
                1
                for row in open_rows
                if row.next_step_date
                and row.next_step_date < today
            ),
        },
        "pipeline": {
            "qualified_unweighted_ex_vat":
                float(unweighted),
            "weighted_ex_vat":
                float(weighted),
            "weighted_is_commit":
                False,
        },
        "policy_reference": {
            "source":
                _SALES_POLICY_SOURCE,
            "proposed_margin_floor_pct":
                30,
            "proposed_margin_target_pct":
                40,
            "proposed_commission_rate_pct":
                10,
            "proposed_figures_binding":
                False,
        },
        "safety": {
            "automatic_external_communication":
                False,
            "automatic_customer_creation_in_finance":
                False,
            "automatic_invoice_creation":
                False,
            "automatic_collection_confirmation":
                False,
            "automatic_commission_payment":
                False,
            "automatic_payroll_change":
                False,
            "automatic_bank_transfer":
                False,
        },
    }

# ============================================================
# Sales & CRM - Phase 1B API
# Quotations, targets, Finance-verified collections, commissions.
# No auto invoice, collection confirmation, payroll change or payment.
# ============================================================
import uuid as _salb_uuid
from datetime import date as _salb_date
from decimal import Decimal as _SalBDecimal, InvalidOperation as _SalBInvalidOperation

from pydantic import BaseModel as _SalBBaseModel
from sqlalchemy import (
    func as _salb_func,
    select as _salb_select,
)

from .models import (
    CompanyProfile as _SalBCompanyProfile,
    FinanceCustomer as _SalBFinanceCustomer,
    FinanceInvoice as _SalBFinanceInvoice,
    FinanceInvoiceReceipt as _SalBFinanceInvoiceReceipt,
    HREmployee as _SalBHREmployee,
    SalesAccount as _SalBSalesAccount,
    SalesOpportunity as _SalBSalesOpportunity,
    SalesCollectionAllocation,
    SalesCollectionMilestone,
    SalesCommissionPlan,
    SalesFinanceCustomerLink,
    SalesQuotation,
    SalesQuotationLine,
    SalesTargetPlan,
)

_SALB_SOURCE = "EN-SAL-POL-001 / EN-SAL-GD-001 v1.0 draft"
_SALB_TARGET_METRICS = {"gross_profit", "net_revenue", "collection"}


def _salb_money(value):
    try:
        amount = _SalBDecimal(str(value or 0)).quantize(
            _SalBDecimal("0.01")
        )
    except (
        _SalBInvalidOperation,
        ValueError,
        TypeError,
    ) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid monetary amount: {value}",
        ) from exc

    if amount < 0:
        raise HTTPException(
            status_code=400,
            detail="Monetary amounts cannot be negative",
        )

    return amount


def _salb_pct(value, field):
    try:
        amount = _SalBDecimal(str(value or 0))
    except (
        _SalBInvalidOperation,
        ValueError,
        TypeError,
    ) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid {field}",
        ) from exc

    if amount < 0:
        raise HTTPException(
            status_code=400,
            detail=f"{field} cannot be negative",
        )

    return amount


async def _salb_sales_agent_id(db):
    agent = (
        await db.execute(
            _salb_select(Agent).where(
                Agent.slug == "sales"
            )
        )
    ).scalars().first()

    return agent.id if agent else None


async def _salb_company_profile(db):
    return (
        await db.execute(
            _salb_select(_SalBCompanyProfile).where(
                _SalBCompanyProfile.profile_key == "primary"
            )
        )
    ).scalars().first()


def _salb_quote_calculation(lines, discount_amount, vat_rate_pct, vat_registered):
    if not lines:
        raise HTTPException(
            status_code=400,
            detail="At least one quotation line is required",
        )

    subtotal = _SalBDecimal("0.00")
    direct_cost = _SalBDecimal("0.00")
    normalized = []

    for index, line in enumerate(lines, start=1):
        description = str(line.description or "").strip()

        if not description:
            raise HTTPException(
                status_code=400,
                detail=f"Quotation line {index} description is required",
            )

        qty = _salb_pct(line.quantity, "quantity")
        unit = _salb_money(line.unit_price)
        cost = _salb_money(line.direct_cost)

        if qty <= 0:
            raise HTTPException(
                status_code=400,
                detail=f"Quotation line {index} quantity must be greater than zero",
            )

        amount = (qty * unit).quantize(_SalBDecimal("0.01"))

        subtotal += amount
        direct_cost += cost

        normalized.append({
            "line_number": index,
            "description": description,
            "quantity": qty,
            "unit_price": unit,
            "net_amount_ex_vat": amount,
            "direct_cost": cost,
            "notes": (
                str(line.notes).strip()
                if line.notes
                else None
            ),
        })

    discount = _salb_money(discount_amount)

    if discount > subtotal:
        raise HTTPException(
            status_code=409,
            detail="Discount cannot exceed quotation subtotal",
        )

    net = subtotal - discount
    gross_profit = net - direct_cost

    margin = (
        (
            gross_profit
            / net
            * _SalBDecimal("100")
        ).quantize(_SalBDecimal("0.0001"))
        if net > 0
        else _SalBDecimal("0.0000")
    )

    vat_rate = _salb_pct(vat_rate_pct, "VAT rate")

    if vat_rate > 100:
        raise HTTPException(
            status_code=400,
            detail="VAT rate cannot exceed 100%",
        )

    if vat_rate > 0 and not vat_registered:
        raise HTTPException(
            status_code=409,
            detail=(
                "Positive VAT is blocked until Company Profile "
                "contains a verified VAT registration number"
            ),
        )

    vat_amount = (
        net * vat_rate / _SalBDecimal("100")
    ).quantize(_SalBDecimal("0.01"))

    return {
        "lines": normalized,
        "subtotal_ex_vat": subtotal,
        "discount_amount": discount,
        "net_revenue_ex_vat": net,
        "direct_cost": direct_cost,
        "gross_profit": gross_profit,
        "gross_margin_pct": margin,
        "vat_rate_pct": vat_rate,
        "vat_amount": vat_amount,
        "total_inc_vat": net + vat_amount,
    }


def _salb_quote_payload(row, lines=None, approval=None):
    return {
        "id": str(row.id),
        "opportunity_id": str(row.opportunity_id),
        "version": row.version,
        "external_quote_number": row.external_quote_number,
        "status": row.status,
        "subtotal_ex_vat": float(_salb_money(row.subtotal_ex_vat)),
        "discount_amount": float(_salb_money(row.discount_amount)),
        "net_revenue_ex_vat": float(_salb_money(row.net_revenue_ex_vat)),
        "direct_cost": float(_salb_money(row.direct_cost)),
        "gross_profit": float(_salb_money(row.gross_profit)),
        "gross_margin_pct": float(row.gross_margin_pct or 0),
        "vat_rate_pct": float(row.vat_rate_pct or 0),
        "vat_amount": float(_salb_money(row.vat_amount)),
        "total_inc_vat": float(_salb_money(row.total_inc_vat)),
        "validity_date": row.validity_date,
        "payment_terms": row.payment_terms,
        "scope_summary": row.scope_summary,
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else None,
        "notes": row.notes,
        "margin_below_proposed_floor": float(row.gross_margin_pct or 0) < 30,
        "policy_reference": {
            "proposed_margin_floor_pct": 30,
            "proposed_margin_target_pct": 40,
            "binding": False,
        },
        "lines": [
            {
                "id": str(item.id),
                "line_number": item.line_number,
                "description": item.description,
                "quantity": float(item.quantity),
                "unit_price": float(item.unit_price),
                "net_amount_ex_vat": float(item.net_amount_ex_vat),
                "direct_cost": float(item.direct_cost),
                "notes": item.notes,
            }
            for item in (lines or [])
        ],
    }


