@app.put("/api/sales/accounts/{account_id}/finance-customer")
async def link_sales_account_to_finance_customer(
    account_id: _salb_uuid.UUID,
    payload: SalesFinanceCustomerLinkRequest,
    db: AsyncSession = Depends(get_db),
):
    account = await db.get(_SalBSalesAccount, account_id)
    customer = await db.get(_SalBFinanceCustomer, payload.finance_customer_id)

    if account is None:
        raise HTTPException(status_code=404, detail="Sales account not found")

    if customer is None:
        raise HTTPException(status_code=404, detail="Finance customer not found")

    conflicting = (
        await db.execute(
            _salb_select(SalesFinanceCustomerLink).where(
                SalesFinanceCustomerLink.finance_customer_id == customer.id,
                SalesFinanceCustomerLink.sales_account_id != account.id,
            )
        )
    ).scalars().first()

    if conflicting:
        raise HTTPException(
            status_code=409,
            detail="Finance customer is already linked to another Sales account",
        )

    row = (
        await db.execute(
            _salb_select(SalesFinanceCustomerLink).where(
                SalesFinanceCustomerLink.sales_account_id == account.id
            )
        )
    ).scalars().first()

    if row is None:
        row = SalesFinanceCustomerLink(
            sales_account_id=account.id,
            finance_customer_id=customer.id,
            is_active=True,
        )
        db.add(row)
    else:
        row.finance_customer_id = customer.id
        row.is_active = True

    await write_audit_log(
        db,
        actor="user",
        action="sales.finance_customer_link.updated",
        details={
            "sales_account_id": str(account.id),
            "finance_customer_id": str(customer.id),
            "automatic_customer_creation": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return {
        "id": str(row.id),
        "sales_account_id": str(row.sales_account_id),
        "finance_customer_id": str(row.finance_customer_id),
        "automatic_customer_creation": False,
    }


@app.get("/api/sales/quotations")
async def list_sales_quotations(
    opportunity_id: _salb_uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _salb_select(SalesQuotation)

    if opportunity_id:
        query = query.where(
            SalesQuotation.opportunity_id == opportunity_id
        )

    rows = (
        await db.execute(
            query.order_by(SalesQuotation.created_at.desc())
        )
    ).scalars().all()

    output = []

    for row in rows:
        lines = (
            await db.execute(
                _salb_select(SalesQuotationLine)
                .where(SalesQuotationLine.quotation_id == row.id)
                .order_by(SalesQuotationLine.line_number.asc())
            )
        ).scalars().all()

        approval = (
            await db.get(Approval, row.approval_id)
            if row.approval_id
            else None
        )

        output.append(_salb_quote_payload(row, lines, approval))

    return output


@app.post("/api/sales/quotations")
async def create_sales_quotation(
    payload: SalesQuotationCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    opportunity = await db.get(
        _SalBSalesOpportunity,
        payload.opportunity_id,
    )

    if opportunity is None:
        raise HTTPException(status_code=404, detail="Sales opportunity not found")

    profile = await _salb_company_profile(db)

    vat_registered = bool(
        profile
        and profile.vat_status == "registered"
        and profile.vat_number
    )

    calc = _salb_quote_calculation(
        payload.lines,
        payload.discount_amount,
        payload.vat_rate_pct,
        vat_registered,
    )

    previous = (
        await db.execute(
            _salb_select(SalesQuotation.version).where(
                SalesQuotation.opportunity_id == opportunity.id
            )
        )
    ).scalars().all()

    version = max(previous) + 1 if previous else 1

    row = SalesQuotation(
        opportunity_id=opportunity.id,
        version=version,
        external_quote_number=(
            payload.external_quote_number.strip()
            if payload.external_quote_number
            and payload.external_quote_number.strip()
            else None
        ),
        status="draft",
        subtotal_ex_vat=calc["subtotal_ex_vat"],
        discount_amount=calc["discount_amount"],
        net_revenue_ex_vat=calc["net_revenue_ex_vat"],
        direct_cost=calc["direct_cost"],
        gross_profit=calc["gross_profit"],
        gross_margin_pct=calc["gross_margin_pct"],
        vat_rate_pct=calc["vat_rate_pct"],
        vat_amount=calc["vat_amount"],
        total_inc_vat=calc["total_inc_vat"],
        validity_date=payload.validity_date,
        payment_terms=(
            payload.payment_terms.strip()
            if payload.payment_terms
            and payload.payment_terms.strip()
            else None
        ),
        scope_summary=(
            payload.scope_summary.strip()
            if payload.scope_summary
            and payload.scope_summary.strip()
            else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        quotation_metadata={
            "source_policy": _SALB_SOURCE,
            "external_send_performed": False,
            "auto_invoice_created": False,
            "proposed_margin_floor_pct": 30,
            "proposed_margin_target_pct": 40,
            "policy_figures_binding": False,
        },
    )

    db.add(row)
    await db.flush()

    for item in calc["lines"]:
        db.add(
            SalesQuotationLine(
                quotation_id=row.id,
                **item,
            )
        )

    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="sales.quotation.created",
        details={
            "quotation_id": str(row.id),
            "opportunity_id": str(opportunity.id),
            "version": version,
            "net_revenue_ex_vat": str(row.net_revenue_ex_vat),
            "gross_margin_pct": str(row.gross_margin_pct),
            "vat_rate_pct": str(row.vat_rate_pct),
            "external_send_performed": False,
            "auto_invoice_created": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    lines = (
        await db.execute(
            _salb_select(SalesQuotationLine)
            .where(SalesQuotationLine.quotation_id == row.id)
            .order_by(SalesQuotationLine.line_number.asc())
        )
    ).scalars().all()

    return _salb_quote_payload(row, lines)


@app.post("/api/sales/quotations/{quotation_id}/request-approval")
async def request_sales_quotation_approval(
    quotation_id: _salb_uuid.UUID,
    payload: SalesPhase1BApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(SalesQuotation, quotation_id)

    if row is None:
        raise HTTPException(status_code=404, detail="Sales quotation not found")

    if row.status not in {"draft", "rejected"}:
        raise HTTPException(
            status_code=409,
            detail="Only draft/rejected quotations can request approval",
        )

    approval = Approval(
        agent_id=await _salb_sales_agent_id(db),
        title="Approve Sales Quotation",
        description=(
            "Commercial quotation approval before external use. "
            "This action does not send the quotation."
        ),
        action_type="sales_quotation_approval",
        risk_level="high",
        status="pending",
        action_payload={
            "quotation_id": str(row.id),
            "opportunity_id": str(row.opportunity_id),
            "net_revenue_ex_vat": str(row.net_revenue_ex_vat),
            "gross_profit": str(row.gross_profit),
            "gross_margin_pct": str(row.gross_margin_pct),
            "vat_rate_pct": str(row.vat_rate_pct),
            "margin_below_proposed_floor":
                float(row.gross_margin_pct or 0) < 30,
            "external_send": False,
            "automatic_invoice_creation": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _salb_quote_payload(row, approval=approval)


