@app.post("/api/sales/targets")
async def create_sales_target(
    payload: SalesTargetCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.year < 2000 or payload.year > 2200:
        raise HTTPException(status_code=400, detail="Invalid target year")

    if payload.start_date > payload.end_date:
        raise HTTPException(
            status_code=400,
            detail="Target start_date must be on/before end_date",
        )

    metric = payload.target_metric.strip().lower()

    if metric not in _SALB_TARGET_METRICS:
        raise HTTPException(status_code=400, detail="Invalid target metric")

    amount = _salb_money(payload.target_amount)

    if amount <= 0:
        raise HTTPException(
            status_code=400,
            detail="Target amount must be greater than zero",
        )

    coverage = None

    if payload.coverage_multiplier is not None:
        coverage = _salb_pct(
            payload.coverage_multiplier,
            "coverage multiplier",
        )

        if coverage <= 0:
            raise HTTPException(
                status_code=400,
                detail="Coverage multiplier must be greater than zero",
            )

    label = payload.period_label.strip()

    if not label:
        raise HTTPException(status_code=400, detail="Target period label is required")

    row = SalesTargetPlan(
        year=payload.year,
        period_label=label,
        start_date=payload.start_date,
        end_date=payload.end_date,
        owner_name=(
            payload.owner_name.strip()
            if payload.owner_name
            and payload.owner_name.strip()
            else None
        ),
        target_metric=metric,
        target_amount=amount,
        coverage_multiplier=coverage,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return {
        "id": str(row.id),
        "status": row.status,
        "note": "Draft only until explicit approval.",
    }


