@app.post("/api/sales/collection-milestones")
async def create_sales_collection_milestone(
    payload: SalesCollectionMilestoneCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    opportunity = await db.get(
        _SalBSalesOpportunity,
        payload.opportunity_id,
    )

    if opportunity is None:
        raise HTTPException(status_code=404, detail="Sales opportunity not found")

    quote = None

    if payload.quotation_id:
        quote = await db.get(SalesQuotation, payload.quotation_id)

        if quote is None or quote.opportunity_id != opportunity.id:
            raise HTTPException(
                status_code=409,
                detail="Quotation does not belong to this opportunity",
            )

    amount = _salb_money(payload.expected_amount_ex_vat)

    if amount <= 0:
        raise HTTPException(
            status_code=400,
            detail="Expected collection must be greater than zero",
        )

    if quote is not None:
        existing = (
            await db.execute(
                _salb_select(SalesCollectionMilestone).where(
                    SalesCollectionMilestone.quotation_id == quote.id
                )
            )
        ).scalars().all()

        planned_total = sum(
            (_salb_money(x.expected_amount_ex_vat) for x in existing),
            _SalBDecimal("0.00"),
        )

        if planned_total + amount > _salb_money(quote.net_revenue_ex_vat):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Planned collection milestones cannot exceed "
                    "quotation net revenue before VAT"
                ),
            )

    row = SalesCollectionMilestone(
        opportunity_id=opportunity.id,
        quotation_id=payload.quotation_id,
        due_date=payload.due_date,
        expected_amount_ex_vat=amount,
        verified_amount_ex_vat=0,
        status="planned",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return {
        "id": str(row.id),
        "status": row.status,
        "verified_amount_ex_vat": 0,
    }


@app.post("/api/sales/collection-milestones/{milestone_id}/allocate-finance-receipt")
async def allocate_finance_receipt_to_sales_collection(
    milestone_id: _salb_uuid.UUID,
    payload: SalesCollectionAllocateRequest,
    db: AsyncSession = Depends(get_db),
):
    milestone = await db.get(SalesCollectionMilestone, milestone_id)

    if milestone is None:
        raise HTTPException(
            status_code=404,
            detail="Sales collection milestone not found",
        )

    opportunity = await db.get(
        _SalBSalesOpportunity,
        milestone.opportunity_id,
    )

    account = await db.get(
        _SalBSalesAccount,
        opportunity.account_id,
    )

    link = (
        await db.execute(
            _salb_select(SalesFinanceCustomerLink).where(
                SalesFinanceCustomerLink.sales_account_id == account.id,
                SalesFinanceCustomerLink.is_active.is_(True),
            )
        )
    ).scalars().first()

    if link is None:
        raise HTTPException(
            status_code=409,
            detail=(
                "Sales account must be explicitly linked to "
                "a Finance customer before collection verification"
            ),
        )

    receipt = await db.get(
        _SalBFinanceInvoiceReceipt,
        payload.finance_receipt_id,
    )

    if receipt is None:
        raise HTTPException(status_code=404, detail="Finance receipt not found")

    if receipt.status != "applied":
        raise HTTPException(
            status_code=409,
            detail="Finance receipt must be applied before Sales verification",
        )

    already = (
        await db.execute(
            _salb_select(SalesCollectionAllocation).where(
                SalesCollectionAllocation.finance_receipt_id == receipt.id
            )
        )
    ).scalars().first()

    if already:
        raise HTTPException(
            status_code=409,
            detail="Finance receipt is already allocated to Sales",
        )

    invoice = await db.get(_SalBFinanceInvoice, receipt.invoice_id)

    if invoice is None:
        raise HTTPException(status_code=409, detail="Finance invoice not found")

    if invoice.customer_id != link.finance_customer_id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Finance receipt customer does not match "
                "the linked Sales account"
            ),
        )

    receipt_amount = _salb_money(receipt.amount)
    invoice_total = _salb_money(invoice.total_amount)
    invoice_ex_vat = _salb_money(invoice.subtotal)

    if invoice_total <= 0:
        raise HTTPException(
            status_code=409,
            detail="Finance invoice total must be positive",
        )

    eligible_ex_vat = (
        receipt_amount
        * invoice_ex_vat
        / invoice_total
    ).quantize(_SalBDecimal("0.01"))

    allocation = SalesCollectionAllocation(
        milestone_id=milestone.id,
        finance_receipt_id=receipt.id,
        finance_invoice_id=invoice.id,
        cash_amount_total=receipt_amount,
        eligible_amount_ex_vat=eligible_ex_vat,
    )

    db.add(allocation)
    await db.flush()

    allocations = (
        await db.execute(
            _salb_select(SalesCollectionAllocation).where(
                SalesCollectionAllocation.milestone_id == milestone.id
            )
        )
    ).scalars().all()

    verified = sum(
        (_salb_money(x.eligible_amount_ex_vat) for x in allocations),
        _SalBDecimal("0.00"),
    )

    milestone.verified_amount_ex_vat = verified

    expected = _salb_money(milestone.expected_amount_ex_vat)

    if verified >= expected:
        milestone.status = "collected"
    elif verified > 0:
        milestone.status = "partially_collected"
    else:
        milestone.status = "planned"

    await write_audit_log(
        db,
        actor="user",
        action="sales.collection.finance_receipt_allocated",
        details={
            "milestone_id": str(milestone.id),
            "finance_receipt_id": str(receipt.id),
            "finance_invoice_id": str(invoice.id),
            "cash_amount_total": str(receipt_amount),
            "eligible_amount_ex_vat": str(eligible_ex_vat),
            "automatic_collection_confirmation": False,
        },
    )

    await db.commit()
    await db.refresh(milestone)

    return {
        "milestone_id": str(milestone.id),
        "status": milestone.status,
        "verified_amount_ex_vat": float(milestone.verified_amount_ex_vat),
        "eligible_amount_ex_vat": float(eligible_ex_vat),
        "source_of_truth": "Finance applied invoice receipt",
    }


