@app.post("/api/sales/commission-preview")
async def sales_commission_preview(
    payload: SalesCommissionPreviewRequest,
    db: AsyncSession = Depends(get_db),
):
    opportunity = await db.get(
        _SalBSalesOpportunity,
        payload.opportunity_id,
    )

    if opportunity is None:
        raise HTTPException(status_code=404, detail="Sales opportunity not found")

    plan = await db.get(SalesCommissionPlan, payload.commission_plan_id)

    if plan is None:
        raise HTTPException(status_code=404, detail="Commission plan not found")

    if plan.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Only an approved commission plan can be used",
        )

    milestones = (
        await db.execute(
            _salb_select(SalesCollectionMilestone).where(
                SalesCollectionMilestone.opportunity_id == opportunity.id,
                SalesCollectionMilestone.verified_amount_ex_vat > 0,
            )
        )
    ).scalars().all()

    verified_collection = sum(
        (_salb_money(row.verified_amount_ex_vat) for row in milestones),
        _SalBDecimal("0.00"),
    )

    margin_pct = _SalBDecimal(
        str(opportunity.gross_margin_pct or 0)
    )

    eligible_collected_profit = (
        verified_collection
        * margin_pct
        / _SalBDecimal("100")
    ).quantize(_SalBDecimal("0.01"))

    contribution = _salb_pct(
        payload.contribution_factor,
        "contribution factor",
    )
    achievement = _salb_pct(
        payload.achievement_factor,
        "achievement factor",
    )
    margin_factor = _salb_pct(
        payload.margin_factor,
        "margin factor",
    )

    if contribution > 1:
        raise HTTPException(
            status_code=400,
            detail="Contribution factor cannot exceed 1.0",
        )

    clawback = _salb_money(payload.clawback_amount)
    rate = _SalBDecimal(str(plan.commission_rate_pct)) / _SalBDecimal("100")

    gross_commission = (
        eligible_collected_profit
        * rate
        * contribution
        * achievement
        * margin_factor
    ).quantize(_SalBDecimal("0.01"))

    net_commission = max(
        _SalBDecimal("0.00"),
        gross_commission - clawback,
    )

    return {
        "opportunity_id": str(opportunity.id),
        "commission_plan_id": str(plan.id),
        "verified_collection_ex_vat": float(verified_collection),
        "gross_margin_pct": float(margin_pct),
        "eligible_collected_profit": float(eligible_collected_profit),
        "commission_rate_pct": float(plan.commission_rate_pct),
        "contribution_factor": float(contribution),
        "achievement_factor": float(achievement),
        "margin_factor": float(margin_factor),
        "clawback_amount": float(clawback),
        "commission_preview": float(net_commission),
        "payable": False,
        "payment_created": False,
        "payroll_changed": False,
        "bank_transfer_created": False,
        "note": (
            "Preview only. Finance verification + HR eligibility + "
            "approved commission plan do not themselves create payment."
        ),
    }


