async def sales_phase1b_summary(
    db: AsyncSession = Depends(get_db),
):
    counts = {}

    for name, model in (
        ("quotations", SalesQuotation),
        ("targets", SalesTargetPlan),
        ("collection_milestones", SalesCollectionMilestone),
        ("collection_allocations", SalesCollectionAllocation),
        ("commission_plans", SalesCommissionPlan),
        ("finance_customer_links", SalesFinanceCustomerLink),
    ):
        counts[name] = int(
            await db.scalar(
                _salb_select(_salb_func.count()).select_from(model)
            )
            or 0
        )

    return {
        "counts": counts,
        "policy_reference": {
            "source": _SALB_SOURCE,
            "proposed_margin_floor_pct": 30,
            "proposed_margin_target_pct": 40,
            "proposed_commission_rate_pct": 10,
            "proposed_figures_binding": False,
        },
        "safety": {
            "automatic_external_communication": False,
            "automatic_customer_creation_in_finance": False,
            "automatic_invoice_creation": False,
            "automatic_collection_confirmation": False,
            "automatic_commission_payment": False,
            "automatic_payroll_change": False,
            "automatic_bank_transfer": False,
        },
    }

# ============================================================
# Sales & CRM - Phase 1C API
# Weekly pipeline hygiene, activities, follow-ups, aging and dashboards.
# No automatic stage movement, communication, invoicing, collection or payment.
# ============================================================
import uuid as _salc_uuid
from datetime import (
    date as _salc_date,
    datetime as _salc_datetime,
    timezone as _salc_timezone,
)

from pydantic import BaseModel as _SalCBaseModel
from sqlalchemy import (
    func as _salc_func,
    select as _salc_select,
)

from .models import (
    HRAttachment as _SalCHRAttachment,
    SalesAccount as _SalCSalesAccount,
    SalesActivity,
    SalesCollectionAllocation as _SalCSalesCollectionAllocation,
    SalesCollectionMilestone as _SalCSalesCollectionMilestone,
    SalesContact as _SalCSalesContact,
    SalesOpportunity as _SalCSalesOpportunity,
    SalesOpportunityStageHistory as _SalCSalesOpportunityStageHistory,
    SalesQuotation as _SalCSalesQuotation,
    SalesTargetPlan as _SalCSalesTargetPlan,
)

_SALC_ACTIVITY_TYPES = {
    "call",
    "email",
    "meeting",
    "discovery",
    "proposal",
    "negotiation",
    "procurement",
    "follow_up",
    "collection_follow_up",
    "note",
    "other",
}

_SALC_ACTIVITY_STATUSES = {
    "planned",
    "completed",
    "cancelled",
}


def _salc_activity_payload(row):
    return {
        "id": str(row.id),
        "account_id": str(row.account_id),
        "opportunity_id": (
            str(row.opportunity_id)
            if row.opportunity_id
            else None
        ),
        "contact_id": (
            str(row.contact_id)
            if row.contact_id
            else None
        ),
        "collection_milestone_id": (
            str(row.collection_milestone_id)
            if row.collection_milestone_id
            else None
        ),
        "activity_type": row.activity_type,
        "subject": row.subject,
        "summary": row.summary,
        "outcome": row.outcome,
        "activity_date": row.activity_date,
        "next_follow_up_date": row.next_follow_up_date,
        "status": row.status,
        "created_by": row.created_by,
        "external_communication_sent":
            row.external_communication_sent,
        "completed_at": row.completed_at,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


class SalesActivityCreateRequest(_SalCBaseModel):
    account_id: _salc_uuid.UUID
    opportunity_id: _salc_uuid.UUID | None = None
    contact_id: _salc_uuid.UUID | None = None
    collection_milestone_id: _salc_uuid.UUID | None = None
    activity_type: str
    subject: str
    summary: str | None = None
    outcome: str | None = None
    activity_date: _salc_date
    next_follow_up_date: _salc_date | None = None
    status: str = "planned"
    created_by: str = "user"


class SalesActivityCompleteRequest(_SalCBaseModel):
    outcome: str | None = None
    next_follow_up_date: _salc_date | None = None
    completed_by: str = "user"


async def _salc_validate_activity_links(
    db,
    account_id,
    opportunity_id,
    contact_id,
    milestone_id,
):
    account = await db.get(
        _SalCSalesAccount,
        account_id,
    )

    if account is None:
        raise HTTPException(
            status_code=404,
            detail="Sales account not found",
        )

    opportunity = None

    if opportunity_id:
        opportunity = await db.get(
            _SalCSalesOpportunity,
            opportunity_id,
        )

        if opportunity is None:
            raise HTTPException(
                status_code=404,
                detail="Sales opportunity not found",
            )

        if opportunity.account_id != account.id:
            raise HTTPException(
                status_code=409,
                detail="Opportunity does not belong to the Sales account",
            )

    if contact_id:
        contact = await db.get(
            _SalCSalesContact,
            contact_id,
        )

        if contact is None:
            raise HTTPException(
                status_code=404,
                detail="Sales contact not found",
            )

        if contact.account_id != account.id:
            raise HTTPException(
                status_code=409,
                detail="Contact does not belong to the Sales account",
            )

    if milestone_id:
        milestone = await db.get(
            _SalCSalesCollectionMilestone,
            milestone_id,
        )

        if milestone is None:
            raise HTTPException(
                status_code=404,
                detail="Sales collection milestone not found",
            )

        milestone_opportunity = await db.get(
            _SalCSalesOpportunity,
            milestone.opportunity_id,
        )

        if (
            milestone_opportunity is None
            or milestone_opportunity.account_id != account.id
        ):
            raise HTTPException(
                status_code=409,
                detail="Collection milestone does not belong to the Sales account",
            )

        if (
            opportunity is not None
            and milestone.opportunity_id != opportunity.id
        ):
            raise HTTPException(
                status_code=409,
                detail="Collection milestone does not belong to the opportunity",
            )


@app.get("/api/sales/activities")
async def list_sales_activities(
    account_id: _salc_uuid.UUID | None = None,
    opportunity_id: _salc_uuid.UUID | None = None,
    status: str | None = None,
    limit: int = 300,
    db: AsyncSession = Depends(get_db),
):
    limit = max(1, min(int(limit), 500))
    query = _salc_select(SalesActivity)

    if account_id:
        query = query.where(
            SalesActivity.account_id == account_id
        )

    if opportunity_id:
        query = query.where(
            SalesActivity.opportunity_id == opportunity_id
        )

    if status:
        normalized = status.strip().lower()

        if normalized not in _SALC_ACTIVITY_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid Sales activity status",
            )

        query = query.where(
            SalesActivity.status == normalized
        )

    rows = (
        await db.execute(
            query.order_by(
                SalesActivity.activity_date.desc(),
                SalesActivity.created_at.desc(),
            ).limit(limit)
        )
    ).scalars().all()

    return [
        _salc_activity_payload(row)
        for row in rows
    ]


@app.post("/api/sales/activities")
async def create_sales_activity(
    payload: SalesActivityCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    activity_type = payload.activity_type.strip().lower()
    status = payload.status.strip().lower()
    subject = payload.subject.strip()

    if activity_type not in _SALC_ACTIVITY_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid Sales activity type",
        )

    if status not in _SALC_ACTIVITY_STATUSES:
        raise HTTPException(
            status_code=400,
            detail="Invalid Sales activity status",
        )

    if not subject:
        raise HTTPException(
            status_code=400,
            detail="Activity subject is required",
        )

    await _salc_validate_activity_links(
        db,
        payload.account_id,
        payload.opportunity_id,
        payload.contact_id,
        payload.collection_milestone_id,
    )

    row = SalesActivity(
        account_id=payload.account_id,
        opportunity_id=payload.opportunity_id,
        contact_id=payload.contact_id,
        collection_milestone_id=payload.collection_milestone_id,
        activity_type=activity_type,
        subject=subject,
        summary=(
            payload.summary.strip()
            if payload.summary
            and payload.summary.strip()
            else None
        ),
        outcome=(
            payload.outcome.strip()
            if payload.outcome
            and payload.outcome.strip()
            else None
        ),
        activity_date=payload.activity_date,
        next_follow_up_date=payload.next_follow_up_date,
        status=status,
        created_by=(
            payload.created_by.strip()
            or "user"
        ),
        external_communication_sent=False,
        completed_at=(
            _salc_datetime.now(_salc_timezone.utc)
            if status == "completed"
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor=row.created_by,
        action="sales.activity.created",
        details={
            "activity_id": str(row.id),
            "account_id": str(row.account_id),
            "opportunity_id": (
                str(row.opportunity_id)
                if row.opportunity_id
                else None
            ),
            "activity_type": row.activity_type,
            "status": row.status,
            "external_communication_sent": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _salc_activity_payload(row)


@app.post("/api/sales/activities/{activity_id}/complete")
async def complete_sales_activity(
    activity_id: _salc_uuid.UUID,
    payload: SalesActivityCompleteRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        SalesActivity,
        activity_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Sales activity not found",
        )

    if row.status == "cancelled":
        raise HTTPException(
            status_code=409,
            detail="Cancelled Sales activity cannot be completed",
        )

    row.status = "completed"
    row.completed_at = _salc_datetime.now(
        _salc_timezone.utc
    )

    if payload.outcome is not None:
        row.outcome = (
            payload.outcome.strip()
            or None
        )

    if payload.next_follow_up_date is not None:
        row.next_follow_up_date = (
            payload.next_follow_up_date
        )

    await write_audit_log(
        db,
        actor=(
            payload.completed_by.strip()
            or "user"
        ),
        action="sales.activity.completed",
        details={
            "activity_id": str(row.id),
            "next_follow_up_date": (
                row.next_follow_up_date.isoformat()
                if row.next_follow_up_date
                else None
            ),
            "automatic_follow_up_created": False,
            "external_communication_sent": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _salc_activity_payload(row)


@app.get("/api/sales/follow-ups")
async def sales_follow_ups(
    through_date: _salc_date | None = None,
    db: AsyncSession = Depends(get_db),
):
    through = through_date or _salc_date.today()

    activities = (
        await db.execute(
            _salc_select(SalesActivity)
            .where(
                SalesActivity.status == "planned",
                SalesActivity.activity_date <= through,
            )
            .order_by(
                SalesActivity.activity_date.asc()
            )
        )
    ).scalars().all()

    completed_followups = (
        await db.execute(
            _salc_select(SalesActivity)
            .where(
                SalesActivity.status == "completed",
                SalesActivity.next_follow_up_date.is_not(None),
                SalesActivity.next_follow_up_date <= through,
            )
            .order_by(
                SalesActivity.next_follow_up_date.asc()
            )
        )
    ).scalars().all()

    opportunities = (
        await db.execute(
            _salc_select(_SalCSalesOpportunity)
            .where(
                _SalCSalesOpportunity.status == "open",
                _SalCSalesOpportunity.next_step_date.is_not(None),
                _SalCSalesOpportunity.next_step_date <= through,
            )
            .order_by(
                _SalCSalesOpportunity.next_step_date.asc()
            )
        )
    ).scalars().all()

    items = []

    for row in activities:
        items.append({
            "kind": "planned_activity",
            "source_id": str(row.id),
            "account_id": str(row.account_id),
            "opportunity_id": (
                str(row.opportunity_id)
                if row.opportunity_id
                else None
            ),
            "due_date": row.activity_date,
            "title": row.subject,
            "status": "due",
        })

    for row in completed_followups:
        items.append({
            "kind": "activity_follow_up",
            "source_id": str(row.id),
            "account_id": str(row.account_id),
            "opportunity_id": (
                str(row.opportunity_id)
                if row.opportunity_id
                else None
            ),
            "due_date": row.next_follow_up_date,
            "title": (
                "Follow-up: "
                + row.subject
            ),
            "status": "due",
        })

    for row in opportunities:
        items.append({
            "kind": "opportunity_next_step",
            "source_id": str(row.id),
            "account_id": str(row.account_id),
            "opportunity_id": str(row.id),
            "due_date": row.next_step_date,
            "title": row.next_step or "Opportunity next step",
            "status": "due",
        })

    items.sort(
        key=lambda item: (
            item["due_date"],
            item["kind"],
        )
    )

    return {
        "through_date": through,
        "total": len(items),
        "items": items,
        "safety": {
            "automatic_external_communication": False,
            "automatic_activity_creation": False,
            "automatic_stage_change": False,
        },
    }


async def _salc_pipeline_aging_rows(db):
    today = _salc_date.today()

    opportunities = (
        await db.execute(
            _salc_select(_SalCSalesOpportunity)
            .where(
                _SalCSalesOpportunity.status == "open"
            )
            .order_by(
                _SalCSalesOpportunity.updated_at.asc()
            )
        )
    ).scalars().all()

    output = []

    for row in opportunities:
        latest_activity = await db.scalar(
            _salc_select(
                _salc_func.max(
                    SalesActivity.activity_date
                )
            ).where(
                SalesActivity.opportunity_id == row.id
            )
        )

        latest_stage_at = await db.scalar(
            _salc_select(
                _salc_func.max(
                    _SalCSalesOpportunityStageHistory.created_at
                )
            ).where(
                _SalCSalesOpportunityStageHistory.opportunity_id == row.id
            )
        )

        touch_dates = [
            row.updated_at.date()
            if row.updated_at
            else row.created_at.date(),
        ]

        if latest_activity:
            touch_dates.append(latest_activity)

        if latest_stage_at:
            touch_dates.append(
                latest_stage_at.date()
            )

        last_touch = max(touch_dates)
        days_since_touch = max(
            0,
            (today - last_touch).days,
        )

        no_next_step = not bool(
            row.next_step
            and row.next_step.strip()
        )

        overdue_next_step = bool(
            row.next_step_date
            and row.next_step_date < today
        )

        stale_weekly_update = (
            days_since_touch >= 7
        )

        if days_since_touch >= 21:
            severity = "critical"
        elif days_since_touch >= 14:
            severity = "high"
        elif (
            stale_weekly_update
            or no_next_step
            or overdue_next_step
        ):
            severity = "warning"
        else:
            severity = "ok"

        output.append({
            "opportunity_id": str(row.id),
            "opportunity_code": row.code,
            "name": row.name,
            "account_id": str(row.account_id),
            "owner_name": row.owner_name,
            "stage": row.stage,
            "probability_pct": row.probability_pct,
            "last_touch_date": last_touch,
            "days_since_touch": days_since_touch,
            "next_step": row.next_step,
            "next_step_date": row.next_step_date,
            "no_next_step": no_next_step,
            "overdue_next_step": overdue_next_step,
            "stale_weekly_update": stale_weekly_update,
            "severity": severity,
            "automatic_stage_change": False,
        })

    return output


@app.get("/api/sales/pipeline-aging")
async def sales_pipeline_aging(
    db: AsyncSession = Depends(get_db),
):
    rows = await _salc_pipeline_aging_rows(db)

    return {
        "total_open": len(rows),
        "needs_review": sum(
            1
            for row in rows
            if row["severity"] != "ok"
        ),
        "rows": rows,
        "policy_reference": (
            "Pipeline values, dates, next steps and risks "
            "are expected to be reviewed weekly."
        ),
        "safety": {
            "automatic_stage_downgrade": False,
            "automatic_close": False,
        },
    }


@app.get("/api/sales/account-manager-workload")
async def sales_account_manager_workload(
    db: AsyncSession = Depends(get_db),
):
    today = _salc_date.today()

    opportunities = (
        await db.execute(
            _salc_select(_SalCSalesOpportunity)
            .where(
                _SalCSalesOpportunity.status == "open"
            )
        )
    ).scalars().all()

    workload = {}

    for row in opportunities:
        owner = (
            row.owner_name.strip()
            if row.owner_name
            and row.owner_name.strip()
            else "Unassigned"
        )

        bucket = workload.setdefault(
            owner,
            {
                "owner_name": owner,
                "open_opportunities": 0,
                "qualified_opportunities": 0,
                "unweighted_pipeline_ex_vat": 0.0,
                "weighted_pipeline_ex_vat": 0.0,
                "gross_profit_pipeline": 0.0,
                "no_next_step": 0,
                "overdue_next_step": 0,
            },
        )

        bucket["open_opportunities"] += 1

        if 2 <= row.stage <= 7:
            bucket["qualified_opportunities"] += 1

            period_value = float(
                row.period_value_ex_vat or 0
            )

            bucket[
                "unweighted_pipeline_ex_vat"
            ] += period_value

            bucket[
                "weighted_pipeline_ex_vat"
            ] += (
                period_value
                * float(
                    row.probability_pct or 0
                )
                / 100
            )

            bucket[
                "gross_profit_pipeline"
            ] += float(
                row.gross_profit or 0
            )

        if not (
            row.next_step
            and row.next_step.strip()
        ):
            bucket["no_next_step"] += 1

        if (
            row.next_step_date
            and row.next_step_date < today
        ):
            bucket["overdue_next_step"] += 1

    rows = list(workload.values())
    rows.sort(
        key=lambda row: (
            -row["open_opportunities"],
            row["owner_name"],
        )
    )

    return {
        "total_owners": len(rows),
        "rows": rows,
        "note": (
            "Visibility only. No automatic reassignment "
            "or quota allocation is performed."
        ),
    }


@app.get("/api/sales/forecast-dashboard")
async def sales_forecast_dashboard(
    year: int | None = None,
    db: AsyncSession = Depends(get_db),
):
    selected_year = (
        year
        if year is not None
        else _salc_date.today().year
    )

    targets = (
        await db.execute(
            _salc_select(_SalCSalesTargetPlan)
            .where(
                _SalCSalesTargetPlan.year == selected_year,
                _SalCSalesTargetPlan.status == "approved",
            )
            .order_by(
                _SalCSalesTargetPlan.start_date.asc()
            )
        )
    ).scalars().all()

    opportunities = (
        await db.execute(
            _salc_select(_SalCSalesOpportunity)
        )
    ).scalars().all()

    won_stage_rows = (
        await db.execute(
            _salc_select(
                _SalCSalesOpportunityStageHistory
            ).where(
                _SalCSalesOpportunityStageHistory.to_stage == 8
            )
        )
    ).scalars().all()

    won_date_by_opportunity = {}

    for row in won_stage_rows:
        current = won_date_by_opportunity.get(
            row.opportunity_id
        )

        if (
            current is None
            or row.created_at < current
        ):
            won_date_by_opportunity[
                row.opportunity_id
            ] = row.created_at

    allocations = (
        await db.execute(
            _salc_select(
                _SalCSalesCollectionAllocation
            )
        )
    ).scalars().all()

    milestones = {
        row.id: row
        for row in (
            await db.execute(
                _salc_select(
                    _SalCSalesCollectionMilestone
                )
            )
        ).scalars().all()
    }

    opportunity_map = {
        row.id: row
        for row in opportunities
    }

    rows = []

    for target in targets:
        metric = target.target_metric
        target_amount = float(
            target.target_amount or 0
        )
        realized = 0.0
        qualified_pipeline = 0.0
        weighted_pipeline = 0.0

        owner_filter = (
            target.owner_name.strip()
            if target.owner_name
            and target.owner_name.strip()
            else None
        )

        for opportunity in opportunities:
            if (
                owner_filter
                and (
                    opportunity.owner_name
                    or ""
                ).strip()
                != owner_filter
            ):
                continue

            won_at = won_date_by_opportunity.get(
                opportunity.id
            )

            if won_at:
                won_date = won_at.date()

                if (
                    target.start_date
                    <= won_date
                    <= target.end_date
                ):
                    if metric == "gross_profit":
                        realized += float(
                            opportunity.gross_profit
                            or 0
                        )
                    elif metric == "net_revenue":
                        realized += float(
                            opportunity.net_revenue_ex_vat
                            or 0
                        )

            if (
                opportunity.status == "open"
                and 2 <= opportunity.stage <= 7
                and opportunity.expected_close_date
                and target.start_date
                <= opportunity.expected_close_date
                <= target.end_date
            ):
                if metric == "gross_profit":
                    metric_value = float(
                        opportunity.gross_profit or 0
                    )
                elif metric == "net_revenue":
                    metric_value = float(
                        opportunity.net_revenue_ex_vat
                        or 0
                    )
                else:
                    metric_value = 0.0

                qualified_pipeline += metric_value
                weighted_pipeline += (
                    metric_value
                    * float(
                        opportunity.probability_pct
                        or 0
                    )
                    / 100
                )

        if metric == "collection":
            for allocation in allocations:
                verified_date = (
                    allocation.verified_at.date()
                )

                if not (
                    target.start_date
                    <= verified_date
                    <= target.end_date
                ):
                    continue

                milestone = milestones.get(
                    allocation.milestone_id
                )

                if milestone is None:
                    continue

                opportunity = opportunity_map.get(
                    milestone.opportunity_id
                )

                if opportunity is None:
                    continue

                if (
                    owner_filter
                    and (
                        opportunity.owner_name
                        or ""
                    ).strip()
                    != owner_filter
                ):
                    continue

                realized += float(
                    allocation.eligible_amount_ex_vat
                    or 0
                )

        remaining = max(
            0.0,
            target_amount - realized,
        )

        coverage = (
            qualified_pipeline / remaining
            if remaining > 0
            and metric in {
                "gross_profit",
                "net_revenue",
            }
            else None
        )

        rows.append({
            "target_id": str(target.id),
            "period_label": target.period_label,
            "owner_name": target.owner_name,
            "metric": metric,
            "target_amount": target_amount,
            "realized_amount": round(realized, 2),
            "remaining_amount": round(remaining, 2),
            "qualified_pipeline": round(
                qualified_pipeline,
                2,
            ),
            "weighted_pipeline": round(
                weighted_pipeline,
                2,
            ),
            "coverage_ratio": (
                round(coverage, 4)
                if coverage is not None
                else None
            ),
            "approved_coverage_multiplier": (
                float(target.coverage_multiplier)
                if target.coverage_multiplier
                is not None
                else None
            ),
        })

    return {
        "year": selected_year,
        "targets": rows,
        "policy_reference": {
            "stable_data_coverage_suggestion": 3,
            "startup_or_low_win_rate_suggestion": 4,
            "binding": False,
        },
        "note": (
            "Only approved targets are shown. "
            "Coverage suggestions are draft-policy references "
            "and are not auto-enforced."
        ),
    }


@app.get("/api/sales/alerts")
async def sales_alerts(
    db: AsyncSession = Depends(get_db),
):
    today = _salc_date.today()
    alerts = []

    aging = await _salc_pipeline_aging_rows(db)

    for row in aging:
        if row["severity"] == "ok":
            continue

        alerts.append({
            "type": "pipeline_hygiene",
            "severity": row["severity"],
            "entity_type": "opportunity",
            "entity_id": row["opportunity_id"],
            "title": row["name"],
            "message": (
                "Pipeline opportunity needs review: "
                f"{row['days_since_touch']} days since touch; "
                f"no_next_step={row['no_next_step']}; "
                f"overdue_next_step={row['overdue_next_step']}."
            ),
            "automatic_action": False,
        })

    milestones = (
        await db.execute(
            _salc_select(
                _SalCSalesCollectionMilestone
            ).where(
                _SalCSalesCollectionMilestone.due_date < today,
                _SalCSalesCollectionMilestone.status
                != "collected",
            )
        )
    ).scalars().all()

    for row in milestones:
        outstanding = max(
            0.0,
            float(
                row.expected_amount_ex_vat
                or 0
            )
            - float(
                row.verified_amount_ex_vat
                or 0
            ),
        )

        alerts.append({
            "type": "collection_overdue",
            "severity": "high",
            "entity_type": "collection_milestone",
            "entity_id": str(row.id),
            "title": "Overdue collection milestone",
            "message": (
                f"Due {row.due_date}; "
                f"outstanding before VAT={outstanding:.2f} SAR."
            ),
            "automatic_action": False,
        })

    quotations = (
        await db.execute(
            _salc_select(
                _SalCSalesQuotation
            ).where(
                _SalCSalesQuotation.validity_date.is_not(None),
                _SalCSalesQuotation.validity_date < today,
                _SalCSalesQuotation.status.in_(
                    [
                        "draft",
                        "pending_approval",
                        "approved",
                    ]
                ),
            )
        )
    ).scalars().all()

    for row in quotations:
        alerts.append({
            "type": "quotation_expired",
            "severity": "warning",
            "entity_type": "quotation",
            "entity_id": str(row.id),
            "title": "Quotation validity expired",
            "message": (
                f"Quotation v{row.version} validity date "
                f"was {row.validity_date}."
            ),
            "automatic_action": False,
        })

    planned = (
        await db.execute(
            _salc_select(SalesActivity).where(
                SalesActivity.status == "planned",
                SalesActivity.activity_date < today,
            )
        )
    ).scalars().all()

    for row in planned:
        alerts.append({
            "type": "activity_overdue",
            "severity": "warning",
            "entity_type": "sales_activity",
            "entity_id": str(row.id),
            "title": row.subject,
            "message": (
                f"Planned activity date was {row.activity_date}."
            ),
            "automatic_action": False,
        })

    severity_rank = {
        "critical": 0,
        "high": 1,
        "warning": 2,
        "info": 3,
    }

    alerts.sort(
        key=lambda row: (
            severity_rank.get(
                row["severity"],
                9,
            ),
            row["type"],
        )
    )

    return {
        "total": len(alerts),
        "alerts": alerts,
        "safety": {
            "automatic_external_communication": False,
            "automatic_stage_change": False,
            "automatic_collection_action": False,
        },
    }


