@app.post("/api/marketing/content/{content_id}/status")
async def update_marketing_content_status(
    content_id: _mkt_uuid.UUID,
    payload: MarketingContentStatusRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        MarketingContentItem,
        content_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing content item not found",
        )

    target = payload.status.strip().lower()

    if target not in _MKT_CONTENT_STATUSES:
        raise HTTPException(
            status_code=400,
            detail="Invalid marketing content status",
        )

    external_reference = (
        payload.external_reference.strip()
        if payload.external_reference
        and payload.external_reference.strip()
        else None
    )

    if target == "published" and not external_reference:
        raise HTTPException(
            status_code=409,
            detail=(
                "Published status requires an external "
                "reference proving publication happened "
                "outside this system"
            ),
        )

    old_status = row.status
    row.status = target

    if external_reference:
        row.external_reference = external_reference

    await write_audit_log(
        db,
        actor=payload.actor.strip() or "user",
        action="marketing.content.status_changed",
        details={
            "content_id": str(row.id),
            "from_status": old_status,
            "to_status": target,
            "system_published_externally": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _mkt_content_payload(row)


