@app.post("/api/marketing/attributions")
async def create_marketing_attribution(
    payload: MarketingLeadAttributionCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    lead = await db.get(
        _MktSalesLead,
        payload.lead_id,
    )

    if lead is None:
        raise HTTPException(
            status_code=404,
            detail="Sales Lead not found",
        )

    if payload.campaign_id:
        campaign = await db.get(
            MarketingCampaign,
            payload.campaign_id,
        )
        if campaign is None:
            raise HTTPException(
                status_code=404,
                detail="Marketing campaign not found",
            )

    touch_type = payload.touch_type.strip().lower()

    if touch_type not in _MKT_TOUCH_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid marketing attribution touch type",
        )

    channel = payload.channel.strip()
    source = payload.source.strip()

    if not channel or not source:
        raise HTTPException(
            status_code=400,
            detail="Attribution channel and source are required",
        )

    existing = (
        await db.execute(
            _mkt_select(
                MarketingLeadAttribution
            ).where(
                MarketingLeadAttribution.lead_id
                == payload.lead_id,
                MarketingLeadAttribution.campaign_id
                == payload.campaign_id,
                MarketingLeadAttribution.touch_type
                == touch_type,
                MarketingLeadAttribution.source
                == source,
            )
        )
    ).scalars().first()

    if existing is not None:
        raise HTTPException(
            status_code=409,
            detail="Duplicate marketing attribution touch",
        )

    if payload.is_primary:
        primary_rows = (
            await db.execute(
                _mkt_select(
                    MarketingLeadAttribution
                ).where(
                    MarketingLeadAttribution.lead_id
                    == payload.lead_id,
                    MarketingLeadAttribution.is_primary.is_(True),
                )
            )
        ).scalars().all()

        for item in primary_rows:
            item.is_primary = False

    row = MarketingLeadAttribution(
        lead_id=payload.lead_id,
        campaign_id=payload.campaign_id,
        touch_type=touch_type,
        channel=channel,
        source=source,
        is_primary=payload.is_primary,
        utm_source=(
            payload.utm_source.strip()
            if payload.utm_source
            and payload.utm_source.strip()
            else None
        ),
        utm_medium=(
            payload.utm_medium.strip()
            if payload.utm_medium
            and payload.utm_medium.strip()
            else None
        ),
        utm_campaign=(
            payload.utm_campaign.strip()
            if payload.utm_campaign
            and payload.utm_campaign.strip()
            else None
        ),
        utm_content=(
            payload.utm_content.strip()
            if payload.utm_content
            and payload.utm_content.strip()
            else None
        ),
        utm_term=(
            payload.utm_term.strip()
            if payload.utm_term
            and payload.utm_term.strip()
            else None
        ),
        landing_page=(
            payload.landing_page.strip()
            if payload.landing_page
            and payload.landing_page.strip()
            else None
        ),
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="marketing.lead_attribution.created",
        details={
            "attribution_id": str(row.id),
            "lead_id": str(row.lead_id),
            "sales_lead_created": False,
            "opportunity_created": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _mkt_attribution_payload(row)


@app.get("/api/marketing/summary")
async def marketing_summary(
    db: AsyncSession = Depends(get_db),
):
    campaigns = (
        await db.execute(
            _mkt_select(MarketingCampaign)
        )
    ).scalars().all()

    content = (
        await db.execute(
            _mkt_select(MarketingContentItem)
        )
    ).scalars().all()

    attributions = (
        await db.execute(
            _mkt_select(MarketingLeadAttribution)
        )
    ).scalars().all()

    leads = (
        await db.execute(
            _mkt_select(_MktSalesLead)
        )
    ).scalars().all()

    lead_map = {
        row.id: row
        for row in leads
    }

    campaign_metrics = []

    for campaign in campaigns:
        linked = [
            item
            for item in attributions
            if item.campaign_id == campaign.id
        ]

        linked_leads = [
            lead_map[item.lead_id]
            for item in linked
            if item.lead_id in lead_map
        ]

        campaign_metrics.append({
            "campaign_id": str(campaign.id),
            "campaign_code": campaign.code,
            "name": campaign.name,
            "status": campaign.status,
            "planned_budget": float(
                _mkt_money(campaign.planned_budget)
            ),
            "attribution_touches": len(linked),
            "unique_leads": len({
                row.id for row in linked_leads
            }),
            "qualified_leads": len({
                row.id
                for row in linked_leads
                if row.status == "qualified"
            }),
            "converted_leads": len({
                row.id
                for row in linked_leads
                if row.status == "converted"
            }),
        })

    return {
        "campaigns": {
            "total": len(campaigns),
            "draft": sum(
                1 for row in campaigns
                if row.status == "draft"
            ),
            "active": sum(
                1 for row in campaigns
                if row.status == "active"
            ),
            "planned_budget": float(
                sum(
                    (
                        _mkt_money(row.planned_budget)
                        for row in campaigns
                    ),
                    _MktDecimal("0.00"),
                )
            ),
        },
        "content": {
            "total": len(content),
            "draft": sum(
                1 for row in content
                if row.status == "draft"
            ),
            "scheduled": sum(
                1 for row in content
                if row.status == "scheduled"
            ),
            "published": sum(
                1 for row in content
                if row.status == "published"
            ),
        },
        "attribution": {
            "touches": len(attributions),
            "unique_leads": len({
                row.lead_id
                for row in attributions
            }),
            "primary_touches": sum(
                1 for row in attributions
                if row.is_primary
            ),
        },
        "campaign_metrics": campaign_metrics,
        "safety": {
            "automatic_external_publication": False,
            "automatic_external_communication": False,
            "automatic_sales_lead_creation": False,
            "automatic_opportunity_creation": False,
            "automatic_finance_posting": False,
            "automatic_budget_spend": False,
            "automatic_bank_transfer": False,
        },
    }

# ============================================================
# Marketing - Phase 1B API
# Approval governance and evidence-based performance snapshots.
# Approval does not execute external publication or spend.
# ============================================================
import uuid as _mktb_uuid
from datetime import date as _mktb_date

from pydantic import BaseModel as _MktBBaseModel
from sqlalchemy import select as _mktb_select

from .models import (
    MarketingApprovalBinding,
    MarketingCampaign as _MktBCampaign,
    MarketingContentItem as _MktBContent,
    MarketingLeadAttribution as _MktBAttribution,
    MarketingPerformanceSnapshot,
    SalesLead as _MktBSalesLead,
)


_MKTB_CAMPAIGN_PURPOSE = "campaign_activation"
_MKTB_CONTENT_PURPOSE = "content_authorization"


async def _mktb_marketing_agent_id(db):
    agent = (
        await db.execute(
            _mktb_select(Agent).where(
                Agent.slug == "marketing"
            )
        )
    ).scalars().first()

    return agent.id if agent else None


async def _mktb_binding(
    db,
    *,
    entity_type,
    entity_id,
    purpose,
):
    return (
        await db.execute(
            _mktb_select(
                MarketingApprovalBinding
            ).where(
                MarketingApprovalBinding.entity_type
                == entity_type,
                MarketingApprovalBinding.entity_id
                == entity_id,
                MarketingApprovalBinding.purpose
                == purpose,
            )
        )
    ).scalars().first()


def _mktb_binding_payload(binding, approval=None):
    return {
        "id": str(binding.id),
        "entity_type": binding.entity_type,
        "entity_id": str(binding.entity_id),
        "purpose": binding.purpose,
        "approval_id": str(binding.approval_id),
        "approval_status": (
            approval.status
            if approval
            else None
        ),
        "created_at": binding.created_at,
        "updated_at": binding.updated_at,
    }


def _mktb_snapshot_payload(row):
    ctr = (
        (row.clicks / row.impressions * 100)
        if row.impressions
        else 0.0
    )

    engagement_rate = (
        (row.engagements / row.impressions * 100)
        if row.impressions
        else 0.0
    )

    return {
        "id": str(row.id),
        "campaign_id": str(row.campaign_id),
        "snapshot_date": row.snapshot_date,
        "impressions": row.impressions,
        "clicks": row.clicks,
        "engagements": row.engagements,
        "website_sessions": row.website_sessions,
        "inquiries": row.inquiries,
        "ctr_pct": round(ctr, 4),
        "engagement_rate_pct": round(
            engagement_rate,
            4,
        ),
        "source_reference": row.source_reference,
        "notes": row.notes,
        "created_at": row.created_at,
    }


class MarketingApprovalRequest(_MktBBaseModel):
    requested_by: str = "user"
    notes: str | None = None


class MarketingPerformanceSnapshotCreateRequest(_MktBBaseModel):
    campaign_id: _mktb_uuid.UUID
    snapshot_date: _mktb_date
    impressions: int = 0
    clicks: int = 0
    engagements: int = 0
    website_sessions: int = 0
    inquiries: int = 0
    source_reference: str
    notes: str | None = None


@app.get("/api/marketing/approval-bindings")
async def list_marketing_approval_bindings(
    entity_type: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _mktb_select(
        MarketingApprovalBinding
    )

    if entity_type:
        query = query.where(
            MarketingApprovalBinding.entity_type
            == entity_type.strip().lower()
        )

    rows = (
        await db.execute(
            query.order_by(
                MarketingApprovalBinding.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = await db.get(
            Approval,
            row.approval_id,
        )
        output.append(
            _mktb_binding_payload(
                row,
                approval,
            )
        )

    return output


@app.post(
    "/api/marketing/campaigns/{campaign_id}/request-approval"
)
async def request_marketing_campaign_approval(
    campaign_id: _mktb_uuid.UUID,
    payload: MarketingApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    campaign = await db.get(
        _MktBCampaign,
        campaign_id,
    )

    if campaign is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing campaign not found",
        )

    if campaign.status in {
        "active",
        "completed",
        "cancelled",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Campaign approval can only be requested "
                "before activation"
            ),
        )

    existing = await _mktb_binding(
        db,
        entity_type="campaign",
        entity_id=campaign.id,
        purpose=_MKTB_CAMPAIGN_PURPOSE,
    )

    if existing:
        current = await db.get(
            Approval,
            existing.approval_id,
        )
        if current and current.status == "pending":
            return _mktb_binding_payload(
                existing,
                current,
            )

    approval = Approval(
        agent_id=await _mktb_marketing_agent_id(db),
        title="Approve Marketing Campaign Activation",
        description=(
            "Approve internal campaign activation. "
            "Approval does not publish content, commit spend "
            "or execute an external platform action."
        ),
        action_type="marketing_campaign_activation",
        risk_level=(
            "high"
            if float(campaign.planned_budget or 0) > 0
            else "medium"
        ),
        status="pending",
        action_payload={
            "campaign_id": str(campaign.id),
            "campaign_code": campaign.code,
            "campaign_name": campaign.name,
            "channel": campaign.channel,
            "planned_budget": str(
                campaign.planned_budget or 0
            ),
            "automatic_spend": False,
            "external_action": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    if existing:
        existing.approval_id = approval.id
        binding = existing
    else:
        binding = MarketingApprovalBinding(
            entity_type="campaign",
            entity_id=campaign.id,
            purpose=_MKTB_CAMPAIGN_PURPOSE,
            approval_id=approval.id,
        )
        db.add(binding)

    campaign.status = "planned"

    await write_audit_log(
        db,
        actor=payload.requested_by.strip() or "user",
        action="marketing.campaign.approval_requested",
        details={
            "campaign_id": str(campaign.id),
            "approval_id": str(approval.id),
            "planned_budget": str(
                campaign.planned_budget or 0
            ),
            "external_action": False,
            "automatic_spend": False,
        },
    )

    await db.commit()
    await db.refresh(binding)

    return _mktb_binding_payload(
        binding,
        approval,
    )


@app.post(
    "/api/marketing/campaigns/{campaign_id}/activate"
)
async def activate_marketing_campaign(
    campaign_id: _mktb_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    campaign = await db.get(
        _MktBCampaign,
        campaign_id,
    )

    if campaign is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing campaign not found",
        )

    binding = await _mktb_binding(
        db,
        entity_type="campaign",
        entity_id=campaign.id,
        purpose=_MKTB_CAMPAIGN_PURPOSE,
    )

    if binding is None:
        raise HTTPException(
            status_code=409,
            detail="Campaign approval is required before activation",
        )

    approval = await db.get(
        Approval,
        binding.approval_id,
    )

    if approval is None or approval.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Approved campaign authorization is required",
        )

    if not campaign.start_date:
        raise HTTPException(
            status_code=409,
            detail="Campaign start date is required before activation",
        )

    campaign.status = "active"

    await write_audit_log(
        db,
        actor="user",
        action="marketing.campaign.activated",
        details={
            "campaign_id": str(campaign.id),
            "approval_id": str(approval.id),
            "external_action": False,
            "automatic_spend": False,
        },
    )

    await db.commit()
    await db.refresh(campaign)

    return _mkt_campaign_payload(campaign)


@app.post(
    "/api/marketing/content/{content_id}/request-approval"
)
async def request_marketing_content_approval(
    content_id: _mktb_uuid.UUID,
    payload: MarketingApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    content = await db.get(
        _MktBContent,
        content_id,
    )

    if content is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing content item not found",
        )

    if content.status in {
        "published",
        "cancelled",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Published/cancelled content cannot request approval"
            ),
        )

    existing = await _mktb_binding(
        db,
        entity_type="content",
        entity_id=content.id,
        purpose=_MKTB_CONTENT_PURPOSE,
    )

    if existing:
        current = await db.get(
            Approval,
            existing.approval_id,
        )
        if current and current.status == "pending":
            return _mktb_binding_payload(
                existing,
                current,
            )

    approval = Approval(
        agent_id=await _mktb_marketing_agent_id(db),
        title="Approve Marketing Content",
        description=(
            "Approve internal marketing content for use. "
            "Approval does not publish externally."
        ),
        action_type="marketing_content_approval",
        risk_level="medium",
        status="pending",
        action_payload={
            "content_id": str(content.id),
            "campaign_id": (
                str(content.campaign_id)
                if content.campaign_id
                else None
            ),
            "title": content.title,
            "content_type": content.content_type,
            "channel": content.channel,
            "automatic_publish": False,
            "external_communication": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    if existing:
        existing.approval_id = approval.id
        binding = existing
    else:
        binding = MarketingApprovalBinding(
            entity_type="content",
            entity_id=content.id,
            purpose=_MKTB_CONTENT_PURPOSE,
            approval_id=approval.id,
        )
        db.add(binding)

    content.status = "review"

    await write_audit_log(
        db,
        actor=payload.requested_by.strip() or "user",
        action="marketing.content.approval_requested",
        details={
            "content_id": str(content.id),
            "approval_id": str(approval.id),
            "automatic_publish": False,
        },
    )

    await db.commit()
    await db.refresh(binding)

    return _mktb_binding_payload(
        binding,
        approval,
    )


