@app.post("/api/marketing/performance-snapshots")
async def create_marketing_performance_snapshot(
    payload: MarketingPerformanceSnapshotCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    campaign = await db.get(
        _MktBCampaign,
        payload.campaign_id,
    )

    if campaign is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing campaign not found",
        )

    values = {
        "impressions": payload.impressions,
        "clicks": payload.clicks,
        "engagements": payload.engagements,
        "website_sessions": payload.website_sessions,
        "inquiries": payload.inquiries,
    }

    if any(value < 0 for value in values.values()):
        raise HTTPException(
            status_code=400,
            detail="Marketing metrics cannot be negative",
        )

    source_reference = payload.source_reference.strip()

    if not source_reference:
        raise HTTPException(
            status_code=400,
            detail=(
                "Performance snapshot requires a source reference"
            ),
        )

    row = MarketingPerformanceSnapshot(
        campaign_id=campaign.id,
        snapshot_date=payload.snapshot_date,
        impressions=payload.impressions,
        clicks=payload.clicks,
        engagements=payload.engagements,
        website_sessions=payload.website_sessions,
        inquiries=payload.inquiries,
        source_reference=source_reference,
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="marketing.performance_snapshot.created",
        details={
            "snapshot_id": str(row.id),
            "campaign_id": str(campaign.id),
            "snapshot_date": row.snapshot_date.isoformat(),
            "source_reference": source_reference,
            "external_data_pull": False,
            "finance_spend_recorded": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _mktb_snapshot_payload(row)


@app.get("/api/marketing/performance-dashboard")
async def marketing_performance_dashboard(
    db: AsyncSession = Depends(get_db),
):
    campaigns = (
        await db.execute(
            _mktb_select(_MktBCampaign)
        )
    ).scalars().all()

    snapshots = (
        await db.execute(
            _mktb_select(
                MarketingPerformanceSnapshot
            )
        )
    ).scalars().all()

    attributions = (
        await db.execute(
            _mktb_select(_MktBAttribution)
        )
    ).scalars().all()

    leads = (
        await db.execute(
            _mktb_select(_MktBSalesLead)
        )
    ).scalars().all()

    lead_map = {
        row.id: row
        for row in leads
    }

    rows = []

    for campaign in campaigns:
        metrics = [
            row
            for row in snapshots
            if row.campaign_id == campaign.id
        ]

        touches = [
            row
            for row in attributions
            if row.campaign_id == campaign.id
        ]

        attributed_ids = {
            row.lead_id
            for row in touches
        }

        impressions = sum(
            row.impressions
            for row in metrics
        )
        clicks = sum(
            row.clicks
            for row in metrics
        )
        engagements = sum(
            row.engagements
            for row in metrics
        )
        sessions = sum(
            row.website_sessions
            for row in metrics
        )
        inquiries = sum(
            row.inquiries
            for row in metrics
        )

        rows.append({
            "campaign_id": str(campaign.id),
            "campaign_code": campaign.code,
            "campaign_name": campaign.name,
            "status": campaign.status,
            "planned_budget": float(
                _mkt_money(campaign.planned_budget)
            ),
            "snapshot_count": len(metrics),
            "impressions": impressions,
            "clicks": clicks,
            "engagements": engagements,
            "website_sessions": sessions,
            "inquiries": inquiries,
            "ctr_pct": round(
                (
                    clicks
                    / impressions
                    * 100
                )
                if impressions
                else 0.0,
                4,
            ),
            "engagement_rate_pct": round(
                (
                    engagements
                    / impressions
                    * 100
                )
                if impressions
                else 0.0,
                4,
            ),
            "attributed_leads": len(
                attributed_ids
            ),
            "qualified_leads": sum(
                1
                for lead_id in attributed_ids
                if lead_id in lead_map
                and lead_map[lead_id].status
                == "qualified"
            ),
            "converted_leads": sum(
                1
                for lead_id in attributed_ids
                if lead_id in lead_map
                and lead_map[lead_id].status
                == "converted"
            ),
        })

    return {
        "campaigns": rows,
        "totals": {
            "campaigns": len(campaigns),
            "snapshots": len(snapshots),
            "impressions": sum(
                row.impressions
                for row in snapshots
            ),
            "clicks": sum(
                row.clicks
                for row in snapshots
            ),
            "engagements": sum(
                row.engagements
                for row in snapshots
            ),
            "website_sessions": sum(
                row.website_sessions
                for row in snapshots
            ),
            "inquiries": sum(
                row.inquiries
                for row in snapshots
            ),
            "attributed_leads": len({
                row.lead_id
                for row in attributions
            }),
        },
        "governance": {
            "campaign_activation_requires_approval": True,
            "content_authorization_requires_approval": True,
            "published_status_requires_external_reference": True,
            "performance_requires_source_reference": True,
        },
        "safety": {
            "automatic_external_publication": False,
            "automatic_external_communication": False,
            "automatic_sales_lead_creation": False,
            "automatic_opportunity_creation": False,
            "automatic_finance_posting": False,
            "automatic_budget_spend": False,
            "automatic_bank_transfer": False,
        },
    }

# ============================================================
# Marketing - Phase 1C API
# Explicit links to approved Finance budgets, Finance expenses,
# Procurement requests/orders, and unified attachment evidence.
# No automatic spend, posting, procurement, payment or dispatch.
# ============================================================
import uuid as _mktc_uuid
from decimal import Decimal as _MktCDecimal

from pydantic import BaseModel as _MktCBaseModel
from sqlalchemy import (
    func as _mktc_func,
    select as _mktc_select,
)

from .models import (
    FinanceAccount as _MktCFinanceAccount,
    FinanceBudget as _MktCFinanceBudget,
    FinanceBudgetLine as _MktCFinanceBudgetLine,
    FinanceExpense as _MktCFinanceExpense,
    HRAttachment as _MktCAttachment,
    MarketingBudgetAllocation,
    MarketingCampaign as _MktCCampaign,
    MarketingFinanceExpenseLink,
    MarketingPurchaseOrderLink,
    MarketingPurchaseRequestLink,
    ProcurementPurchaseOrder as _MktCPurchaseOrder,
    ProcurementPurchaseOrderLine as _MktCPurchaseOrderLine,
    ProcurementPurchaseRequest as _MktCPurchaseRequest,
    ProcurementPurchaseRequestLine as _MktCPurchaseRequestLine,
)


_MKTC_MARKETING_ACCOUNT_CODE = "650000"


def _mktc_money(value):
    return _MktCDecimal(str(value or 0)).quantize(
        _MktCDecimal("0.01")
    )


async def _mktc_campaign(db, campaign_id):
    row = await db.get(_MktCCampaign, campaign_id)
    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Marketing campaign not found",
        )
    return row


async def _mktc_marketing_account(db):
    row = (
        await db.execute(
            _mktc_select(_MktCFinanceAccount).where(
                _MktCFinanceAccount.code
                == _MKTC_MARKETING_ACCOUNT_CODE,
                _MktCFinanceAccount.account_type == "expense",
                _MktCFinanceAccount.allow_posting.is_(True),
                _MktCFinanceAccount.is_active.is_(True),
            )
        )
    ).scalars().first()

    if row is None:
        raise HTTPException(
            status_code=409,
            detail=(
                "Active posting Finance account 650000 "
                "(Marketing) is required"
            ),
        )

    return row


async def _mktc_pr_marketing_amount(
    db,
    purchase_request_id,
    marketing_account_id,
):
    rows = (
        await db.execute(
            _mktc_select(_MktCPurchaseRequestLine).where(
                _MktCPurchaseRequestLine.purchase_request_id
                == purchase_request_id,
                _MktCPurchaseRequestLine.account_id
                == marketing_account_id,
            )
        )
    ).scalars().all()

    return sum(
        (
            _mktc_money(row.estimated_total_amount)
            for row in rows
        ),
        _MktCDecimal("0.00"),
    )


async def _mktc_po_marketing_amount(
    db,
    purchase_order_id,
    marketing_account_id,
):
    rows = (
        await db.execute(
            _mktc_select(_MktCPurchaseOrderLine).where(
                _MktCPurchaseOrderLine.purchase_order_id
                == purchase_order_id,
                _MktCPurchaseOrderLine.account_id
                == marketing_account_id,
            )
        )
    ).scalars().all()

    return sum(
        (
            _mktc_money(row.total_amount)
            for row in rows
        ),
        _MktCDecimal("0.00"),
    )


class MarketingBudgetAllocationCreateRequest(_MktCBaseModel):
    finance_budget_line_id: _mktc_uuid.UUID
    allocated_amount: float
    linked_by: str = "user"
    notes: str | None = None


class MarketingLinkRequest(_MktCBaseModel):
    linked_by: str = "user"
    notes: str | None = None


@app.get("/api/marketing/eligible-finance-budget-lines")
async def marketing_eligible_finance_budget_lines(
    db: AsyncSession = Depends(get_db),
):
    account = await _mktc_marketing_account(db)

    lines = (
        await db.execute(
            _mktc_select(_MktCFinanceBudgetLine).where(
                _MktCFinanceBudgetLine.account_id == account.id
            ).order_by(_MktCFinanceBudgetLine.month.asc())
        )
    ).scalars().all()

    output = []

    for line in lines:
        budget = await db.get(_MktCFinanceBudget, line.budget_id)

        if (
            budget is None
            or budget.status != "approved"
            or not budget.is_current
        ):
            continue

        allocated = await db.scalar(
            _mktc_select(
                _mktc_func.coalesce(
                    _mktc_func.sum(
                        MarketingBudgetAllocation.allocated_amount
                    ),
                    0,
                )
            ).where(
                MarketingBudgetAllocation.finance_budget_line_id
                == line.id
            )
        )

        output.append({
            "budget_id": str(budget.id),
            "budget_name": budget.name,
            "budget_year": budget.year,
            "budget_version": budget.version,
            "budget_status": budget.status,
            "budget_is_current": budget.is_current,
            "budget_line_id": str(line.id),
            "month": line.month,
            "department_code": line.department_code,
            "cost_center": line.cost_center,
            "amount": float(_mktc_money(line.amount)),
            "allocated_amount": float(_mktc_money(allocated)),
            "available_amount": float(
                _mktc_money(line.amount)
                - _mktc_money(allocated)
            ),
            "account_code": account.code,
            "account_name_en": account.name_en,
        })

    return output


@app.post(
    "/api/marketing/campaigns/{campaign_id}/budget-allocations"
)
async def create_marketing_budget_allocation(
    campaign_id: _mktc_uuid.UUID,
    payload: MarketingBudgetAllocationCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    campaign = await _mktc_campaign(db, campaign_id)
    account = await _mktc_marketing_account(db)

    line = await db.get(
        _MktCFinanceBudgetLine,
        payload.finance_budget_line_id,
    )

    if line is None:
        raise HTTPException(
            status_code=404,
            detail="Finance budget line not found",
        )

    if line.account_id != account.id:
        raise HTTPException(
            status_code=409,
            detail=(
                "Marketing campaigns can only allocate "
                "Finance budget lines on account 650000"
            ),
        )

    budget = await db.get(_MktCFinanceBudget, line.budget_id)

    if (
        budget is None
        or budget.status != "approved"
        or not budget.is_current
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Only an approved current Finance budget "
                "can be allocated to Marketing"
            ),
        )

    amount = _mktc_money(payload.allocated_amount)

    if amount <= 0:
        raise HTTPException(
            status_code=400,
            detail="Allocated amount must be greater than zero",
        )

    existing = (
        await db.execute(
            _mktc_select(MarketingBudgetAllocation).where(
                MarketingBudgetAllocation.campaign_id
                == campaign.id,
                MarketingBudgetAllocation.finance_budget_line_id
                == line.id,
            )
        )
    ).scalars().first()

    filters = [
        MarketingBudgetAllocation.finance_budget_line_id
        == line.id
    ]

    if existing:
        filters.append(
            MarketingBudgetAllocation.id != existing.id
        )

    other_total = await db.scalar(
        _mktc_select(
            _mktc_func.coalesce(
                _mktc_func.sum(
                    MarketingBudgetAllocation.allocated_amount
                ),
                0,
            )
        ).where(*filters)
    )

    if _mktc_money(other_total) + amount > _mktc_money(line.amount):
        raise HTTPException(
            status_code=409,
            detail=(
                "Marketing allocation exceeds the available "
                "amount on the approved Finance budget line"
            ),
        )

    if existing:
        existing.allocated_amount = amount
        existing.linked_by = (
            payload.linked_by.strip() or "user"
        )
        existing.notes = (
            payload.notes.strip()
            if payload.notes and payload.notes.strip()
            else None
        )
        row = existing
    else:
        row = MarketingBudgetAllocation(
            campaign_id=campaign.id,
            finance_budget_line_id=line.id,
            allocated_amount=amount,
            linked_by=(
                payload.linked_by.strip() or "user"
            ),
            notes=(
                payload.notes.strip()
                if payload.notes and payload.notes.strip()
                else None
            ),
        )
        db.add(row)

    await write_audit_log(
        db,
        actor=row.linked_by,
        action="marketing.finance_budget_allocated",
        details={
            "campaign_id": str(campaign.id),
            "finance_budget_id": str(budget.id),
            "finance_budget_line_id": str(line.id),
            "allocated_amount": str(amount),
            "finance_budget_changed": False,
            "spend_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return {
        "id": str(row.id),
        "campaign_id": str(row.campaign_id),
        "finance_budget_line_id": str(
            row.finance_budget_line_id
        ),
        "allocated_amount": float(
            _mktc_money(row.allocated_amount)
        ),
        "finance_budget_changed": False,
        "spend_executed": False,
    }


