@app.get("/api/admin/facilities")
async def list_admin_facilities(
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _ad_select(AdminFacility)

    if status:
        normalized = status.strip().lower()
        if normalized not in _AD_FACILITY_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid facility status",
            )
        query = query.where(
            AdminFacility.status == normalized
        )

    rows = (
        await db.execute(
            query.order_by(
                AdminFacility.created_at.desc()
            )
        )
    ).scalars().all()

    return [
        _ad_facility_payload(row)
        for row in rows
    ]


@app.post("/api/admin/facilities")
async def create_admin_facility(
    payload: AdminFacilityCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    name = payload.name.strip()
    facility_type = payload.facility_type.strip().lower()

    if not name:
        raise HTTPException(
            status_code=400,
            detail="Facility name is required",
        )

    if facility_type not in _AD_FACILITY_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid facility type",
        )

    row = AdminFacility(
        code=_ad_code("FAC"),
        name=name,
        facility_type=facility_type,
        address=(
            payload.address.strip()
            if payload.address
            and payload.address.strip()
            else None
        ),
        city=(
            payload.city.strip()
            if payload.city
            and payload.city.strip()
            else None
        ),
        responsible_owner=(
            payload.responsible_owner.strip()
            if payload.responsible_owner
            and payload.responsible_owner.strip()
            else None
        ),
        status="active",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        facility_metadata={
            "physical_access_system_changed": False,
            "procurement_created": False,
        },
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="admin.facility.created",
        details={
            "facility_id": str(row.id),
            "facility_code": row.code,
            "physical_access_system_changed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _ad_facility_payload(row)


