@app.post("/api/admin/custody")
async def create_admin_custody(
    payload: AdminCustodyCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    item_type = payload.item_type.strip().lower()
    assignee_type = (
        payload.assigned_to_type.strip().lower()
    )
    identifier = payload.item_identifier.strip()
    assignee_name = payload.assigned_to_name.strip()

    if item_type not in _AD_CUSTODY_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid custody item type",
        )

    if assignee_type not in _AD_CUSTODY_ASSIGNEE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid custody assignee type",
        )

    if not identifier or not assignee_name:
        raise HTTPException(
            status_code=400,
            detail=(
                "Item identifier and assigned-to name "
                "are required"
            ),
        )

    if payload.facility_id:
        await _ad_facility(
            db,
            payload.facility_id,
        )

    if payload.finance_fixed_asset_id:
        asset = await db.get(
            _AdFinanceFixedAsset,
            payload.finance_fixed_asset_id,
        )
        if asset is None:
            raise HTTPException(
                status_code=404,
                detail="Finance fixed asset not found",
            )

    if (
        payload.due_return_at
        and payload.due_return_at
        <= payload.issued_at
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Custody due-return time must be "
                "after issue time"
            ),
        )

    row = AdminCustodyAssignment(
        code=_ad_code("CUS"),
        facility_id=payload.facility_id,
        finance_fixed_asset_id=(
            payload.finance_fixed_asset_id
        ),
        item_type=item_type,
        item_identifier=identifier,
        assigned_to_type=assignee_type,
        assigned_to_reference=(
            payload.assigned_to_reference.strip()
            if payload.assigned_to_reference
            and payload.assigned_to_reference.strip()
            else None
        ),
        assigned_to_name=assignee_name,
        issued_by=(
            payload.issued_by.strip()
            or "user"
        ),
        issued_at=payload.issued_at,
        due_return_at=payload.due_return_at,
        status="issued",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        custody_metadata={
            "finance_asset_mutated": False,
            "physical_key_system_changed": False,
        },
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor=row.issued_by,
        action="admin.custody.issued",
        details={
            "custody_id": str(row.id),
            "finance_fixed_asset_id": (
                str(row.finance_fixed_asset_id)
                if row.finance_fixed_asset_id
                else None
            ),
            "finance_asset_mutated": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _ad_custody_payload(row)


@app.post("/api/admin/custody/{custody_id}/return")
async def return_admin_custody(
    custody_id: _ad_uuid.UUID,
    payload: AdminCustodyReturnRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AdminCustodyAssignment,
        custody_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Admin custody record not found",
        )

    target = payload.status.strip().lower()

    if target not in {
        "returned",
        "lost",
        "damaged",
    }:
        raise HTTPException(
            status_code=400,
            detail=(
                "Custody return status must be "
                "returned, lost or damaged"
            ),
        )

    if row.status != "issued":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only issued custody can be closed"
            ),
        )

    row.status = target
    row.returned_at = _ad_datetime.now(
        _ad_timezone.utc
    )
    row.received_back_by = (
        payload.received_back_by.strip()
    )

    if payload.notes and payload.notes.strip():
        row.notes = payload.notes.strip()

    await write_audit_log(
        db,
        actor=(
            payload.received_back_by.strip()
            or "user"
        ),
        action="admin.custody.closed",
        details={
            "custody_id": str(row.id),
            "status": target,
            "finance_asset_mutated": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _ad_custody_payload(row)


