@app.put(
    "/api/admin/corporate-records/{record_id}/archive"
)
async def archive_admin_corporate_record(
    record_id: _ad_uuid.UUID,
    payload: AdminRecordArchiveRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AdminCorporateRecord,
        record_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Admin corporate record not found",
        )

    if row.status == "archived":
        return _ad_record_payload(row)

    actor = payload.archived_by.strip()
    reason = payload.reason.strip()

    if not actor or not reason:
        raise HTTPException(
            status_code=400,
            detail=(
                "archived_by and reason are required"
            ),
        )

    row.status = "archived"
    row.archived_by = actor
    row.archive_reason = reason
    row.archived_at = _ad_datetime.now(
        _ad_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="admin.corporate_record.archived",
        details={
            "corporate_record_id": str(row.id),
            "file_deleted": False,
            "government_compliance_changed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _ad_record_payload(row)


