@app.get("/api/admin/leases")
async def list_admin_leases(
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _adb_select(AdminFacilityLease)

    if status:
        normalized = status.strip().lower()
        if normalized not in _ADB_LEASE_STATUSES:
            raise HTTPException(status_code=400, detail="Invalid lease status")
        query = query.where(AdminFacilityLease.status == normalized)

    rows = (
        await db.execute(
            query.order_by(AdminFacilityLease.created_at.desc())
        )
    ).scalars().all()

    output = []
    for row in rows:
        approval = (
            await db.get(_AdBApproval, row.approval_id)
            if row.approval_id else None
        )
        output.append(_adb_lease_payload(row, approval))
    return output


@app.post("/api/admin/leases")
async def create_admin_lease(
    payload: AdminLeaseCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    await _adb_facility(db, payload.facility_id)

    counterparty = payload.counterparty_name.strip()
    if not counterparty:
        raise HTTPException(status_code=400, detail="Lease counterparty is required")

    if payload.end_date <= payload.start_date:
        raise HTTPException(status_code=400, detail="Lease end date must be after start date")

    if payload.annual_value < 0:
        raise HTTPException(status_code=400, detail="Lease annual value cannot be negative")

    row = AdminFacilityLease(
        code=_adb_code("LEASE"),
        facility_id=payload.facility_id,
        counterparty_name=counterparty,
        start_date=payload.start_date,
        end_date=payload.end_date,
        annual_value=payload.annual_value,
        currency=payload.currency.strip().upper() or "SAR",
        status="draft",
        notes=payload.notes.strip() if payload.notes else None,
        lease_metadata={
            "external_signature_executed": False,
            "payment_executed": False,
            "procurement_created": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _adb_lease_payload(row)


@app.post("/api/admin/leases/{lease_id}/request-approval")
async def request_admin_lease_approval(
    lease_id: _adb_uuid.UUID,
    payload: AdminLeaseApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminFacilityLease, lease_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Admin lease not found")

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(status_code=409, detail="Lease cannot enter approval now")

    if row.approval_id:
        previous = await db.get(_AdBApproval, row.approval_id)
        if previous and previous.status == "pending":
            return _adb_lease_payload(row, previous)

    agent = await _ad_agent(db)

    approval = _AdBApproval(
        agent_id=agent.id if agent else None,
        title=f"Authorize facility lease {row.code}",
        description=(
            f"{row.counterparty_name} | "
            f"{float(row.annual_value or 0):,.2f} {row.currency}"
        ),
        action_type="admin_facility_lease_authorization",
        risk_level="critical",
        status="pending",
        action_payload={
            "lease_id": str(row.id),
            "external_signature_executed": False,
            "payment_executed": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _adb_lease_payload(row, approval)


@app.post("/api/admin/leases/{lease_id}/authorize")
async def authorize_admin_lease(
    lease_id: _adb_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminFacilityLease, lease_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Admin lease not found")

    approval = (
        await db.get(_AdBApproval, row.approval_id)
        if row.approval_id else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "admin_facility_lease_authorization"
        or str((approval.action_payload or {}).get("lease_id") or "")
        != str(row.id)
    ):
        raise HTTPException(status_code=409, detail="Approved lease authorization is required")

    row.status = "approved"
    await db.commit()
    await db.refresh(row)

    return _adb_lease_payload(row, approval)


@app.post("/api/admin/leases/{lease_id}/record-execution")
async def record_admin_lease_execution(
    lease_id: _adb_uuid.UUID,
    payload: AdminLeaseExecutionRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminFacilityLease, lease_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Admin lease not found")

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Lease must be approved before recording external execution",
        )

    reference = payload.external_contract_reference.strip()
    if not reference:
        raise HTTPException(status_code=400, detail="External contract reference is required")

    row.status = "active"
    row.executed_contract_reference = reference

    await write_audit_log(
        db,
        actor=payload.actor.strip() or "user",
        action="admin.lease.external_execution_recorded",
        details={
            "lease_id": str(row.id),
            "external_reference": reference,
            "system_signed_contract": False,
            "system_paid_counterparty": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _adb_lease_payload(row)


