    coverage = payload.coverage_summary.strip()

    if insurance_type not in _ADB_INSURANCE_TYPES:
        raise HTTPException(status_code=400, detail="Invalid company insurance type")

    if not coverage:
        raise HTTPException(status_code=400, detail="Coverage summary is required")

