@app.post(
    "/api/admin/insurance-authorizations/{authorization_id}/record-issued"
)
async def record_admin_insurance_issued(
    authorization_id: _adb_uuid.UUID,
    payload: AdminInsuranceIssueRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminInsuranceAuthorization, authorization_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Insurance authorization not found")

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Insurance must be approved before recording issuance",
        )

    policy_number = payload.policy_number.strip()
    evidence = payload.external_evidence_reference.strip()

    if not policy_number or not evidence:
        raise HTTPException(
            status_code=400,
            detail="Policy number and external evidence reference are required",
        )

    if payload.compliance_record_id:
        compliance = await db.get(
            _AdBComplianceRecord,
            payload.compliance_record_id,
        )
        if compliance is None:
            raise HTTPException(
                status_code=404,
                detail="Corporate compliance record not found",
            )

    row.policy_number = policy_number
    row.external_evidence_reference = evidence
    row.compliance_record_id = payload.compliance_record_id
    row.status = "active"

    await write_audit_log(
        db,
        actor=payload.actor.strip() or "user",
        action="admin.insurance.external_issuance_recorded",
        details={
            "insurance_authorization_id": str(row.id),
            "system_purchased_policy": False,
            "system_paid_premium": False,
            "compliance_record_created": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _adb_insurance_payload(row)


