@app.post("/api/admin/bookings")
async def create_admin_booking(
    payload: AdminBookingCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    resource = await db.get(AdminSharedResource, payload.resource_id)

    if resource is None:
        raise HTTPException(status_code=404, detail="Admin shared resource not found")

    if resource.status != "active":
        raise HTTPException(status_code=409, detail="Only active resources can be booked")

    if payload.end_at <= payload.start_at:
        raise HTTPException(status_code=400, detail="Booking end must be after start")

    title = payload.title.strip()
    booked_by = payload.booked_by.strip()

    if not title or not booked_by:
        raise HTTPException(status_code=400, detail="Booking title and booked_by are required")

    conflict = (
        await db.execute(
            _adb_select(AdminResourceBooking).where(
                AdminResourceBooking.resource_id == resource.id,
                AdminResourceBooking.status == "reserved",
                AdminResourceBooking.start_at < payload.end_at,
                AdminResourceBooking.end_at > payload.start_at,
            )
        )
    ).scalars().first()

    if conflict:
        raise HTTPException(status_code=409, detail="Resource already has an overlapping booking")

    row = AdminResourceBooking(
        code=_adb_code("BOOK"),
        resource_id=resource.id,
        title=title,
        booked_by=booked_by,
        start_at=payload.start_at,
        end_at=payload.end_at,
        status="reserved",
        notes=payload.notes.strip() if payload.notes else None,
        booking_metadata={
            "external_booking_created": False,
            "external_notification_sent": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _adb_booking_payload(row)


