@app.get("/api/admin/alerts")
async def admin_alerts(
    db: AsyncSession = Depends(get_db),
):
    now = _adb_datetime.now(_adb_timezone.utc)
    today = now.date()

    overdue_work_orders = (
        await db.execute(
            _adb_select(_AdBWorkOrder).where(
                _AdBWorkOrder.status.in_(["open", "in_progress"]),
                _AdBWorkOrder.due_date.is_not(None),
                _AdBWorkOrder.due_date < today,
            )
        )
    ).scalars().all()

    overdue_access = (
        await db.execute(
            _adb_select(_AdBAccess).where(
                _AdBAccess.status == "checked_in",
                _AdBAccess.end_at.is_not(None),
                _AdBAccess.end_at < now,
            )
        )
    ).scalars().all()

    overdue_custody = (
        await db.execute(
            _adb_select(_AdBCustody).where(
                _AdBCustody.status == "issued",
                _AdBCustody.due_return_at.is_not(None),
                _AdBCustody.due_return_at < now,
            )
        )
    ).scalars().all()

    retention_due = (
        await db.execute(
            _adb_select(_AdBRecord).where(
                _AdBRecord.status == "active",
                _AdBRecord.retention_until.is_not(None),
                _AdBRecord.retention_until
                <= today + _adb_timedelta(days=30),
            )
        )
    ).scalars().all()

    lease_due = (
        await db.execute(
            _adb_select(AdminFacilityLease).where(
                AdminFacilityLease.status == "active",
                AdminFacilityLease.end_date
                <= today + _adb_timedelta(days=90),
            )
        )
    ).scalars().all()

    insurance_due = (
        await db.execute(
            _adb_select(AdminInsuranceAuthorization).where(
                AdminInsuranceAuthorization.status == "active",
                AdminInsuranceAuthorization.expiry_date.is_not(None),
                AdminInsuranceAuthorization.expiry_date
                <= today + _adb_timedelta(days=60),
            )
        )
    ).scalars().all()

    return {
        "total": (
            len(overdue_work_orders)
            + len(overdue_access)
            + len(overdue_custody)
            + len(retention_due)
            + len(lease_due)
            + len(insurance_due)
        ),
        "overdue_work_orders": len(overdue_work_orders),
        "overdue_checked_in_visitors": len(overdue_access),
        "overdue_custody": len(overdue_custody),
        "retention_reviews_due": len(retention_due),
        "leases_expiring_90_days": len(lease_due),
        "insurance_expiring_60_days": len(insurance_due),
    }


@app.get("/api/admin/phase1b-summary")
async def admin_phase1b_summary(
    db: AsyncSession = Depends(get_db),
):
    leases = (
        await db.execute(_adb_select(AdminFacilityLease))
    ).scalars().all()

    insurance = (
        await db.execute(_adb_select(AdminInsuranceAuthorization))
    ).scalars().all()

    resources = (
        await db.execute(_adb_select(AdminSharedResource))
    ).scalars().all()

    bookings = (
        await db.execute(_adb_select(AdminResourceBooking))
    ).scalars().all()

    alerts = await admin_alerts(db)

    return {
        "leases": {
            "total": len(leases),
            "active": sum(1 for x in leases if x.status == "active"),
            "pending_approval": sum(
                1 for x in leases if x.status == "pending_approval"
            ),
        },
        "company_insurance": {
            "total": len(insurance),
            "active": sum(1 for x in insurance if x.status == "active"),
            "pending_approval": sum(
                1 for x in insurance if x.status == "pending_approval"
            ),
        },
        "resources": {
            "total": len(resources),
            "active": sum(1 for x in resources if x.status == "active"),
        },
        "bookings": {
            "total": len(bookings),
            "reserved": sum(1 for x in bookings if x.status == "reserved"),
        },
        "alerts": alerts["total"],
        "safety": {
            "automatic_contract_signature": False,
            "automatic_insurance_purchase": False,
            "automatic_payment": False,
            "automatic_finance_posting": False,
            "automatic_procurement_creation": False,
            "automatic_compliance_record_creation": False,
            "automatic_external_booking": False,
            "automatic_external_communication": False,
        },
    }

# ============================================================
# Admin - Phase 1C API
# Lease termination approval/evidence + custody stocktake.
# No external termination, asset mutation or physical action occurs.
# ============================================================
import uuid as _adc_uuid
from datetime import (
    date as _adc_date,
    datetime as _adc_datetime,
    timezone as _adc_timezone,
)

from pydantic import BaseModel as _AdCBaseModel
from sqlalchemy import select as _adc_select

from .models import (
    AdminCustodyAssignment as _AdCCustody,
    AdminCustodyStocktake,
    AdminCustodyStocktakeItem,
    AdminFacility as _AdCFacility,
    AdminFacilityLease as _AdCLease,
    AdminLeaseTermination,
    Approval as _AdCApproval,
)

_ADB_LEASE_STATUSES.update({
    "termination_pending",
    "terminated",
})


class AdminLeaseTerminationRequest(_AdCBaseModel):
    requested_by: str = "user"
    reason: str | None = None


class AdminLeaseTerminationEvidenceRequest(_AdCBaseModel):
    external_termination_reference: str
    recorded_by: str = "user"


class AdminCustodyStocktakeCreateRequest(_AdCBaseModel):
    facility_id: _adc_uuid.UUID | None = None
    stocktake_date: _adc_date
    performed_by: str
    notes: str | None = None


class AdminCustodyObservationRequest(_AdCBaseModel):
    observed_status: str
    observed_by: str
    notes: str | None = None


def _adc_termination_payload(row, approval=None):
    return {
        "id": str(row.id),
        "lease_id": str(row.lease_id),
        "requested_by": row.requested_by,
        "reason": row.reason,
        "status": row.status,
        "approval_id": str(row.approval_id) if row.approval_id else None,
        "approval_status": approval.status if approval else None,
        "external_termination_reference": row.external_termination_reference,
        "recorded_by": row.recorded_by,
        "terminated_at": row.terminated_at,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


async def _adc_stocktake_payload(db, row):
    items = (
        await db.execute(
            _adc_select(AdminCustodyStocktakeItem).where(
                AdminCustodyStocktakeItem.stocktake_id == row.id
            ).order_by(
                AdminCustodyStocktakeItem.id.asc()
            )
        )
    ).scalars().all()

    counts = {
        "pending": 0,
        "present": 0,
        "missing": 0,
        "damaged": 0,
    }
    payload_items = []

    for item in items:
        custody = await db.get(_AdCCustody, item.custody_id)
        counts[item.observed_status] = counts.get(item.observed_status, 0) + 1

        payload_items.append({
            "id": str(item.id),
            "custody_id": str(item.custody_id),
            "custody_code": custody.code if custody else None,
            "item_type": custody.item_type if custody else None,
            "item_identifier": custody.item_identifier if custody else None,
            "assigned_to_name": custody.assigned_to_name if custody else None,
            "custody_status": custody.status if custody else None,
            "observed_status": item.observed_status,
            "observed_by": item.observed_by,
            "observed_at": item.observed_at,
            "notes": item.notes,
        })

    return {
        "id": str(row.id),
        "code": row.code,
        "facility_id": str(row.facility_id) if row.facility_id else None,
        "stocktake_date": row.stocktake_date,
        "performed_by": row.performed_by,
        "status": row.status,
        "notes": row.notes,
        "completed_at": row.completed_at,
        "counts": counts,
        "discrepancies": counts["missing"] + counts["damaged"],
        "items": payload_items,
    }


@app.get("/api/admin/lease-terminations")
async def list_admin_lease_terminations(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _adc_select(AdminLeaseTermination).order_by(
                AdminLeaseTermination.created_at.desc()
            )
        )
    ).scalars().all()

    output = []
    for row in rows:
        approval = (
            await db.get(_AdCApproval, row.approval_id)
            if row.approval_id
            else None
        )
        output.append(_adc_termination_payload(row, approval))
    return output


@app.post("/api/admin/leases/{lease_id}/termination/request-approval")
async def request_admin_lease_termination_control(
    lease_id: _adc_uuid.UUID,
    payload: AdminLeaseTerminationRequest,
    db: AsyncSession = Depends(get_db),
):
    lease = await db.get(_AdCLease, lease_id)

    if lease is None:
        raise HTTPException(status_code=404, detail="Admin lease not found")

    if lease.status != "active":
        raise HTTPException(
            status_code=409,
            detail="Only an active lease can request termination",
        )

    existing = (
        await db.execute(
            _adc_select(AdminLeaseTermination).where(
                AdminLeaseTermination.lease_id == lease.id
            )
        )
    ).scalars().first()

    if existing:
        approval = (
            await db.get(_AdCApproval, existing.approval_id)
            if existing.approval_id
            else None
        )
        return _adc_termination_payload(existing, approval)

    agent = await _ad_agent(db)

    approval = _AdCApproval(
        agent_id=agent.id if agent else None,
        title="Authorize facility lease termination " + lease.code,
        description=lease.counterparty_name,
        action_type="admin_facility_lease_termination",
        risk_level="critical",
        status="pending",
        action_payload={
            "lease_id": str(lease.id),
            "external_termination_executed": False,
            "payment_executed": False,
            "requested_by": payload.requested_by,
            "reason": payload.reason,
        },
    )

    db.add(approval)
    await db.flush()

    row = AdminLeaseTermination(
        lease_id=lease.id,
        requested_by=payload.requested_by.strip() or "user",
        reason=(
            payload.reason.strip()
            if payload.reason and payload.reason.strip()
            else None
        ),
        status="pending_approval",
        approval_id=approval.id,
    )

    db.add(row)
    await db.flush()

    lease.status = "termination_pending"

    await write_audit_log(
        db,
        actor=row.requested_by,
        action="admin.lease_termination.approval_requested",
        details={
            "lease_id": str(lease.id),
            "termination_id": str(row.id),
            "approval_id": str(approval.id),
            "external_termination_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _adc_termination_payload(row, approval)


@app.post("/api/admin/lease-terminations/{termination_id}/record-execution")
async def record_admin_lease_termination_execution(
    termination_id: _adc_uuid.UUID,
    payload: AdminLeaseTerminationEvidenceRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminLeaseTermination, termination_id)

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Lease termination request not found",
        )

    approval = (
        await db.get(_AdCApproval, row.approval_id)
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type != "admin_facility_lease_termination"
    ):
        raise HTTPException(
            status_code=409,
            detail="Approved lease-termination authorization is required",
        )

    reference = payload.external_termination_reference.strip()

    if not reference:
        raise HTTPException(
            status_code=400,
            detail="External termination reference is required",
        )

    lease = await db.get(_AdCLease, row.lease_id)

    if lease is None:
        raise HTTPException(
            status_code=409,
            detail="Linked lease no longer exists",
        )

    now = _adc_datetime.now(_adc_timezone.utc)

    row.status = "terminated"
    row.external_termination_reference = reference
    row.recorded_by = payload.recorded_by.strip() or "user"
    row.terminated_at = now
    lease.status = "terminated"

    await write_audit_log(
        db,
        actor=row.recorded_by,
        action="admin.lease_termination.external_execution_recorded",
        details={
            "lease_id": str(lease.id),
            "termination_id": str(row.id),
            "external_reference": reference,
            "system_executed_termination": False,
            "payment_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _adc_termination_payload(row, approval)


@app.get("/api/admin/custody-stocktakes")
async def list_admin_custody_stocktakes(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _adc_select(AdminCustodyStocktake).order_by(
                AdminCustodyStocktake.created_at.desc()
            )
        )
    ).scalars().all()

    return [
        await _adc_stocktake_payload(db, row)
        for row in rows
    ]


@app.post("/api/admin/custody-stocktakes")
async def create_admin_custody_stocktake(
    payload: AdminCustodyStocktakeCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    performer = payload.performed_by.strip()

    if not performer:
        raise HTTPException(status_code=400, detail="performed_by is required")

    if payload.facility_id:
        facility = await db.get(_AdCFacility, payload.facility_id)
        if facility is None:
            raise HTTPException(status_code=404, detail="Admin facility not found")

    query = _adc_select(_AdCCustody).where(
        _AdCCustody.status == "issued"
    )

    if payload.facility_id:
        query = query.where(
            _AdCCustody.facility_id == payload.facility_id
        )

    custody_rows = (
        await db.execute(
            query.order_by(_AdCCustody.created_at.asc())
        )
    ).scalars().all()

    if not custody_rows:
        raise HTTPException(
            status_code=409,
            detail="No issued custody records are available for this stocktake",
        )

    row = AdminCustodyStocktake(
        code="STK-" + _adc_uuid.uuid4().hex[:8].upper(),
        facility_id=payload.facility_id,
        stocktake_date=payload.stocktake_date,
        performed_by=performer,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes and payload.notes.strip()
            else None
        ),
    )

    db.add(row)
    await db.flush()

    for custody in custody_rows:
        db.add(
            AdminCustodyStocktakeItem(
                stocktake_id=row.id,
                custody_id=custody.id,
                observed_status="pending",
            )
        )

    await write_audit_log(
        db,
        actor=performer,
        action="admin.custody_stocktake.created",
        details={
            "stocktake_id": str(row.id),
            "expected_items": len(custody_rows),
            "custody_records_mutated": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _adc_stocktake_payload(db, row)


@app.put("/api/admin/custody-stocktakes/{stocktake_id}/items/{item_id}")
async def update_admin_custody_stocktake_item(
    stocktake_id: _adc_uuid.UUID,
    item_id: _adc_uuid.UUID,
    payload: AdminCustodyObservationRequest,
    db: AsyncSession = Depends(get_db),
):
    stocktake = await db.get(AdminCustodyStocktake, stocktake_id)

    if stocktake is None:
        raise HTTPException(status_code=404, detail="Custody stocktake not found")

    if stocktake.status != "draft":
        raise HTTPException(
            status_code=409,
            detail="Only draft stocktakes can be updated",
        )

    item = await db.get(AdminCustodyStocktakeItem, item_id)

    if item is None or item.stocktake_id != stocktake.id:
        raise HTTPException(status_code=404, detail="Stocktake item not found")

    observed_status = payload.observed_status.strip().lower()

    if observed_status not in {"present", "missing", "damaged"}:
        raise HTTPException(
            status_code=400,
            detail="Observed status must be present, missing or damaged",
        )

    observer = payload.observed_by.strip()

    if not observer:
        raise HTTPException(status_code=400, detail="observed_by is required")

    item.observed_status = observed_status
    item.observed_by = observer
    item.observed_at = _adc_datetime.now(_adc_timezone.utc)
    item.notes = (
        payload.notes.strip()
        if payload.notes and payload.notes.strip()
        else None
    )

    await db.commit()

    return await _adc_stocktake_payload(db, stocktake)


@app.post("/api/admin/custody-stocktakes/{stocktake_id}/complete")
async def complete_admin_custody_stocktake(
    stocktake_id: _adc_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(AdminCustodyStocktake, stocktake_id)

    if row is None:
        raise HTTPException(status_code=404, detail="Custody stocktake not found")

    if row.status == "completed":
        return await _adc_stocktake_payload(db, row)

    items = (
        await db.execute(
            _adc_select(AdminCustodyStocktakeItem).where(
                AdminCustodyStocktakeItem.stocktake_id == row.id
            )
        )
    ).scalars().all()

    if not items:
        raise HTTPException(status_code=409, detail="Stocktake has no items")

    if any(item.observed_status == "pending" for item in items):
        raise HTTPException(
            status_code=409,
            detail="All stocktake items must be observed before completion",
        )

    row.status = "completed"
    row.completed_at = _adc_datetime.now(_adc_timezone.utc)

    discrepancies = sum(
        1
        for item in items
        if item.observed_status in {"missing", "damaged"}
    )

    await write_audit_log(
        db,
        actor=row.performed_by,
        action="admin.custody_stocktake.completed",
        details={
            "stocktake_id": str(row.id),
            "discrepancies": discrepancies,
            "custody_records_mutated": False,
            "finance_assets_mutated": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return await _adc_stocktake_payload(db, row)


@app.get("/api/admin/phase1c-summary")
async def admin_phase1c_summary(
    db: AsyncSession = Depends(get_db),
):
    terminations = (
        await db.execute(_adc_select(AdminLeaseTermination))
    ).scalars().all()

    stocktakes = (
        await db.execute(_adc_select(AdminCustodyStocktake))
    ).scalars().all()

    completed = [
        row
        for row in stocktakes
        if row.status == "completed"
    ]

    discrepancy_count = 0
    for row in completed:
        payload = await _adc_stocktake_payload(db, row)
        discrepancy_count += payload["discrepancies"]

    return {
        "lease_terminations": {
            "total": len(terminations),
            "pending_approval": sum(
                1 for x in terminations
                if x.status == "pending_approval"
            ),
            "terminated": sum(
                1 for x in terminations
                if x.status == "terminated"
            ),
        },
        "custody_stocktakes": {
            "total": len(stocktakes),
            "draft": sum(
                1 for x in stocktakes
                if x.status == "draft"
            ),
            "completed": len(completed),
            "discrepancies": discrepancy_count,
        },
        "safety": {
            "automatic_external_lease_termination": False,
            "automatic_payment": False,
            "automatic_custody_status_mutation": False,
            "automatic_finance_asset_mutation": False,
            "automatic_physical_action": False,
            "automatic_external_communication": False,
        },
    }

