@app.get("/api/legal/contracts")
async def list_legal_contracts(
    status: str | None = None,
    contract_type: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _lega_select(LegalContract)

    if status:
        normalized = status.strip().lower()
        if normalized not in _LEGA_CONTRACT_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid legal contract status",
            )
        query = query.where(
            LegalContract.status == normalized
        )

    if contract_type:
        normalized = contract_type.strip().lower()
        if normalized not in _LEGA_CONTRACT_TYPES:
            raise HTTPException(
                status_code=400,
                detail="Invalid legal contract type",
            )
        query = query.where(
            LegalContract.contract_type == normalized
        )

    rows = (
        await db.execute(
            query.order_by(
                LegalContract.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = (
            await db.get(
                _LegaApproval,
                row.approval_id,
            )
            if row.approval_id
            else None
        )
        output.append(
            _lega_contract_payload(
                row,
                approval,
            )
        )

    return output


@app.post("/api/legal/contracts")
async def create_legal_contract(
    payload: LegalContractCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    contract_type = (
        payload.contract_type.strip().lower()
    )
    title = payload.title.strip()
    counterparty = (
        payload.counterparty_name.strip()
    )

    if contract_type not in _LEGA_CONTRACT_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid legal contract type",
        )

    if not title or not counterparty:
        raise HTTPException(
            status_code=400,
            detail=(
                "Contract title and counterparty "
                "are required"
            ),
        )

    if (
        payload.effective_date
        and payload.expiry_date
        and payload.expiry_date
        <= payload.effective_date
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Contract expiry must be after "
                "effective date"
            ),
        )

    if (
        payload.notice_days is not None
        and payload.notice_days < 0
    ):
        raise HTTPException(
            status_code=400,
            detail="Notice days cannot be negative",
        )

    row = LegalContract(
        code=_lega_code("LEG-CTR"),
        contract_type=contract_type,
        title=title,
        counterparty_name=counterparty,
        owner_department=(
            payload.owner_department.strip()
            if payload.owner_department
            and payload.owner_department.strip()
            else None
        ),
        source_module=(
            payload.source_module.strip()
            if payload.source_module
            and payload.source_module.strip()
            else None
        ),
        source_entity_id=payload.source_entity_id,
        effective_date=payload.effective_date,
        expiry_date=payload.expiry_date,
        auto_renew=payload.auto_renew,
        notice_days=payload.notice_days,
        governing_law=(
            payload.governing_law.strip()
            if payload.governing_law
            and payload.governing_law.strip()
            else None
        ),
        jurisdiction=(
            payload.jurisdiction.strip()
            if payload.jurisdiction
            and payload.jurisdiction.strip()
            else None
        ),
        confidentiality_required=(
            payload.confidentiality_required
        ),
        data_processing_involved=(
            payload.data_processing_involved
        ),
        unlimited_liability=(
            payload.unlimited_liability
        ),
        material_indemnity=(
            payload.material_indemnity
        ),
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        contract_metadata={
            "external_signature_executed": False,
            "external_communication_sent": False,
            "finance_posting_created": False,
            "procurement_record_created": False,
        },
    )

    db.add(row)
    await db.flush()

    await write_audit_log(
        db,
        actor="user",
        action="legal.contract.created",
        details={
            "contract_id": str(row.id),
            "contract_type": row.contract_type,
            "source_module": row.source_module,
            "source_entity_id": (
                str(row.source_entity_id)
                if row.source_entity_id
                else None
            ),
            "external_signature_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _lega_contract_payload(row)


