@app.post("/api/legal/contracts/{contract_id}/reviews")
async def create_legal_contract_review(
    contract_id: _lega_uuid.UUID,
    payload: LegalContractReviewRequest,
    db: AsyncSession = Depends(get_db),
):
    contract = await db.get(
        LegalContract,
        contract_id,
    )

    if contract is None:
        raise HTTPException(
            status_code=404,
            detail="Legal contract not found",
        )

    if contract.status in {
        "executed",
        "expired",
        "terminated",
        "cancelled",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Executed/closed contract cannot "
                "receive a new legal review"
            ),
        )

    review_type = (
        payload.review_type.strip().lower()
    )
    risk_level = (
        payload.risk_level.strip().lower()
    )
    reviewer = payload.reviewer.strip()

    if review_type not in _LEGA_REVIEW_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid legal review type",
        )

    if risk_level not in _LEGA_RISK_LEVELS:
        raise HTTPException(
            status_code=400,
            detail="Invalid legal review risk",
        )

    if not reviewer:
        raise HTTPException(
            status_code=400,
            detail="Reviewer is required",
        )

    next_round = int(
        await db.scalar(
            _lega_select(
                _lega_func.max(
                    LegalContractReview.review_round
                )
            ).where(
                LegalContractReview.contract_id
                == contract.id
            )
        )
        or 0
    ) + 1

    row = LegalContractReview(
        contract_id=contract.id,
        review_round=next_round,
        review_type=review_type,
        risk_level=risk_level,
        reviewer=reviewer,
        deviations_summary=(
            payload.deviations_summary.strip()
            if payload.deviations_summary
            and payload.deviations_summary.strip()
            else None
        ),
        liability_summary=(
            payload.liability_summary.strip()
            if payload.liability_summary
            and payload.liability_summary.strip()
            else None
        ),
        indemnity_summary=(
            payload.indemnity_summary.strip()
            if payload.indemnity_summary
            and payload.indemnity_summary.strip()
            else None
        ),
        privacy_summary=(
            payload.privacy_summary.strip()
            if payload.privacy_summary
            and payload.privacy_summary.strip()
            else None
        ),
        recommendation=(
            payload.recommendation.strip()
            if payload.recommendation
            and payload.recommendation.strip()
            else None
        ),
        status="completed",
    )

    db.add(row)
    contract.status = "under_review"

    await write_audit_log(
        db,
        actor=reviewer,
        action="legal.contract.review_completed",
        details={
            "contract_id": str(contract.id),
            "review_round": next_round,
            "review_type": review_type,
            "risk_level": risk_level,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _lega_review_payload(row)


@app.post("/api/legal/contracts/{contract_id}/request-approval")
async def request_legal_contract_approval(
    contract_id: _lega_uuid.UUID,
    payload: LegalApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    contract = await db.get(
        LegalContract,
        contract_id,
    )

    if contract is None:
        raise HTTPException(
            status_code=404,
            detail="Legal contract not found",
        )

    if contract.status not in {
        "draft",
        "under_review",
        "pending_approval",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Contract cannot enter approval "
                "in its current status"
            ),
        )

    reviews = (
        await db.execute(
            _lega_select(
                LegalContractReview
            ).where(
                LegalContractReview.contract_id
                == contract.id
            ).order_by(
                LegalContractReview.review_round.desc()
            )
        )
    ).scalars().all()

    if not reviews:
        raise HTTPException(
            status_code=409,
            detail=(
                "At least one completed legal review "
                "is required before approval"
            ),
        )

    latest_review = reviews[0]

    if contract.approval_id:
        existing = await db.get(
            _LegaApproval,
            contract.approval_id,
        )
        if (
            existing
            and existing.status == "pending"
        ):
            return _lega_contract_payload(
                contract,
                existing,
            )

    risk_level = latest_review.risk_level

    if (
        contract.unlimited_liability
        or contract.material_indemnity
    ):
        risk_level = "critical"
    elif (
        latest_review.review_type
        in {"deviation", "high_risk"}
        and risk_level
        in {"low", "medium"}
    ):
        risk_level = "high"

    agent = await _lega_agent(db)

    approval = _LegaApproval(
        agent_id=(
            agent.id
            if agent
            else None
        ),
        title=(
            "Approve Legal Contract "
            + contract.code
        ),
        description=(
            contract.title
            + " | "
            + contract.counterparty_name
        ),
        action_type="legal_contract_approval",
        risk_level=risk_level,
        status="pending",
        action_payload={
            "contract_id": str(contract.id),
            "contract_type": contract.contract_type,
            "review_id": str(latest_review.id),
            "review_type":
                latest_review.review_type,
            "unlimited_liability":
                contract.unlimited_liability,
            "material_indemnity":
                contract.material_indemnity,
            "external_signature_executed": False,
            "external_communication_sent": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    contract.approval_id = approval.id
    contract.status = "pending_approval"

    await write_audit_log(
        db,
        actor=(
            payload.requested_by.strip()
            or "user"
        ),
        action="legal.contract.approval_requested",
        details={
            "contract_id": str(contract.id),
            "approval_id": str(approval.id),
            "risk_level": risk_level,
            "external_signature_executed": False,
        },
    )

    await db.commit()
    await db.refresh(contract)

    return _lega_contract_payload(
        contract,
        approval,
    )


@app.post("/api/legal/contracts/{contract_id}/authorize")
async def authorize_legal_contract(
    contract_id: _lega_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    contract = await db.get(
        LegalContract,
        contract_id,
    )

    if contract is None:
        raise HTTPException(
            status_code=404,
            detail="Legal contract not found",
        )

    approval = (
        await db.get(
            _LegaApproval,
            contract.approval_id,
        )
        if contract.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "legal_contract_approval"
        or str(
            (
                approval.action_payload
                or {}
            ).get("contract_id")
            or ""
        )
        != str(contract.id)
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved legal-contract authorization "
                "is required"
            ),
        )

    contract.status = "approved"

    await write_audit_log(
        db,
        actor="user",
        action="legal.contract.authorized",
        details={
            "contract_id": str(contract.id),
            "approval_id": str(approval.id),
            "system_signed_contract": False,
            "external_communication_sent": False,
        },
    )

    await db.commit()
    await db.refresh(contract)

    return _lega_contract_payload(
        contract,
        approval,
    )


@app.post("/api/legal/contracts/{contract_id}/record-execution")
async def record_legal_contract_execution(
    contract_id: _lega_uuid.UUID,
    payload: LegalContractExecutionRequest,
    db: AsyncSession = Depends(get_db),
):
    contract = await db.get(
        LegalContract,
        contract_id,
    )

    if contract is None:
        raise HTTPException(
            status_code=404,
            detail="Legal contract not found",
        )

    if contract.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Contract must be approved before "
                "recording external execution"
            ),
        )

    reference = (
        payload.external_execution_reference.strip()
    )

    if not reference:
        raise HTTPException(
            status_code=400,
            detail=(
                "External execution reference is required"
            ),
        )

    contract.status = "executed"
    contract.external_execution_reference = (
        reference
    )
    contract.executed_at = _lega_datetime.now(
        _lega_timezone.utc
    )

    await write_audit_log(
        db,
        actor=(
            payload.recorded_by.strip()
            or "user"
        ),
        action="legal.contract.external_execution_recorded",
        details={
            "contract_id": str(contract.id),
            "external_reference": reference,
            "system_signed_contract": False,
            "external_communication_sent": False,
        },
    )

    await db.commit()
    await db.refresh(contract)

    approval = (
        await db.get(
            _LegaApproval,
            contract.approval_id,
        )
        if contract.approval_id
        else None
    )

    return _lega_contract_payload(
        contract,
        approval,
    )


