@app.get("/api/legal/summary")
async def legal_summary(
    db: AsyncSession = Depends(get_db),
):
    contracts = (
        await db.execute(
            _lega_select(LegalContract)
        )
    ).scalars().all()

    reviews = (
        await db.execute(
            _lega_select(LegalContractReview)
        )
    ).scalars().all()

    matters = (
        await db.execute(
            _lega_select(LegalMatter)
        )
    ).scalars().all()

    attachments = int(
        await db.scalar(
            _lega_select(
                _lega_func.count()
            ).select_from(
                _LegaAttachment
            ).where(
                _LegaAttachment.module == "legal",
                _LegaAttachment.status == "active",
            )
        )
        or 0
    )

    return {
        "contracts": {
            "total": len(contracts),
            "draft_or_review": sum(
                1
                for x in contracts
                if x.status
                in {"draft", "under_review"}
            ),
            "pending_approval": sum(
                1
                for x in contracts
                if x.status == "pending_approval"
            ),
            "approved": sum(
                1
                for x in contracts
                if x.status == "approved"
            ),
            "executed": sum(
                1
                for x in contracts
                if x.status == "executed"
            ),
            "high_risk_terms": sum(
                1
                for x in contracts
                if x.unlimited_liability
                or x.material_indemnity
            ),
        },
        "reviews": {
            "total": len(reviews),
            "deviation_or_high_risk": sum(
                1
                for x in reviews
                if x.review_type
                in {"deviation", "high_risk"}
            ),
        },
        "matters": {
            "total": len(matters),
            "open": sum(
                1
                for x in matters
                if x.status == "open"
            ),
            "high_or_critical": sum(
                1
                for x in matters
                if x.status != "closed"
                and x.risk_level
                in {"high", "critical"}
            ),
        },
        "active_attachments": attachments,
        "safety": {
            "automatic_contract_signature": False,
            "automatic_external_communication": False,
            "automatic_finance_posting": False,
            "automatic_payment": False,
            "automatic_sales_mutation": False,
            "automatic_procurement_mutation": False,
            "automatic_compliance_mutation": False,
            "automatic_external_filing": False,
            "automatic_settlement": False,
        },
    }

# ============================================================
# Legal - Phase 1B API
# Privacy + data-sharing governance + DPIA + gifts/hospitality
# + evidence-based third-party integrity screening.
# No personal-data disclosure/deletion, data transfer, gift
# commitment, screening callout, payment or external communication
# is executed automatically.
# ============================================================
