def _legb_code(prefix):
    return prefix + "-" + _legb_uuid.uuid4().hex[:8].upper()


def _legb_privacy_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "request_type": row.request_type,
        "subject_type": row.subject_type,
        "subject_reference": row.subject_reference,
        "received_date": row.received_date,
        "due_date": row.due_date,
        "identity_verified": row.identity_verified,
        "identity_evidence_reference":
            row.identity_evidence_reference,
        "status": row.status,
        "external_response_reference":
            row.external_response_reference,
        "completed_by": row.completed_by,
        "completed_at": row.completed_at,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


