@app.get("/api/legal/privacy-requests")
async def list_legal_privacy_requests(
    status: str | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _legb_select(LegalPrivacyRequest)

    if status:
        normalized = status.strip().lower()
        if normalized not in _LEGB_PRIVACY_STATUSES:
            raise HTTPException(
                status_code=400,
                detail="Invalid privacy request status",
            )
        query = query.where(
            LegalPrivacyRequest.status == normalized
        )

    rows = (
        await db.execute(
            query.order_by(
                LegalPrivacyRequest.received_date.desc()
            )
        )
    ).scalars().all()

    return [
        _legb_privacy_payload(row)
        for row in rows
    ]


@app.post("/api/legal/privacy-requests")
async def create_legal_privacy_request(
    payload: LegalPrivacyRequestCreate,
    db: AsyncSession = Depends(get_db),
):
    request_type = payload.request_type.strip().lower()
    subject_type = payload.subject_type.strip().lower()

    if request_type not in _LEGB_PRIVACY_REQUEST_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid privacy request type",
        )

    if subject_type not in _LEGB_SUBJECT_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid privacy subject type",
        )

    if payload.due_date < payload.received_date:
        raise HTTPException(
            status_code=400,
            detail="Privacy due date cannot precede received date",
        )

    row = LegalPrivacyRequest(
        code=_legb_code("LEG-DSR"),
        request_type=request_type,
        subject_type=subject_type,
        subject_reference=(
            payload.subject_reference.strip()
            if payload.subject_reference
            and payload.subject_reference.strip()
            else None
        ),
        received_date=payload.received_date,
        due_date=payload.due_date,
        identity_verified=False,
        status="open",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        privacy_metadata={
            "personal_data_disclosed": False,
            "personal_data_deleted": False,
            "external_response_sent": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _legb_privacy_payload(row)


@app.post("/api/legal/privacy-requests/{request_id}/verify")
async def verify_legal_privacy_request(
    request_id: _legb_uuid.UUID,
    payload: LegalPrivacyVerifyRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalPrivacyRequest,
        request_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Privacy request not found",
        )

    if row.status == "completed":
        raise HTTPException(
            status_code=409,
            detail="Completed privacy request cannot be re-verified",
        )

    evidence = payload.identity_evidence_reference.strip()

    if not evidence:
        raise HTTPException(
            status_code=400,
            detail="Identity evidence reference is required",
        )

    row.identity_verified = True
    row.identity_evidence_reference = evidence
    row.status = "verified"

    await db.commit()
    await db.refresh(row)

    return _legb_privacy_payload(row)


@app.post("/api/legal/privacy-requests/{request_id}/complete")
async def complete_legal_privacy_request(
    request_id: _legb_uuid.UUID,
    payload: LegalPrivacyCompleteRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalPrivacyRequest,
        request_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Privacy request not found",
        )

    if not row.identity_verified:
        raise HTTPException(
            status_code=409,
            detail="Identity verification is required before completion",
        )

    reference = payload.external_response_reference.strip()
    actor = payload.completed_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail="External response reference and completed_by are required",
        )

    row.status = "completed"
    row.external_response_reference = reference
    row.completed_by = actor
    row.completed_at = _legb_datetime.now(
        _legb_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="legal.privacy_request.external_completion_recorded",
        details={
            "privacy_request_id": str(row.id),
            "external_response_reference": reference,
            "system_disclosed_personal_data": False,
            "system_deleted_personal_data": False,
            "system_sent_response": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _legb_privacy_payload(row)


@app.get("/api/legal/data-sharing-assessments")
async def list_legal_data_sharing_assessments(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _legb_select(
                LegalDataSharingAssessment
            ).order_by(
                LegalDataSharingAssessment.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = (
            await db.get(
                _LegBApproval,
                row.approval_id,
            )
            if row.approval_id
            else None
        )
        output.append(
            _legb_data_sharing_payload(
                row,
                approval,
            )
        )

    return output


@app.post("/api/legal/data-sharing-assessments")
async def create_legal_data_sharing_assessment(
    payload: LegalDataSharingCreate,
    db: AsyncSession = Depends(get_db),
):
    recipient = payload.recipient_name.strip()
    purpose = payload.purpose.strip()
    legal_basis = payload.legal_basis.strip()
    categories = payload.data_categories.strip()
    risk = payload.risk_level.strip().lower()

    if not recipient or not purpose or not legal_basis or not categories:
        raise HTTPException(
            status_code=400,
            detail="Recipient, purpose, legal basis and data categories are required",
        )

    if risk not in _LEGB_RISK_LEVELS:
        raise HTTPException(
            status_code=400,
            detail="Invalid data-sharing risk level",
        )

    row = LegalDataSharingAssessment(
        code=_legb_code("LEG-SHARE"),
        recipient_name=recipient,
        purpose=purpose,
        legal_basis=legal_basis,
        data_categories=categories,
        cross_border=payload.cross_border,
        dpa_required=payload.dpa_required,
        risk_level=risk,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        assessment_metadata={
            "personal_data_transferred_by_system": False,
            "external_communication_sent": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _legb_data_sharing_payload(row)


@app.post("/api/legal/data-sharing-assessments/{assessment_id}/request-approval")
async def request_legal_data_sharing_approval(
    assessment_id: _legb_uuid.UUID,
    payload: LegalApprovalRequestB,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalDataSharingAssessment,
        assessment_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Data-sharing assessment not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="Data-sharing assessment cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _LegBApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _legb_data_sharing_payload(
                row,
                existing,
            )

    risk = row.risk_level

    if row.cross_border and risk in {"low", "medium"}:
        risk = "high"

    if row.dpa_required and risk == "low":
        risk = "medium"

    agent = await _lega_agent(db)

    approval = _LegBApproval(
        agent_id=agent.id if agent else None,
        title=(
            "Approve Personal Data Sharing "
            + row.code
        ),
        description=(
            row.recipient_name
            + " | "
            + row.purpose
        ),
        action_type="legal_personal_data_sharing_approval",
        risk_level=risk,
        status="pending",
        action_payload={
            "assessment_id": str(row.id),
            "cross_border": row.cross_border,
            "dpa_required": row.dpa_required,
            "personal_data_transferred": False,
            "external_communication_sent": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _legb_data_sharing_payload(
        row,
        approval,
    )


@app.post("/api/legal/data-sharing-assessments/{assessment_id}/authorize")
async def authorize_legal_data_sharing(
    assessment_id: _legb_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalDataSharingAssessment,
        assessment_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Data-sharing assessment not found",
        )

    approval = (
        await db.get(
            _LegBApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "legal_personal_data_sharing_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail="Approved personal-data-sharing authorization is required",
        )

    row.status = "approved"

    await db.commit()
    await db.refresh(row)

    return _legb_data_sharing_payload(
        row,
        approval,
    )


@app.post("/api/legal/data-sharing-assessments/{assessment_id}/record-execution")
async def record_legal_data_sharing_execution(
    assessment_id: _legb_uuid.UUID,
    payload: LegalDataSharingExecutionRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalDataSharingAssessment,
        assessment_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Data-sharing assessment not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Data-sharing assessment must be approved before recording execution",
        )

    reference = payload.external_execution_reference.strip()
    actor = payload.recorded_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail="External execution reference and recorded_by are required",
        )

    row.status = "executed"
    row.external_execution_reference = reference
    row.executed_at = _legb_datetime.now(
        _legb_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="legal.data_sharing.external_execution_recorded",
        details={
            "assessment_id": str(row.id),
            "external_reference": reference,
            "system_transferred_personal_data": False,
            "system_sent_external_communication": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = (
        await db.get(
            _LegBApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    return _legb_data_sharing_payload(
        row,
        approval,
    )


