@app.post("/api/legal/dpias")
async def create_legal_dpia(
    payload: LegalDPIACreate,
    db: AsyncSession = Depends(get_db),
):
    title = payload.title.strip()
    owner = payload.owner.strip()
    trigger = payload.trigger_reason.strip()
    processing = payload.processing_summary.strip()
    residual = payload.residual_risk.strip().lower()

    if not title or not owner or not trigger or not processing:
        raise HTTPException(
            status_code=400,
            detail="DPIA title, owner, trigger and processing summary are required",
        )

    if residual not in _LEGB_RISK_LEVELS:
        raise HTTPException(
            status_code=400,
            detail="Invalid DPIA residual risk",
        )

    row = LegalPrivacyImpactAssessment(
        code=_legb_code("LEG-DPIA"),
        title=title,
        owner=owner,
        trigger_reason=trigger,
        processing_summary=processing,
        high_risk_processing=payload.high_risk_processing,
        sensitive_data=payload.sensitive_data,
        cross_border=payload.cross_border,
        safeguards_summary=(
            payload.safeguards_summary.strip()
            if payload.safeguards_summary
            and payload.safeguards_summary.strip()
            else None
        ),
        residual_risk=residual,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        dpia_metadata={
            "processing_started_by_system": False,
            "personal_data_transferred_by_system": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _legb_dpia_payload(row)


@app.post("/api/legal/dpias/{dpia_id}/request-approval")
async def request_legal_dpia_approval(
    dpia_id: _legb_uuid.UUID,
    payload: LegalApprovalRequestB,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalPrivacyImpactAssessment,
        dpia_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="DPIA not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="DPIA cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _LegBApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _legb_dpia_payload(
                row,
                existing,
            )

    risk = row.residual_risk

    if (
        row.high_risk_processing
        or row.sensitive_data
        or row.cross_border
    ) and risk in {"low", "medium"}:
        risk = "high"

    agent = await _lega_agent(db)

    approval = _LegBApproval(
        agent_id=agent.id if agent else None,
        title="Approve DPIA " + row.code,
        description=row.title,
        action_type="legal_dpia_approval",
        risk_level=risk,
        status="pending",
        action_payload={
            "dpia_id": str(row.id),
            "high_risk_processing":
                row.high_risk_processing,
            "sensitive_data":
                row.sensitive_data,
            "cross_border":
                row.cross_border,
            "processing_started": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _legb_dpia_payload(
        row,
        approval,
    )


