    row.status = "revoked"
    row.revocation_evidence_reference = evidence
    row.revoked_at = _legc_datetime.now(
        _legc_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="legal.authority.external_revocation_recorded",
        details={
            "authority_id": str(row.id),
            "external_evidence_reference": evidence,
            "system_executed_revocation": False,
        },
    )

