@app.post("/api/legal/ip-assets/{asset_id}/record-registration")
async def record_legal_ip_registration(
    asset_id: _legc_uuid.UUID,
    payload: LegalIPRegistrationRecord,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalIPAsset,
        asset_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Legal IP asset not found",
        )

    if row.status != "filing_recorded":
        raise HTTPException(
            status_code=409,
            detail="IP filing must be recorded before registration",
        )

    reg_no = payload.registration_number.strip()
    evidence = (
        payload.registration_evidence_reference.strip()
    )
    actor = payload.recorded_by.strip()

    if not reg_no or not evidence or not actor:
        raise HTTPException(
            status_code=400,
            detail="Registration number, evidence and recorded_by are required",
        )

    if (
        payload.expiry_date
        and payload.expiry_date < payload.registration_date
    ):
        raise HTTPException(
            status_code=400,
            detail="IP expiry cannot precede registration date",
        )

    row.registration_number = reg_no
    row.registration_date = payload.registration_date
    row.expiry_date = payload.expiry_date
    row.registration_evidence_reference = evidence
    row.status = "registered"

    await db.commit()
    await db.refresh(row)

    approval = await db.get(
        _LegCApproval,
        row.approval_id,
    )

    return _legc_ip_payload(
        row,
        approval,
    )


@app.get("/api/legal/matter-actions")
async def list_legal_matter_actions(
    matter_id: _legc_uuid.UUID | None = None,
    db: AsyncSession = Depends(get_db),
):
    query = _legc_select(LegalMatterAction)

    if matter_id:
        query = query.where(
            LegalMatterAction.matter_id == matter_id
        )

    rows = (
        await db.execute(
            query.order_by(
                LegalMatterAction.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = (
            await db.get(
                _LegCApproval,
                row.approval_id,
            )
            if row.approval_id
            else None
        )
        output.append(
            _legc_action_payload(
                row,
                approval,
            )
        )

    return output


@app.post("/api/legal/matters/{matter_id}/actions")
async def create_legal_matter_action(
    matter_id: _legc_uuid.UUID,
    payload: LegalMatterActionCreate,
    db: AsyncSession = Depends(get_db),
):
    matter = await db.get(
        _LegCMatter,
        matter_id,
    )

    if matter is None:
        raise HTTPException(
            status_code=404,
            detail="Legal matter not found",
        )

    if matter.status == "closed":
        raise HTTPException(
            status_code=409,
            detail="Closed legal matter cannot receive a new material action",
        )

    action_type = payload.action_type.strip().lower()
    description = payload.description.strip()
    risk = payload.risk_level.strip().lower()

    if action_type not in _LEGC_ACTION_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid legal matter action type",
        )

    if risk not in _LEGC_RISK_LEVELS:
        raise HTTPException(
            status_code=400,
            detail="Invalid legal matter action risk",
        )

    if not description:
        raise HTTPException(
            status_code=400,
            detail="Legal action description is required",
        )

    if payload.amount is not None and payload.amount < 0:
        raise HTTPException(
            status_code=400,
            detail="Legal action amount cannot be negative",
        )

    if action_type in {
        "claim_filing",
        "settlement",
        "waiver",
        "regulatory_notification",
    }:
        risk = "critical"
    elif action_type in {
        "external_counsel",
        "formal_notice",
    } and risk in {"low", "medium"}:
        risk = "high"

    row = LegalMatterAction(
        matter_id=matter.id,
        code=_legc_code("LEG-ACT"),
        action_type=action_type,
        description=description,
        amount=payload.amount,
        currency=payload.currency.strip().upper() or "SAR",
        risk_level=risk,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        action_metadata={
            "external_action_executed": False,
            "external_counsel_appointed": False,
            "claim_filed": False,
            "settlement_executed": False,
            "legal_notice_sent": False,
            "regulator_notified": False,
            "payment_executed": False,
            "procurement_created": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _legc_action_payload(row)


@app.post("/api/legal/matter-actions/{action_id}/request-approval")
async def request_legal_matter_action_approval(
    action_id: _legc_uuid.UUID,
    payload: LegalApprovalRequestC,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalMatterAction,
        action_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Legal matter action not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="Legal matter action cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _LegCApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _legc_action_payload(
                row,
                existing,
            )

    agent = await _lega_agent(db)

    approval = _LegCApproval(
        agent_id=agent.id if agent else None,
        title="Approve Legal Action " + row.code,
        description=(
            row.action_type
            + " | "
            + row.description[:180]
        ),
        action_type="legal_matter_action_approval",
        risk_level=row.risk_level,
        status="pending",
        action_payload={
            "matter_action_id": str(row.id),
            "matter_id": str(row.matter_id),
            "legal_action_type": row.action_type,
            "amount": (
                str(row.amount)
                if row.amount is not None
                else None
            ),
            "external_action_executed": False,
            "payment_executed": False,
            "procurement_created": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _legc_action_payload(
        row,
        approval,
    )


@app.post("/api/legal/matter-actions/{action_id}/authorize")
async def authorize_legal_matter_action(
    action_id: _legc_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalMatterAction,
        action_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Legal matter action not found",
        )

    approval = (
        await db.get(
            _LegCApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "legal_matter_action_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail="Approved legal-matter action authorization is required",
        )

    row.status = "approved"

    await db.commit()
    await db.refresh(row)

    return _legc_action_payload(
        row,
        approval,
    )


@app.post("/api/legal/matter-actions/{action_id}/record-execution")
async def record_legal_matter_action_execution(
    action_id: _legc_uuid.UUID,
    payload: LegalMatterActionExecute,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        LegalMatterAction,
        action_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Legal matter action not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Legal matter action must be approved before recording execution",
        )

    evidence = payload.external_evidence_reference.strip()
    actor = payload.executed_by.strip()

    if not evidence or not actor:
        raise HTTPException(
            status_code=400,
            detail="External evidence and executed_by are required",
        )

    row.status = "executed"
    row.external_evidence_reference = evidence
    row.executed_by = actor
    row.executed_at = _legc_datetime.now(
        _legc_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="legal.matter_action.external_execution_recorded",
        details={
            "matter_action_id": str(row.id),
            "matter_id": str(row.matter_id),
            "legal_action_type": row.action_type,
            "external_evidence_reference": evidence,
            "system_executed_external_action": False,
            "payment_executed": False,
            "procurement_created": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = await db.get(
        _LegCApproval,
        row.approval_id,
    )

    return _legc_action_payload(
        row,
        approval,
    )


