@app.post("/api/it/changes")
async def create_it_change(
    payload: ITChangeCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    service = await db.get(
        ITService,
        payload.service_id,
    )

    if service is None:
        raise HTTPException(
            status_code=404,
            detail="IT service not found",
        )

    title = payload.title.strip()
    change_type = payload.change_type.strip().lower()
    risk_level = payload.risk_level.strip().lower()
    requested_by = payload.requested_by.strip()
    description = payload.description.strip()
    test_evidence = payload.test_evidence.strip()
    rollback_plan = payload.rollback_plan.strip()

    if (
        not title
        or not requested_by
        or not description
        or not test_evidence
        or not rollback_plan
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Title, requester, description, test evidence "
                "and rollback plan are required"
            ),
        )

    if change_type not in _ITA_CHANGE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid IT change type",
        )

    if risk_level not in _ITA_CRITICALITIES:
        raise HTTPException(
            status_code=400,
            detail="Invalid IT change risk",
        )

    if change_type == "high_risk":
        risk_level = (
            "high"
            if risk_level in {"low", "medium"}
            else risk_level
        )

    if change_type == "emergency":
        risk_level = "critical"

    if (
        payload.customer_or_data_impact
        and risk_level in {"low", "medium"}
    ):
        risk_level = "high"

    row = ITChangeRequest(
        code=_ita_code("IT-CHG"),
        service_id=service.id,
        title=title,
        change_type=change_type,
        risk_level=risk_level,
        requested_by=requested_by,
        description=description,
        test_evidence=test_evidence,
        rollback_plan=rollback_plan,
        customer_or_data_impact=(
            payload.customer_or_data_impact
        ),
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        change_metadata={
            "production_changed_by_system": False,
            "code_deployed_by_system": False,
            "infrastructure_mutated_by_system": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _ita_change_payload(row)


@app.post("/api/it/changes/{change_id}/request-approval")
async def request_it_change_approval(
    change_id: _ita_uuid.UUID,
    payload: ITApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITChangeRequest,
        change_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT change request not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="IT change cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _ItAApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _ita_change_payload(
                row,
                existing,
            )

    agent = await _ita_agent(db)

    approval = _ItAApproval(
        agent_id=agent.id if agent else None,
        title="Approve IT Change " + row.code,
        description=(
            row.change_type
            + " | "
            + row.title
        ),
        action_type="it_change_approval",
        risk_level=row.risk_level,
        status="pending",
        action_payload={
            "change_id": str(row.id),
            "service_id": str(row.service_id),
            "change_type": row.change_type,
            "test_evidence_present": True,
            "rollback_plan_present": True,
            "customer_or_data_impact":
                row.customer_or_data_impact,
            "production_changed": False,
            "deployment_executed": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _ita_change_payload(
        row,
        approval,
    )


@app.post("/api/it/changes/{change_id}/authorize")
async def authorize_it_change(
    change_id: _ita_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITChangeRequest,
        change_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT change request not found",
        )

    approval = (
        await db.get(
            _ItAApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "it_change_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail="Approved IT change authorization is required",
        )

    row.status = "approved"

    await write_audit_log(
        db,
        actor="user",
        action="it.change.authorized",
        details={
            "change_id": str(row.id),
            "approval_id": str(approval.id),
            "production_changed": False,
            "deployment_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _ita_change_payload(
        row,
        approval,
    )


