@app.post("/api/it/releases")
async def create_it_release(
    payload: ITReleaseCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    change = await db.get(
        ITChangeRequest,
        payload.change_request_id,
    )

    if change is None:
        raise HTTPException(
            status_code=404,
            detail="Linked IT change request not found",
        )

    if change.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "IT change must be approved before "
                "creating a release"
            ),
        )

    version = payload.release_version.strip()
    environment = payload.target_environment.strip().lower()
    notes = payload.release_notes.strip()
    evidence = payload.pre_release_test_evidence.strip()
    rollback = payload.rollback_plan.strip()

    if not version or not notes or not evidence or not rollback:
        raise HTTPException(
            status_code=400,
            detail=(
                "Release version, notes, pre-release test "
                "evidence and rollback plan are required"
            ),
        )

    if environment not in _ITA_ENVIRONMENTS:
        raise HTTPException(
            status_code=400,
            detail="Invalid release target environment",
        )

    row = ITRelease(
        code=_ita_code("IT-REL"),
        change_request_id=change.id,
        release_version=version,
        target_environment=environment,
        release_notes=notes,
        pre_release_test_evidence=evidence,
        rollback_plan=rollback,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        release_metadata={
            "deployment_executed_by_system": False,
            "rollback_executed_by_system": False,
            "production_mutated_by_system": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _ita_release_payload(row)


@app.post("/api/it/releases/{release_id}/request-approval")
async def request_it_release_approval(
    release_id: _ita_uuid.UUID,
    payload: ITApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITRelease,
        release_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT release not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="IT release cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _ItAApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _ita_release_payload(
                row,
                existing,
            )

    change = await db.get(
        ITChangeRequest,
        row.change_request_id,
    )

    risk = (
        change.risk_level
        if change
        else "high"
    )

    if row.target_environment == "production":
        risk = (
            "high"
            if risk in {"low", "medium"}
            else risk
        )

    agent = await _ita_agent(db)

    approval = _ItAApproval(
        agent_id=agent.id if agent else None,
        title="Approve IT Release " + row.code,
        description=(
            row.release_version
            + " -> "
            + row.target_environment
        ),
        action_type="it_release_deployment_approval",
        risk_level=risk,
        status="pending",
        action_payload={
            "release_id": str(row.id),
            "change_id": str(row.change_request_id),
            "target_environment":
                row.target_environment,
            "pre_release_test_evidence_present": True,
            "rollback_plan_present": True,
            "deployment_executed": False,
            "production_mutated": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _ita_release_payload(
        row,
        approval,
    )


