@app.post("/api/it/releases/{release_id}/record-deployment")
async def record_it_release_deployment(
    release_id: _ita_uuid.UUID,
    payload: ITDeploymentEvidenceRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITRelease,
        release_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT release not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Release must be approved before "
                "recording deployment"
            ),
        )

    reference = payload.external_deployment_reference.strip()
    actor = payload.deployed_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "External deployment reference and "
                "deployed_by are required"
            ),
        )

    row.status = "deployed"
    row.external_deployment_reference = reference
    row.deployed_by = actor
    row.deployed_at = _ita_datetime.now(
        _ita_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="it.release.external_deployment_recorded",
        details={
            "release_id": str(row.id),
            "change_id": str(row.change_request_id),
            "external_deployment_reference":
                reference,
            "system_executed_deployment": False,
            "system_mutated_production": False,
            "system_executed_rollback": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = await db.get(
        _ItAApproval,
        row.approval_id,
    )

    return _ita_release_payload(
        row,
        approval,
    )


