# IT - Phase 1B API
# Logical Access + Backup / Recovery / DR Governance.
# Admin remains authoritative for physical premises access.
# No IAM provisioning/revocation or backup/restore execution.
# ============================================================
import uuid as _itb_uuid
from datetime import (
    date as _itb_date,
    datetime as _itb_datetime,
    timedelta as _itb_timedelta,
    timezone as _itb_timezone,
)

from pydantic import BaseModel as _ItBBaseModel
from sqlalchemy import (
    func as _itb_func,
    select as _itb_select,
)

from .models import (
    AdminAccessRequest as _ItBAdminAccessRequest,
    Approval as _ItBApproval,
    ITAccessRequest,
    ITRecoveryProfile,
    ITRecoveryTest,
    ITService as _ItBService,
)


_ITB_ACCESS_TYPES = {
    "standard",
    "privileged",
}

_ITB_SUBJECT_TYPES = {
    "employee",
    "contractor",
    "service_account",
    "vendor",
    "other",
}

_ITB_ACCESS_STATUSES = {
    "draft",
    "pending_approval",
    "approved",
    "active",
    "revoked",
    "cancelled",
}

_ITB_RECOVERY_TEST_TYPES = {
    "backup_restore",
    "disaster_recovery",
    "business_continuity",
}

_ITB_RECOVERY_PROFILE_STATUSES = {
    "draft",
    "pending_approval",
    "active",
    "inactive",
}

_ITB_RECOVERY_TEST_STATUSES = {
    "planned",
    "completed",
}


def _itb_code(prefix):
    return prefix + "-" + _itb_uuid.uuid4().hex[:8].upper()


def _itb_access_payload(row, approval=None):
    return {
        "id": str(row.id),
        "code": row.code,
        "service_id": str(row.service_id),
        "access_type": row.access_type,
        "subject_type": row.subject_type,
        "subject_name": row.subject_name,
        "role_or_scope": row.role_or_scope,
        "requested_by": row.requested_by,
        "justification": row.justification,
        "least_privilege_confirmed":
            row.least_privilege_confirmed,
        "monitoring_required":
            row.monitoring_required,
        "starts_at": row.starts_at,
        "expires_at": row.expires_at,
        "status": row.status,
        "approval_id": (
            str(row.approval_id)
            if row.approval_id
            else None
        ),
        "approval_status": (
            approval.status
            if approval
            else None
        ),
        "external_provisioning_reference":
            row.external_provisioning_reference,
        "provisioned_by": row.provisioned_by,
        "provisioned_at": row.provisioned_at,
        "external_revocation_reference":
            row.external_revocation_reference,
        "revoked_by": row.revoked_by,
        "revoked_at": row.revoked_at,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


