class ITAccessCreateRequest(_ItBBaseModel):
    service_id: _itb_uuid.UUID
    access_type: str
    subject_type: str
    subject_name: str
    role_or_scope: str
    requested_by: str
    justification: str
    least_privilege_confirmed: bool
    starts_at: _itb_datetime | None = None
    expires_at: _itb_datetime | None = None
    notes: str | None = None


class ITAccessProvisionRequest(_ItBBaseModel):
    external_provisioning_reference: str
    provisioned_by: str = "user"


class ITAccessRevokeRequest(_ItBBaseModel):
    external_revocation_reference: str
    revoked_by: str = "user"


class ITRecoveryProfileCreateRequest(_ItBBaseModel):
    service_id: _itb_uuid.UUID
    backup_strategy: str
    backup_frequency: str
    recovery_location: str | None = None
    rpo_target_minutes: int
    rto_target_minutes: int
    test_frequency_days: int = 90
    next_test_due_date: _itb_date
    notes: str | None = None


class ITRecoveryTestCreateRequest(_ItBBaseModel):
    recovery_profile_id: _itb_uuid.UUID
    test_type: str
    planned_at: _itb_datetime
    notes: str | None = None


class ITRecoveryTestResultRequest(_ItBBaseModel):
    restoration_verified: bool
    actual_rpo_minutes: int
    actual_rto_minutes: int
    external_test_reference: str
    performed_by: str
    issues_summary: str | None = None


@app.get("/api/it/access-requests")
async def list_it_access_requests(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _itb_select(
                ITAccessRequest
            ).order_by(
                ITAccessRequest.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = (
            await db.get(
                _ItBApproval,
                row.approval_id,
            )
            if row.approval_id
            else None
        )
        output.append(
            _itb_access_payload(
                row,
                approval,
            )
        )

    return output


@app.post("/api/it/access-requests")
async def create_it_access_request(
    payload: ITAccessCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    service = await db.get(
        _ItBService,
        payload.service_id,
    )

    if service is None:
        raise HTTPException(
            status_code=404,
            detail="IT service not found",
        )

    access_type = payload.access_type.strip().lower()
    subject_type = payload.subject_type.strip().lower()
    subject_name = payload.subject_name.strip()
    scope = payload.role_or_scope.strip()
    requested_by = payload.requested_by.strip()
    justification = payload.justification.strip()

    if access_type not in _ITB_ACCESS_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid logical access type",
        )

    if subject_type not in _ITB_SUBJECT_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid logical access subject type",
        )

    if (
        not subject_name
        or not scope
        or not requested_by
        or not justification
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Subject, scope, requester and justification "
                "are required"
            ),
        )

    if not payload.least_privilege_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Least-privilege confirmation is required",
        )

    if (
        payload.starts_at
        and payload.expires_at
        and payload.expires_at <= payload.starts_at
    ):
        raise HTTPException(
            status_code=400,
            detail="Access expiry must be after start time",
        )

    if (
        access_type == "privileged"
        and payload.expires_at is None
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Privileged access must have "
                "a defined expiry time"
            ),
        )

    row = ITAccessRequest(
        code=_itb_code("IT-ACC"),
        service_id=service.id,
        access_type=access_type,
        subject_type=subject_type,
        subject_name=subject_name,
        role_or_scope=scope,
        requested_by=requested_by,
        justification=justification,
        least_privilege_confirmed=True,
        monitoring_required=(
            access_type == "privileged"
        ),
        starts_at=payload.starts_at,
        expires_at=payload.expires_at,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        access_metadata={
            "identity_provider_mutated": False,
            "credential_created_by_system": False,
            "access_revoked_by_system": False,
            "physical_access_changed": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _itb_access_payload(row)


@app.post("/api/it/access-requests/{access_id}/request-approval")
async def request_it_access_approval(
    access_id: _itb_uuid.UUID,
    payload: ITApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITAccessRequest,
        access_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT access request not found",
        )

    if row.status not in {
        "draft",
        "pending_approval",
    }:
        raise HTTPException(
            status_code=409,
            detail="IT access request cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _ItBApproval,
            row.approval_id,
        )
        if (
            existing
            and existing.status == "pending"
        ):
            return _itb_access_payload(
                row,
                existing,
            )

    service = await db.get(
        _ItBService,
        row.service_id,
    )

    risk = "medium"

    if row.access_type == "privileged":
        risk = "high"

    if (
        row.access_type == "privileged"
        and service is not None
        and service.criticality == "critical"
    ):
        risk = "critical"

    agent = await _ita_agent(db)

    approval = _ItBApproval(
        agent_id=(
            agent.id
            if agent
            else None
        ),
        title=(
            "Approve IT Logical Access "
            + row.code
        ),
        description=(
            row.subject_name
            + " | "
            + row.access_type
            + " | "
            + row.role_or_scope
        ),
        action_type="it_logical_access_approval",
        risk_level=risk,
        status="pending",
        action_payload={
            "access_id": str(row.id),
            "service_id": str(row.service_id),
            "access_type": row.access_type,
            "least_privilege_confirmed":
                row.least_privilege_confirmed,
            "monitoring_required":
                row.monitoring_required,
            "expires_at": (
                row.expires_at.isoformat()
                if row.expires_at
                else None
            ),
            "identity_provider_mutated": False,
            "credential_created": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _itb_access_payload(
        row,
        approval,
    )


@app.post("/api/it/access-requests/{access_id}/authorize")
async def authorize_it_access(
    access_id: _itb_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITAccessRequest,
        access_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT access request not found",
        )

    approval = (
        await db.get(
            _ItBApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "it_logical_access_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved logical-access authorization "
                "is required"
            ),
        )

    row.status = "approved"

    await db.commit()
    await db.refresh(row)

    return _itb_access_payload(
        row,
        approval,
    )


@app.post("/api/it/access-requests/{access_id}/record-provisioning")
async def record_it_access_provisioning(
    access_id: _itb_uuid.UUID,
    payload: ITAccessProvisionRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITAccessRequest,
        access_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT access request not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail=(
                "Access must be approved before "
                "recording provisioning"
            ),
        )

    reference = (
        payload.external_provisioning_reference.strip()
    )
    actor = payload.provisioned_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "External provisioning reference "
                "and provisioned_by are required"
            ),
        )

    row.status = "active"
    row.external_provisioning_reference = (
        reference
    )
    row.provisioned_by = actor
    row.provisioned_at = _itb_datetime.now(
        _itb_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="it.access.external_provisioning_recorded",
        details={
            "access_id": str(row.id),
            "external_reference": reference,
            "identity_provider_mutated_by_system": False,
            "credential_created_by_system": False,
            "physical_access_changed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = await db.get(
        _ItBApproval,
        row.approval_id,
    )

    return _itb_access_payload(
        row,
        approval,
    )


@app.post("/api/it/access-requests/{access_id}/record-revocation")
async def record_it_access_revocation(
    access_id: _itb_uuid.UUID,
    payload: ITAccessRevokeRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITAccessRequest,
        access_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT access request not found",
        )

    if row.status not in {
        "active",
        "approved",
    }:
        raise HTTPException(
            status_code=409,
            detail=(
                "Only approved/active access can "
                "record revocation"
            ),
        )

    reference = (
        payload.external_revocation_reference.strip()
    )
    actor = payload.revoked_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "External revocation reference "
                "and revoked_by are required"
            ),
        )

    row.status = "revoked"
    row.external_revocation_reference = reference
    row.revoked_by = actor
    row.revoked_at = _itb_datetime.now(
        _itb_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="it.access.external_revocation_recorded",
        details={
            "access_id": str(row.id),
            "external_reference": reference,
            "access_revoked_by_system": False,
            "identity_provider_mutated_by_system": False,
            "physical_access_changed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = (
        await db.get(
            _ItBApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    return _itb_access_payload(
        row,
        approval,
    )


