@app.post("/api/it/recovery-tests")
async def create_it_recovery_test(
    payload: ITRecoveryTestCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    profile = await db.get(
        ITRecoveryProfile,
        payload.recovery_profile_id,
    )

    if profile is None:
        raise HTTPException(
            status_code=404,
            detail="IT recovery profile not found",
        )

    if profile.status != "active":
        raise HTTPException(
            status_code=409,
            detail=(
                "Recovery profile must be active "
                "before planning a test"
            ),
        )

    test_type = payload.test_type.strip().lower()

    if test_type not in _ITB_RECOVERY_TEST_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid recovery test type",
        )

    row = ITRecoveryTest(
        code=_itb_code("IT-DRT"),
        recovery_profile_id=profile.id,
        test_type=test_type,
        planned_at=payload.planned_at,
        status="planned",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        test_metadata={
            "backup_executed_by_system": False,
            "restore_executed_by_system": False,
            "dr_failover_executed_by_system": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _itb_test_payload(row)


@app.post("/api/it/recovery-tests/{test_id}/record-result")
async def record_it_recovery_test_result(
    test_id: _itb_uuid.UUID,
    payload: ITRecoveryTestResultRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITRecoveryTest,
        test_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT recovery test not found",
        )

    if row.status != "planned":
        raise HTTPException(
            status_code=409,
            detail=(
                "Only planned recovery test "
                "can record a result"
            ),
        )

    if (
        payload.actual_rpo_minutes < 0
        or payload.actual_rto_minutes < 0
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Actual RPO/RTO cannot be negative"
            ),
        )

    reference = (
        payload.external_test_reference.strip()
    )
    actor = payload.performed_by.strip()

    if not reference or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "External test reference "
                "and performed_by are required"
            ),
        )

    profile = await db.get(
        ITRecoveryProfile,
        row.recovery_profile_id,
    )

    if profile is None:
        raise HTTPException(
            status_code=409,
            detail="Recovery profile is missing",
        )

    passed = bool(
        payload.restoration_verified
        and payload.actual_rpo_minutes
        <= profile.rpo_target_minutes
        and payload.actual_rto_minutes
        <= profile.rto_target_minutes
    )

    result = (
        "passed"
        if passed
        else "failed"
    )

    now = _itb_datetime.now(
        _itb_timezone.utc
    )

    row.restoration_verified = (
        payload.restoration_verified
    )
    row.actual_rpo_minutes = (
        payload.actual_rpo_minutes
    )
    row.actual_rto_minutes = (
        payload.actual_rto_minutes
    )
    row.result = result
    row.external_test_reference = reference
    row.performed_by = actor
    row.issues_summary = (
        payload.issues_summary.strip()
        if payload.issues_summary
        and payload.issues_summary.strip()
        else None
    )
    row.completed_at = now
    row.status = "completed"

    profile.last_test_at = now
    profile.last_test_result = result
    profile.next_test_due_date = (
        now.date()
        + _itb_timedelta(
            days=profile.test_frequency_days
        )
    )

    await write_audit_log(
        db,
        actor=actor,
        action="it.recovery.external_test_result_recorded",
        details={
            "recovery_test_id": str(row.id),
            "recovery_profile_id":
                str(profile.id),
            "result": result,
            "external_reference": reference,
            "backup_executed_by_system": False,
            "restore_executed_by_system": False,
            "dr_failover_executed_by_system": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _itb_test_payload(row)


@app.get("/api/it/access-recovery-alerts")
async def it_access_recovery_alerts(
    db: AsyncSession = Depends(get_db),
):
    now = _itb_datetime.now(
        _itb_timezone.utc
    )
    today = now.date()

    privileged_expiring = (
        await db.execute(
            _itb_select(
                ITAccessRequest
            ).where(
                ITAccessRequest.status == "active",
                ITAccessRequest.access_type
                == "privileged",
                ITAccessRequest.expires_at
                .is_not(None),
                ITAccessRequest.expires_at
                <= now + _itb_timedelta(days=7),
            )
        )
    ).scalars().all()

    expired_active = (
        await db.execute(
            _itb_select(
                ITAccessRequest
            ).where(
                ITAccessRequest.status == "active",
                ITAccessRequest.expires_at
                .is_not(None),
                ITAccessRequest.expires_at
                < now,
            )
        )
    ).scalars().all()

    recovery_due = (
        await db.execute(
            _itb_select(
                ITRecoveryProfile
            ).where(
                ITRecoveryProfile.status == "active",
                ITRecoveryProfile.next_test_due_date
                <= today,
            )
        )
    ).scalars().all()

    failed_profiles = (
        await db.execute(
            _itb_select(
                ITRecoveryProfile
            ).where(
                ITRecoveryProfile.status == "active",
                ITRecoveryProfile.last_test_result
                == "failed",
            )
        )
    ).scalars().all()

    return {
        "total": (
            len(privileged_expiring)
            + len(expired_active)
            + len(recovery_due)
            + len(failed_profiles)
        ),
        "privileged_access_expiring_7_days":
            len(privileged_expiring),
        "expired_active_access":
            len(expired_active),
        "recovery_tests_due":
            len(recovery_due),
        "failed_recovery_profiles":
            len(failed_profiles),
    }


@app.get("/api/it/phase1b-summary")
async def it_phase1b_summary(
    db: AsyncSession = Depends(get_db),
):
    access = (
        await db.execute(
            _itb_select(
                ITAccessRequest
            )
        )
    ).scalars().all()

    profiles = (
        await db.execute(
            _itb_select(
                ITRecoveryProfile
            )
        )
    ).scalars().all()

    tests = (
        await db.execute(
            _itb_select(
                ITRecoveryTest
            )
        )
    ).scalars().all()

    physical_access_count = int(
        await db.scalar(
            _itb_select(
                _itb_func.count()
            ).select_from(
                _ItBAdminAccessRequest
            )
        )
        or 0
    )

    alerts = await it_access_recovery_alerts(
        db
    )

    return {
        "logical_access": {
            "total": len(access),
            "active": sum(
                1
                for x in access
                if x.status == "active"
            ),
            "privileged_active": sum(
                1
                for x in access
                if x.status == "active"
                and x.access_type == "privileged"
            ),
            "revoked": sum(
                1
                for x in access
                if x.status == "revoked"
            ),
        },
        "recovery_profiles": {
            "total": len(profiles),
            "active": sum(
                1
                for x in profiles
                if x.status == "active"
            ),
            "failed_last_test": sum(
                1
                for x in profiles
                if x.last_test_result == "failed"
            ),
        },
        "recovery_tests": {
            "total": len(tests),
            "completed": sum(
                1
                for x in tests
                if x.status == "completed"
            ),
            "passed": sum(
                1
                for x in tests
                if x.result == "passed"
            ),
            "failed": sum(
                1
                for x in tests
                if x.result == "failed"
            ),
        },
        "physical_access_reference_count":
            physical_access_count,
        "alerts": alerts["total"],
        "safety": {
            "automatic_identity_provider_mutation": False,
            "automatic_credential_creation": False,
            "automatic_access_revocation": False,
            "automatic_physical_access_change": False,
            "automatic_backup_execution": False,
            "automatic_restore_execution": False,
            "automatic_dr_failover": False,
            "automatic_procurement_creation": False,
            "automatic_payment": False,
            "automatic_external_communication": False,
        },
    }

