def _itc_code(prefix):
    return prefix + "-" + _itc_uuid.uuid4().hex[:8].upper()


def _itc_config_payload(row):
    return {
        "id": str(row.id),
        "code": row.code,
        "service_id": str(row.service_id),
        "name": row.name,
        "item_type": row.item_type,
        "environment": row.environment,
        "owner": row.owner,
        "baseline_reference":
            row.baseline_reference,
        "status": row.status,
        "notes": row.notes,
        "created_at": row.created_at,
        "updated_at": row.updated_at,
    }


