@app.post("/api/it/security-exceptions")
async def create_it_security_exception(
    payload: ITSecurityExceptionCreate,
    db: AsyncSession = Depends(get_db),
):
    service = await db.get(
        _ItCService,
        payload.service_id,
    )

    if service is None:
        raise HTTPException(
            status_code=404,
            detail="IT service not found",
        )

    risk = payload.risk_level.strip().lower()
    control_reference = payload.control_reference.strip()
    title = payload.title.strip()
    justification = payload.justification.strip()
    controls = payload.compensating_controls.strip()
    requested_by = payload.requested_by.strip()

    if risk not in _ITC_RISKS:
        raise HTTPException(
            status_code=400,
            detail="Invalid security exception risk",
        )

    if (
        not control_reference
        or not title
        or not justification
        or not controls
        or not requested_by
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Control reference, title, justification, "
                "compensating controls and requester are required"
            ),
        )

    if payload.expiry_date <= _itc_date.today():
        raise HTTPException(
            status_code=400,
            detail="Security exception must have a future expiry date",
        )

    row = ITSecurityException(
        code=_itc_code("IT-EXC"),
        service_id=service.id,
        control_reference=control_reference,
        title=title,
        justification=justification,
        compensating_controls=controls,
        requested_by=requested_by,
        risk_level=risk,
        expiry_date=payload.expiry_date,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        exception_metadata={
            "security_control_disabled_by_system": False,
            "configuration_mutated_by_system": False,
            "risk_auto_accepted": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _itc_exception_payload(row)


@app.post("/api/it/security-exceptions/{exception_id}/request-approval")
async def request_it_security_exception_approval(
    exception_id: _itc_uuid.UUID,
    payload: ITApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITSecurityException,
        exception_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT security exception not found",
        )

    if row.status not in {"draft", "pending_approval"}:
        raise HTTPException(
            status_code=409,
            detail="Security exception cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _ItCApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _itc_exception_payload(
                row,
                existing,
            )

    risk = (
        "critical"
        if row.risk_level in {"high", "critical"}
        else "high"
    )

    agent = await _ita_agent(db)

    approval = _ItCApproval(
        agent_id=agent.id if agent else None,
        title="Approve Security Exception " + row.code,
        description=row.title,
        action_type="it_security_exception_approval",
        risk_level=risk,
        status="pending",
        action_payload={
            "exception_id": str(row.id),
            "service_id": str(row.service_id),
            "control_reference": row.control_reference,
            "risk_level": row.risk_level,
            "expiry_date": row.expiry_date.isoformat(),
            "compensating_controls_present": True,
            "security_control_disabled": False,
            "configuration_mutated": False,
            "requested_by": payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _itc_exception_payload(
        row,
        approval,
    )


