@app.post("/api/it/security-assessments/{assessment_id}/record-result")
async def record_it_security_assessment_result(
    assessment_id: _itc_uuid.UUID,
    payload: ITSecurityAssessmentResult,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        ITSecurityAssessment,
        assessment_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="IT security assessment not found",
        )

    if row.status != "approved":
        raise HTTPException(
            status_code=409,
            detail="Security assessment must be approved before recording result",
        )

    reference = (
        payload.external_execution_reference.strip()
    )
    summary = payload.result_summary.strip()
    actor = payload.recorded_by.strip()

    if not reference or not summary or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "External execution reference, result summary "
                "and recorded_by are required"
            ),
        )

    row.status = "executed"
    row.external_execution_reference = reference
    row.result_summary = summary
    row.executed_at = _itc_datetime.now(
        _itc_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="it.security_assessment.external_result_recorded",
        details={
            "assessment_id": str(row.id),
            "external_reference": reference,
            "scan_executed_by_system": False,
            "exploit_executed_by_system": False,
            "external_testing_started_by_system": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    approval = await db.get(
        _ItCApproval,
        row.approval_id,
    )

    return _itc_assessment_payload(
        row,
        approval,
    )


@app.get("/api/it/security-governance-alerts")
async def it_security_governance_alerts(
    db: AsyncSession = Depends(get_db),
):
    today = _itc_date.today()

    expiring_exceptions = (
        await db.execute(
            _itc_select(
                ITSecurityException
            ).where(
                ITSecurityException.status == "approved",
                ITSecurityException.expiry_date
                <= today,
            )
        )
    ).scalars().all()

    overdue_vulnerabilities = (
        await db.execute(
            _itc_select(
                ITVulnerability
            ).where(
                ITVulnerability.status
                .in_([
                    "open",
                    "risk_acceptance_pending",
                ]),
                ITVulnerability.due_date < today,
            )
        )
    ).scalars().all()

    expiring_acceptances = (
        await db.execute(
            _itc_select(
                ITVulnerabilityRiskAcceptance
            ).where(
                ITVulnerabilityRiskAcceptance.status
                == "approved",
                ITVulnerabilityRiskAcceptance.accepted_until
                <= today,
            )
        )
    ).scalars().all()

    return {
        "total": (
            len(expiring_exceptions)
            + len(overdue_vulnerabilities)
            + len(expiring_acceptances)
        ),
        "expired_security_exceptions":
            len(expiring_exceptions),
        "overdue_vulnerabilities":
            len(overdue_vulnerabilities),
        "expired_risk_acceptances":
            len(expiring_acceptances),
    }


@app.get("/api/it/phase1c-summary")
async def it_phase1c_summary(
    db: AsyncSession = Depends(get_db),
):
    config_items = (
        await db.execute(
            _itc_select(
                ITConfigurationItem
            )
        )
    ).scalars().all()

    reviews = (
        await db.execute(
            _itc_select(
                ITArchitectureReview
            )
        )
    ).scalars().all()

    exceptions = (
        await db.execute(
            _itc_select(
                ITSecurityException
            )
        )
    ).scalars().all()

    vulnerabilities = (
        await db.execute(
            _itc_select(
                ITVulnerability
            )
        )
    ).scalars().all()

    acceptances = (
        await db.execute(
            _itc_select(
                ITVulnerabilityRiskAcceptance
            )
        )
    ).scalars().all()

    assessments = (
        await db.execute(
            _itc_select(
                ITSecurityAssessment
            )
        )
    ).scalars().all()

    mismatches = int(
        await db.scalar(
            _itc_select(
                _itc_func.count()
            ).select_from(
                _ItCPolicyMismatch
            )
        )
        or 0
    )

    verifications = int(
        await db.scalar(
            _itc_select(
                _itc_func.count()
            ).select_from(
                _ItCTechnicalVerification
            )
        )
        or 0
    )

    alerts = await it_security_governance_alerts(
        db
    )

    return {
        "configuration_items": {
            "total": len(config_items),
        },
        "architecture_reviews": {
            "total": len(reviews),
            "approved": sum(
                1
                for x in reviews
                if x.status == "approved"
            ),
        },
        "security_exceptions": {
            "total": len(exceptions),
            "approved": sum(
                1
                for x in exceptions
                if x.status == "approved"
            ),
            "closed": sum(
                1
                for x in exceptions
                if x.status == "closed"
            ),
        },
        "vulnerabilities": {
            "total": len(vulnerabilities),
            "open": sum(
                1
                for x in vulnerabilities
                if x.status in {
                    "open",
                    "risk_acceptance_pending",
                }
            ),
            "risk_accepted": sum(
                1
                for x in vulnerabilities
                if x.status == "risk_accepted"
            ),
            "closed": sum(
                1
                for x in vulnerabilities
                if x.status == "closed"
            ),
        },
        "risk_acceptances": {
            "total": len(acceptances),
            "approved": sum(
                1
                for x in acceptances
                if x.status == "approved"
            ),
        },
        "security_assessments": {
            "total": len(assessments),
            "executed": sum(
                1
                for x in assessments
                if x.status == "executed"
            ),
        },
        "policy_boundary": {
            "system_mismatches": mismatches,
            "technical_verifications":
                verifications,
        },
        "alerts": alerts["total"],
        "safety": {
            "automatic_configuration_mutation": False,
            "automatic_architecture_deployment": False,
            "automatic_cloud_vendor_selection": False,
            "automatic_security_control_disable": False,
            "automatic_vulnerability_scan": False,
            "automatic_exploit_execution": False,
            "automatic_patch_execution": False,
            "automatic_risk_acceptance": False,
            "automatic_external_security_testing": False,
            "automatic_procurement_creation": False,
            "automatic_external_communication": False,
        },
    }

