@app.post("/api/audit/plans")
async def create_audit_plan(
    payload: AuditPlanCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    title = payload.title.strip()
    basis = payload.risk_basis.strip()
    scope = payload.scope_summary.strip()
    prepared_by = payload.prepared_by.strip()

    if payload.year < 2000 or payload.year > 2100:
        raise HTTPException(
            status_code=400,
            detail="Invalid audit plan year",
        )

    if not title or not basis or not scope or not prepared_by:
        raise HTTPException(
            status_code=400,
            detail=(
                "Title, risk basis, scope and prepared_by "
                "are required"
            ),
        )

    if not payload.independence_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Audit independence confirmation is required",
        )

    existing = (
        await db.execute(
            _auda_select(
                AuditPlan
            ).where(
                AuditPlan.year == payload.year
            )
        )
    ).scalars().first()

    if existing is not None:
        raise HTTPException(
            status_code=409,
            detail="Audit plan already exists for this year",
        )

    row = AuditPlan(
        code=_auda_code("AUD-PLAN"),
        year=payload.year,
        title=title,
        risk_basis=basis,
        scope_summary=scope,
        prepared_by=prepared_by,
        independence_confirmed=True,
        status="draft",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        plan_metadata={
            "operational_transaction_approved_by_audit": False,
            "operational_control_operated_by_audit": False,
            "compliance_certified_automatically": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _auda_plan_payload(row)


@app.post("/api/audit/plans/{plan_id}/request-approval")
async def request_audit_plan_approval(
    plan_id: _auda_uuid.UUID,
    payload: AuditApprovalRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditPlan,
        plan_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit plan not found",
        )

    if row.status not in {
        "draft",
        "pending_approval",
    }:
        raise HTTPException(
            status_code=409,
            detail="Audit plan cannot enter approval now",
        )

    if row.approval_id:
        existing = await db.get(
            _AudAApproval,
            row.approval_id,
        )
        if existing and existing.status == "pending":
            return _auda_plan_payload(
                row,
                existing,
            )

    agent = await _auda_agent(db)

    approval = _AudAApproval(
        agent_id=(
            agent.id
            if agent
            else None
        ),
        title="Approve Annual Internal Audit Plan " + row.code,
        description=(
            str(row.year)
            + " | "
            + row.title
        ),
        action_type="audit_annual_plan_approval",
        risk_level="high",
        status="pending",
        action_payload={
            "audit_plan_id": str(row.id),
            "year": row.year,
            "independence_confirmed":
                row.independence_confirmed,
            "operational_transaction_approved": False,
            "requested_by":
                payload.requested_by,
            "notes": payload.notes,
        },
    )

    db.add(approval)
    await db.flush()

    row.approval_id = approval.id
    row.status = "pending_approval"

    await db.commit()
    await db.refresh(row)

    return _auda_plan_payload(
        row,
        approval,
    )


@app.post("/api/audit/plans/{plan_id}/authorize")
async def authorize_audit_plan(
    plan_id: _auda_uuid.UUID,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditPlan,
        plan_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit plan not found",
        )

    approval = (
        await db.get(
            _AudAApproval,
            row.approval_id,
        )
        if row.approval_id
        else None
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "audit_annual_plan_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail="Approved annual-audit-plan authorization is required",
        )

    row.status = "approved"

    await db.commit()
    await db.refresh(row)

    return _auda_plan_payload(
        row,
        approval,
    )


