@app.post("/api/audit/engagements")
async def create_audit_engagement(
    payload: AuditEngagementCreateRequest,
    db: AsyncSession = Depends(get_db),
):
    if payload.plan_id:
        plan = await db.get(
            AuditPlan,
            payload.plan_id,
        )

        if plan is None:
            raise HTTPException(
                status_code=404,
                detail="Audit plan not found",
            )

        if plan.status != "approved":
            raise HTTPException(
                status_code=409,
                detail=(
                    "Linked annual audit plan must be approved "
                    "before creating an engagement"
                ),
            )

    title = payload.title.strip()
    domain = payload.domain.strip()
    objective = payload.objective.strip()
    scope = payload.scope_summary.strip()
    records = payload.records_access_scope.strip()
    auditor = payload.auditor.strip()

    if (
        not title
        or not domain
        or not objective
        or not scope
        or not records
        or not auditor
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Title, domain, objective, scope, records access "
                "scope and auditor are required"
            ),
        )

    if not payload.independence_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Engagement independence confirmation is required",
        )

    if (
        payload.planned_start_date
        and payload.planned_end_date
        and payload.planned_end_date
        < payload.planned_start_date
    ):
        raise HTTPException(
            status_code=400,
            detail="Audit engagement end date cannot precede start date",
        )

    row = AuditEngagement(
        code=_auda_code("AUD-ENG"),
        plan_id=payload.plan_id,
        title=title,
        domain=domain,
        objective=objective,
        scope_summary=scope,
        records_access_scope=records,
        auditor=auditor,
        independence_confirmed=True,
        planned_start_date=
            payload.planned_start_date,
        planned_end_date=
            payload.planned_end_date,
        status="planned",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        engagement_metadata={
            "source_module_mutated": False,
            "operational_control_operated_by_audit": False,
            "transaction_approved_by_audit": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _auda_engagement_payload(row)


@app.put("/api/audit/engagements/{engagement_id}/status")
async def update_audit_engagement_status(
    engagement_id: _auda_uuid.UUID,
    payload: AuditEngagementStatusRequest,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditEngagement,
        engagement_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit engagement not found",
        )

    target = payload.status.strip().lower()

    if target not in _AUDA_ENGAGEMENT_STATUSES:
        raise HTTPException(
            status_code=400,
            detail="Invalid audit engagement status",
        )

    if target == "in_progress":
        if row.status != "planned":
            raise HTTPException(
                status_code=409,
                detail="Only planned engagement can start",
            )

        row.status = "in_progress"
        row.started_at = _auda_datetime.now(
            _auda_timezone.utc
        )

    elif target == "reporting":
        if row.status != "in_progress":
            raise HTTPException(
                status_code=409,
                detail="Only in-progress engagement can enter reporting",
            )

        row.status = "reporting"

    elif target == "closed":
        if row.status not in {
            "in_progress",
            "reporting",
        }:
            raise HTTPException(
                status_code=409,
                detail="Engagement cannot close from current status",
            )

        open_findings = int(
            await db.scalar(
                _auda_select(
                    _auda_func.count()
                ).select_from(
                    AuditFinding
                ).where(
                    AuditFinding.engagement_id
                    == row.id,
                    AuditFinding.status
                    != "closed",
                )
            )
            or 0
        )

        if open_findings:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Audit engagement cannot close while "
                    "findings remain open"
                ),
            )

        row.status = "closed"
        row.closed_at = _auda_datetime.now(
            _auda_timezone.utc
        )

    elif target == "cancelled":
        row.status = "cancelled"

    await write_audit_log(
        db,
        actor=payload.actor.strip() or "user",
        action="audit.engagement.status_changed",
        details={
            "engagement_id": str(row.id),
            "status": row.status,
            "source_module_mutated": False,
            "operational_transaction_approved": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _auda_engagement_payload(row)


