@app.get("/api/audit/integrity-investigations")
async def list_audit_integrity_investigations(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _audc_select(
                AuditIntegrityInvestigation
            ).order_by(
                AuditIntegrityInvestigation.created_at.desc()
            )
        )
    ).scalars().all()

    output = []

    for row in rows:
        approval = await db.get(
            _AudCApproval,
            row.approval_id,
        )
        output.append(
            _audc_investigation_payload(
                row,
                approval,
            )
        )

    return output


@app.post("/api/audit/integrity-investigations")
async def create_audit_integrity_investigation(
    payload: AuditIntegrityInvestigationCreate,
    db: AsyncSession = Depends(get_db),
):
    case_type = payload.case_type.strip().lower()
    title = payload.title.strip()
    allegation = payload.allegation_summary.strip()
    channel = payload.received_channel.strip()
    severity = payload.severity.strip().lower()
    investigator = payload.investigator.strip()

    if case_type not in _AUDC_CASE_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid audit integrity case type",
        )

    if severity not in _AUDC_SEVERITIES:
        raise HTTPException(
            status_code=400,
            detail="Invalid audit integrity severity",
        )

    if (
        not title
        or not allegation
        or not channel
        or not investigator
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Title, allegation summary, channel "
                "and investigator are required"
            ),
        )

    if not payload.independence_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Investigator independence confirmation is required",
        )

    if not payload.conflict_check_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Investigator conflict check confirmation is required",
        )

    reporter_reference = (
        payload.reporter_reference.strip()
        if payload.reporter_reference
        and payload.reporter_reference.strip()
        else None
    )

    if (
        not payload.anonymous_reporter
        and not reporter_reference
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Non-anonymous report requires a protected "
                "reporter reference"
            ),
        )

    risk_level = (
        "critical"
        if severity == "critical"
        else "high"
    )

    approval = _AudCApproval(
        agent_id=None,
        title="Approve Integrity Investigation Opening",
        description=title,
        action_type="audit_integrity_investigation_open_approval",
        risk_level=risk_level,
        status="pending",
        action_payload={
            "case_type": case_type,
            "severity": severity,
            "investigator":
                investigator,
            "independence_confirmed": True,
            "conflict_check_confirmed": True,
            "reporter_protection_required": True,
            "external_action_executed": False,
            "hr_action_executed": False,
            "legal_action_executed": False,
            "regulatory_notification_sent": False,
        },
    )

    db.add(approval)
    await db.flush()

    row = AuditIntegrityInvestigation(
        code=_audc_code("AUD-INV"),
        case_type=case_type,
        title=title,
        allegation_summary=allegation,
        received_channel=channel,
        anonymous_reporter=
            payload.anonymous_reporter,
        reporter_reference=
            reporter_reference,
        reporter_protection_required=True,
        retaliation_monitoring_required=True,
        severity=severity,
        investigator=investigator,
        independence_confirmed=True,
        conflict_check_confirmed=True,
        status="pending_approval",
        approval_id=approval.id,
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
        investigation_metadata={
            "reporter_identity_disclosed_by_system": False,
            "hr_case_created_by_system": False,
            "legal_matter_created_by_system": False,
            "disciplinary_action_executed_by_system": False,
            "regulator_notified_by_system": False,
            "external_referral_executed_by_system": False,
            "payment_executed_by_system": False,
        },
    )

    db.add(row)
    await db.commit()
    await db.refresh(row)

    return _audc_investigation_payload(
        row,
        approval,
    )


@app.post("/api/audit/integrity-investigations/{investigation_id}/start")
async def start_audit_integrity_investigation(
    investigation_id: _audc_uuid.UUID,
    payload: AuditIntegrityStart,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditIntegrityInvestigation,
        investigation_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit integrity investigation not found",
        )

    approval = await db.get(
        _AudCApproval,
        row.approval_id,
    )

    if (
        approval is None
        or approval.status != "approved"
        or approval.action_type
        != "audit_integrity_investigation_open_approval"
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Approved investigation-opening authorization "
                "is required"
            ),
        )

    if row.status != "pending_approval":
        raise HTTPException(
            status_code=409,
            detail="Investigation cannot start from current status",
        )

    row.status = "investigating"
    row.opened_at = _audc_datetime.now(
        _audc_timezone.utc
    )

    await write_audit_log(
        db,
        actor=payload.actor.strip() or "user",
        action="audit.integrity_investigation.started",
        details={
            "investigation_id": str(row.id),
            "reporter_identity_disclosed": False,
            "hr_case_created": False,
            "legal_matter_created": False,
            "external_referral_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _audc_investigation_payload(
        row,
        approval,
    )


@app.post("/api/audit/integrity-investigations/{investigation_id}/record-findings")
async def record_audit_integrity_findings(
    investigation_id: _audc_uuid.UUID,
    payload: AuditIntegrityFindings,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditIntegrityInvestigation,
        investigation_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit integrity investigation not found",
        )

    if row.status != "investigating":
        raise HTTPException(
            status_code=409,
            detail="Only active investigation can record findings",
        )

    summary = payload.findings_summary.strip()

    if not summary:
        raise HTTPException(
            status_code=400,
            detail="Investigation findings summary is required",
        )

    row.findings_summary = summary
    row.status = "reporting"

    await db.commit()
    await db.refresh(row)

    return _audc_investigation_payload(
        row,
        await db.get(
            _AudCApproval,
            row.approval_id,
        ),
    )


@app.post("/api/audit/integrity-investigations/{investigation_id}/close")
async def close_audit_integrity_investigation(
    investigation_id: _audc_uuid.UUID,
    payload: AuditIntegrityClose,
    db: AsyncSession = Depends(get_db),
):
    row = await db.get(
        AuditIntegrityInvestigation,
        investigation_id,
    )

    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Audit integrity investigation not found",
        )

    if row.status != "reporting":
        raise HTTPException(
            status_code=409,
            detail="Investigation must be in reporting before closure",
        )

    if not row.findings_summary:
        raise HTTPException(
            status_code=409,
            detail="Investigation findings are required before closure",
        )

    outcome = payload.outcome.strip().lower()

    if outcome not in _AUDC_OUTCOMES:
        raise HTTPException(
            status_code=400,
            detail="Invalid investigation outcome",
        )

    report_ref = (
        payload.investigation_report_reference.strip()
    )
    actor = payload.closed_by.strip()

    if not report_ref or not actor:
        raise HTTPException(
            status_code=400,
            detail=(
                "Investigation report reference "
                "and closed_by are required"
            ),
        )

    row.outcome = outcome
    row.investigation_report_reference = report_ref
    row.hr_referral_recommended = (
        payload.hr_referral_recommended
    )
    row.legal_referral_recommended = (
        payload.legal_referral_recommended
    )
    row.regulatory_referral_recommended = (
        payload.regulatory_referral_recommended
    )
    row.external_referral_recommended = (
        payload.external_referral_recommended
    )
    row.status = "closed"
    row.closed_at = _audc_datetime.now(
        _audc_timezone.utc
    )

    await write_audit_log(
        db,
        actor=actor,
        action="audit.integrity_investigation.closed",
        details={
            "investigation_id": str(row.id),
            "outcome": outcome,
            "report_reference": report_ref,
            "hr_referral_recommended":
                row.hr_referral_recommended,
            "legal_referral_recommended":
                row.legal_referral_recommended,
            "regulatory_referral_recommended":
                row.regulatory_referral_recommended,
            "external_referral_recommended":
                row.external_referral_recommended,
            "hr_action_executed": False,
            "legal_action_executed": False,
            "regulatory_notification_sent": False,
            "external_referral_executed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _audc_investigation_payload(
        row,
        await db.get(
            _AudCApproval,
            row.approval_id,
        ),
    )


async def _audc_governance_snapshot(db):
    it_exceptions = (
        await db.execute(
            _audc_select(
                _AudCITSecurityException
            )
        )
    ).scalars().all()

    legal_delegations = (
        await db.execute(
            _audc_select(
                _AudCLegalAuthorityDelegation
            )
        )
    ).scalars().all()

    authority_rules = (
        await db.execute(
            _audc_select(
                _AudCCompanyAuthorityRule
            )
        )
    ).scalars().all()

    authority_limits = (
        await db.execute(
            _audc_select(
                _AudCCompanyAuthorityLimit
            )
        )
    ).scalars().all()

    return {
        "it_security_exceptions": {
            "total": len(it_exceptions),
            "approved_open": sum(
                1
                for x in it_exceptions
                if x.status == "approved"
            ),
            "closed": sum(
                1
                for x in it_exceptions
                if x.status == "closed"
            ),
        },
        "legal_authority_delegations": {
            "total": len(legal_delegations),
            "active": sum(
                1
                for x in legal_delegations
                if x.status == "active"
            ),
            "revoked": sum(
                1
                for x in legal_delegations
                if x.status == "revoked"
            ),
        },
        "company_authority_matrix": {
            "rules_total":
                len(authority_rules),
            "rules_enforcement_enabled":
                sum(
                    1
                    for x in authority_rules
                    if x.enforcement_enabled
                ),
            "limits_total":
                len(authority_limits),
            "limits_enforcement_enabled":
                sum(
                    1
                    for x in authority_limits
                    if x.enforcement_enabled
                ),
            "reference_only": (
                not any(
                    x.enforcement_enabled
                    for x in authority_rules
                )
                and not any(
                    x.enforcement_enabled
                    for x in authority_limits
                )
            ),
        },
    }


@app.get("/api/audit/governance-monitoring/source-snapshot")
async def audit_governance_source_snapshot(
    db: AsyncSession = Depends(get_db),
):
    return {
        "read_only": True,
        "snapshot":
            await _audc_governance_snapshot(
                db
            ),
        "authoritative_sources": {
            "security_exceptions":
                "IT",
            "authority_delegations":
                "Legal",
            "authority_matrix":
                "Company Control",
        },
    }


@app.get("/api/audit/governance-monitoring/reviews")
async def list_audit_governance_monitoring_reviews(
    db: AsyncSession = Depends(get_db),
):
    rows = (
        await db.execute(
            _audc_select(
                AuditGovernanceMonitoringReview
            ).order_by(
                AuditGovernanceMonitoringReview.review_date.desc()
            )
        )
    ).scalars().all()

    return [
        _audc_monitoring_payload(row)
        for row in rows
    ]


@app.post("/api/audit/governance-monitoring/reviews")
async def create_audit_governance_monitoring_review(
    payload: AuditGovernanceMonitoringCreate,
    db: AsyncSession = Depends(get_db),
):
    review_type = (
        payload.review_type.strip().lower()
    )
    period_label = payload.period_label.strip()
    reviewer = payload.reviewed_by.strip()
    evidence = payload.evidence_reference.strip()
    observations = payload.observations.strip()

    if review_type not in _AUDC_REVIEW_TYPES:
        raise HTTPException(
            status_code=400,
            detail="Invalid governance monitoring review type",
        )

    if (
        not period_label
        or not reviewer
        or not evidence
        or not observations
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Period, reviewer, evidence "
                "and observations are required"
            ),
        )

    if payload.next_review_date <= _audc_date.today():
        raise HTTPException(
            status_code=400,
            detail="Next governance review date must be in the future",
        )

    snapshot = await _audc_governance_snapshot(
        db
    )

    row = AuditGovernanceMonitoringReview(
        code=_audc_code("AUD-GOV"),
        review_type=review_type,
        period_label=period_label,
        reviewed_by=reviewer,
        review_date=_audc_date.today(),
        evidence_reference=evidence,
        source_snapshot=snapshot,
        observations=observations,
        follow_up_required=
            payload.follow_up_required,
        next_review_date=
            payload.next_review_date,
        status="completed",
        notes=(
            payload.notes.strip()
            if payload.notes
            and payload.notes.strip()
            else None
        ),
    )

    db.add(row)

    await write_audit_log(
        db,
        actor=reviewer,
        action="audit.governance_monitoring.review_completed",
        details={
            "review_type": review_type,
            "source_modules_mutated": False,
            "company_authority_enforcement_changed": False,
            "it_exception_changed": False,
            "legal_delegation_changed": False,
        },
    )

    await db.commit()
    await db.refresh(row)

    return _audc_monitoring_payload(row)


@app.get("/api/audit/phase1c-alerts")
async def audit_phase1c_alerts(
    db: AsyncSession = Depends(get_db),
):
    today = _audc_date.today()

    open_investigations = (
        await db.execute(
            _audc_select(
                AuditIntegrityInvestigation
            ).where(
                AuditIntegrityInvestigation.status
                .in_([
                    "pending_approval",
                    "investigating",
                    "reporting",
                ])
            )
        )
    ).scalars().all()

    critical_open = [
        x
        for x in open_investigations
        if x.severity == "critical"
    ]

    overdue_reviews = (
        await db.execute(
            _audc_select(
                AuditGovernanceMonitoringReview
            ).where(
                AuditGovernanceMonitoringReview.next_review_date
                <= today
            )
        )
    ).scalars().all()

    return {
        "total": (
            len(open_investigations)
            + len(critical_open)
            + len(overdue_reviews)
        ),
        "open_integrity_investigations":
            len(open_investigations),
        "critical_open_investigations":
            len(critical_open),
        "overdue_governance_reviews":
            len(overdue_reviews),
    }


@app.get("/api/audit/phase1c-summary")
async def audit_phase1c_summary(
    db: AsyncSession = Depends(get_db),
):
    investigations = (
        await db.execute(
            _audc_select(
                AuditIntegrityInvestigation
            )
        )
    ).scalars().all()

    monitoring = (
        await db.execute(
            _audc_select(
                AuditGovernanceMonitoringReview
            )
        )
    ).scalars().all()

    alerts = await audit_phase1c_alerts(
        db
    )

    return {
        "integrity_investigations": {
            "total": len(investigations),
            "open": sum(
                1
                for x in investigations
                if x.status
                in {
                    "pending_approval",
                    "investigating",
                    "reporting",
                }
            ),
            "closed": sum(
                1
                for x in investigations
                if x.status == "closed"
            ),
            "substantiated": sum(
                1
                for x in investigations
                if x.outcome == "substantiated"
            ),
        },
        "governance_monitoring": {
            "total": len(monitoring),
            "monthly_exception_delegation_reviews":
                sum(
                    1
                    for x in monitoring
                    if x.review_type
                    == "monthly_exceptions_delegations"
                ),
            "annual_authority_matrix_reviews":
                sum(
                    1
                    for x in monitoring
                    if x.review_type
                    == "annual_authority_matrix"
                ),
            "follow_up_required":
                sum(
                    1
                    for x in monitoring
                    if x.follow_up_required
                ),
        },
        "alerts": alerts["total"],
        "safety": {
            "automatic_reporter_identity_disclosure": False,
            "automatic_hr_case_creation": False,
            "automatic_legal_matter_creation": False,
            "automatic_disciplinary_action": False,
            "automatic_regulatory_notification": False,
            "automatic_external_referral": False,
            "automatic_source_register_mutation": False,
            "automatic_authority_matrix_enforcement": False,
            "automatic_payment": False,
            "automatic_external_communication": False,
        },
    }
